gameforge.dragon_soul = {}
gameforge.dragon_soul._010_sayTitle = "Ejderha Tasi Parcasi+?! "
gameforge.dragon_soul._020_say = "Elinde bir tas parcasi duruyor. Garip bir[ENTER]pariltiyla parliyor ve gucunun seni doldurdugunu[ENTER]hissediyorsun.[ENTER]Bu gizemli tas da ne? Onu simyaciya gotur.[ENTER]Kesinlikle sana yardimci olabilecektir. "
gameforge.dragon_soul._030_npcChat = "Ejderha Tasi Parcasi+?! "
gameforge.dragon_soul._040_say = "Bu, olaganustu guce sahip cok nadir ve degerli bir[ENTER]kristal olan Ejderha Tasi'nin bir parcasi.[ENTER]Icinde bir ejderhanin ruhunun uyudugu soylenir. Ah,[ENTER]ne kadar guzel![ENTER]Gucunun seni doldurdugunu hissediyor musun?[ENTER]Bana toplamda on tane boyle parca getir, onlari[ENTER]tek bir tasta birlestireyim. "
gameforge.dragon_soul._050_npcChat = "Ejderha Tasi Donusumu "
gameforge.dragon_soul._060_say = "O kadar acele etme. Onlari bir Ejderha Tasi'nda[ENTER]birlestirmek icin on parcaya ihtiyacim var.[ENTER]Aramaya devam et! "
gameforge.dragon_soul._070_say = "Aaa, harika! On Ejderha Tasi Parcasi'ni bulmayi[ENTER]basardin. Bir dakika bekle.[ENTER]...[ENTER]Basardik! Inanilmaz... donusum sonucunda,[ENTER]ejderha tasini saran kristal bir ejderha kalbi[ENTER]olan Cor Draconis olustu.[ENTER]Once onu kirmalisin, icinde hangi tasin[ENTER]bulundugunu gormek icin. Tas hemen[ENTER]Ejderha Taslari simya envanterine eklenecek.[ENTER]Unutma, Ejderha Taslari gelistirilebilir. "
gameforge.dragon_soul._080_say = "Bir Cor Draconis daha ister misin?[ENTER]Eh, artik genc degilim ve bu kadar karmasik[ENTER]bir esyanin fuzyonu buyuk bir caba[ENTER]gerektiriyor.[ENTER]Ama senin icin biraz fedakarlik yapabilirim.[ENTER]Ama unutma, gunde on taneden fazlasi[ENTER]soz konusu degil! "
gameforge.dragon_soul._090_say = "Bugunluk bu kadari yeterli. Gunde ondan fazla[ENTER]Cor Draconis gucumu asiyor.[ENTER]Bitkinim ve biraz dinlenmeliyim.[ENTER]Yarin tekrar gel. "
gameforge.dragon_soul._100_npcChat = "Dukkani ac "
gameforge.dragon_soul._1010_sendLetter = "Ejderha Tasi Parcasi Geldi "
gameforge.dragon_soul._1020_say = "Tum ulkedeki minerallere dair derin bilgisi olan[ENTER]simyaci seni ariyor. Hizlica ona git. "
gameforge.dragon_soul._1030_npcChat = "Ejderha Tasi Parcasi+?! "
gameforge.dragon_soul._1040_say = "Ah, geldin! Inanilmaz bir sey kesfettim: bir[ENTER]ejderha tasi parcasi! Ejderha Tasi, muazzam bir[ENTER]guce sahip cok nadir ve degerli bir mucevherdir.[ENTER]Ejderha'nin Ruhu da denir. Inanilmaz derecede guzel![ENTER]Sana parcalari bulabilmen icin Ejderha Gozu[ENTER]gucunu verecegim.[ENTER]Bana toplamda 10 Ejderha Tasi parcasi getir.Ben de onlardan tam bir tas yapayim. "
gameforge.dragon_soul._1050_sendLetter = "Ejderha Tasi Parcalarini Topla "
gameforge.dragon_soul._1060_say = "Simyaciya 10 Ejderha Tasi Parcasi gotur. "
gameforge.dragon_soul._1070_say = "Aaa, harika! On Ejderha Tasi Parcasi'ni bulmayi[ENTER]basardin. Bir dakika bekle...[ENTER]Inanilmaz! Donusum sonucunda, Ejderha Tasi'ni[ENTER]saran kristal bir ejderha kalbi olan Cor[ENTER]Draconis olustu.[ENTER]Onu kirdiginda, Ejderha Tasi hemen[ENTER]Ejderha Taslari Simyasi envanterine eklenecek.[ENTER]Ejderha Tasi Parcalarini bulup birlestirmek[ENTER]icin Ejderha Gozu gucune ihtiyacin var. Gunde bir[ENTER]kez sana bu gucu verebilirim.[ENTER]Senin icin zaten bir Ejderha Tasi yarattim.[ENTER]Kalan %d taneyi kendin yapacaksin. "
gameforge.dragon_soul._1080_say = "Hey, zaman kaybetme! Git ve Ejderha Tasi[ENTER]Parcalarini ara! "
