gameforge.energy_system = {}
gameforge.energy_system._001_npcChat = "Yeni teknik! "
gameforge.energy_system._010_say = "Sonunda![ENTER]Tamamen yeni bir teknik gelistirmeyi basardim.[ENTER]Onun sayesinde esyalari parcalara ayirip[ENTER]iclerinden son derece saf enerji cikarabiliyorum.[ENTER]Bir dahiyim! "
gameforge.energy_system._020_say = "Teknigimle bir esyayi parcalara ayirdiginda,[ENTER]bir enerji parcasi elde edeceksin. Bu tur 30[ENTER]parcayi birlestir, guclu bir enerji kristali[ENTER]olussun - tek bir mucevherde toplanmis son derece[ENTER]saf enerji. Bu guc tum zirhina aktarilacak.[ENTER]Kulaga guzel geliyor, degil mi? "
gameforge.energy_system._030_say = "Bana silah, mucevher, zirh ve diger techizat[ENTER]parcalari getir, ben de onlari enerji parcalarina[ENTER]donustureyim. Bu teknik imparatorlugumuzun[ENTER]gelecegi![ENTER]Yenilmez olacagiz! "
gameforge.energy_system._035_npcChat = "Enerji parcalarini cikar "
gameforge.energy_system._040_say = "Nasil? Ise yaradi mi? Bir enerji parcan var mi[ENTER]zaten? Bana daha fazla esya getir, ben de onlari[ENTER]simyamla parcalayayim.[ENTER]Ama bil ki bu teknik henuz mukemmellestirilmedi.[ENTER]Bu yuzden sana bir esyadan kac parca cikacagini[ENTER]soyleyemem. "
gameforge.energy_system._050_say = "Bir sarti var: hem senin seviyen hem de esyanin[ENTER]seviyesi en az 35 olmali.[ENTER]Hmm, bakalim... "
gameforge.energy_system._060_say = "Biraz daha antrenman yapmalisin! En az[ENTER]35. seviyeye ulastiginda geri don. "
gameforge.energy_system._070_say = "Ah, harika! Goruyorum ki zaten[ENTER]yeterli tecrubeye sahipsin. Parcalayacagim[ENTER]esyayi bana ver. "
gameforge.energy_system._080_say = "Enerji parcalarinda uyuyan buyuyu kontrol[ENTER]etmek icin henuz yeterli guce sahip degilsin.[ENTER]En az 35. seviyeye ulastiginda bana geri[ENTER]don. "
gameforge.energy_system._090_say = "Bu esya benim teknigimle parcalanmaya[ENTER]uygun degil. Bana baska bir sey ver. "
gameforge.energy_system._100_say = "Bu esyada cok fazla enerji yok. Teknigimi[ENTER]kullanmami istiyorsan bana 35. seviye veya ustu bir[ENTER]esya ver. "
gameforge.energy_system._110_say = "Bu esyayi parcalamami ister misin? "
gameforge.energy_system._120_select = "Evet "
gameforge.energy_system._130_select = "Hayir, henuz degil! "
gameforge.energy_system._140_say = "Ah, ne yazik ki bir enerji parcasi cikarmayi[ENTER]basaramadim. Belki bir dahaki sefere[ENTER]olur. "
gameforge.energy_system._150_say = "Harika! %d x enerji parcasi cikarmayi[ENTER]basardim.[ENTER]Buyur! "
gameforge.energy_system._160_npcChat = "Enerji kristali birlestir "
gameforge.energy_system._170_say = "Yavas yavas gucten dusuyorsun, degil mi? Kendini[ENTER]bu kadar zorlama, bir gun canindan olabilirsin.[ENTER]Bir enerji kristali yapmak icin %d x[ENTER]enerji parcasina ihtiyacim var. "
gameforge.energy_system._180_say = "Bunlardan bir enerji kristali olusturmak icin[ENTER]henuz yeterli enerji parcana sahip degilsin.[ENTER]En az %d x enerji parcasina sahip[ENTER]oldugunda geri don. "
gameforge.energy_system._190_say = "Harika, goruyorum ki zaten %d x enerji[ENTER]parcana sahipsin. O halde onlardan bir[ENTER]enerji kristali yapabilirim. Bir dakika bekle. Deneyecegim, ama[ENTER]basarili olacagini garanti edemem. "
gameforge.energy_system._200_say = "Her sey hazir. Parcalari eritip[ENTER]enerji kristaline donusturebiliriz.[ENTER]Ama benim de bir seyden gecinmem gerekiyor,[ENTER]degil mi? Bu ozel islem sana %d[ENTER]Yang'a mal olacak. Bunu oder misin? "
gameforge.energy_system._210_select = "Elbette. "
gameforge.energy_system._220_select = "Hayir, simdi olmaz. "
gameforge.energy_system._230_say = "Peki, kararina saygi duyuyorum.[ENTER]Fikrini degistirir ve enerji kristaline ihtiyacin[ENTER]olursa geri don. "
gameforge.energy_system._240_say = "Üzgunum ama once odemen gerekiyor. Ben[ENTER]hayir kurumu degilim.[ENTER]Is istir - hizmetler icin odeme yapilmali. "
gameforge.energy_system._250_say = "Buyur, iste enerji kristalin. Ama sadece[ENTER]ilk deneme her zaman basarili olur. Simya cok[ENTER]ongorulemez bir bilim dalidir. Bu yuzden[ENTER]deneyin basarisiz olma ihtimali her zaman[ENTER]vardir. "
gameforge.energy_system._260_say = "Ne yazik ki, enerji kristali yapmayi[ENTER]basaramadim. Teknigim dahice ama ne yazik ki[ENTER]henuz mukemmellesmedi. Simya boyle bir[ENTER]sey iste.[ENTER]Bir dahaki sefere kesinlikle basaracagim! "
gameforge.energy_system._270_say = "Biliyordum! Teknigim dahice![ENTER]Iste enerji kristalin.[ENTER]Guzel bir esya, degil mi? O nabiz gibi atan[ENTER]enerjiyi hissediyor musun? "
