gameforge.fortune_telling = {}
gameforge.fortune_telling._100_sayTitle = "Yasli Kadin "
gameforge.fortune_telling._10_npcChat = "Senin Falci oldugunu duydum. "
gameforge.fortune_telling._110_say = "Bu kadar derin nefes almak icin cok gencsin![ENTER]Mistik bir guc tarafindan okunan gelecegini[ENTER]ogrenmek ister misin? Bilmelisin ki, en zor[ENTER]sorularina cevap verebilecek gucler var. "
gameforge.fortune_telling._120_select = "Soyle bana "
gameforge.fortune_telling._130_select = "Bilmek istemiyorum... "
gameforge.fortune_telling._140_say = "Peki. Kendi yolunu izlemek ve elinden geleni[ENTER]yapmak hayattaki en onemli sey.[ENTER]Bol sans! "
gameforge.fortune_telling._150_select = "Evet, isterim. "
gameforge.fortune_telling._160_select = "Hayir, tesekkurler. "
gameforge.fortune_telling._170_say = "Dostane olabilirim ama onlari bedava dagitamam.[ENTER]Kotu kaderden ve talihsizlikten kacinmak[ENTER]istiyorsan, bu Karma Muskasi icin bana odeme[ENTER]yapmalisin.[ENTER]Karma Muskasi %s Yang'a mal olur. "
gameforge.fortune_telling._180_say = "Gidiyor musun? Muhtemelen haklisin. Kotu kader ve[ENTER]uzuntu hayatimizin bir parcasi. Bol sans ve[ENTER]hosca kal! Fikrini degistirirsen, geri gel. "
gameforge.fortune_telling._20_say = "Yuzun bana cok uzun suredir buralarda[ENTER]olmadigini soyluyor... Neden gelecegini bu kadar[ENTER]hizli ogrenmek istiyorsun? Bir sorunun mu var?[ENTER]Gelecegin henuz benim icin belli degil...[ENTER]Lutfen, daha sonra gel. "
gameforge.fortune_telling._30_say = "Tum hayatini bir Falci'nin tavsiyelerine kulak[ENTER]vererek gecirmek istediginden emin misin? Fallari[ENTER]asla ciddiye almamalisin. En onemli sey sadece[ENTER]kendin olmak. Bu kurala uyarsan her sey yoluna[ENTER]girer. Yine de gelecegini ogrenmek istiyorsan,[ENTER]yarin gel. "
gameforge.fortune_telling._40_sayTitle = "Yasli Kadin "
gameforge.fortune_telling._50_say = "Sana daha once soyledigim gibi, bugun icin[ENTER]kehanetin soyle: "
gameforge.fortune_telling._60_say = "Mutsuz olacaksin ve henuz kotuluge karsi[ENTER]Muskani satin almadin... Boyle bir Muska[ENTER]satin almak istemez miydin? "
gameforge.fortune_telling._70_select = "Evet, satin aliyorum. "
gameforge.fortune_telling._80_select = "Hayir, tesekkurler! "
gameforge.fortune_telling._90_say = "Dostane olabilirim ama bunu bedava dagitamam.[ENTER]Kotu kaderden ve talihsizlikten kacinmak[ENTER]istiyorsan, Muska icin odeme yapmalisin. "
