gameforge.ghost_story = {}
gameforge.ghost_story._010_sayTitle = "Sura Ruhu: "
gameforge.ghost_story._020_npcChat = "Sen bir ruh musun? "
gameforge.ghost_story._030_say = "Hayir, ben senin buyukannenim... Tabii ki[ENTER]bir ruhum! Hus agaci kadar uzun, keci kadar aptal! "
gameforge.ghost_story._040_npcChat = "Imdat! Ruh! "
gameforge.ghost_story._050_say = "Bak sen su korkusuz savasciya! Eh!! "
gameforge.ghost_story._060_npcChat = "Sen kimsin? "
gameforge.ghost_story._070_say = "Adim Akuma. Bir zamanlar buyuk bir savasciydim,[ENTER]hatta en iyisi oldugum soylenirdi.[ENTER]Ozel biri olduguma inanirdim! Ama simdi[ENTER]magarayi bulduktan sonra bana ne kaldigina bak...[ENTER]ve oldum. "
gameforge.ghost_story._080_npcChat = "Bu yerin tarihini biliyor musun? "
gameforge.ghost_story._090_say = "Oh evet, o zaman tam olarak ne oldugunu[ENTER]biliyorum. Daha yasarken nedenlerini kesfetmek[ENTER]ve magarayi bulmak icin uzun arastirmalar yaptim.[ENTER]Oldukten sonra da bunu dusunmek icin cok[ENTER]zamanim oldu. Soyle bana, ilgini ceken ne! "
gameforge.ghost_story._100_npcChat = "Bu portal ne? "
gameforge.ghost_story._110_say = "Bu portal, dusmus tanri Beran-Setaou'nun karanlik[ENTER]ejderha magarasina gider. Sadece Beran-Setaou[ENTER]birliklerinin liderlerinin aldigi buyulu bir[ENTER]anahtarla etkinlestirilebilir... "
gameforge.ghost_story._120_npcChat = "Üc Tanri "
gameforge.ghost_story._130_say = "Bir zamanlar tanrisal kardesler varligin diregini[ENTER]olusturuyordu. Yaratilis Tanricasi Bahar-Taraji,[ENTER]uc kardesin en gencuydu. Gorevi hayat yaratmakti -[ENTER]nereye gitse cicekler filizlenir ve bereketli[ENTER]hayat gelisirdi. "
gameforge.ghost_story._140_say = "En buyuk kardesin adi Beran-Setaou idi. Sonlanma[ENTER]ve cozulmeden sorumluydu. Yasam dongusu sona[ENTER]yaklastiginda, bedeni ruhtan ayirir ve onu[ENTER]oteki dunyaya yonlendirirdi.[ENTER]Boylece hayat kendi ritminde - dogum ve[ENTER]gecis - akip giderdi, ve tum varliklarin yasaminin[ENTER]temelleri korunurdu. "
gameforge.ghost_story._150_say = "Kardeslerin ikincisi Koruma ve Denge Tanrisi[ENTER]Baljit-Elvedin, kardesleri arasinda arabuluculuk[ENTER]yapardi ve dunyevi varliklara kesintisiz bir[ENTER]hayat dongusu saglardi. Gorevleri arasinda[ENTER]ornegin mevsimlerin gecisini gozetmek vardi. "
gameforge.ghost_story._160_npcChat = "Kavga "
gameforge.ghost_story._170_say = "Insanlar Tanrilara ictenlikle dua eder ve yardim[ENTER]dilerdi. Ama herkese gereken saygiyi gostermezlerdi.[ENTER]Beran-Setaou'yu dusunmek bile onlari korkuya[ENTER]sevk ederdi. Onun, uygun yasam dongusunu korumak[ENTER]icin gerekli bir unsur oldugunu anlayamiyorlardi.[ENTER]Isik ve golge gibi, dogum ve olum de[ENTER]var olmaliydi. "
gameforge.ghost_story._180_say = "Tanri uzun sure bunu insanlara affetti, ama[ENTER]zamanla Beran-Setaou'da buyuyen kiskanclik,[ENTER]kotuluge ve nefrete donustu. Sonunda hastalik[ENTER]ve kanli savaslar belasi gonderdi. Ancak olumcul[ENTER]korkuya kapilan insanlar ofkeli Beran-Setaou'dan[ENTER]tamamen yuz cevirdi ve yeni hayatin tanricasi[ENTER]Bahar-Taraji'den yardim aradi. Boylece, yikima[ENTER]goturen bir kisir dongu olustu. "
gameforge.ghost_story._190_say = "Sonunda tanrinin ofkesi o kadar guclendi ki,[ENTER]Beran-Setaou insanlarin gozdesi olan kiz kardesini[ENTER]oldurdu. Bunun icin bir plana ihtiyaci yoktu.[ENTER]Iyi kalpli kiz kardesi hicbir seyden suphelenmedi,[ENTER]guvenle Beran-Setaou ile bulustu, o ise[ENTER]kiskanclikla kor olmus, kiz kardesinin masum ve[ENTER]sevgi dolu gozlerine bakarken olumcul darbeyi[ENTER]indirdi. "
gameforge.ghost_story._200_npcChat = "Sonuclar "
gameforge.ghost_story._210_say = "Tanricanin olumu hem tanrilar hem de insanlar[ENTER]dunyasinda korkunc sonuclar dogurdu.[ENTER]Uzun ve acimasiz bir kis geldi, karada ve suda[ENTER]bircok canlinin hayatini aldi. Toprak o kadar[ENTER]donmustu ki, kayalar gurultuyle catladi ve dev[ENTER]yasli agaclar bile donun gucune dayanamadi. "
gameforge.ghost_story._220_say = "Sonunda gunesin ilk isinlari topragi isitmaya[ENTER]basladiginda, yeni doganlarin sayisi hic olmadigi[ENTER]kadar dusuktu. Kuraklasan toprak, acliktan ve[ENTER]soguktan tukenmis halki beslemeye yetecek kadar[ENTER]urun vermedi. Insanlar tum umutlarini kaybetti ve[ENTER]guclerini ve guvenlerini yeniden kazanmalari uzun[ENTER]zaman aldi. "
gameforge.ghost_story._230_say = "Tanrilar da aci cekti, gerci zaman onlar icin[ENTER]insanlardan daha yavas geciyordu. Beran-Setaou[ENTER]yaptigini anladiginda yalnizlik aradi.[ENTER]Kalbinde derin pismanlik ve tatmin duygulari[ENTER]ic ice gecti - sonunda ikincisi agir basti.[ENTER]Kalbi dondu ve Cozulme Tanrisi'ndan, Buz ve[ENTER]Soguk, Nefret ve Korku Tanrisi dogdu. "
gameforge.ghost_story._240_npcChat = "Savas "
gameforge.ghost_story._250_say = "Koruma Tanrisi Baljit-Elvedin, sevgili kiz[ENTER]kardesinin olumune uzun sure yas tuttu.[ENTER]Sonunda acinin demir penceleri gevsediginde,[ENTER]kardesini aramaya cikti. Hayat yolu hala[ENTER]sagduyu ve bilgelikle isaretliydi ve kiz[ENTER]kardesini kaybetmenin acisina ragmen, kaos ve[ENTER]dengesizligin hukum surdugu bir dunyada hayatin[ENTER]hicbir sansi olmadigini anladi. "
gameforge.ghost_story._260_say = "Kardesinin izini surdu, sonunda yillar suren[ENTER]aramadan sonra onu nefret ve yalnizlikla dolu,[ENTER]tum canli varliklardan uzak bir buz magarasinda[ENTER]buldu. Baljit-Elvedin yapmasi gerekeni yapti,[ENTER]gerci kalbi yine pismanlikla kanayarak kardesini[ENTER]duelloya davet etti. Beran-Setaou icin artik[ENTER]hicbir sey onemli degildi ve bir saniye[ENTER]bile tereddut etmeden meydan okumayi kabul etti... "
gameforge.ghost_story._270_say = "Boylesine acimasiz ve siddetli bir savasin[ENTER]hayal bile edilemeyecegi soylenir.[ENTER]Baljit-Elvedin kazandi. Ilkelerine sadik kalarak[ENTER]kardesini oldurmedi, ancak gucunu aldi ve onu[ENTER]bu magaraya hapsetti. O zamandan beri[ENTER]Beran-Setaou burada, yuzyillar boyunca yarattigi[ENTER]yaratiklariyla birlikte yasiyor... "
gameforge.ghost_story._280_npcChat = "Yeterince duydum. "
gameforge.ghost_story._290_say = "Kader senden yana olsun. Bol sans! "
gameforge.ghost_story._300_sayTitle = "Savasci Ruhu: "
gameforge.ghost_story._310_npcChat = "Neden seffafsin? "
gameforge.ghost_story._320_say = "Ne dusunmustun ki? Bin yildir bir kayaya[ENTER]hapsolmus bir ruhum... "
gameforge.ghost_story._330_say = "Imdat! Ruh! "
gameforge.ghost_story._340_say = "Haklisin, ruh. Kac, yoksa seni yerim! "
gameforge.ghost_story._350_npcChat = "Sen kimsin? "
gameforge.ghost_story._360_say = "Bir zamanlar bir parali askerdim, siradan bir[ENTER]adam. Ailemin kucuk bir ciftligi vardi. Ama[ENTER]hayatim boyunca tarla surmek istemedim, bu[ENTER]yuzden orduya katildim. Zordu ama guzel[ENTER]zamanlardi. Ama bir sure sonra degersiz[ENTER]asillerin bana emir vermesinden biktim ve[ENTER]firar ettim. Bu karanlik yerde bulmam sadece[ENTER]bir tesaduf. "
gameforge.ghost_story._370_npcChat = "Magaranin tarihini biliyor musun? "
gameforge.ghost_story._380_say = "Hayir, hicbir sey bilmiyorum, sadece sansim[ENTER]kotuydu. Firar ettikten sonra, daglarda siginak[ENTER]aradim ve bu magarayi buldum. Bastan beri[ENTER]bana supheli gorunuyordu, ama konumu elverisliydi[ENTER]ve tamamen terk edilmisti. Birkac gun sonra[ENTER]inanilmaz bir savasa hem tanik hem de kurban[ENTER]oldum. Istersen sana anlatayim. "
gameforge.ghost_story._390_npcChat = "Savasin Baslangici "
gameforge.ghost_story._400_say = "Bir gun - yamacta kok topluyordum - uyari[ENTER]vermeden gokten gumus bir ejderha dustu. Sonum[ENTER]geldi sandim, ama garip bir sekilde bana bile[ENTER]bakmadi - gozlerini magaraya dikti. Hiz bile[ENTER]kesmedi, dogrudan vadiye yoneldi ve magaraya[ENTER]daldi. "
gameforge.ghost_story._410_say = "Bir sure tam bir sessizlik oldu. Ne yapacagimi[ENTER]bilmiyordum. Tum esyalarim magaradaydi, ama[ENTER]ejderha ile goz goze gelmek istemiyordum! Aniden[ENTER]yer sarsildi ve magaranin derinliklerinden boguk[ENTER]bir kukreme duydum - ama garip bir sekilde, bu[ENTER]bir degil iki sesti! Kisa sure sonra magaradan[ENTER]yildirim gibi iki ejderha firladi, once gumus,[ENTER]hemen arkasindan mavi. "
gameforge.ghost_story._420_say = "Ejderhalar arasinda kelimelerle tarif edilmesi[ENTER]zor, acimasiz bir savas basladi. Penceleriyle[ENTER]birbirlerinin kanatlarini yirttilar, birbirlerine[ENTER]kenetlendiler, kocaman dislerini rakiplerinin[ENTER]boynuna gecirdiler... Kan her yone akiyordu...[ENTER]Ancak hicbir ejderha bir an bile geri adim[ENTER]atmadi. "
gameforge.ghost_story._430_npcChat = "Savasin Sonu "
gameforge.ghost_story._440_say = "Iki ejderha dev bir yildirim firtinasi gibi[ENTER]daglarin uzerinden gecti ve dag zirvelerini[ENTER]vadilerle esitledi. Atesli yildirimlar gumus[ENTER]ejderhanin yuzunu yakti, buz dolu ise mavi olanin[ENTER]kanatlarini tamamen yok etti. Yuzyillardir[ENTER]topragi kaplayan kalin buz zirhi, goz acip[ENTER]kapayana kadar eriyip pis kokulu camura donustu.[ENTER]Dehsetten donakalmis halde, kayanin arkasina[ENTER]saklanmayi basardim ama artik gozlerimi[ENTER]ceviremiyordum. "
gameforge.ghost_story._450_say = "Ancak birkac saatlik savastan sonra gucleri[ENTER]yavasca tukenmeye basladi. Bu tek sansi[ENTER]degerlendirmeliydim, kayalarin arkasindan firladim[ENTER]ve var gucumle vadiye dogru kostum, magaradan[ENTER]esyalarimi almak icin. Bu, kaderimi muhurledi.[ENTER]Geri donus yolundaydim ki, iki ejderha ok gibi[ENTER]daglardan yuvarlandi, onde korkunc yarali mavi[ENTER]olan vardi. "
gameforge.ghost_story._460_say = "Magarada kaybolmasindan kisa sure once, gumus[ENTER]ejderha ona yetisti ve cok garip bir sey oldu:[ENTER]Havada parlayan bir sey belirdi, bu bir hava[ENTER]akimina, sonra bir enerji topuna donustu, icinde[ENTER]aci ve ofkeyle uluyan mavi ejderha hapsolmustu...[ENTER]Yavasca kuculdu, ulumalari zayifladi, pullari[ENTER]parlakligini kaybetti, matlasti ve[ENTER]renksizlesti... "
gameforge.ghost_story._470_say = "Sonunda mavi ejderha son gucuyle karanlik[ENTER]magaraya suruklendi ve derinliklerinde kayboldu.[ENTER]Gumus ejderha, magaranin girisini bir enerji[ENTER]bariyeriyle muhurleyen ve dagin bir kismini[ENTER]cokturen guclu, buyulu bir kasirga serbest[ENTER]birakti. Ben ve karanlik ejderha hapsolmustuk.[ENTER]Yavas ve aci verici bir aclik olumune mahkum[ENTER]edildik... "
gameforge.ghost_story._480_npcChat = "Yeterince duydum. "
gameforge.ghost_story._490_say = "Dinledigin icin tesekkurler. Son bin yildir[ENTER]kendimi yalniz hissettim.... "
