gameforge.locale.monster_chat_1003_2 = "Mizrak kilictan daha kotu, ha? "
gameforge.locale.monster_chat_1003_3 = "Hey, gitme! Hadi! "
gameforge.locale.monster_chat_1003_4 = "Sadece bakmak bile agzimin suyunu akitiyor... "
gameforge.locale.monster_chat_1003_5 = "Beni kiskirtiyorsun! "
gameforge.locale.monster_chat_1003_6 = "Oleceksiiin! "
gameforge.locale.monster_chat_1004_1 = "Oldur! Oldur! Olduuuuuur! "
gameforge.locale.monster_chat_1004_2 = "Fena degil deneme. "
gameforge.locale.monster_chat_1004_3 = "Eglence basliyor gibi hissediyorum! "
gameforge.locale.monster_chat_1004_4 = "Henuz olmaz! Bu kadar cabuk olme! Hehehe. "
gameforge.locale.monster_chat_1004_5 = "Ne oldu? Ellerin titriyor! "
gameforge.locale.monster_chat_1004_6 = "Bizi ziyaret etmekten korkmuyor musun? Merak etme! "
gameforge.locale.monster_chat_1035_1 = "Olmeden once intikamimi alacagim! "
gameforge.locale.monster_chat_1035_2 = "Evet, yavas oyna... "
gameforge.locale.monster_chat_1035_3 = "Sen bizim sevincimizsin... "
gameforge.locale.monster_chat_1035_4 = "Vucudun korkudan titriyor. (gulus) "
gameforge.locale.monster_chat_1035_5 = "Korku mu, ha? (gulus) "
gameforge.locale.monster_chat_1035_6 = "Huh, gorunuse gore birkac kafa yere dusecek. Bu bitti mi? "
gameforge.locale.monster_chat_1036_1 = "Kiminle geziyorsun sen boyle?! "
gameforge.locale.monster_chat_1036_2 = "Kopekler! Sizi cildirtacagim! "
gameforge.locale.monster_chat_1036_3 = "(Gulus) "
gameforge.locale.monster_chat_1036_4 = "Ruhunu vererek hayatin icin yalvar! "
gameforge.locale.monster_chat_1036_5 = {}
gameforge.locale.monster_chat_1036_6 = "Sagini solunu ayirt edemiyorsun! (gulus) "
gameforge.locale.monster_chat_1037_1 = "Neden surekli boyle geziniyorsun? "
gameforge.locale.monster_chat_1037_2 = "Ne oldu? Karanligi sevmiyor musun? "
gameforge.locale.monster_chat_1037_3 = "Cehenneme hos geldin (gulus) "
gameforge.locale.monster_chat_1037_4 = "Elbette, elbette! Bagirmaya devam et! "
gameforge.locale.monster_chat_1037_5 = "Bununla beni olduremezsin! (gulus) "
gameforge.locale.monster_chat_1037_6 = "Evet, simdi daha iyi! "
gameforge.locale.monster_chat_1038_1 = "Bu cehennem. "
gameforge.locale.monster_chat_1038_2 = "Cehenneme hos geldin. "
gameforge.locale.monster_chat_1038_3 = "Lutfen, bu kadar cabuk olme... "
gameforge.locale.monster_chat_1038_4 = "Bana saldirmak anlamsiz! (gulus) "
gameforge.locale.monster_chat_1038_5 = {}
gameforge.locale.monster_chat_1038_6 = "Cok cabuk olme, seninle oynamak istiyoruz... "
gameforge.locale.monster_chat_1039_1 = "Yeni biri gelene kadar... "
gameforge.locale.monster_chat_1039_2 = "Gercekten kacabilecegini mi dusunuyorsun? "
gameforge.locale.monster_chat_1039_3 = "Burada her sey insanlarda korku uyandiriyor... "
gameforge.locale.monster_chat_1039_4 = "Evimize hos geldin! (gulus) "
gameforge.locale.monster_chat_1039_5 = "Goruyor musun? Bunu kacirdin... "
gameforge.locale.monster_chat_1039_6 = "Hmm... cok taze... "
gameforge.locale.monster_chat_1040_1 = "Tum hareketlerini goruyoruz. "
gameforge.locale.monster_chat_1040_2 = "Sakin ol... "
gameforge.locale.monster_chat_1040_3 = "Birine dokunursan olursun. (gulus) "
gameforge.locale.monster_chat_1040_4 = "Zilimin caldigini duyuyor musun? Duyacagin son sey bu olacak! "
gameforge.locale.monster_chat_1040_5 = "Kanamayi durdurmazsan, tehlikeli olabilir... "
gameforge.locale.monster_chat_1040_6 = "Evet! Savas, savas! (gulus) "
gameforge.locale.monster_chat_1041_1 = "(gulus)(gulus)(gulus) "
gameforge.locale.monster_chat_1041_2 = "Yeni bedenler geldi... "
gameforge.locale.monster_chat_1041_3 = "Evet, yeni bedenler edinmek icin iyi bir zaman... "
gameforge.locale.monster_chat_1041_4 = "Hayatta kalacagiz! Biz asla olmeyiz! "
gameforge.locale.monster_chat_1041_5 = "Bize saldirmak anlamsiz! (gulus) "
gameforge.locale.monster_chat_1041_6 = "Seni buraya getiren ne? Olmek mi istiyorsun? "
gameforge.locale.monster_chat_1091_1 = "Benden daha iyi ucup saldirabilen kim var? "
gameforge.locale.monster_chat_1091_2 = "Benim gibi olabilirsin. "
gameforge.locale.monster_chat_1091_3 = "Benim gibi olmak istemiyor musun? "
gameforge.locale.monster_chat_1091_4 = "Bedenin ve ruhun bana ait! (gulus) "
gameforge.locale.monster_chat_1091_5 = "Tukendin mi? Bacaklarin titriyor... "
gameforge.locale.monster_chat_1091_6 = "Ne kadar dayanacaksin? (gulus) "
gameforge.locale.monster_chat_1093_1 = "Olumden daha kotu bir sey var mi? "
gameforge.locale.monster_chat_1093_2 = "Hos geldin, olume susamis! "
gameforge.locale.monster_chat_1093_3 = "Dua et... "
gameforge.locale.monster_chat_1093_4 = "Bedenini ve ruhunu yiyecegim! "
gameforge.locale.monster_chat_1093_5 = "Ne kadar dayanacaksin? Ha? "
gameforge.locale.monster_chat_1093_6 = "Olum arkanda guluyor. (gulus) "
gameforge.locale.monster_chat_11000_1 = "Karakter gelisimini onemseyen herkes, dinleyin! "
gameforge.locale.monster_chat_11000_10 = "Doganin ve yildirimin gucunu kontrol etmek istiyorsan, Iyilestirmeyi sec. "
gameforge.locale.monster_chat_11000_11 = "Her savasci kendi tarzinda farklidir! Bedeni gelistirmeye odaklan! "
gameforge.locale.monster_chat_11000_12 = "Guclu bir Sura olarak, Zeka, hiz ve beden gucunu gelistirmelisin! "
gameforge.locale.monster_chat_11000_13 = "Ninja becerilerini kullan! Hiz ve beden gucune odaklan! "
gameforge.locale.monster_chat_11000_14 = "Samanlar iyilestirebilir, siklikla yardimci rolundedirler. Gucleri zekadir! "
gameforge.locale.monster_chat_11000_15 = "Antrenmani unutma! "
gameforge.locale.monster_chat_11000_16 = "Becerilerini guclendirmek istiyorsan antrenman yap! "
gameforge.locale.monster_chat_11000_17 = "M seviyesi, becerilere 17 ile 20 arasi puan eklendiginde aktiflesir! "
gameforge.locale.monster_chat_11000_18 = "Buyuk Usta olmak mi istiyorsun? O halde ozel bir Beceri Kitabina ihtiyacin var! "
gameforge.locale.monster_chat_11000_19 = "Okunduktan sonra Beceri Kitabi kaybolur! "
gameforge.locale.monster_chat_11000_2 = "5. seviyenin altindaki savascilar, dinleyin! "
gameforge.locale.monster_chat_11000_20 = "Baska bir Beceri Kitabi okumak mi istiyorsun? Bir gun beklemelisin! "
gameforge.locale.monster_chat_11000_21 = "Sura Becerilerini gelistirmek icin Zeka degerini artir. "
gameforge.locale.monster_chat_11000_22 = "Savasta Sura'nin muhtesem gucunu gor! "
gameforge.locale.monster_chat_11000_23 = "Karanlik Ezoterikler Tapinagi'nin nerede oldugunu biliyor musun? Seungryong Vadisi'nin ortasinda! "
gameforge.locale.monster_chat_11000_24 = "Orumcek Zindani'ni mi ariyorsun! Onu Col'de bulacaksin! "
gameforge.locale.monster_chat_11000_25 = "Gorevleri tamamla ve odulleri gelistirmelere harca! "
gameforge.locale.monster_chat_11000_26 = "Balik tutmak mi? Kulaga harika geliyor! Balikcidan Olta ve yem aldin mi? "
gameforge.locale.monster_chat_11000_27 = "Daha iyi bir sey avlamak mi istiyorsun? Portala dogru git! Seviyene uygun bir avlanma yeri bul! "
gameforge.locale.monster_chat_11000_28 = "Diger Kralliklardan dusmanlara dikkat et. Ne zaman arkanda belireceklerini asla bilemezsin! "
gameforge.locale.monster_chat_11000_29 = "Becerilerini sifirlamak mi istiyorsun? Yasli Kadina git. Yaninda yeterli Yang goturmeyi unutma! "
gameforge.locale.monster_chat_11000_3 = "Guclu olmak istiyorsan, Kilic Gucu Egitmenine git! "
gameforge.locale.monster_chat_11000_30 = "Buyuk bir usta ol! Sadece boyle tarih sayfalarina adini yazdirabilirsin! "
gameforge.locale.monster_chat_11000_31 = "Baska bir bolgeye gecmek istiyorsan, Yasli Adamla konus! "
gameforge.locale.monster_chat_11000_4 = "Gercek bir savasci olmak istiyorsan, Ruh Gucunu denemelisin. "
gameforge.locale.monster_chat_11000_5 = "Buyulu Kilic kullanabilen bir Sura olmak istiyorsan, Silah Gucu Egitmenini sec! "
gameforge.locale.monster_chat_11000_6 = "Kara buyu alaninda egitim almak istiyorsan, Kara Buyu Egitmenini sec! "
gameforge.locale.monster_chat_11000_7 = "Yay Gucu Egitimi, Ninja'nin 5. seviyeye ulastiktan sonra izleyebilecegi bir yoldur! "
gameforge.locale.monster_chat_11000_8 = "Saklanma yetenegine sahip olmak istiyorsan, Yakin Dovusu sec! "
gameforge.locale.monster_chat_11000_9 = "Ejderha gucune sahip biri olmak istiyorsan, Ejderha Tanrisi yolunu sec! "
