gameforge.locale.monster_chat_1105_1 = "Kis harika. "
gameforge.locale.monster_chat_1105_2 = "Sohan Dagi en iyisi. "
gameforge.locale.monster_chat_1105_3 = "Ne guzel bir hava. "
gameforge.locale.monster_chat_1105_4 = "Benim gibi olacaksin. "
gameforge.locale.monster_chat_1105_5 = "Sonsuza dek yasayabilirsin... en azindan iklim isinana kadar... "
gameforge.locale.monster_chat_1105_6 = "Sence sonunda donman icin ne kadar zaman gecmeli? "
gameforge.locale.monster_chat_1106_1 = "Insanlar... burada mi?! "
gameforge.locale.monster_chat_1106_2 = "Cok yorgunum... ama yine de seni yenecegim! "
gameforge.locale.monster_chat_1106_3 = "Beni duyan var mi? "
gameforge.locale.monster_chat_1106_4 = "Burali degilsin! "
gameforge.locale.monster_chat_1106_5 = "Geri cekilsen iyi olur! "
gameforge.locale.monster_chat_1106_6 = "Yabanci... bu kadar yalniz mi? "
gameforge.locale.monster_chat_1191_1 = "Bakalim, belki yakisikli biri cikagelir. "
gameforge.locale.monster_chat_1191_2 = "Cok usuyorum ve uzgunum. Nerede benim mustakbel kocam? "
gameforge.locale.monster_chat_1191_3 = "Onun uzerinde calismali miyim? "
gameforge.locale.monster_chat_1191_4 = {}
gameforge.locale.monster_chat_1191_5 = "Bir sey eksik, mutlu degilim... "
gameforge.locale.monster_chat_1191_6 = "Hayatini alacagim! "
gameforge.locale.monster_chat_1301_1 = "Bu bir insan...! "
gameforge.locale.monster_chat_1301_2 = "Simdi yuzunu daha da soldurayim! "
gameforge.locale.monster_chat_1301_3 = "Beni duelloya mi davet ediyorsun? Kabul ediyorum! "
gameforge.locale.monster_chat_1301_4 = "Bana saldirdin! Iyk! Bunu sana bagislamayacagim! "
gameforge.locale.monster_chat_1301_5 = "Zayif, zayif insan! "
gameforge.locale.monster_chat_1301_6 = "Bakalim ne kadar dayanabilecksin! "
gameforge.locale.monster_chat_1302_1 = "Kacmak mi? Bunu dusunme bile! "
gameforge.locale.monster_chat_1302_2 = "Evet... daha yaklas... IYK! "
gameforge.locale.monster_chat_1302_3 = "Kilic elimde titriyor. Iyk!! "
gameforge.locale.monster_chat_1302_4 = "Bu savastan sag cikamayacaksin! "
gameforge.locale.monster_chat_1302_5 = "Kilicim geliyor! "
gameforge.locale.monster_chat_1302_6 = "Aci verici, degil mi? (gulus) "
gameforge.locale.monster_chat_1303_1 = "Tehlike otlarin icinde bile pusuda olabilir! "
gameforge.locale.monster_chat_1303_2 = "Otlara dikkat et! "
gameforge.locale.monster_chat_1303_3 = "Tamam. Bana gel. (gulus) "
gameforge.locale.monster_chat_1303_4 = "Bana nasil yaklasirsin?! Sonuclarina katlanmalisin! "
gameforge.locale.monster_chat_1303_5 = "Ol! Ol! "
gameforge.locale.monster_chat_1303_6 = "Buraya geldigine pisman misin? "
gameforge.locale.monster_chat_1305_1 = "Beni kim yenecek? "
gameforge.locale.monster_chat_1305_2 = "Sen mi?! Savasmak mi istiyorsun? "
gameforge.locale.monster_chat_1305_3 = "Savasmak istiyorsan buraya gel! "
gameforge.locale.monster_chat_1305_4 = "Kacmayi dusunmuyorsun, degil mi? "
gameforge.locale.monster_chat_1305_5 = "Kilicimin gucunu kucumsuyorsun. "
gameforge.locale.monster_chat_1305_6 = "Korkuyor musun? (gulus) "
gameforge.locale.monster_chat_1901_1 = "Bugun ellerimde olecegini dusunuyorum. "
gameforge.locale.monster_chat_1901_2 = "Oh, senden hoslaniyorum... "
gameforge.locale.monster_chat_1901_3 = "Peki ne olacak? Sevgili yemegim... "
gameforge.locale.monster_chat_1901_4 = "Hey! Siradan bir korkak gibi kacmak sana yardimci olmaz. "
gameforge.locale.monster_chat_1901_5 = "Zaten buyumun etkisi altinda misin? Hmm? "
gameforge.locale.monster_chat_1901_6 = "Biraz ciglik atmak istemez misin? (gulus) "
gameforge.locale.monster_chat_20001_1 = "Sanirim biraz gerginsin... korkma, bir sey patlamamali. "
gameforge.locale.monster_chat_20001_2 = "Bazen her seyden bikiyorum... "
gameforge.locale.monster_chat_20001_3 = "Cok sikici. Torunlarim artik beni ziyaret bile etmiyor. "
gameforge.locale.monster_chat_20001_4 = "Yaslandikca, arkadasliga ihtiyacin olur. "
gameforge.locale.monster_chat_20001_5 = "En iyi gunlerim coktan gecti. "
gameforge.locale.monster_chat_20002_1 = "Gunes cok sicak... "
gameforge.locale.monster_chat_20002_2 = "Mukemmel hava! Camasir yikamaliyim. "
gameforge.locale.monster_chat_20002_3 = "Nerede o tembel kocam?! "
gameforge.locale.monster_chat_20002_4 = "Kendine baba diyor... ve uzun zamandir cocuklariyla hic iletisimi yok! "
gameforge.locale.monster_chat_20002_5 = "Hic para kazanmiyor. Sadece kitap okuyor... "
gameforge.locale.monster_chat_20003_1 = "Oooh, ninni, bebegim. Iyi uyudun mu? "
gameforge.locale.monster_chat_20003_2 = "Kucuk bir melek gibi kokuyorsun. "
gameforge.locale.monster_chat_20003_3 = "Annen saglikli oldugun icin cok mutlu. "
gameforge.locale.monster_chat_20003_4 = "Ilgi mi cekmek istiyorsun? Yoksa ac mi? "
gameforge.locale.monster_chat_20003_5 = "Iyi bebek... uyu canim, uyu. "
gameforge.locale.monster_chat_20004_1 = "Bir sikici gun daha... "
gameforge.locale.monster_chat_20004_2 = "Bugun nereden yemek bulacagim? "
gameforge.locale.monster_chat_20004_3 = "Rakipler artik beni sikiyor... "
gameforge.locale.monster_chat_20004_4 = "Bakalim. Belki Octavios'un mekanina ugramaliyim? "
gameforge.locale.monster_chat_20004_5 = "Oh, bu arada, gorunuse gore artik savas olmayacak. "
gameforge.locale.monster_chat_20005_1 = "Comlek Ustasinin ruhu parmak uclarindan akiyor. "
gameforge.locale.monster_chat_20005_2 = "Ülke kaosa suruklendiginden beri, her yerde kotuluk hukum suruyor. "
gameforge.locale.monster_chat_20005_3 = "Herkes savasmak istiyor. "
gameforge.locale.monster_chat_20005_4 = "Sakin ve savassiz bir ulke icin dua ediyorum. "
gameforge.locale.monster_chat_20005_5 = "Hey, bence biraz dinlenmelisin. "
gameforge.locale.monster_chat_20006_1 = "Oh, simdi ne yapmaliyim? "
gameforge.locale.monster_chat_20006_2 = "Hala kardesimi ariyorum. Hem de her zaman yanimda olacagina soz vermisti! "
gameforge.locale.monster_chat_20006_3 = "Simdi sadece kilicli savascilar goruyorum. "
gameforge.locale.monster_chat_20006_4 = "Kardesimi ozluyorum. "
gameforge.locale.monster_chat_20006_5 = "Kardesimi goren oldu mu? "
gameforge.locale.monster_chat_20007_1 = "Hmm, bu gercekten taze et! "
gameforge.locale.monster_chat_20007_2 = "Insanlarin daha fazla et yemeye baslamasi iyi. "
gameforge.locale.monster_chat_20007_3 = "Is iyi gidiyor ama et bulmak hala zor. "
gameforge.locale.monster_chat_20007_4 = "Siparis ettigimiz ete ne oldu? "
gameforge.locale.monster_chat_20007_5 = "Zamaninda gelmezse, ava cikmak zorunda kalacagiz. "
gameforge.locale.monster_chat_20008_1 = "Umarim bugun cok musterim olur. Hava cok guzel. "
gameforge.locale.monster_chat_20008_2 = "O tembel kopek yakinda gelip bir sey yemek isteyecek. "
gameforge.locale.monster_chat_20008_3 = "Oh, ne zavalli! "
gameforge.locale.monster_chat_20008_4 = "Bir zamanlar gercekten buyuk bir savasciydi. "
gameforge.locale.monster_chat_20008_5 = "Neden artik savasmiyor merak ediyorum. "
gameforge.locale.monster_chat_20009_1 = "Eh, su genc adamlar... cok canli ve hevesliler! "
gameforge.locale.monster_chat_20009_2 = "Bir savasci silahini tasirken cok daha iyi gorunuyor. "
gameforge.locale.monster_chat_20009_3 = "Simdi herkesin boyle suc dolu bir akli var. "
gameforge.locale.monster_chat_20009_4 = "Kalbini terbiye et, zihnini odakla ve ruhunu sakinlestir. "
gameforge.locale.monster_chat_20009_5 = "Mutluluk icin guvenilir bir tarif yok. Ama surekli uyulmasi gereken birkac basit kural var. "
gameforge.locale.monster_chat_20010_1 = "Sana muhtesem bir esya getiriyorum. "
gameforge.locale.monster_chat_20010_2 = "Uzak diyarlardan mallar! Guzel, egzotik esyalar! "
gameforge.locale.monster_chat_20010_3 = "Yaklasin! Herkes buraya gelsin! "
gameforge.locale.monster_chat_20010_4 = "Gelin insanlar, satin alin! Boyle bir firsat bir daha cikmaz! "
gameforge.locale.monster_chat_20010_5 = "Etrafimda cok fazla hirsiz var. Servetimden uzak durmalilar! "
gameforge.locale.monster_chat_20011_1 = "Burada her sey kurudu... "
gameforge.locale.monster_chat_20011_2 = "Tahilin kalitesi eskisinden daha kotu. "
gameforge.locale.monster_chat_20011_3 = "Tahilin daha yavas buyumesine ne sebep oluyor? "
gameforge.locale.monster_chat_20011_4 = "Bu tahil kirilgan ve curuk tadi var. "
gameforge.locale.monster_chat_20011_5 = "Bu kotu bir isaret. Koyumuzde tarim temel tasimiz. "
gameforge.locale.monster_chat_20012_1 = "Pirinc Kekleri! Lezzetli Pirinc Kekleri! "
gameforge.locale.monster_chat_20012_2 = "Tatli Pirinc Kekleri satiyorum. "
gameforge.locale.monster_chat_20012_3 = "Dogru, isler pek iyi gitmiyor... "
gameforge.locale.monster_chat_20012_4 = "Belki baska bir sehirde denemeliyim? "
gameforge.locale.monster_chat_20012_5 = "Ama etrafimda o kadar cok vahsi yirtici var ki... "
gameforge.locale.monster_chat_20013_1 = "Boyle gunlerde teknede olmak en iyi fikir. "
gameforge.locale.monster_chat_20013_2 = "Balik tutmak icin harika bir hava! "
gameforge.locale.monster_chat_20013_3 = "Sadece bir dugum daha... tamam! Hicbir balik bu kancayi koparamaz! "
gameforge.locale.monster_chat_20013_4 = "O lanet ayi Oltami mahvetti! "
gameforge.locale.monster_chat_20013_5 = "Bu aglari bir daha yamamak iyi olurdu. "
gameforge.locale.monster_chat_20014_1 = "Huh! "
gameforge.locale.monster_chat_20014_2 = "Merak etme, ben boyleyim iste. "
gameforge.locale.monster_chat_20014_3 = "Haaaaa! "
gameforge.locale.monster_chat_20014_4 = "Ne yapmaliyim ki... Oh hayir, az once ne dedim? "
gameforge.locale.monster_chat_20014_5 = "Cesur degilim... "
gameforge.locale.monster_chat_20015_1 = "Bu balta 20 yildan fazladir bana hizmet ediyor. "
gameforge.locale.monster_chat_20015_2 = "Hala keskin ama belki eskisi kadar degil... "
gameforge.locale.monster_chat_20015_3 = "Onu kullanarak guclenmek istiyorum. "
gameforge.locale.monster_chat_20015_4 = "Ama minerallerle dolu fosillere ihtiyacim var. "
gameforge.locale.monster_chat_20015_5 = "Onlari nerede bulabilirim? "
gameforge.locale.monster_chat_20016_1 = "Musteriler akin akin geliyor. "
gameforge.locale.monster_chat_20016_2 = "Umarim her seyi zamaninda yetistiririm. "
gameforge.locale.monster_chat_20016_3 = "Celik celige, daha sert vur... "
gameforge.locale.monster_chat_20016_4 = "Cekic boyle calmali! "
gameforge.locale.monster_chat_20016_5 = "Burasi cok sicak. "
gameforge.locale.monster_chat_20017_1 = "Enstruman calma istegim yok. "
gameforge.locale.monster_chat_20017_2 = "Enstrumanim iyi durumda degil. "
gameforge.locale.monster_chat_20017_3 = "Belki yeni bir enstruman almaliyim? "
gameforge.locale.monster_chat_20017_4 = "Enstrumanim eski ve yipranmis... eski seyleri severim! "
gameforge.locale.monster_chat_20017_5 = "Kopan telleri degistirmek icin hemen yeni tel bulmaliyim. "
gameforge.locale.monster_chat_20018_1 = "Cok mesgulum! "
gameforge.locale.monster_chat_20018_2 = "Her gun bana yarali insanlar geliyor. "
gameforge.locale.monster_chat_20018_3 = "Hicbir yere gidecek vaktim bile yok! "
gameforge.locale.monster_chat_20018_4 = "Ilaclarimiz tukendi. "
gameforge.locale.monster_chat_20018_5 = "Keske biri bana ilac malzemeleri getirse... "
gameforge.locale.monster_chat_20019_1 = "30 yildir yayimla Daglara gidiyorum! "
gameforge.locale.monster_chat_20019_2 = "Sayesinde karima destek olup uc cocuk buyutebildim. "
gameforge.locale.monster_chat_20019_3 = "Hayat zor ama yine de yasamaya deger. "
gameforge.locale.monster_chat_20019_4 = "Simdi kiris koptu, avlanamiyorum... ailemi nasil doyuracagim?! "
gameforge.locale.monster_chat_20019_5 = "Yayimi tamir etmezsem, emekli olmak zorunda kalacagim... "
gameforge.locale.monster_chat_20020_1 = "Hey! Neye oyle bakiyorsun?! "
gameforge.locale.monster_chat_20020_2 = "Buradan git! "
gameforge.locale.monster_chat_20020_3 = "Oh, daha ne kadar saklanmam gerekecek? "
gameforge.locale.monster_chat_20020_4 = "Tamamen unutulmus, yalniz biri olarak mi olecegim? "
gameforge.locale.monster_chat_20020_5 = "Aaaaah, umarim biri bana yardim eder... "
gameforge.locale.monster_chat_20021_1 = "Bu gun digerleri gibi bitecek. "
gameforge.locale.monster_chat_20021_2 = "Simdi ne yapabilirim ki? "
gameforge.locale.monster_chat_20021_3 = "Boyle bitecegini hic dusunmemistim. "
gameforge.locale.monster_chat_20021_4 = "Hayir! Boyle biten tek kisi o olamaz! "
gameforge.locale.monster_chat_20021_5 = "Umarim biri onun intikamini alir! "
gameforge.locale.monster_chat_20022_1 = "Yine guzel bir gun! "
gameforge.locale.monster_chat_20022_2 = "Ariyoung'un kocasi kayboldu. "
gameforge.locale.monster_chat_20022_3 = "Yardim etmek istedim ama o inatcilik... "
gameforge.locale.monster_chat_20022_4 = "Benimle evlenseydi, cok daha iyi bir hayati olurdu. "
gameforge.locale.monster_chat_20022_5 = "Belki duygularimi daha iyi gostermeliyim... "
gameforge.locale.monster_chat_20023_1 = "Oh hayir! Karim bunu ogrenince ne yapacagim?! "
gameforge.locale.monster_chat_20023_2 = "Keske sadece kitap okuyarak gecinebilseydim... "
gameforge.locale.monster_chat_20023_3 = "Kitaplar cok gizemli. "
gameforge.locale.monster_chat_20023_4 = "Hep boyle yasayamam, ama... "
gameforge.locale.monster_chat_20023_5 = "Sanirim karim icin bir sey yapabilirim, ama... "
gameforge.locale.monster_chat_20024_1 = "Hadi bakalim! Hareketlerine daha fazla his kat! "
gameforge.locale.monster_chat_20024_2 = "Orada ne yapiyorsun?! Acele edemez misin? "
gameforge.locale.monster_chat_20024_3 = "Bir savascinin kilic kullanisini hayal et ve bu hareketi tekrarla! "
gameforge.locale.monster_chat_20024_4 = "Nerede o kilicli beceriksiz? "
gameforge.locale.monster_chat_20024_5 = "Bu bir kopek! Sen erkek degilsin, ha! "
gameforge.locale.monster_chat_2091_1 = "cirt, cirt... sac, boyun... "
gameforge.locale.monster_chat_2091_2 = "Senin icin bir seyim var: ebedi uyku! "
gameforge.locale.monster_chat_2091_3 = "Derin bir nefes al ve.... ver. Merak etme, sadece zehir! "
gameforge.locale.monster_chat_2091_4 = "Sadece yuzunu birakacagim! Sus olsun diye... "
gameforge.locale.monster_chat_2091_5 = {}
gameforge.locale.monster_chat_2091_6 = "Orumcek agina sarilmis halde sonraki atistirmaligim icin tam kivaminda olacaksin... "
gameforge.locale.monster_chat_2092_1 = "Karimin iniltilerine dayanamiyorum... "
gameforge.locale.monster_chat_2092_2 = "Neden uyuyamiyorum? "
gameforge.locale.monster_chat_2092_3 = "Oh, gorunuse gore biri orumcek agina dolanmis! "
gameforge.locale.monster_chat_2092_4 = "Genelde dostane biriyimdir. Ama kizdirilmaktan hoslanmam. "
gameforge.locale.monster_chat_2092_5 = "Evet, her seyi ver! "
gameforge.locale.monster_chat_2092_6 = "Burada bana denk kimse yok! "
gameforge.locale.monster_chat_2104_1 = "Eh, insanlarda neden bu kadar cok kan var? Boyle giderse kilicim tamamen paslanacak! "
gameforge.locale.monster_chat_2104_2 = "Ignendeki zehir coktan mi kurudu? "
gameforge.locale.monster_chat_2104_3 = "Savasalim mi? "
gameforge.locale.monster_chat_2104_4 = "Fazla sicak degil mi? "
gameforge.locale.monster_chat_2104_5 = "Insanlari colde birakmayi severim. "
gameforge.locale.monster_chat_2104_6 = "Zavalli, bu colde digerleri gibi yanacaksin. "
gameforge.locale.monster_chat_2105_1 = "Seninle bir sir paylasayim - mustehcenlikten nefret ederim. "
gameforge.locale.monster_chat_2105_2 = "Cok sicak, degil mi? "
gameforge.locale.monster_chat_2105_3 = "Burasi tehlikeli bir yer. "
gameforge.locale.monster_chat_2105_4 = {}
gameforge.locale.monster_chat_2105_5 = "Seni gozlerinin arasindan vuracagim! "
gameforge.locale.monster_chat_2106_1 = "Bugun bana bir sey verecek misin? (islik) "
gameforge.locale.monster_chat_2106_2 = "Oh evet! Av geliyor! (gulus) "
gameforge.locale.monster_chat_2106_3 = "Bunu severim! Bunu cok severim! (gulus) "
gameforge.locale.monster_chat_2106_4 = "Su adam guzelce sisman. O benim! "
gameforge.locale.monster_chat_2106_5 = {}
gameforge.locale.monster_chat_2106_6 = "Kan kokusunu severim. "
gameforge.locale.monster_chat_2107_1 = "Son zamanlarda burada yapacak pek bir sey yok. (islik) "
gameforge.locale.monster_chat_2107_2 = "Hey! Su gercekten sisman! "
gameforge.locale.monster_chat_2107_3 = "Bu komutanin hosuna gidecek... "
gameforge.locale.monster_chat_2107_4 = {}
gameforge.locale.monster_chat_2107_5 = "Hadi gidelim! "
gameforge.locale.monster_chat_2107_6 = "Ok geliyor! "
gameforge.locale.monster_chat_2108_1 = "Bunu alirsam... "
gameforge.locale.monster_chat_2108_2 = "Hey! Neden oyle bakiyorsun? "
gameforge.locale.monster_chat_2108_3 = "Beni yenmenin kolay oldugunu mu dusunuyorsun? "
gameforge.locale.monster_chat_2108_4 = "Colde beni rahatsiz edersen basin belaya girer! "
gameforge.locale.monster_chat_2108_5 = "Ah! Ne harika bir his! "
gameforge.locale.monster_chat_2108_6 = "Tesekkurler! "
gameforge.locale.monster_chat_2191_1 = "Bir insan hissediyorum - ahhh su koku! "
gameforge.locale.monster_chat_2191_2 = "Guzel. Bana gel, gel... "
gameforge.locale.monster_chat_2191_3 = {}
gameforge.locale.monster_chat_2191_4 = "Birini gormek guzel... colde... "
gameforge.locale.monster_chat_2191_5 = "Kimildama! Kkkk! "
gameforge.locale.monster_chat_2191_6 = "Bir insan hissediyorum - lezzetli bir insan! "
gameforge.locale.monster_chat_2202_1 = "Gercekten neden bu kadar sicak olmasi gerektigini bilmiyorum... "
gameforge.locale.monster_chat_2202_2 = "Uh, burada soguk bir sey olsaydi... "
gameforge.locale.monster_chat_2202_3 = "Belki onlarin kaninda serinleyebilirim? "
gameforge.locale.monster_chat_2202_4 = "Sicak! Sanirim kanlarinda serinleyecegim! "
gameforge.locale.monster_chat_2202_5 = "Kanini bana ver! "
gameforge.locale.monster_chat_2202_6 = "Benim gibi ol! "
gameforge.locale.monster_chat_2204_1 = "Ben burada oldugum surece kimse giremez! "
gameforge.locale.monster_chat_2204_2 = "Bir nedenden dolayi beni sinirlendirmeye basliyorsun. "
gameforge.locale.monster_chat_2204_3 = {}
gameforge.locale.monster_chat_2204_4 = "Huh, simdi nerede oldugunu biliyor musun? "
gameforge.locale.monster_chat_2204_5 = {}
gameforge.locale.monster_chat_2204_6 = "Bu kadar zayif mi?! (gulus) "
gameforge.locale.monster_chat_2205_1 = "Kilic ancak gercek bir savascinin elinde ise yarar. "
gameforge.locale.monster_chat_2205_2 = "Kilici elinde tut. "
gameforge.locale.monster_chat_2205_3 = "Savas yaklasiyor... "
gameforge.locale.monster_chat_2205_4 = "Simdi savasacagiz! Olene kadar! "
gameforge.locale.monster_chat_2205_5 = "Olume direnmeye devam mi edeceksin? "
gameforge.locale.monster_chat_2205_6 = "Evet, bu kadar genc olmemelisin. "
gameforge.locale.monster_chat_2206_1 = "Lavda yuzmek cok guzel. "
gameforge.locale.monster_chat_2206_2 = "Sicak lavda dinlenmeyi severim! "
gameforge.locale.monster_chat_2206_3 = "Lav artik eskisi kadar sicak degil... "
gameforge.locale.monster_chat_2206_4 = "Seni alcak, huzurumu bozuyorsun! "
gameforge.locale.monster_chat_2206_5 = "Beni rahatsiz etme. "
gameforge.locale.monster_chat_2206_6 = "Yaparsan, pisman olursun... "
gameforge.locale.monster_chat_2291_1 = "Guzel hava. Biraz uyumak iyi olurdu... "
gameforge.locale.monster_chat_2291_2 = "Hicbir sey Doyyumhwaji ile karsilastirilamaz. "
gameforge.locale.monster_chat_2291_3 = "Neden uyumuyorum? "
gameforge.locale.monster_chat_2291_4 = "Beni rahatsiz ettin... "
gameforge.locale.monster_chat_2291_5 = "Gorunuse gore hatani anladin. "
gameforge.locale.monster_chat_2291_6 = "Kacmak icin cok gec! Zaten sana bir faydasi olmaz! "
gameforge.locale.monster_chat_301_1 = "Sikici! Yapacak ilginc bir sey yok mu? "
gameforge.locale.monster_chat_301_2 = "Iki gun once, buraya cok yakisikli bir adam geldi! "
gameforge.locale.monster_chat_301_3 = "Kizlar, sonunda guzel saclar yapalim! "
gameforge.locale.monster_chat_301_4 = "Sorun degil! Hehe, guzel gorunmek her sey degil. "
gameforge.locale.monster_chat_301_5 = "Bu kilici mi istiyorsun? Saka yapmiyoruz. "
gameforge.locale.monster_chat_302_1 = "Hey! Iste gercek bir yakisikli! "
gameforge.locale.monster_chat_302_2 = "Biliyorsun, diyetteyim... "
gameforge.locale.monster_chat_302_3 = "Alisverise gitmek istiyorum. "
gameforge.locale.monster_chat_302_4 = "Bu benim okumdu! "
gameforge.locale.monster_chat_302_5 = "Goruyor musun? Kalbini hedef aliyorum! "
gameforge.locale.monster_chat_302_6 = "Oh! Alisverise gitmek istiyorum! "
gameforge.locale.monster_chat_303_1 = "Cocuklarimiz son zamanlarda cok tembel. "
gameforge.locale.monster_chat_303_2 = "Askerler saldirmaya karar verirse ne olacak?! "
gameforge.locale.monster_chat_303_3 = "Bana neden oyle bakiyorsun? "
gameforge.locale.monster_chat_303_4 = "Of! Ne korkak! "
gameforge.locale.monster_chat_303_5 = "Bunun kolay oldugunu sanma. "
gameforge.locale.monster_chat_303_6 = "Bu savas sanilandan daha zor olacak. "
gameforge.locale.monster_chat_304_1 = "Kadinlar, surekli erkeklere bagimli olamazsiniz! "
gameforge.locale.monster_chat_304_2 = "Iyi erkek yok! "
gameforge.locale.monster_chat_304_3 = "Sinirimi bozuyorsun. "
gameforge.locale.monster_chat_304_4 = "Nasil bir his bu? Olumun sana baktigini goruyor musun? "
gameforge.locale.monster_chat_304_5 = "Oh hayir! Simdiden mi pes ediyorsun? "
gameforge.locale.monster_chat_304_6 = "Aci cok cabuk gelir. "
gameforge.locale.monster_chat_305_1 = "Oh! Bu kilic harika gorunuyor. "
gameforge.locale.monster_chat_305_2 = "Azmin ve gucun uzerinde calis! "
gameforge.locale.monster_chat_305_3 = "Benim kadar guclu olabilecegini mi dusunuyorsun? "
gameforge.locale.monster_chat_305_4 = "Tamam, sakalar bitti. "
gameforge.locale.monster_chat_305_5 = "Oh! Ben sadece zayif bir kadinim! "
gameforge.locale.monster_chat_305_6 = "Yoruldun mu? Neden pes etmiyorsun? Hehe. "
gameforge.locale.monster_chat_306_1 = "Liderimiz bugun ne yapacak, hm? "
gameforge.locale.monster_chat_306_2 = "Ne sikici! Benimle oyna! "
gameforge.locale.monster_chat_306_3 = "Bir sey itiraf etmeliyim! Sura'lar beni cekiyor... "
gameforge.locale.monster_chat_306_4 = "Hey sen! Bir savasa ne dersin? "
gameforge.locale.monster_chat_306_5 = "Beni yanlis anlama, sadece bir kadinim! "
gameforge.locale.monster_chat_306_6 = "Aci sadece bir an surecek... "
gameforge.locale.monster_chat_307_1 = "Her ne pahasina olursa olsun buradan cikmak istiyorum! "
gameforge.locale.monster_chat_307_2 = "Evleri nasil korunuyor? "
gameforge.locale.monster_chat_307_3 = "Kapa ceneni! "
gameforge.locale.monster_chat_307_4 = "Seni tek vurusla yenebilirim. "
gameforge.locale.monster_chat_307_5 = "Kacmayi bile dusunme! "
gameforge.locale.monster_chat_307_6 = "Peki, neden hala baslamadik? "
gameforge.locale.monster_chat_394_1 = "Unutmayin: tum erkekler dusmandir! "
gameforge.locale.monster_chat_394_2 = "Birinin guzel bir yuzu varsa, daha az kotu olabiliriz. "
gameforge.locale.monster_chat_394_3 = "Ne? Savasmak mi istiyorsun?! "
gameforge.locale.monster_chat_394_4 = "Uzun surmez ama acitacak! "
gameforge.locale.monster_chat_394_5 = "Oh, gercekten aci cekiyor gibisin. "
gameforge.locale.monster_chat_394_6 = "Hosca kal, cehenneme git! "
gameforge.locale.monster_chat_401_1 = "Peki, Yeminliler Tarikati'nda ne yapiyorsun? "
gameforge.locale.monster_chat_401_2 = "Nereye gidiyorsun? "
gameforge.locale.monster_chat_401_3 = "Hey, savasmak ister misin? "
gameforge.locale.monster_chat_401_4 = "Hehe, vuruslarimdan kaciyorsun. "
gameforge.locale.monster_chat_401_5 = "Benden kacabilecegini mi saniyorsun? "
gameforge.locale.monster_chat_401_6 = "Iste vurusum! "
gameforge.locale.monster_chat_402_1 = "Uh, cok yorgunum! "
gameforge.locale.monster_chat_402_2 = "Heh, guzel zirh! Ne kadara mal oldu? "
gameforge.locale.monster_chat_402_3 = "Ama havamiz cok guzel. "
gameforge.locale.monster_chat_402_4 = "Oh, cok antrenman yapmissin! Cok iyi. "
gameforge.locale.monster_chat_402_5 = "Becerilerim hakkinda ne dusunuyorsun? Super, ha? Hehe. "
gameforge.locale.monster_chat_402_6 = "Ne oldu? Elbette, bu inanilmaz bir hiz! "
gameforge.locale.monster_chat_403_1 = "Sanirim ava cikacagim... "
gameforge.locale.monster_chat_403_2 = "Bugun kimse koyumuze saldirmiyor. "
gameforge.locale.monster_chat_403_3 = "Savasmak istiyorsan, savas! Seni alcak! "
gameforge.locale.monster_chat_403_4 = "Hehe, sen sadece bir acemisin. "
gameforge.locale.monster_chat_403_5 = "Ilk hedefim ne olsun? Bacagin mi kolun mu? "
gameforge.locale.monster_chat_403_6 = "Okum geliyor! "
gameforge.locale.monster_chat_404_1 = "Yakinda koye gidip antrenman yapmaliyim. "
gameforge.locale.monster_chat_404_2 = "Kendimi cok guclu hissediyorum. "
gameforge.locale.monster_chat_404_3 = "Bugun aksam yemeginde ne var? "
gameforge.locale.monster_chat_404_4 = "Seni izliyorum... istedigin kadar bagir. "
gameforge.locale.monster_chat_404_5 = "Bu kadar mi bekleyeceksin? Meydan okumayi kabul et! "
gameforge.locale.monster_chat_404_6 = "Kilic, kulaga heyecan verici geliyor! "
gameforge.locale.monster_chat_405_1 = "Bu kilic hazir! "
gameforge.locale.monster_chat_405_2 = "Bakalim kilictan once kim olecek. "
gameforge.locale.monster_chat_405_3 = "Hey! Neye bakiyorsun? "
gameforge.locale.monster_chat_405_4 = "Once, karnin! "
gameforge.locale.monster_chat_405_5 = "Seni kalkan olarak kullanacagim. "
gameforge.locale.monster_chat_405_6 = "Seni kalkan olarak kullanacagim. "
gameforge.locale.monster_chat_406_1 = "Acliktan oluyorum... "
gameforge.locale.monster_chat_406_2 = "Burada yiyecek bir sey var mi? "
gameforge.locale.monster_chat_406_3 = "Neden hala acim?! O kadar cok yedim ki... "
gameforge.locale.monster_chat_406_4 = "Aaargh, ol! "
gameforge.locale.monster_chat_406_5 = "Cok acim... benimle savas! "
gameforge.locale.monster_chat_406_6 = "Bu cennet ile cehennem arasinda bir secim! "
gameforge.locale.monster_chat_491_1 = "Buna daha fazla dayanamam! Her yerim kasiniyor. "
gameforge.locale.monster_chat_491_2 = "Oh evet. Domuzlar goruyorum! "
gameforge.locale.monster_chat_491_3 = "Yerde mi? "
gameforge.locale.monster_chat_491_4 = "Seni tek vurusla yenecegim. "
gameforge.locale.monster_chat_491_5 = "Bu guzel bir ani olacak! "
gameforge.locale.monster_chat_491_6 = "Ol! "
gameforge.locale.monster_chat_492_1 = "Vucudum degisiyor... "
gameforge.locale.monster_chat_492_2 = "Neden artik antrenman yapmiyorum? "
gameforge.locale.monster_chat_492_3 = "Korkuyor musun, ha? "
gameforge.locale.monster_chat_492_4 = "Oh, donen silahimin bir kurbani daha mi? "
gameforge.locale.monster_chat_492_5 = "Saldiri tarzimi gordun mu? Hayir mi? Senin kaybin! "
gameforge.locale.monster_chat_492_6 = "En kucuk cizik bile senin icin olumcul olacak! "
gameforge.locale.monster_chat_493_1 = "Boyle bir ele sahip olmak cok rahatsiz edici! "
gameforge.locale.monster_chat_493_2 = "Neye bakiyorsun? Hic boyle bir el gormedin mi?! "
gameforge.locale.monster_chat_493_3 = "Insanlar beni gercekten sinirlendiriyor. "
gameforge.locale.monster_chat_493_4 = "Seni yere mi sermeliyim yoksa ne? Yoksa kacsan iyi olur! "
gameforge.locale.monster_chat_493_5 = "Sana muhtesem vurusumu gosterecegim! "
gameforge.locale.monster_chat_493_6 = "Elime baktigini biliyorum! "
gameforge.locale.monster_chat_494_1 = "Hey sen! Savasmak istiyorsan buraya gel! "
gameforge.locale.monster_chat_494_2 = "Sana muhtesem vurusumu gosterecegim! "
gameforge.locale.monster_chat_494_3 = "Neden bir sey planlamiyoruz? "
gameforge.locale.monster_chat_494_4 = "Hayir, simdi geri cekilemezsin! Savas! "
gameforge.locale.monster_chat_494_5 = "Bunu hak ettin! "
gameforge.locale.monster_chat_494_6 = "Biraz daha ve oleceksin! "
gameforge.locale.monster_chat_501_1 = "Benimle oyna! Gitme! "
gameforge.locale.monster_chat_501_2 = "Kemiklerinden daha guzel bir sey yontabilirdim... "
gameforge.locale.monster_chat_501_3 = "Henuz antrenman yapmadik... "
gameforge.locale.monster_chat_501_4 = "Ne muhtesem bir zirh! Onu istiyorum! "
gameforge.locale.monster_chat_501_5 = "Artik vuruslarimdan kacmak bu kadar kolay olmayacak! "
gameforge.locale.monster_chat_501_6 = "Hehe, sasirdin mi? "
gameforge.locale.monster_chat_502_1 = "Guzellik her sey degil. "
gameforge.locale.monster_chat_502_2 = "Bakma, savas! "
gameforge.locale.monster_chat_502_3 = "Bana bakis seklini sevmiyorum. Savas! "
gameforge.locale.monster_chat_502_4 = "Kilicimdan olmek bir onurdur! "
gameforge.locale.monster_chat_502_5 = {}
gameforge.locale.monster_chat_502_6 = "Harika! "
gameforge.locale.monster_chat_503_1 = "Hey sen! Dokunma! "
gameforge.locale.monster_chat_503_2 = "Gorunuse gore usta yayim kesilmis. "
gameforge.locale.monster_chat_503_3 = "Kahretsin! Bu salaklar zaten buradaydi. "
gameforge.locale.monster_chat_503_4 = "Fena degil, ama yine de oleceksin. "
gameforge.locale.monster_chat_503_5 = "Iyi mi? Harika! "
gameforge.locale.monster_chat_503_6 = "Ok geliyor! "
gameforge.locale.monster_chat_504_1 = "Herkes, buraya gelin! "
gameforge.locale.monster_chat_504_2 = "La la la, sarkimi mirildaniyorum... "
gameforge.locale.monster_chat_504_3 = "Ne muhtesem bir hava! "
gameforge.locale.monster_chat_504_4 = {}
gameforge.locale.monster_chat_504_5 = "Eh, savasma istegini begendim! "
gameforge.locale.monster_chat_504_6 = "Iste! Herkes bana gelsin! "
gameforge.locale.monster_chat_601_1 = "Acliktan oluyorum... "
gameforge.locale.monster_chat_601_2 = "Meyve canim cekiyor. "
gameforge.locale.monster_chat_601_3 = "Evet. Baliklar uygun. Saldir! "
gameforge.locale.monster_chat_601_4 = "Kacma, dur! "
gameforge.locale.monster_chat_601_5 = "Zafer! Belliydi zaten! "
gameforge.locale.monster_chat_601_6 = "Goruyor musun? Iska! "
gameforge.locale.monster_chat_601_7 = "Dikkatli olmalisin, haha! "
gameforge.locale.monster_chat_602_1 = "Ben neredeyim?! "
gameforge.locale.monster_chat_602_2 = "Guzel hava. "
gameforge.locale.monster_chat_602_3 = "Beni mi avliyorsun? Sacmalik. "
gameforge.locale.monster_chat_602_4 = "Sen benim avimsin. "
gameforge.locale.monster_chat_602_5 = "Ne iskence, degil mi? Neyse, seninle isim hemen bitiyor. "
gameforge.locale.monster_chat_602_6 = "Cok gucluyum! Buyuk bir yuku kaldirabilirim! "
gameforge.locale.monster_chat_603_1 = "Sikici! "
gameforge.locale.monster_chat_603_2 = "Tum vucudum kasiniyor. "
gameforge.locale.monster_chat_603_3 = "Biri sonunda baslasin... "
gameforge.locale.monster_chat_603_4 = "Ilk sen mi vurdun? Seni buradan kovalayacagim! "
gameforge.locale.monster_chat_603_5 = "Ikinci kez basaramayacaksin! Kacmak anlamsiz! "
gameforge.locale.monster_chat_603_6 = "Bu son vurus olacak, seni bitirecegim! "
gameforge.locale.monster_chat_604_1 = "Lezzetli yeni bir zehir hazirladim. Belki tadina bakarsin? "
gameforge.locale.monster_chat_604_2 = "Nasil calistigini gormek istiyorum! Savun kendini! "
gameforge.locale.monster_chat_604_3 = "Hey, sen orada! Buraya gel, uzerinde birkac deney yapmak istiyorum! "
gameforge.locale.monster_chat_604_4 = "Seni zehirleyecegim! "
gameforge.locale.monster_chat_604_5 = "Hey, deney faresim olmak ister misin? "
gameforge.locale.monster_chat_604_6 = "Simdiden mi pes ettin? Eglence nerede?! Hadi, savun kendini! "
gameforge.locale.monster_chat_631_1 = "Bir dakika, avlayacak bir sey ariyorum. "
gameforge.locale.monster_chat_631_2 = "Bu kadar yavassan basaramazsin! "
gameforge.locale.monster_chat_631_3 = "Cok acim! "
gameforge.locale.monster_chat_631_4 = "Super, sonunda avlayacak birini buldum! "
gameforge.locale.monster_chat_631_5 = "Hayatta kalmayi umsun! "
gameforge.locale.monster_chat_631_6 = "Sana gercek aciyi tattiracagim! "
gameforge.locale.monster_chat_632_1 = "Sikici! "
gameforge.locale.monster_chat_632_2 = "Orada yem olarak kullanilabilecek bir sey var mi? "
gameforge.locale.monster_chat_632_3 = "Istiyorsan gel ve savas! "
gameforge.locale.monster_chat_632_4 = "Sen bir savasci misin? Kanitla! "
gameforge.locale.monster_chat_632_5 = {}
gameforge.locale.monster_chat_632_6 = "Hayatta kalmak istiyorsan, koye kac! "
gameforge.locale.monster_chat_633_1 = "Acliktan olmek aci verir... "
gameforge.locale.monster_chat_633_2 = "Oh, bize saldiriyorlar. "
gameforge.locale.monster_chat_633_3 = "Bir duelloya ne dersin? "
gameforge.locale.monster_chat_633_4 = "Beni o alcaklarla karistirma! "
gameforge.locale.monster_chat_633_5 = "Iste yildirim gibi bir vurus! "
gameforge.locale.monster_chat_633_6 = "Simdi kacan gercek bir savasci degildir! "
gameforge.locale.monster_chat_634_1 = "Bu sefer zehir daha guclu! "
gameforge.locale.monster_chat_634_2 = "Yiyecek bir seyin yok mu? Yarasalar cok lezzetlidir. "
gameforge.locale.monster_chat_634_3 = "Bir savasa ne dersin? "
gameforge.locale.monster_chat_634_4 = "Zehir vucuda girerse, tedavisi yoktur! "
gameforge.locale.monster_chat_634_5 = "Buyum her seyi yakacak, hehehe! "
gameforge.locale.monster_chat_634_6 = "Yan! Ha, ha! "
gameforge.locale.monster_chat_635_1 = "Sadece kilicini bilemeyi unutma! Her zaman biriyle dovusebilirsin! "
gameforge.locale.monster_chat_635_2 = "Bayilma mi? "
gameforge.locale.monster_chat_635_3 = "Ol ki uyanabilesin! "
gameforge.locale.monster_chat_635_4 = "Beni yenmek mi? Mucizelere mi inaniyorsun? "
gameforge.locale.monster_chat_635_5 = "Bir savasci gibi savas! "
gameforge.locale.monster_chat_635_6 = "Hadi, sadece biraz daha kaldi. "
gameforge.locale.monster_chat_636_1 = "Goruyorum ki ilginc bir savas beni bekliyor. "
gameforge.locale.monster_chat_636_2 = "Duellolar tam bir sevinc. "
gameforge.locale.monster_chat_636_3 = "Surekli savasmak istiyorum! "
gameforge.locale.monster_chat_636_4 = "Ne guzel! Tekrar dene! "
gameforge.locale.monster_chat_636_5 = "Silahima bak! Sansin yok! "
gameforge.locale.monster_chat_636_6 = "Bu vurus icin ozur dileyeceksin! "
gameforge.locale.monster_chat_636_7 = "Cok zayif! Cok acinasi! "
gameforge.locale.monster_chat_637_1 = "Kimsenin beni rahatsiz etmesini istemiyorum. "
gameforge.locale.monster_chat_637_2 = "Uyumaya git. Sonsuza dek! "
gameforge.locale.monster_chat_637_3 = "Hala uyumadin mi? "
gameforge.locale.monster_chat_637_4 = "Yapilacak cok sey var! Baslayalim! "
gameforge.locale.monster_chat_637_5 = "Gucum icin endiselenme! "
gameforge.locale.monster_chat_637_6 = "Seni un ufak edecegim! "
gameforge.locale.monster_chat_691_1 = "Harika, guclu rakipler daha uzun dayanir! Savun kendini! "
gameforge.locale.monster_chat_691_2 = "Ne dedin? Nasil mi gorunuyorum? "
gameforge.locale.monster_chat_691_3 = "Beni o acemiyle karistirma! "
gameforge.locale.monster_chat_691_4 = "O seni sevmiyor, ben de sevmiyorum! "
gameforge.locale.monster_chat_691_5 = "Savasalim! "
gameforge.locale.monster_chat_691_6 = "Olene kadar! "
gameforge.locale.monster_chat_701_1 = "Bak, bir kelebek! Ne guzel! "
gameforge.locale.monster_chat_701_2 = "Cennet ve Cehennem'in gercegini henuz bilmiyor musun? "
gameforge.locale.monster_chat_701_3 = "Simdi inan! Sonra cok gec olacak! "
gameforge.locale.monster_chat_701_4 = "Mistisizm doktrinine inan! "
gameforge.locale.monster_chat_701_5 = "Suphe eden olur! "
gameforge.locale.monster_chat_701_6 = "Olum gelmeden once aydinlan! "
gameforge.locale.monster_chat_702_1 = "Ezoterik inanclarin gercegi gogun duzenini anlamakta yatar. "
gameforge.locale.monster_chat_702_2 = "Mistik inanclarin felsefesi goklerden bir hediyedir! "
gameforge.locale.monster_chat_702_3 = "Mistik gercek, Kaplan Tanrisi'nin gercegi! Sabaha! Sabaha! "
gameforge.locale.monster_chat_702_4 = "Cennet ve Dunya'nin gerceginden suphe etmeye mi curet ediyorsun?! "
gameforge.locale.monster_chat_702_5 = {}
gameforge.locale.monster_chat_702_6 = "Silahim geliyor! "
gameforge.locale.monster_chat_703_1 = "Kaplan Tanrisi'nin ogretilerini her zaman tekrarlarsak, acimiz son bulacak. "
gameforge.locale.monster_chat_703_2 = "Ezoterik inanclarin gercegi gogun duzenini anlamakta yatar. "
gameforge.locale.monster_chat_703_3 = "Sabaha! Sabaha! Bilgeligini bize gonder! "
gameforge.locale.monster_chat_703_4 = "Suphe etme! "
gameforge.locale.monster_chat_703_5 = "Gokten yildirim gonder! "
gameforge.locale.monster_chat_703_6 = "Adaletin vurusu! "
gameforge.locale.monster_chat_704_1 = "Ezoterik inanclarin gercegi gogun duzenini anlamakta yatar. "
gameforge.locale.monster_chat_704_2 = "Mistik gercek, Kaplan Tanrisi'nin gercegi! Sabaha! Sabaha! "
gameforge.locale.monster_chat_704_3 = "Soytari gibi mi gorunuyorum sence? Az sonra fikrini degistireceksin! "
gameforge.locale.monster_chat_704_4 = "Tarikat lideri kutsaldir! Herkesin ustundedir. "
gameforge.locale.monster_chat_704_5 = "Cehennem atesinde yan! "
gameforge.locale.monster_chat_704_6 = "Sanirim hic bu kadar guclu bir rakip gormedin, ha? "
gameforge.locale.monster_chat_705_1 = "Mistik gercek, Kaplan Tanrisi'nin gercegi! Sabaha! Sabaha! "
gameforge.locale.monster_chat_705_2 = "Ezoterik inanclarin gercegi gogun duzenini anlamakta yatar. "
gameforge.locale.monster_chat_705_3 = "Kardesimden kucuk olmam daha zayif oldugum anlamina gelmez! "
gameforge.locale.monster_chat_705_4 = "Seni ebedi karanlik ve aci bekliyor! "
gameforge.locale.monster_chat_705_5 = {}
gameforge.locale.monster_chat_705_6 = "Bu son degil, daha iyisi gelecek! "
gameforge.locale.monster_chat_706_1 = "Huzur ve mahremiyet istiyoruz! Rica ediyoruz! "
gameforge.locale.monster_chat_706_2 = "Korku hukum surdugunde, Kaplan Tanrisi'nin gercegi bize yardim eder! "
gameforge.locale.monster_chat_706_3 = "Mistisizmin gercegi hem goklerin bir hediyesi hem de laneti! "
gameforge.locale.monster_chat_706_4 = "Hepimiz cehennemde olacagiz! "
gameforge.locale.monster_chat_706_5 = "Gitmene izin vermeyecegim! "
gameforge.locale.monster_chat_706_6 = "Sahip oldugum her seyi sana verecegim. "
gameforge.locale.monster_chat_707_1 = "Yalvaririm, bizi kurtar! "
gameforge.locale.monster_chat_707_2 = "Ezoterik inanclarin gercegi gogun duzenini anlamakta yatar. "
gameforge.locale.monster_chat_707_3 = "Mistik gercek, Kaplan Tanrisi'nin gercegi! Sabaha! Sabaha! "
gameforge.locale.monster_chat_707_4 = "Cehennemin kapilari acik, ol! (tehditkar gulus) "
gameforge.locale.monster_chat_707_5 = "Uyariyorum: beni guc kullanmaya zorlama! "
gameforge.locale.monster_chat_707_6 = "Olumunu simdiden goruyorum! "
gameforge.locale.monster_chat_791_1 = "Kaplan Tanrisi'nin yolunu sana kisaca nasil anlatabilirim? "
gameforge.locale.monster_chat_791_2 = "Inananlarin monoton ilahilerini duyuyorum. "
gameforge.locale.monster_chat_791_3 = "Bu gercek! Pismanlik dolu ol, kurtulacaksin! "
gameforge.locale.monster_chat_791_4 = "Suphe ettigin icin aci cekeceksin! "
gameforge.locale.monster_chat_791_5 = "Sana bir sey ogreteyim... "
gameforge.locale.monster_chat_791_6 = "Bunun aci oldugunu sanma, bu bir talimat! "
gameforge.locale.monster_chat_901_1 = "Belki cekici gorunmuyorum, ama mizah anlayisim var, hihihihi! "
gameforge.locale.monster_chat_901_2 = "Bizim gibi olacaksin! "
gameforge.locale.monster_chat_901_3 = "Buraya gel, hihi! "
gameforge.locale.monster_chat_901_4 = "Haaa, haha! "
gameforge.locale.monster_chat_901_5 = "Basliyor... "
gameforge.locale.monster_chat_903_1 = "Cehennem boyle gorunuyor! "
gameforge.locale.monster_chat_903_2 = "Ahhhhh! "
gameforge.locale.monster_chat_903_3 = "Bunu tek basimiza yapamayiz! Hayir! "
gameforge.locale.monster_chat_903_4 = "Acinin tadina bakmalisin! "
gameforge.locale.monster_chat_903_5 = "Kucuk bir takasa ne dersin? Ruhun benim acima karsilik! "
gameforge.locale.monster_chat_903_6 = "Yakinda ebedi huzura kavusacaksin... "
gameforge.locale.monster_chat_904_1 = "Bu acitiyor! Oh, acitiyor! "
gameforge.locale.monster_chat_904_2 = "Aargghh, kahretsin! Elim yaniyor! "
gameforge.locale.monster_chat_904_3 = "Neden aci cekmeliyiz? Neden?! "
gameforge.locale.monster_chat_904_4 = "O kadar korkunc degil... aci cekiyorum, ama bunun karsiliginda mistik gercegi biliyorum. "
