gameforge.locale.old_pirate.baekgo_start_say = "Baek-Go:[ENTER]Enfekte olmus biriyle tek bir temasi oldu ve o[ENTER]zamandan beri yarasi irinleniyor ve kasiniyor mu? "
gameforge.locale.old_pirate.baekgo_start_say2 = "Baek-Go:[ENTER]Oh!! Neredeyse eminim ki o gizemli hastaliga[ENTER]yakalanmis! Onunla ilgilenmezsem, hastalik[ENTER]tum koye yayilacak! "
gameforge.locale.old_pirate.baekgo_start_say3 = "Baek-Go:[ENTER]Kimseyi enfekte edemez! Hemen tedavi edilmeli.[ENTER]Bunun icin bu gizemli hastaligin mikrop ornegine[ENTER]ihtiyacimiz var. Bu ornegi, buradan kuzeyde,[ENTER]Sohan Dagi'nda toplu halde bulunan hastalardan[ENTER]elde edebilirsin. "
gameforge.locale.old_pirate.baekgo_success_say = "Baek-Go:[ENTER]Basardin! Ilac icin biraz bekle![ENTER][DELAY value;1000] [/DELAY][ENTER][ENTER]Ilaci o kadar hizli yaptim ki, ise yarayacagindan[ENTER]emin degilim. Ama kesinlikle kendini daha iyi[ENTER]hissedecek. Bu ilaci ona mumkun oldugunca[ENTER]cabuk gotur. "
gameforge.locale.old_pirate.baekgo_talk = "Beni Yasli Korsan gonderdi. "
gameforge.locale.old_pirate.baekgo_talk_about_old_pirate = "Yasli Korsan'in Hastaligi "
gameforge.locale.old_pirate.complete_say = "Yasli Korsan:[ENTER]Hala kasiniyor. Ama artik kendimi daha iyi[ENTER]hissediyorum.[ENTER]Hayatta kalacagim. "
gameforge.locale.old_pirate.do_you_get_the_medicine = "Ilac henuz bende degil. "
gameforge.locale.old_pirate.do_you_mean_this_medicine = "Iste ilac! "
gameforge.locale.old_pirate.etc_shop_start_say = "Genel Satici:[ENTER]Yasli Korsan mi? Elbette onu taniyorum. Her zaman[ENTER]kufredip kasinan adam, degil mi?[ENTER]Her zaman sivi bir ilac almaya gelir.[ENTER]Kizil Iksirlere binlerce Yang harcadi. "
gameforge.locale.old_pirate.etc_shop_start_say2 = "Genel Satici:[ENTER]Hicbir yerde calismiyorken Tanri askina bu kadar[ENTER]Yang'i nereden buluyor? Ona bir doktora muayene[ENTER]olmasini defalarca soyledim, ama beni hic[ENTER]dinlemiyor.[ENTER]Kizil ilac sadece belirtileri hafifletir, hastaligin[ENTER]kendisini tedavi etmez. Bunun kotu biteceginden[ENTER]korkuyorum. "
gameforge.locale.old_pirate.etc_shop_talk_about_old_pirate = "Yasli Korsan'i taniyor musun? "
gameforge.locale.old_pirate.order_accept = "Sana yardim edecegim. "
gameforge.locale.old_pirate.order_accept_answer = "Yasli Korsan:[ENTER]Harika. Bol sans![ENTER]Doktor kesinlikle sehirde. "
gameforge.locale.old_pirate.order_find_medicine_label = "Yasli Korsan icin ilac "
gameforge.locale.old_pirate.order_find_medicine_text_1 = "Yasli Korsan icin ilac elde et. "
gameforge.locale.old_pirate.order_find_medicine_text_2 = "Sehirdeki Baek-Go'ya git ve ona Yasli Korsan icin[ENTER]ilac hakkinda sor. "
gameforge.locale.old_pirate.order_refuse = "Ne yazik ki yapamam. "
gameforge.locale.old_pirate.order_refuse_answer = "Yasli Korsan:[ENTER]O halde soyleyecek baska bir seyim yok! "
gameforge.locale.old_pirate.order_say1 = "Yasli Korsan:[ENTER]Kahretsin! Ne istiyorsun? Kahretsin! Su adi[ENTER]dukkanci sana hakkimda bir sey mi soyledi,[ENTER]oyle mi?[ENTER]Evet, dogru. Ama doktora gidecek vaktim yok.[ENTER]O kadar cok dusmanim var ki! "
gameforge.locale.old_pirate.order_say2 = "Yasli Korsan:[ENTER]Hangi alcagin birden yanina gelip seni bicaklayacagini[ENTER]asla bilemezsin! Ama gercekten kasiniyor... Dayanamiyorum...[ENTER]Yani - doktora gidip bana bu hastalik icin[ENTER]ilac getirir misin? Comertce[ENTER]odullendirileceksin... "
gameforge.locale.old_pirate.order_too_late = "Yasli Korsan:[ENTER]Baska biri bana zaten ilac getirdi. Yani[ENTER]benden odul alamayacaksin! "
gameforge.locale.old_pirate.start_find_old_pirate_label = "Yasli Korsan'a git. "
gameforge.locale.old_pirate.start_find_old_pirate_text_1 = "Yasli Korsan'a git. "
gameforge.locale.old_pirate.start_find_old_pirate_text_2 = "Yasli Korsan'a git ve neden doktora gitmedigini[ENTER]sor. "
gameforge.locale.old_pirate.start_say = "Yasli Korsan:[ENTER]Her yerim kasiniyor!!! O adama carpmamaliydim.[ENTER]Sadece bir dokunustu! O zamandan beri o bolge[ENTER]irinleniyor ve tum vucudum kasiniyor![ENTER]Sanki hayattayken curuyorum. Lanet olasi adam! "
gameforge.locale.old_pirate.success_thanks = "Yasli Korsan:[ENTER]Ne? Gizemli bir hastaliga mi yakalandim? Iste[ENTER]gereken ilac! Cok, cok tesekkur ederim![ENTER]Hayatimi kurtardin! Sana cok minnettarim! "
