gameforge.locale.questscroll.exist = "Baska bir gorev zaten aktif. "
gameforge.locale.questscroll.finish = "Gorev tamamlandi![ENTER]Odul olarak alindi: "
gameforge.locale.questscroll.finish_button = "Gorev tamamlandi. "
gameforge.locale.questscroll_10_hunt = "Yilan Askerleri "
gameforge.locale.questscroll_10_mis = "Yari insan yari yilan olan askerleri oldur. "
gameforge.locale.questscroll_10_text = "Onlara insan denemez. Ama insan degiller de[ENTER]denemez. Insan gibi gorunuyorlar, ama kafalari,[ENTER]derileri ve mizaclari daha cok yilana benziyor.[ENTER]Onlarla colde karsilasabilirsin, sik sik[ENTER]tuccarlara saldiriyorlar.[ENTER]20 Yilan Adam oldur, odulu kacirma: "
gameforge.locale.questscroll_11_hunt = "Yilan Okculari "
gameforge.locale.questscroll_11_mis = "Yari insan yari yilan olan Okculari oldur. "
gameforge.locale.questscroll_11_text = "Insanlar kadar zekiler. Kurnazlar ve silah[ENTER]kullanmayi biliyorlar. Yari insan yari yilan[ENTER]okcular, uzaktan masum tuccarlara saldiriyor.[ENTER]Cogu coktan oldu.[ENTER]20 Yilan Okcusu oldur, odulu[ENTER]kacirma: "
gameforge.locale.questscroll_12_hunt = "Col Kabadayilari "
gameforge.locale.questscroll_12_mis = "Col Kabadayilarini oldur. "
gameforge.locale.questscroll_12_text = "Yongbi Colu'nde kotu varliklar yasiyor. Halk[ENTER]arasinda Col Serserileri olarak biliniyorlar ve[ENTER]gokyuzu bile kotu islerine agliyor. Sadece[ENTER]eglence icin tuccarlari soyup olduruyorlar.[ENTER]Coldeki koyleri yok ediyorlar.[ENTER]12 Col Serserisi oldur, basarirsan[ENTER]odul alacaksin: "
gameforge.locale.questscroll_13_hunt = "Savasan Kaplanlar "
gameforge.locale.questscroll_13_mis = "Savasan Kaplanlari oldur. "
gameforge.locale.questscroll_13_text = "Burada bir yerde Savasan Kaplanlar denen hayvanlar[ENTER]var. Kanlari atesten, bedenleri volkanik[ENTER]kayalardan yaratilmis. Inanilmaz derecede guclu[ENTER]canavarlar. Bu canavarlar lav ve volkanik atesle[ENTER]besleniyor. Bazen volkani terk edip insanlara[ENTER]saldirip onlari yiyorlar.[ENTER]20 Savasan Kaplan oldur, basarirsan[ENTER]odul seni kacirmayacak: "
gameforge.locale.questscroll_14_hunt = "Savas Insanlari "
gameforge.locale.questscroll_14_mis = "Savas Insanlarini oldur "
gameforge.locale.questscroll_14_text = "Doyyumhwaji, vahsi hayvanlarla dolu buyuk ve[ENTER]sicak bir bolge. Chunjo, Jinno ve Shinsoo'dan[ENTER]savascilar orada bulusuyor. Onlari korkunc ve[ENTER]guclu canavarlar bekliyor. Savas Insanlari,[ENTER]Doyyumhwaji'yi kontrol edenlerden biri.[ENTER]Onlarla yuzlesmek ister misin? 20 tanesini[ENTER]oldurursen, su odulu alacaksin: "
gameforge.locale.questscroll_15_hunt = "Taehwa Savascilari "
gameforge.locale.questscroll_15_mis = "Taehwa Savascilarini yen "
gameforge.locale.questscroll_15_text = "Dinleyin, kendinizi korkusuz ve guclu savascilar[ENTER]olarak gorenler! Bu, gozyasi, savas, aci ve[ENTER]olumle dolu Alevli Savas Alani! Burada bircok[ENTER]canavar ve kotu adamla yasiyorum! Beni meydan[ENTER]okuyacak kadar cesur olan var mi?[ENTER]Karsimda elinde kilicla duracak biri var mi?[ENTER]Kendine guveniyorsan, bana meydan oku! Beni[ENTER]ve 12 yoldasimi yenersen, su odulu alacaksin: "
gameforge.locale.questscroll_16_hunt = "Kara Ayilar "
gameforge.locale.questscroll_16_mis = "Kara Ayilari oldur "
gameforge.locale.questscroll_16_text = "Korkarim bu benim sonum. Ama sana onemli bir[ENTER]olaydan bahsetmeme izin ver... Bu mektubu[ENTER]okudugunda, muhtemelen olmusumdur ya da az[ENTER]sonra olecegim. Seungryong Vadisi'nde[ENTER]yasiyordum, tibbi bitkiler topluyordum. Ama[ENTER]Karanlik Ayilar denen canavarlar burada[ENTER]cok fazla zarar vermeye basladi. Ailemi[ENTER]oldurduler. Lutfen, beni ve ailemi[ENTER]intikamini al.[ENTER]25 Karanlik Ayi oldurursen, su[ENTER]odulu alacaksin: "
gameforge.locale.questscroll_17_hunt = "Dev Ayilar "
gameforge.locale.questscroll_17_mis = "Dev Ayilari oldur "
gameforge.locale.questscroll_17_text = "Ayi Tanrisi yeni bir canavar yaratti: siradan[ENTER]ayilari daha da kotu canavarlarla birlestirdi.[ENTER]Boylece siradan ayilardan daha buyuk ve guclu[ENTER]Dev Ayilar ortaya cikti. Inanilmaz derecede[ENTER]kotuler. Seungryong Vadisi'nde kaldiklari[ENTER]surece, insanlar aci cekecek.[ENTER]20 Dev Ayi oldur. Basarirsan,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_18_hunt = "Gizemli hastaliga yakalanan Askerler... "
gameforge.locale.questscroll_18_mis = "Gizemli salgina yakalanan Askerleri oldur. "
gameforge.locale.questscroll_18_text = "Koy toza donusmus gibi gorunuyor. Gizemli[ENTER]salgindan sag kalan sakinler tuccarlara saldirip[ENTER]masum insanlari yiyor. Son derece[ENTER]tehlikeliler.[ENTER]35 gizemli salgina yakalanan Asker oldur.[ENTER]Basarirsan, su odulu alacaksin: "
gameforge.locale.questscroll_19_hunt = "Gizemli salgina yakalanan Okcular... "
gameforge.locale.questscroll_19_mis = "Gizemli hastaliga yakalanan Okculari oldur. "
gameforge.locale.questscroll_19_text = "Gizemli salgin, ona yakalanan bircok insanin[ENTER]aci cekmesine sebep oluyor. En tehlikelileri[ENTER]salgini yayan okcular. Okcular zehirli oklar[ENTER]atiyor, yolculari felc edip kaciriyorlar.[ENTER]25 gizemli salgina yakalanan Okcu oldur.[ENTER]Basarirsan, su odulu[ENTER]alacaksin: "
gameforge.locale.questscroll_1_hunt = "Atesli Ayilar "
gameforge.locale.questscroll_1_mis = "25 Atesli Ayi oldur "
gameforge.locale.questscroll_1_text = "Atesli Ayilar sik sik sehirlerin yakininda[ENTER]goruluyor. Bozkirlarda dolasiyorlar, ama ayni[ENTER]zamanda dar insan sokaklarinda da. Giderek[ENTER]daha cok insan onlarin kurbani oluyor. Bircok[ENTER]insan coktan oldu.[ENTER]Bu Atesli Ayilari avla. 25 tanesini[ENTER]oldurdugunde, su odulu alacaksin: "
gameforge.locale.questscroll_20_hunt = {}
gameforge.locale.questscroll_20_mis = "4 dusman oldur "
gameforge.locale.questscroll_20_text = "Korkarim bu benim sonum! Gozlerim coktan[ENTER]bulaniklasti... Bu mektubu okudugunda, muhtemelen[ENTER]parcalara ayrilmisimdir. Bu alcaklar beni kacirdi.[ENTER]Kacabilirdim, ama yaralarim cok derindi ve[ENTER]dustum. Seni tanimiyorum. Ama lutfen, intikamimi al![ENTER]Savas alaninda 4 dusman oldur. Basarirsan,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_2_hunt = "Buyuk Kaplan "
gameforge.locale.questscroll_2_mis = "20 Buyuk Kaplan oldur "
gameforge.locale.questscroll_2_text = "Isimleri havada ugursuzca asili: Buyuk[ENTER]Kaplanlar. Sehrin yakininda yasiyorlar.[ENTER]Insanlara saldiriyor ve bircok tedarikciyi[ENTER]yiyorlar. Kurbanlarini saymak artik zor.[ENTER]Buyuk Kaplanlari avla. 20 tanesini oldurdugunde,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_3_hunt = "Daglarin Kopek Tanrisi "
gameforge.locale.questscroll_3_mis = "Daglarin kopek liderini oldur "
gameforge.locale.questscroll_3_text = "Daglarin Kopek Tanrisi savasci toplamaya devam[ENTER]ediyor. Guclu ve vahsi. Cok gecmeden koyun[ENTER]yakininda belirdi ve tuccarlara saldirmaya[ENTER]basladi. Coktan bircok olume sebep oldu. Artik[ENTER]davranisini gormezden gelemeyiz.[ENTER]Kopek liderini oldur. Basarirsan,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_4_hunt = "Domuz liderini oldur "
gameforge.locale.questscroll_4_mis = "Domuz liderini oldur. "
gameforge.locale.questscroll_4_text = "Cevredeki tarlalarda hasat zamani geldi.[ENTER]Hasat zamani. Ciftcilerin zor kazandiklari[ENTER]urunu toplama zamani. Ama domuz lideri ve[ENTER]arkadaslari tum tahili yiyor. Acgozlulukleri[ENTER]ciftcileri tehdit ediyor, onu oldurmelisin.[ENTER]Domuz liderini oldur. Genellikle Ana[ENTER]Sehir'in cevresinde bulunur. Basarirsan,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_5_hunt = "Ayi Tanrisi "
gameforge.locale.questscroll_5_mis = "Ayi liderini oldur "
gameforge.locale.questscroll_5_text = "Dogal ortaminda, ayi lideri her zaman iyiydi.[ENTER]Ama simdi Ana Sehir'in yakininda belirip[ENTER]insanlara saldiriyor. Giderek daha fazla kurbana[ENTER]sebep oluyor. Kac kisiyi oldurdugunu artik kimse[ENTER]sayamiyor. Buradan yok olmali.[ENTER]Ayi liderini oldur. Onu buradan uzaklastirmayi[ENTER]basarirsan, su odulu alacaksin: "
gameforge.locale.questscroll_6_hunt = "Kaplan Tanrisi "
gameforge.locale.questscroll_6_mis = "Kaplan liderini oldur. "
gameforge.locale.questscroll_6_text = "Kaplan liderinin boyle korkuncluklara sebep[ENTER]olduguna gercekten inanamiyorum... Ben sadece[ENTER]onu her zaman oven basit bir kadinim. Bazen[ENTER]kayalik cikintilarda belirirdi. Ama bir gun,[ENTER]Kaplan lideri ve hizmetkarlari ailemize saldirip[ENTER]hepsini oldurdu! Ben kendim kolumu kaybettim.[ENTER]Lutfen, ailemin intikamini al. Onu oldurursen,[ENTER]odulu kacirmazsin: "
gameforge.locale.questscroll_7_hunt = "Yeminliler Lideri "
gameforge.locale.questscroll_7_mis = "Yeminliler Liderini oldur. "
gameforge.locale.questscroll_7_text = "Yeminliler Klani, kocalari tarafindan terk edilmis[ENTER]ve dunya tarafindan kotu muamele gormus kadinlardan[ENTER]olusan bir grup. Belki magdur oldular, ama[ENTER]koyleri yagmalama sekilleri basitce acimasiz.[ENTER]Tanidiklarimdan biri koye yaklastiginda taslandi.[ENTER]Koye girip insanlara saldirmalarina izin veremeyiz.[ENTER]20 Yeminliler Lideri oldur. Basarirsan,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_8_hunt = "Kara Ruzgar Cetesi Lideri "
gameforge.locale.questscroll_8_mis = "Kara Ruzgar Cetesi Liderini oldur. "
gameforge.locale.questscroll_8_text = "Kara Ruzgar Cetesi'nin hirsizlari uzun suredir[ENTER]tuccarlari avliyor. O kadar korkutucular ki,[ENTER]kimse onlara karsi koyacak kadar cesur degil.[ENTER]Ama bu boyle devam edemez, cok fazla kan doktuler.[ENTER]20 Kara Ruzgar Cetesi Lideri oldur. Basarirsan,[ENTER]su odulu alacaksin: "
gameforge.locale.questscroll_9_hunt = "Vahsiler Lideri "
gameforge.locale.questscroll_9_mis = "Vahsiler Liderini oldur. "
gameforge.locale.questscroll_9_text = "Vahsilerin siniri gecip koye saldirmasinin[ENTER]uzerinden biraz zaman gecti. Oldurulenlerin sayisi[ENTER]zaten yuzlerle ifade ediliyor ve sayilari hala[ENTER]artiyor. Vahsiler o kadar acimasiz ki, kimse[ENTER]onlara karsi koymaya cesaret edemedi. Ama artik[ENTER]bu duruma daha fazla katlanamayiz.[ENTER]25 Vahsiler Lideri oldur. Basarirsan,[ENTER]su odulu alacaksin: "
