gameforge.locale.skill_group = {}
gameforge.locale.skill_group.board = "Brosurdeki metin:[ENTER]Krallikta baris icin savasmaya istekli cesur erkek[ENTER]ve kadinlari ise aliyoruz.[ENTER][ENTER]Bize katilmak icin 5. seviyeye sahip olmalisin. "
gameforge.locale.skill_group.dialog_assassin_1 = "Burada dusmanlarina saklanip gizlice saldirabilen[ENTER]Ninjalar egitiyoruz. En buyuk onem hancer ve[ENTER]zehir kullanimi egitimine veriliyor. Sadece en az[ENTER]5. seviyeye sahip Ninjalar katilabilir. Bu[ENTER]seviyeye ulasirsan, katilim teklifi alacaksin.[ENTER]Bir Ninja olarak karanlikta saklanmaya hazir[ENTER]oldugunda bana geri don. O zaman konusuruz. "
gameforge.locale.skill_group.dialog_assassin_2 = "Burada dusmanlarina saklanip gizlice saldirabilen[ENTER]Ninjalar egitiyoruz. En buyuk onem hancer ve[ENTER]zehir kullanimi egitimine veriliyor. Bir Ninja[ENTER]olarak karanlikta saklanmaya hazir oldugunda[ENTER]bana geri don. Bize katilmaya hazir olan herkesi[ENTER]memnuniyetle karsilarim. "
gameforge.locale.skill_group.dialog_assassin_3 = "Burada yayla uzaktan savasabilen Ninjalar[ENTER]egitiyoruz. Egitim sirasinda en buyuk onem[ENTER]okculuk becerisine veriliyor. Egitmenler sana[ENTER]uzak mesafeden dusmanlarina iyi hedeflenmis bir[ENTER]Atesli Ok'la nasil nisan alacagini ogretecek.[ENTER]Sadece en az 5. seviyeye sahip Ninjalar[ENTER]katilabilir. Bu seviyeye ulasirsan, katilim[ENTER]teklifi alacaksin. Bu gelisim yolu ilgini[ENTER]cekiyorsa benimle konusmaya gel. "
gameforge.locale.skill_group.dialog_assassin_4 = "Burada yayla uzaktan savasabilen Ninjalar[ENTER]egitiyoruz. Egitim sirasinda en buyuk onem[ENTER]okculuk becerisine veriliyor. Egitmenler sana[ENTER]uzak mesafeden dusmanlarina iyi hedeflenmis bir[ENTER]Atesli Ok'la nasil nisan alacagini ogretecek. Bu[ENTER]gelisim yolu ilgini cekiyorsa benimle konusmaya[ENTER]gel. Sayemde Kralligin en iyi okcusu[ENTER]olacaksin. "
gameforge.locale.skill_group.dialog_assassin_5 = "Hancer Dovusu ile Uzak Dovus arasinda sec.[ENTER]Sectigin becerileri alacaksin. "
gameforge.locale.skill_group.dialog_shaman_1 = "Burasi Ejderha Tanrisi'nin yolunu izleyen[ENTER]Samanlarin egitildigi yer. Onlara muskalari ve[ENTER]buyulu gucu nasil kullanacaklari ogretiliyor.[ENTER]Ejderha Tanrisi'nin gucu sayesinde direnc[ENTER]kazanabilirler. Dost canlisi kisileri[ENTER]destekleyebilirler. Sadece en az 5. seviyeye[ENTER]sahip Samanlar katilabilir. Bu seviyeye[ENTER]ulasirsan, katilim teklifi alacaksin. Ejderha[ENTER]Tanrisi'nin yolunu izlemeye hazir oldugunda[ENTER]bana geri don. "
gameforge.locale.skill_group.dialog_shaman_2 = "Burasi Ejderha Tanrisi'nin yolunu izleyen[ENTER]Samanlarin egitildigi yer. Onlara muskalari ve[ENTER]buyulu gucu nasil kullanacaklari ogretiliyor.[ENTER]Ejderha Tanrisi'nin gucu sayesinde direnc[ENTER]kazanabilirler. Dost canlisi kisileri[ENTER]destekleyebilirler. Ejderha Tanrisi'nin yolunu[ENTER]izlemeye hazir oldugunda bana geri don. "
gameforge.locale.skill_group.dialog_shaman_3 = "Burada Samanlar Doga ve Isigin Gucune tapiyor.[ENTER]Yildirim, Firtina ve Iyilestirme becerilerini[ENTER]ogreniyorlar. Sik sik birbirlerini desteklemek[ENTER]icin gruplar halinde calisiyorlar. Sadece en az[ENTER]5. seviyeye sahip Samanlar katilabilir. Bu[ENTER]seviyeye ulasirsan, katilim teklifi alacaksin.[ENTER]Seni bekleyecegim. "
gameforge.locale.skill_group.dialog_shaman_4 = "Burada Samanlar Doga ve Isigin gucune tapiyor.[ENTER]Yildirim, Firtina ve Iyilestirme becerilerini[ENTER]ogreniyorlar. Sik sik birbirlerini desteklemek[ENTER]icin gruplar halinde calisiyorlar. Benimle[ENTER]birlikte diger insanlara yardim etmek ister[ENTER]misin? Destegin aci ceken herkese yardimci[ENTER]olacak. Lutfen, katil. "
gameforge.locale.skill_group.dialog_shaman_5 = "Ejderha Gucu ile Iyilestirme arasinda sec.[ENTER]Sectigin becerileri alacaksin. "
gameforge.locale.skill_group.dialog_sura_1 = "Insanlara, sol kolumda Seytan Tohumu tarafindan[ENTER]ekilmis boyle bir buyuyu nasil kullanacaklarini[ENTER]ogretiyorum. Kilic ve Zirhlari buyuluyorum, bu[ENTER]saldiri degerimi artirmama yardimci oluyor, ayrica[ENTER]cehennemden kotu bir ruh cagirip dusmanin canini[ENTER]azaltabiliyorum. Sadece en az 5. seviyeye ulasan[ENTER]Sura'lar bize katilabilir. Egitimle gerekli[ENTER]seviyeye ulastiysan ise alim teklifi alacaksin.[ENTER]Gece Kiliclari kullanmaya ya da ebedi Gece[ENTER]Buyulerini soylemeye hazirsan, buraya gel. "
gameforge.locale.skill_group.dialog_sura_2 = "Insanlara, sol kolumda Seytan Tohumu tarafindan[ENTER]ekilmis boyle bir buyuyu nasil kullanacaklarini[ENTER]ogretiyorum. Kilic ve Zirhlari buyuluyorum, bu[ENTER]saldiri degerimi artirmama yardimci oluyor,[ENTER]ayrica cehennemden kotu bir ruh cagirip dusmanin[ENTER]canini azaltabiliyorum. Gece Kiliclari kullanmaya[ENTER]ya da ebedi Gece Buyulerini soylemeye hazirsan,[ENTER]seni guclu kilacagim. "
gameforge.locale.skill_group.dialog_sura_3 = "Ilgileniyorsan: burada sadece karanliga[ENTER]adanmislar var. Seytan Alevi ve kotu ruhlarin ve[ENTER]iblislerin Becerilerini kullanmayi ogreniyorlar.[ENTER]Sadece en az 5. seviyeye ulasan Sura'lar[ENTER]katilabilir. Egitimle gerekli Seviyeye ulastiysan[ENTER]ise alim teklifi alacaksin. Karanlikta yasamak[ENTER]istiyorsan bu dunyanin sunduklarini ogrenmek icin[ENTER]gercek yer burasi. "
gameforge.locale.skill_group.dialog_sura_4 = "Ilgileniyorsan: burada sadece karanliga[ENTER]adanmislar var. Seytan Alevi ve kotu ruhlarin ve[ENTER]iblislerin Becerilerini kullanmayi ogreniyorlar.[ENTER]Seni giderek daha fazla tuketen kotu ruhlarin[ENTER]dostu olmakla ilgileniyorsan, gel. Gelirsen -[ENTER]insanligini geride birak. "
gameforge.locale.skill_group.dialog_sura_5 = "Kara Buyu Egitimi ile Silah Egitimi arasinda[ENTER]sec. Sectigin becerileri alacaksin. "
gameforge.locale.skill_group.dialog_warrior_1 = "Nerede oldugunu biliyor musun? Burada tum[ENTER]Krallik'ta en hizli ve en cesur olacak savascilar[ENTER]egitiliyor. Burada hizli tekrarlanan darbe[ENTER]tekniklerini ve kilic ya da mizrakla savasmayi[ENTER]ogretiyoruz. Sadece meslek egitimi almis ve[ENTER]5. Seviye ve ustu savascilar katilabilir.[ENTER]Belirlenen Seviyeye ulastiysan ordu sana kabul[ENTER]edildigini soyleyecek. Bedeninin gercek gucunu[ENTER]bulmak istiyorsan, benimle gel! "
gameforge.locale.skill_group.dialog_warrior_2 = "Nerede oldugunu biliyor musun? Burada en hizli ve[ENTER]en cesur olan savascilar egitiliyor. Hizli[ENTER]tekrarlanabilir ve uyumlu saldirilar ogreniyorlar.[ENTER]Esas olarak Kilic ve Mizrak kullanimi uzerine[ENTER]egitim aliyorlar. Peki, ne dersin? Bize katilmak[ENTER]ister misin? "
gameforge.locale.skill_group.dialog_warrior_3 = "Burada savascilara Chi kullanimi ogretiliyor.[ENTER]Tekrarlamasi biraz daha yavas ve zihinsel olarak[ENTER]yorucu olan Yakin Dovus saldirilarini ogreniyorlar.[ENTER]Ayni zamanda bu saldirilar cok guclu ve etkili.[ENTER]Sadece meslek egitimi almis ve 5. seviye ve ustu[ENTER]savascilar katilabilir. Gerekli seviyeye[ENTER]ulastiysan, orduya alim teklifi alacaksin.[ENTER]Ilgileniyorsan, benimle gel. "
gameforge.locale.skill_group.dialog_warrior_4 = "Burada savascilara Chi kullanimi ogretiliyor.[ENTER]Tekrarlamasi biraz daha yavas ve zihinsel olarak[ENTER]yorucu olan yakin dovusu ogreniyorlar. Ayni[ENTER]zamanda bu saldirilar cok guclu ve etkili.[ENTER]Adanmisligina gore Ruhani Dovus Becerileri[ENTER]savasta ortaya cikar. Ruhani Dovusle ilgileniyor[ENTER]musun? "
gameforge.locale.skill_group.dialog_warrior_5 = "Beden dovusu ile Ruhani dovus arasinda sec, ve[ENTER]sectigin becerileri alacaksin. "
gameforge.locale.skill_group.invite = "Ise alim bildirimi: "
gameforge.locale.skill_group.lets_join_skill_group_1 = "[COLOR r;1|g;0.6|b;0.6]Savasci Ise Alim[ENTER]Bildirimi[/COLOR][ENTER]Savascinin hizina ve tekrarlanabilir saldiri[ENTER]bilgisine hayransan, Beden Dovusunu ogrenmelisin.[ENTER]Tek vurusla tum bir canavar grubunu oldurmek[ENTER]istiyorsan, Ruhani Dovusu ogrenmelisin.[ENTER][ENTER]Seni sehirdeki meydanda bekliyoruz. "
gameforge.locale.skill_group.lets_join_skill_group_2 = "[COLOR r;1|g;0.6|b;0.6]Ninja Ise Alim[ENTER]Bildirimi[/COLOR][ENTER]Kendini en iyi okcu olarak adlandirmak[ENTER]istiyorsan, Yay Egitimini secmelisin. Gizli[ENTER]gorevlere hazirsan, Kilic Egitimi senin icin[ENTER]uygun olacak.[ENTER][ENTER]Seni sehirdeki meydanda bekliyoruz. "
gameforge.locale.skill_group.lets_join_skill_group_3 = "[COLOR r;1|g;0.6|b;0.6]Sura Ise Alim[ENTER]Bildirimi[/COLOR][ENTER]Gercek bir Diplomat ve Sovalye, super insan[ENTER]olabilecek biri mi olmak istiyorsun? Silah[ENTER]sanatini ogren. Karanligin Buyucusu gibi korku[ENTER]sacmak ve Lanet Okumak istiyorsan, Kara Buyu[ENTER]sanatini ogren.[ENTER][ENTER]Seni sehirdeki meydanda bekliyoruz. "
gameforge.locale.skill_group.lets_join_skill_group_4 = "[COLOR r;1|g;0.6|b;0.6]Saman Ise Alim[ENTER]Bildirimi[/COLOR][ENTER]Bir Buyucu olmak, Muskalari efsanevi mistikler[ENTER]ve kutsanmislar kadar iyi kullanmayi bilmek[ENTER]istiyorsan, Ejderha Gucu yolunu izlemelisin.[ENTER]Yenilenme ve iyilestirmeyle yaralarin acisini[ENTER]dindirmek istiyorsan, Iyilestirme Gucunu[ENTER]ogrenmelisin.[ENTER][ENTER]Seni sehirdeki meydanda bekliyoruz. "
