gameforge.main_quest_flame_lv100 = {}
gameforge.main_quest_flame_lv100._010_sendLetter = "Kara Madde "
gameforge.main_quest_flame_lv100._020_say = "Yak-Hwan seni ariyor. Lutfen, ona git. "
gameforge.main_quest_flame_lv100._030_say = "Merhaba. Yon-I-Walker arastirmasini tamamladi.[ENTER]Atesli Toprak'ta gozlemlemeyi basardigin bu[ENTER]fenomen Kara Madde olarak adlandiriliyor. "
gameforge.main_quest_flame_lv100._040_say = "Kaleden yayiliyor ve cevredeki seytanlari[ENTER]donusturuyor. Etkisi altinda ne kadar cok[ENTER]kalirlarsa, o kadar guclu ve saldirgan oluyorlar.[ENTER]Kara Madde'nin yayilmasini onlemeliyiz. "
gameforge.main_quest_flame_lv100._050_say = {}
gameforge.main_quest_flame_lv100._060_say = "Simyacimiz bir cozum ararken kollarimizi[ENTER]kavusturup oturamayiz. Atesli Toprak'a geri don[ENTER]ve kalenin yakininda dolasan 300 seytani oldur. "
gameforge.main_quest_flame_lv100._070_say = "Elbette. "
gameforge.main_quest_flame_lv100._080_say = "Tesekkur ederim. Simdi acele et! "
gameforge.main_quest_flame_lv100._090_notice = "Kalenin yakininda ve Gunes Otlari'nin yetistigi[ENTER]yerde dolasan 300 Atesli Toprak seytanini yok et. "
gameforge.main_quest_flame_lv100._100_sayTitle = "Seytan Avi "
gameforge.main_quest_flame_lv100._110_say = "Kalenin yakininda ve Gunes Otlari'nin bulundugu[ENTER]yerde 300 Atesli Toprak seytanini hallet "
gameforge.main_quest_flame_lv100._120_say = "Korkarim henuz yeterli seytan oldurmedin. Atesli[ENTER]Toprak'a geri don ve savasmaya devam et. "
gameforge.main_quest_flame_lv100._130_notice = "Tum seytanlari yendin.[ENTER]Simdi Yak-Hwan'a rapor ver. "
gameforge.main_quest_flame_lv100._140_say = "Yak-Hwan'i ara. "
gameforge.main_quest_flame_lv100._150_say = "Cok iyi. Kara Madde'nin yayilmasini[ENTER]durdurmalisin.[ENTER]Dinlen, bu sirada ben simyaciyla konusacagim. "
gameforge.main_quest_flame_lv100._160_sendLetter = "Yagmur Yagi "
gameforge.main_quest_flame_lv100._170_say = "Simyaci seni ariyor. Sanirim seninle acil bir[ENTER]meselesi var! "
gameforge.main_quest_flame_lv100._180_say = "Felaket! Yak-Hwan'a dikkatli hareket etmesini[ENTER]soylemistim. Peki o ne yapiyor? Kilicla saldirip[ENTER]bizi inanilmaz bir kaosa surukluyor! Konagi[ENTER]olurse Kara Madde'nin cok daha hizli buyuyup[ENTER]yayilacagini bilmiyordu. Ve simdi ogreniyorum ki[ENTER]zaten 300 enfekte seytan oldurulmus! Bu iyi[ENTER]degil... "
gameforge.main_quest_flame_lv100._190_say = "Bu kosullar altinda Kara Madde'yi buyulemek icin[ENTER]Yagmur Yagi'm bile yetmiyor. Daha fazla uretmek[ENTER]icin malzemelere kesinlikle ihtiyacim var. "
gameforge.main_quest_flame_lv100._200_say = {}
gameforge.main_quest_flame_lv100._210_say = "Bana 10 Kose Tasi, 50 Ayi Safrasi, 10 Orumcek[ENTER]Zehri Torbasi ve 200 Enerji Parcasi getir.[ENTER]Boyle tecrubeli bir savasciya bu malzemeleri[ENTER]nerede bulacagini aciklamama gerek yok, degil mi? "
gameforge.main_quest_flame_lv100._220_say = "Hemen yola cikiyorum. "
gameforge.main_quest_flame_lv100._230_say = "Harika. Acele et, cunku Kara Madde her dakika[ENTER]daha da yayiliyor. "
gameforge.main_quest_flame_lv100._240_notice = "Simyacinin Yagmur Yagi'ni yapabilmesi icin[ENTER]malzemeleri topla "
gameforge.main_quest_flame_lv100._250_say = "Kalan Malzemeler "
gameforge.main_quest_flame_lv100._260_sayTitle = "Yagmur Yagi "
gameforge.main_quest_flame_lv100._270_say = "10 Kose Tasi, 50 Ayi Safrasi, 10 Orumcek Zehri[ENTER]Torbasi ve 200 Enerji Parcasi topla. Tum bu[ENTER]malzemeleri simyaciya gotur. "
gameforge.main_quest_flame_lv100._280_say = "Tum malzemeleri bulmayi basardin.[ENTER]Mukemmel! Simdi ise koyulayim. Yagmur Yagi hazir[ENTER]oldugunda haber verecegim. "
gameforge.main_quest_flame_lv100._290_say = "Kara Madde'yi yakinda durdurmazsak, kotu[ENTER]olacak. Hadi! Yagmur Yagi yapmak icin gereken[ENTER]tum malzemeleri getir bana. "
gameforge.main_quest_flame_lv100._300_notice = "Tum malzemeleri toplamayi basardin.[ENTER]Simdi simyaciya geri don. "
gameforge.main_quest_flame_lv100._310_say = "Simyaciyla konus. "
gameforge.main_quest_flame_lv100._320_sendLetter = "Kara Madde'yi Durdur "
gameforge.main_quest_flame_lv100._330_say = "Ne inatci yasli adam... e, bosuna konusmusum.[ENTER]Kose Taslari cok kalin ogutuldugu icin demirciye[ENTER]sikayet ettim. Simdi alindi ve kalan taslari toz[ENTER]haline getirmek istemiyor. Onunla konus, belki[ENTER]seni dinler? "
gameforge.main_quest_flame_lv100._340_say = "Tabii. "
gameforge.main_quest_flame_lv100._350_say = "Tesekkurler, iste Temel Taslari. Ve ozur olarak[ENTER]ona bu lezzet sepetini gotur "
gameforge.main_quest_flame_lv100._360_sayTitle = "Demirciyi Yumusat "
gameforge.main_quest_flame_lv100._370_say = "Demirciyi yumusat ve Kose Taslarini toz haline[ENTER]getirmesi icin onu ikna et. "
gameforge.main_quest_flame_lv100._380_say = "Kose Tasi Tozu: 1 adet "
gameforge.main_quest_flame_lv100._390_say = "Sana nasil hizmet edebilirim? Kilicini bileyeyim[ENTER]mi? Yoksa zirhini mi parlatayim? "
gameforge.main_quest_flame_lv100._400_say = "Hayir, bugun degil. Simyaci sert sozleri icin[ENTER]ozur dilemek ve onun adina bu lezzet sepetini[ENTER]vermek istedigi icin buradayim. "
gameforge.main_quest_flame_lv100._410_say = "Bu nankor kibirliye isteksizce iyilik yapiyorum[ENTER]ama senin icin yapacagim ve taslari toz haline[ENTER]getirecegim. Bir dakika bekle. "
gameforge.main_quest_flame_lv100._420_say = "Tesekkurler! "
gameforge.main_quest_flame_lv100._430_say = "Demirci inatci olursa, ona bu sepeti ver ve[ENTER]yardim iste. Sana kesinlikle hayir demez. "
gameforge.main_quest_flame_lv100._440_notice = "Kose Tasi Tozu hazir. Onu simyaciya gotur. "
gameforge.main_quest_flame_lv100._450_say = "Oh, bebek pudrasi gibi guzel, mukemmel. Demek o[ENTER]inatci yasli adam yapabiliyormus hehe. Simdi[ENTER]Yagmur Yagi'ni karistirabilirim. Biraz dinlen.[ENTER]Hazir oldugunda seni cagiracagim. "
