gameforge.main_quest_flame_lv101._110_say = "Kaleye gir ve icindeki seytanlari yen. Karanlik[ENTER]Vasallarinin entrikalarina ve kayip izciye dair[ENTER]ipuclari ara. "
gameforge.main_quest_flame_lv101._120_sayReward = "Bu zindana tek basina giremezsin. Gecmek icin bir[ENTER]grup kur. Baska bir gecis izni almayacaksin. "
gameforge.main_quest_flame_lv101._130_say = "Kalenin icine girmeyi basardin mi? Orada[ENTER]Karanlik Vasallarinin entrikalarina dair ipuclari[ENTER]ve izcimin orada bulunduguna dair izler olmali!Atesli Toprak'a tekrar git ve kaleyi arastir. "
gameforge.main_quest_flame_lv101._140_say = "Izci bir suredir olu. Cebinde bir mektup[ENTER]bulacaksin. Onu Yak-Hwan'a gotur. "
gameforge.main_quest_flame_lv101._150_notice = "Izci Yak-Hwan'i bulmayi basardin "
gameforge.main_quest_flame_lv101._160_say = "Herhangi bir haberin var mi "
gameforge.main_quest_flame_lv101._170_say = {}
gameforge.main_quest_flame_lv101._180_say = "Yuzunden iyi haberler getirmedigin belli. Bundan[ENTER]korkuyordum. Yaninda bir mektup mu vardi? Goster.[ENTER]Bu kalede Karanlik Vasallarinin entrikalarina[ENTER]dair bir ipucu olmali.[ENTER]Oraya geri don ve ara. Bu mektubu sonra okuruz. "
gameforge.main_quest_flame_lv101._190_notice = "Ne? Karanlik Vasallarina ait Suslu Kolyeyi mi[ENTER]buldun? Onu Yak-Hwan'a goster. "
gameforge.main_quest_flame_lv101._200_say = "Bu cok ilginc. Demek bu Suslu Kolye gercekten[ENTER]Karanlik Vasallarina ait. Belki entrikalarina[ENTER]dair bir ipucu iceriyor! Ne, izcimden hic iz yok[ENTER]mu? Pes etme, aramaya devam et. O bu kalede[ENTER]olmali. "
gameforge.main_quest_flame_lv101._210_notice = "Hem Suslu Kolyeyi hem de izciyi bulmayi[ENTER]basardin. Simdi Yak-Hwan'a rapor ver. "
gameforge.main_quest_flame_lv101._220_say = "Yak-Hwan'a rapor ver. "
gameforge.main_quest_flame_lv101._230_say = "Demek basardin! Bu Suslu Kolye Karanlik[ENTER]Vasallarina ait. Planlarina dair gizli bir ipucu[ENTER]icerdigine kellemi koyarim. Peki bu ne? Izcimin[ENTER]yazdigi bir mektup mu? Goster. "
gameforge.main_quest_flame_lv101._240_say = {}
gameforge.main_quest_flame_lv101._250_say = "Izcimin bana biraktigi bir mektup. Sarsildim.[ENTER]Son sozlerini birlikte okuyalim "
gameforge.main_quest_flame_lv101._260_sayTitle = "Aceleyle yazilmis sozler: "
gameforge.main_quest_flame_lv101._270_say = "Sevgili Yak-Hwan, eve canli donemeyecegim, ama[ENTER]umarim bu mektup en azindan senin ellerine[ENTER]ulasir. Atesli Toprak'ta hicbir haritada[ENTER]isaretlenmemis bir kale kesfettim. Kalenin efendisi[ENTER]ve hakimi, olaganustu bir aurayla cevrili guclu[ENTER]bir Atesli Toprak seytani. Kukremesi sagir edici[ENTER]ve bana oyle geliyor ki cok onemli bir seyi[ENTER]koruyor olmali. Ama ne oldugunu ne yazik ki[ENTER]ogrenemedim. Affet, seni hayal kirikligina[ENTER]ugrattim... "
gameforge.main_quest_flame_lv101._280_say = "Bu kalede neyin saklandigini kesinlikle ogrenmeliyiz.[ENTER]Bak, Suslu Kolyenin icinde bir oyma var.[ENTER]Yon-I-Walker'dan tavsiye isteyecegim. Yardimina[ENTER]ihtiyaci oldugunda sana haber verecek. "
gameforge.main_quest_flame_lv101._290_sendLetter = "Oymayi Coz "
gameforge.main_quest_flame_lv101._300_say = "Yon-I-Walker seni ariyor. Ona git. "
gameforge.main_quest_flame_lv101._310_say = "Hos geldin, seni zaten bekliyordum. Bu kolyedeki[ENTER]oymayi cozmek icin biraz yardima ihtiyacim var "
gameforge.main_quest_flame_lv101._320_say = {}
gameforge.main_quest_flame_lv101._330_say = "Suslu Kolye'deki oyulmus harfler, coktan yok olmus[ENTER]kadim bir kulture ait. Onlari cozmek icin Atesli[ENTER]Kral'in Kanina ihtiyacim var. Bu kan lavdan daha[ENTER]sicak. "
gameforge.main_quest_flame_lv101._340_say = "Onu sana getirecegim. "
gameforge.main_quest_flame_lv101._350_say = "Kani aldiginda, mumkun oldugunca cabuk bana geri[ENTER]donmelisin. Cunku bu kap bile sicakligina ancak[ENTER]sinirli bir sure hasarsiz dayanabilir "
gameforge.main_quest_flame_lv101._360_notice = "Atesli Kral'in Kanini elde et. "
gameforge.main_quest_flame_lv101._370_say = "Atesli Kral'in Kani olmadan oymayi okuyamayiz! "
gameforge.main_quest_flame_lv101._380_notice = "Atesli Kral'in Kanini elde etmeyi basardin.[ENTER]Simdi Yon-I-Walker'a geri don. "
gameforge.main_quest_flame_lv101._390_say = "Yon-I-Walker'la konus. "
gameforge.main_quest_flame_lv101._400_say = "Mukemmel! Bu kanin yardimiyla oymayi okuyabilecegim.[ENTER]Ama biraz zaman alir. O halde yarin gel. "
gameforge.main_quest_flame_lv101._410_say = "Biraz daha sabret, saat ve dakika "
gameforge.main_quest_flame_lv101._420_say = "Daha fazla zamana ihtiyacim var. Sonra gel! "
gameforge.main_quest_flame_lv101._430_sendLetter = "Oyma "
gameforge.main_quest_flame_lv101._440_say = "Iste, tam zamaninda geliyorsun.[ENTER]Suslu Kolye'deki oymayi cozdum. "
gameforge.main_quest_flame_lv101._450_say = "Bize, Karanligin Hizmetkarlarinin, gizli bir yerde[ENTER]tutsak edilen Alti Ejderha'nin arkasindaki kapi[ENTER]muhurlerini eritmek icin en guclu Atesli Toprak[ENTER]seytanlarindan birini gonderdigini ortaya koyuyor.[ENTER]Ozel bir ergitme firinindan da bahsediliyor. Her[ENTER]seyi Yak-Hwan icin bu yazida kaydettim. Lutfen[ENTER]ona gotur "
gameforge.main_quest_flame_lv101._460_say = {}
gameforge.main_quest_flame_lv101._470_notice = "Yon-I-Walker'in mektubunu Yak-Hwan'a gotur "
gameforge.main_quest_flame_lv101._480_sayTitle = "Yak-Hwan icin Posta "
gameforge.main_quest_flame_lv101._490_say = "Yon-I-Walker'in mektubunu Yak-Hwan'a gotur "
gameforge.main_quest_flame_lv101._500_say = "Yon-I-Walker oymayi okuyabildi mi? Oh, ondan tum[ENTER]bilgileri iceren bir mektup. Cok iyi, goster "
gameforge.main_quest_flame_lv101._510_say = "Aha... Buyuk Ejderhalarin Muhru. Bana oyle geliyor[ENTER]ki kesfettigimiz kale efsanevi Kizil Ejderha[ENTER]Kalesi! Soylentiye gore orada, Gece Incilerini[ENTER]elde etmek icin Karanlik Vasallarinin oldurmesi[ENTER]gereken ejderhalardan biri hapsedilmis. Lutfen, bu[ENTER]Gecis Iznini al, ama iyi sakla. Yakinda kesinlikle[ENTER]ihtiyacin olacak... "
gameforge.main_quest_flame_lv101._520_say = "Atesli Kral'i oldur ve yanan kanini topla "
gameforge.main_quest_flame_lv101._530_say = {}
gameforge.main_quest_flame_lv102 = {}
gameforge.main_quest_flame_lv102._010_sendLetter = "Kaleye Baskin "
gameforge.main_quest_flame_lv102._020_say = "Yak-Hwan seni ariyor. Muhtemelen sana bundan[ENTER]sonraki planlari anlatmak istiyor. "
gameforge.main_quest_flame_lv102._030_say = "Kizil Ejderha Kalesi'ni barikatladik. Bu sekilde[ENTER]enfekte seytanlar disari cikamayacak ve boylece[ENTER]Kara Madde'nin daha fazla yayilmasini[ENTER]onleyecegiz. "
gameforge.main_quest_flame_lv102._040_say = "Gorevin simdi kaleye baskin yapmak, mumkun[ENTER]oldugunca cok seytani etkisiz hale getirmek ve[ENTER]icinde gercekten efsanevi Kizil Ejderha'nin[ENTER]hapsedilip hapsedilmedigini ogrenmek olacak "
gameforge.main_quest_flame_lv102._050_say = "Kabul. "
gameforge.main_quest_flame_lv102._060_say = "30 seytani hallet ve bunun kaniti olarak bana[ENTER]seytan pencelerini getir "
gameforge.main_quest_flame_lv102._070_notice = "30 seytani hallet ve kanit olarak Yak-Hwan'a[ENTER]seytan pencelerini gotur "
gameforge.main_quest_flame_lv102._080_sayTitle = "Kizil Ejderha Kalesine Baskin Yap! "
gameforge.main_quest_flame_lv102._090_say = "Kizil Ejderha Kalesi'nde 30 seytani yen ve kanit[ENTER]olarak Yak-Hwan'a seytan pencelerini gotur "
gameforge.main_quest_flame_lv102._100_say = "Seytan pencesi: adet Seytan pencesi: adet "
gameforge.main_quest_flame_lv102._110_say = "Zirh parcasi: adet Silah parcasi: adet "
gameforge.main_quest_flame_lv102._120_say = "Henuz yeterli seytan yenmedin. Toplamda 30 tanesini[ENTER]hallet ve kanit olarak bana seytan pencelerini getir "
gameforge.main_quest_flame_lv102._130_notice = "Tum Atesli Toprak Seytanlarini yenmeyi[ENTER]basardin. Simdi Yak-Hwan'a rapor ver. "
gameforge.main_quest_flame_lv102._140_say = "Yon-I-Walker'a git. "
gameforge.main_quest_flame_lv102._150_say = "Geri dondun - ve goruyorum ki basarmayi[ENTER]basardin! Nasil gecti anlat bana? "
gameforge.main_quest_flame_lv102._160_say = {}
gameforge.main_quest_flame_lv102._170_say = "Guclu bir ates seytani oldugunu mu soyluyorsun? O[ENTER]Razador'di, atesin efendisi! Karanlik Vasallari onu[ENTER]gonderdiyse, kalede cok onemli bir sey olmali.[ENTER]Efsanevi Kizil Ejderha olmasi oldukca mumkun![ENTER]Simdi danismanlarimla konusmaliyim.[ENTER]Lutfen, bu Gecis Iznini al ve goz bebegin gibi[ENTER]koru. Kesinlikle ona ihtiyacin olacak. "
gameforge.main_quest_flame_lv102._180_sendLetter = "Razador "
gameforge.main_quest_flame_lv102._190_say = "Yon-I-Walker seni ariyor. Detaylari ogrenmek icin[ENTER]ona git. "
gameforge.main_quest_flame_lv102._200_say = "Korkunc Razador'la karsilasmayi hayatta[ENTER]atlatmayi basardin. Onunde egiliyorum. "
gameforge.main_quest_flame_lv102._210_say = {}
gameforge.main_quest_flame_lv102._220_say = "Atesin Efendisi, Buz Krali Alastor'la birlikte[ENTER]insanligin bildigi en tehlikeli ve olumcul yeralti[ENTER]yaratiklarindan biri. Kara Madde'nin kaynaginin[ENTER]bizzat Razador olmasi oldukca mumkun. "
gameforge.main_quest_flame_lv102._230_say = {}
gameforge.main_quest_flame_lv102._240_say = {}
gameforge.main_quest_flame_lv102._250_say = "Ve tam da bu, onu olaganustu guclu bir rakip[ENTER]yapiyor. Once Kizil Ejderha Kalesi'ndeki daha[ENTER]kucuk seytanlari oldur ve bedenlerinden Kara[ENTER]Madde'yi cikar. 10 adet yeterli olmali. Belki bu[ENTER]sekilde, Razador'la yolumuz kesismeden once[ENTER]guclerini etkisiz hale getirecek bir cozum[ENTER]buluruz. "
gameforge.main_quest_flame_lv102._260_say = "O halde ise koyulalim! "
gameforge.main_quest_flame_lv102._270_notice = "Kizil Ejderha Kalesi'ndeki Atesli Toprak[ENTER]Seytanlarini yen. "
gameforge.main_quest_flame_lv102._280_sayTitle = "Madde Kureleri "
gameforge.main_quest_flame_lv102._290_say = "Kizil Ejderha Kalesi'ne saldir, Atesli Toprak[ENTER]Seytanlarini yen ve 10 birim Kara Madde elde et. "
gameforge.main_quest_flame_lv102._300_sayReward = "Kizil Ejderha Kalesi'nin duvarlarini asmak icin,[ENTER]bir gruba ve gecis iznine ihtiyacin var. "
gameforge.main_quest_flame_lv102._310_say = "Bu yeterli degil. Arastirma icin 10 birim Kara[ENTER]Madde'ye ihtiyacim var. "
gameforge.main_quest_flame_lv102._320_notice = "10 birim Kara Madde elde etmeyi basardin.[ENTER]Onlari Yon-I-Walker'a gotur. "
gameforge.main_quest_flame_lv102._330_say = "Kara Madde'yi gormek bile tuylerimi diken diken[ENTER]ediyor! Tamam, simdi ise koyuluyorum...[ENTER]Hazir oldugumda haber verecegim. "
gameforge.main_quest_flame_lv102._340_say = {}
gameforge.main_quest_flame_lv102._350_sendLetter = "Kara Madde'yi Etkisiz Hale Getirme "
gameforge.main_quest_flame_lv102._360_say = "Iyi haberlerim var! Kara Madde'nin gucunu nasil[ENTER]etkisiz hale getirebilecegimizi ogrendim. "
gameforge.main_quest_flame_lv102._370_say = {}
gameforge.main_quest_flame_lv102._380_say = "Dogadaki tum guclerin bir dengeleyicisi vardir -[ENTER]isik ve karanlik, ates ve su, iyi ve kotu. Kara[ENTER]Madde'nin de onu etkisiz hale getirebilecek bir[ENTER]zitti var - bu da Saf Isik. "
gameforge.main_quest_flame_lv102._390_say = "Saf Isik uretmek icin, bir Enerji Parcasini Mong[ENTER]Suyu'nda eritmek gerekiyor. 50 sise Mong Suyu ve[ENTER]100 Enerji Parcasi topla, hepsini Yu-Hwan'a[ENTER]gotur. "
gameforge.main_quest_flame_lv102._400_say = "Memnuniyetle! "
gameforge.main_quest_flame_lv102._410_notice = "50 sise Mong Suyu ve 100 Enerji Parcasi topla.[ENTER]Sonra hepsini Yu-Hwan'a gotur. "
gameforge.main_quest_flame_lv102._420_sayTitle = "Saf Isik "
gameforge.main_quest_flame_lv102._430_say = "50 sise Mong Suyu ve 100 Enerji Parcasi topla.[ENTER]Sonra hepsini Yu-Hwan'a gotur. "
gameforge.main_quest_flame_lv102._440_say = "Yon-I-Walker bana gelecegini soyledi.[ENTER]Tamam, simdi sohbetin sirasi degil, kollari[ENTER]sivayip ise koyulma zamani. Sen bu sirada biraz[ENTER]dinlenebilirsin. "
gameforge.main_quest_flame_lv102._450_say = "Yon-I-Walker bana gelecegini soyledi.[ENTER]Ise koyulurdum ama Saf Isik uretmek icin tum[ENTER]malzemelere henuz sahip degilim. Git ve daha fazlasini[ENTER]bul. "
gameforge.main_quest_flame_lv102._460_notice = "Yeterli miktarda Mong Suyu ve Enerji Parcasi[ENTER]toplamayi basardin. Onlari Yu-Hwan'a gotur. "
gameforge.main_quest_flame_lv102._470_say = "Yu-Hwan'a git. "
gameforge.main_quest_flame_lv102._480_sendLetter = "Saf Isigi Teslim Et "
gameforge.main_quest_flame_lv102._490_say = "Yu-Hwan Saf Isigi uretti. Ona git. "
gameforge.main_quest_flame_lv102._500_say = "Sensin! Tam zamaninda. Saf Isik hazir.[ENTER]Bunu Yak-Hwan'a ver. "
gameforge.main_quest_flame_lv102._510_say = {}
gameforge.main_quest_flame_lv102._520_say = {}
gameforge.main_quest_flame_lv102._530_say = {}
gameforge.main_quest_flame_lv102._540_notice = "Saf Isikla Yak-Hwan'a geri don "
gameforge.main_quest_flame_lv102._550_say = "Hala buradasin. Cok acele ediyor. Saf Isigi[ENTER]Yak-Hwan'a gotur "
gameforge.main_quest_flame_lv102._560_say = "Ah, hos geldin. Saf Isik yaninda. Muhtesem "
gameforge.main_quest_flame_lv102._570_say = {}
gameforge.main_quest_flame_lv102._580_say = "Fena degil! Bu sayede Kizil Ejderha Kalesi[ENTER]savasinda kolumuzda bir kozumuz var. Simdi[ENTER]dinlen, ben birlikleri toplayacagim. "
