gameforge.main_quest_flame_lv103._020_say = "Yak-Hwan seni gormek istiyor. Savasa cikmadan[ENTER]once ondan son talimatlari alacaksin. "
gameforge.main_quest_flame_lv103._030_say = "Zaman geldi. Savas basladi. Kizil Ejderha[ENTER]Kalesi'ne bir birlik gonderdim.[ENTER]Tum askerler Saf Isikla donatildi. Duyulari[ENTER]inanilmaz derecede keskinlesti. Etki muhtesem! "
gameforge.main_quest_flame_lv103._040_say = "Onlari takip et ve Kizil Ejderha Kalesi'nde[ENTER]bulus. Komutani ara. Sana saldiri planini[ENTER]anlatacak "
gameforge.main_quest_flame_lv103._060_say = "Kendine dikkat et. "
