gameforge.main_quest_flame_lv103._080_sayTitle = "Kaleye! "
gameforge.main_quest_flame_lv103._090_say = "Saldiri birligini takip ederek Kizil Ejderha[ENTER]Kalesi'ne git ve komutani ara "
gameforge.main_quest_flame_lv103._100_say = "Hala burada misin? Hadi, askerlerin pesinden[ENTER]Kizil Ejderha Kalesi'ne git. "
gameforge.main_quest_flame_lv103._110_say = "Iyi ki buradasin. Fark edildik ve planlanandan[ENTER]daha erken kaleye baskin yapmak zorunda kaldik.[ENTER]Ilk basta iyi gitti ama sonra Razador'a karsi[ENTER]sansimiz yoktu, tum tabur dustu. Sonuncu benim.[ENTER]Yak-Hwan'a rapor verebilir misin? Tesekkurler "
gameforge.main_quest_flame_lv103._120_say = "Kizil Ejderha Kalesi'ndeki olaylari Yak-Hwan'a[ENTER]anlat. "
gameforge.main_quest_flame_lv103._130_say = "Geri mi dondun zaten? Ne... ne oldu? Konus! "
gameforge.main_quest_flame_lv103._140_say = {}
gameforge.main_quest_flame_lv103._150_say = "Tum tabur mu dustu? Oh, hayir... bu benim[ENTER]hatam. Aceleyle saldirdik ve askerlerim bunun[ENTER]bedelini hayatlariyla odedi. "
gameforge.main_quest_flame_lv103._160_say = {}
gameforge.main_quest_flame_lv103._170_say = "Stratejiyi tekrar dusunmeliyiz. Kesinlikle bu[ENTER]seytani yok etmenin baska bir yolu olmali.[ENTER]Hazirlan. Bir plan buldugumda seni cagiracagim. "
gameforge.main_quest_flame_lv103._180_sendLetter = "Adim Adim "
gameforge.main_quest_flame_lv103._190_say = "Iyi ki buradasin. Razador'a tekrar saldirmadan[ENTER]once, onu zayiflatmak icin once tum gucumuzle[ENTER]seytanlara vurmaya karar verdik. "
gameforge.main_quest_flame_lv103._200_say = "Adamlarim Kizil Ejderha Kalesi'nin kapilarinda[ENTER]nobet tutup disari firlayan tum dusmanlari[ENTER]etkisiz hale getirirken sen iceri girip icindeki[ENTER]Alevli Seytanlarla savasacaksin. Saf Isik seni[ENTER]Kara Madde'nin etkisinden koruyacak ve gucunu[ENTER]etkisiz hale getirecek "
gameforge.main_quest_flame_lv103._210_say = "1000 Alevli Seytani yenmeyi basarirsan, Razador[ENTER]etrafindaki savunma hatlarini ciddi sekilde[ENTER]zayiflatacaksin "
gameforge.main_quest_flame_lv103._220_say = "Silahlara saril! "
gameforge.main_quest_flame_lv103._230_notice = "Kizil Ejderha Kalesi'ne saldir ve 1000 Atesli[ENTER]Seytani yen. "
gameforge.main_quest_flame_lv103._240_sayTitle = "Adim 1: 1000 seytan "
gameforge.main_quest_flame_lv103._250_say = "Kizil Ejderha Kalesi'ne saldir ve 1000 Atesli[ENTER]Seytani yen. "
gameforge.main_quest_flame_lv103._260_sayReward = "Bir gruba ve gecis iznine ihtiyacin var "
gameforge.main_quest_flame_lv103._270_say = "Seytanlarin savunma hatti hala cok guclu. Daha[ENTER]fazla seytan yen. Sana guveniyoruz! "
gameforge.main_quest_flame_lv103._280_notice = "1000 Atesli Seytani yenmeyi basardin.[ENTER]Bunu Yak-Hwan'a bildir. "
gameforge.main_quest_flame_lv103._290_say = "Iyi is cikardin. Alevli Seytanlarin savunma[ENTER]hatlari senin sayende ciddi sekilde zayifladi.[ENTER]Bir dakika bekle, bu arada stratejistlerimle[ENTER]bir sonraki adimi istisare edecegim "
gameforge.main_quest_flame_lv103._300_sendLetter = "Adim 2 "
