gameforge.main_quest_flame_lv103._340_sayTitle = "Adim 2 "
gameforge.main_quest_flame_lv103._350_say = "Tekrar Kizil Ejderha Kalesi'ne gir ve sirasiyla[ENTER]50'ser Atesli Kral, Atesli Sakal, Atesli Golem,[ENTER]Atesli General ve Atesli Prens yen "
gameforge.main_quest_flame_lv103._360_say = "Seytan ordusu hala cok guclu. Yeterli sayida[ENTER]yuksek rutbeli Atesli Toprak Seytani yenmedin.[ENTER]Kaleye geri don ve savasa devam et! "
gameforge.main_quest_flame_lv103._370_notice = "Yuksek rutbeli Atesli Toprak Seytanlarini[ENTER]yenmeyi basardin. Bunu Yak-Hwan'a bildir. "
gameforge.main_quest_flame_lv103._380_say = "Muhtesem! Atesli Toprak Seytanlarinin saflarini[ENTER]ciddi sekilde zayiflattik ve simdi askerlerim[ENTER]sonunda Kizil Ejderha Kalesi'ne baskin[ENTER]yapabilir.[ENTER]Aferin sana! Bir haberim oldugunda sana[ENTER]bildirecegim. "
gameforge.main_quest_flame_lv103._390_sendLetter = "Razador "
gameforge.main_quest_flame_lv103._400_say = "Askerlerim Kizil Ejderha Kalesi'ne girmeyi[ENTER]basardi. Bu kadar cok seytani yenmeyi basardigin[ENTER]icin, kayiplarimiz sinirli kaldi. Yon-I-Walker[ENTER]sana bundan sonraki stratejimizi anlatacak. Ona[ENTER]git. "
gameforge.main_quest_flame_lv103._410_notice = "Yon-I-Walker'a git ve strateji hakkindaki[ENTER]tavsiyelerini dinle. "
gameforge.main_quest_flame_lv103._420_say = "Yon-I-Walker'a git ve strateji hakkindaki[ENTER]tavsiyelerini dinle. "
