gameforge.main_quest_flame_lv104._150_say = {}
gameforge.main_quest_flame_lv104._160_say = "Ne demek istiyorsun? Kizil Ejderha Razador'u[ENTER]tekrar mi diriltecek? Bu nasil mumkun olur?[ENTER]Buyuk ejderhalar hakkinda cok fazla sey[ENTER]bilmiyoruz... ama gorunuse gore gucleri devasa. "
gameforge.main_quest_flame_lv104._170_sendLetter = "Planlari Bozma I "
gameforge.main_quest_flame_lv104._180_say = "Kotu haber! Razador, Kizil Ejderha'nin gucu[ENTER]sayesinde yeniden canlandi. Bu yuzden daha da[ENTER]guclendi. Gorunuse gore Kara Madde'nin etkisi de[ENTER]daha yogunlasmis. "
