gameforge.main_quest_flame_lv104._200_notice = "Yon-I-Walker'a git ve Razador'u kalici olarak[ENTER]nasil yenecegini ogren. "
gameforge.main_quest_flame_lv104._210_sayTitle = "Yon-I-Walker'la konus. "
gameforge.main_quest_flame_lv104._220_say = "Yon-I-Walker'a git ve Razador'u kalici olarak[ENTER]nasil yenecegini ogren. "
gameforge.main_quest_flame_lv104._230_say = "Henuz Yon-I-Walker'a gitmedin mi? O halde[ENTER]Razador'u nasil yenmek istiyorsun? Yola cik,[ENTER]neyi bekliyorsun! "
gameforge.main_quest_flame_lv104._240_say = "Evet, bu dogru. Razador geri dondu - oncekinden[ENTER]bile daha kotu bir ruh haliyle. Karanlik[ENTER]Vasallarini durdurmak icin bize sadece bir[ENTER]secenek kaldi... "
gameforge.main_quest_flame_lv104._250_say = "Razador, gorevini tamamlayip Kizil Ejderha'yi[ENTER]serbest birakana kadar dinlenmeyecek. Bunu[ENTER]onlemek icin, ejderhayi surgun etmeliyiz. "
gameforge.main_quest_flame_lv104._260_say = {}
gameforge.main_quest_flame_lv104._270_say = "Kizil Ejderha'nin unsuru atestir ve atesle en iyi[ENTER]atesle savasilir. Her Alevli Seytan icinde bir[ENTER]Magma Cekirdegi tasir. Bana su canavarlardan[ENTER]beser cekirdek getir: Atesli Kral, Atesli Sakal,[ENTER]Atesli Golem, Atesli General ve Atesli Prens "
gameforge.main_quest_flame_lv104._280_notice = "Alevli Seytanlarin Magma Cekirdeklerini elde et "
gameforge.main_quest_flame_lv104._290_say = "Bu dusmanlardan beser Magma Cekirdegi topla:[ENTER]Atesli Kral, Atesli Sakal, Atesli Golem, Atesli[ENTER]General, Atesli Prens. Bunlarla Yon-I-Walker'a[ENTER]geri don. "
gameforge.main_quest_flame_lv104._300_say = "Oh evet, zaten birkac tane buldun. Biraz daha[ENTER]getir, o yeterli olmali "
gameforge.main_quest_flame_lv104._310_say = "Tamam, simdi tum Magma Halkalarina sahibim.[ENTER]Isleyebilmem icin biraz daha sogumalari gerekiyor.[ENTER]Yardimina ihtiyacim olursa, sana haber[ENTER]verecegim. "
gameforge.main_quest_flame_lv104._320_say = "Hm, bu Magma Halkalari cok soguk ve artik[ENTER]ise yaramaz. Bana yenilerini getir. "
gameforge.main_quest_flame_lv104._330_sendLetter = "Planlari Bozma II "
gameforge.main_quest_flame_lv104._340_say = "Yon-I-Walker seni ariyor. Ona git. "
gameforge.main_quest_flame_lv104._350_say = "Biraz daha bekleyecegim. Magma Halkalarinin ise[ENTER]koyulabilmem icin biraz sogumasi gerekiyor.[ENTER]Bu sirada bana biraz Dok Suyu getir.[ENTER]Magma Halkalarini cozmek icin ona ihtiyacim var. "
gameforge.main_quest_flame_lv104._360_say = "Bu Magma suspansiyonuyla Kizil Ejderha'yi surgun[ENTER]edebilecegiz. Yak-Hwan sana daha sonra tam[ENTER]proseduru anlatacak. Lutfen simdi bana 100 sise[ENTER]Dok Suyu getir. Ben burada devam ediyorum "
