gameforge.main_quest_flame_lv104._410_say = "Hala bir malzemeye daha ihtiyacim var, ama bu[ENTER]sonra... Simdi halkalari eritmeye odaklanmaliyim.[ENTER]Her sey plana gore gitmeli! Sonra sana haber[ENTER]verecegim. "
gameforge.main_quest_flame_lv104._420_say = "Bu 100 sise degil ki. Yuze kadar saymayi[ENTER]biliyor musun? Daha fazla Dok Suyuna ihtiyacim[ENTER]var. "
gameforge.main_quest_flame_lv104._430_notice = "100 sise Dok Suyu toplamayi basardin. Simdi[ENTER]Yon-I-Walker'a geri don. "
gameforge.main_quest_flame_lv104._440_say = "Yon-I-Walker'a git. "
