gameforge.main_quest_flame_lv104._460_say = "Suspansiyonla iyi ilerliyorum. Ama bir kez daha[ENTER]yardimina ihtiyacim var "
gameforge.main_quest_flame_lv104._470_say = "Simdi surgun buyusu icin uygun bir kaba ihtiyacim[ENTER]var. Mantikor lideri Martyaxwar'in kanat derisi[ENTER]isimizi gorur. Bes parca bul "
gameforge.main_quest_flame_lv104._480_notice = "Yon-I-Walker'a Martyaxwar'in kanat derisinden[ENTER]bes parca getir "
gameforge.main_quest_flame_lv104._490_say = "Yon-I-Walker'a Martyaxwar'in kanat derisinden[ENTER]iyi kalitede bes parca getir "
