gameforge.main_quest_lv10._10_sendLetter = "Kaptan'a git. "
gameforge.main_quest_lv10._110_sayTitle = "Kaptan'in Egitimi "
gameforge.main_quest_lv10._120_sayReward = "Kaptan'in ilk gorevi seni komsu koye goturur.[ENTER]Orada muzisyen Yu-Hwan'i bulup Kaptan icin[ENTER]gizli belgeleri sormalisin. "
gameforge.main_quest_lv10._130_sayTitle = "Muzisyen Yu-Hwan: "
gameforge.main_quest_lv10._140_say = "Hayat, her sey gibi sadece bir ruya. Nereden[ENTER]geliyoruz ve nereye gidiyoruz? Dunya catismalarla[ENTER]dolu. Durust calisma asla kazandirmaz. Sarki[ENTER]dinlemeye mi geldin buraya? "
gameforge.main_quest_lv10._150_say = "Oh, seni Kaptan gonderdi! Sss, bu kadar yuksek[ENTER]sesle konusma... Koyden kimse gercek kimligimi[ENTER]ogrenemez. Kaptan seni gonderdigine gore guvenilir[ENTER]biri olmalisin! Al, tut. Bu belge toplayabildigim[ENTER]tum bilgileri iceriyor. Kaptan'a gotur. "
gameforge.main_quest_lv10._160_sayTitle = "Muzisyen Yu-Hwan: "
gameforge.main_quest_lv10._170_say = "Acele et! Burada daha uzun sure durursan kotu[ENTER]bir sey olabilir. Hayat nedir ki? Hayat cok[ENTER]kisa... Elinden geldigince tadini cikar. "
gameforge.main_quest_lv10._180_targetVid = "Kaptan'a geri don. "
gameforge.main_quest_lv10._190_sayReward = "Gizlice casus olarak calisan Muzisyen Yu-Hwan[ENTER]sana onemli belgeler verdi. Onlari ilk koydeki[ENTER]Kaptan'a gotur. "
gameforge.main_quest_lv10._200_say = "Bu Muzisyen'den bir belge mi? Yeni bir macera[ENTER]arayicisi icin fena degil! Senden cok umutluyum.[ENTER]Bunu siki calismanin kaniti olarak al.[ENTER]Kralligin icin boyle calismaya devam et! "
gameforge.main_quest_lv10._20_sayReward = "Kralligina tam tesekkullu bir savasci olarak[ENTER]hizmet edebilecek kadar tecrube biriktirdin.[ENTER]Su andan itibaren Kaptan senin gorevlerini[ENTER]verecek. Onu ilk koyde bulacaksin. Fazla[ENTER]bekletme. "
gameforge.main_quest_lv10._30_sayTitle = "Kaptan "
gameforge.main_quest_lv10._40_say = "Tanidik gorunuyorsun... Oh evet, sanirim seni[ENTER]duymustum. Sen zaten becerilerini kanitlamis olan[ENTER]su yeni macera arayicisisin. Ne kadar yetenekli[ENTER]oldugunu bilmiyorum ama gelecekte bircok gorev[ENTER]alacaksin. "
gameforge.main_quest_lv10._50_say = "Senin icin birkac meydan okuma hazirlanacak.[ENTER]Sik sik Cennet olarak adlandirilan kitanin uc[ENTER]Kralliginin hikayesini biliyor musun? Biliyor[ENTER]musun? Egitmenler sana orada ne ogretti? Sana bu[ENTER]kadar temel seyleri ogretmem mi gerekiyor? "
gameforge.main_quest_lv10._60_say = "Bunlar onemli konular, senin icin ozetleyecegim.[ENTER]Uzun zaman once tek bir Birlesik Krallik vardi.[ENTER]Metin Taslari ortaya ciktiginda, Krallik 3 kucuk[ENTER]Kralliga bolundu: Shinsoo - Ticaret Kralligi,[ENTER]Chunjo - Din Kralligi ve Ordu Kralligi olan[ENTER]Jinno. "
gameforge.main_quest_lv10._70_say = "Her Krallik, Metin Taslarinin yarattigi karisikligin[ENTER]ardindan hala toparlanmaya calisiyor. Herkes[ENTER]Kralliklari yeniden birlestirmeye calisiyor.[ENTER]Sen de Üc Kralligin Birlesmesi icin calismalisin![ENTER]Bu cok onemli, bunu unutamazsin! "
gameforge.main_quest_lv10._80_say = "Sana ilk gorevini verecegim.[ENTER]Merak etme, oldukca basit bir is.[ENTER]Bir sonraki koyde Yu-Hwan adinda bir Muzisyen[ENTER]bulacaksin. Insanlar muzisyen olmak icin orduyu[ENTER]biraktigini dusunuyor. Aslinda bir casus.[ENTER]Yu-Hwan'da ihtiyacim olan bir belge var. Bana[ENTER]getir. Unutma, bu gizli bir gorev. "
gameforge.main_quest_lv10._90_say = "Bir sonraki koye nasil gidilecegini ogrenmek icin[ENTER]M tusuna bas. Mavi noktayla isaretli Portali[ENTER]kullan. Acele et! Muzisyen Yu-Hwan enstrumanli[ENTER]uzun boylu bir adam. "
