gameforge.main_quest_lv12._180_sayReward = "40.000 Tecrube Puani aldin.[ENTER]10.000 Yang aldin.[ENTER]Beceri Kitabi aldin. "
gameforge.main_quest_lv12._20_say = "Koyun hemen disinda dolasan birkac Gri Alfa[ENTER]Kurdunu oldur. Vahsice kosuyorlardi, ama bu[ENTER]artik cok ileri gitti! Koye ve sakinlerine[ENTER]giderek daha sik saldiriyorlar. Durumu kontrol[ENTER]altina almak icin, bu Kurtlardan birkacini oldur.[ENTER]Sanirim 10 tanesi oldugunde saldirilar duracak. "
