gameforge.main_quest_lv27._100_makequestbutton = "Metin Tasi yok edildi "
gameforge.main_quest_lv27._105_say = "Karanlik Metin'i yok ettin. Kaptan'a git ve[ENTER]basarini anlat. "
gameforge.main_quest_lv27._10_makequestbutton = "Metin Taslarini yok et! "
gameforge.main_quest_lv27._110_say = "Metin Tasini mi yok ettin? Sayende koy guvende![ENTER]Bu Taslar nereden geliyor? Onlar hakkinda hicbir[ENTER]bilgi yok, ama bu kadar cok soruna neden[ENTER]oluyorlar. Duyduguma gore Bilge Uriel Metin[ENTER]Taslarini arastiriyor, ama simdiye kadar ne[ENTER]ogrendigini bilmiyorum. Harika is cikardin. "
gameforge.main_quest_lv27._120_sayTitle = "Odul: "
gameforge.main_quest_lv27._130_sayReward = "3.300.000 Tecrube Puani aldin.[ENTER]270.000 Yang aldin.[ENTER]Usta Kitabi aldin. "
gameforge.main_quest_lv27._140_sayReward = "%s aliyorsun. "
gameforge.main_quest_lv27._20_say = "Metin Taslarinin yarattigi yikim buyuyor. Ülke[ENTER]aci cekiyor. Metin Taslarini kesinlikle yok etmek[ENTER]gerekiyor! Kaptan'a git. "
gameforge.main_quest_lv27._30_say = "Metin Taslarinin yarattigi yikim buyuyor. Ülke[ENTER]aci cekiyor. Metin Taslarini kesinlikle yok etmek[ENTER]gerekiyor! Kaptan'a git. "
gameforge.main_quest_lv27._40_say = "Cok siki calistigini duydum. Insanlar iyi isinden[ENTER]bahsediyor. Sayemde, senin icin uygun yeri[ENTER]buldum! Merak etme! Sadece saka yapiyordum! Cok[ENTER]yetenekli oldugunu biliyorum![ENTER]Metin Taslari yenileniyor. Bu buyuk sorunlar[ENTER]anlamina geliyor. "
gameforge.main_quest_lv27._50_say = "Metin Taslari dustugunde, halk aci cekiyor. Bazen[ENTER]Samanlarin kotu Tanri Sung Mahi'nin dirilisine[ENTER]dair kehanetinin coktan gerceklesip[ENTER]gerceklesmedigini merak ediyorum... Ama simdi[ENTER]su anki durumla ilgilenmeliyiz. Bir Metin Tasini[ENTER]yok ettiginde haber ver. "
gameforge.main_quest_lv27._60_sayTitle = "Gorev: "
gameforge.main_quest_lv27._70_say = "Yok etmen gereken Metin Tasi Karanlik Metin[ENTER]olarak adlandiriliyor. Onu bul! "
gameforge.main_quest_lv27._80_say = "Son zamanlarda giderek daha fazla Metin Tasi[ENTER]dusuyor. Tehlikeli radyasyonlarini durdurmak[ENTER]gerekiyor! Karanlik Metin'i bul ve yok et. "
gameforge.main_quest_lv27._90_say = "Karanlik Metin'i yok ettin. Kaptan'a geri don. "
gameforge.main_quest_lv3 = {}
gameforge.main_quest_lv3._100_say = "Merhaba. Seni Sehir Muhafizi mi gonderdi? Senin[ENTER]icin basit bir gorevim var. Babam bu sabah onemli[ENTER]bir kitabini unuttu. Acilen ihtiyaci var. "
gameforge.main_quest_lv3._10_npcChat = "Ilk gorevi tamamladim. "
gameforge.main_quest_lv3._110_say = "Bu Kitabi babama goturebilir misin? Ben burada[ENTER]kalmaliyim. Lutfen bu iyiligi yap benim icin.[ENTER]Bunu yaparsan, seni odullendirecegim. "
gameforge.main_quest_lv3._120_sayItem = "Zirh Üretimi "
gameforge.main_quest_lv3._130_targetVid = "Zirh Saticisini Bul "
gameforge.main_quest_lv3._140_sendLetter = "Kitabi Getir "
gameforge.main_quest_lv3._150_sayReward = "Kitabi Genel Satici'nin babasina gotur. Babasi[ENTER]Zirh Saticisi. "
gameforge.main_quest_lv3._160_sayTitle = "Zirh Saticisi: "
gameforge.main_quest_lv3._170_say = "Seni buraya getiren ne? Ah, kizim gonderdi seni![ENTER]Tesekkur ederim. Yeni bir zirh yapmak icin bu[ENTER]Kitaba ihtiyacim vardi. "
gameforge.main_quest_lv3._180_say = "Kizim seni Kitabi vermem icin gonderdigine gore[ENTER]cok mesgul olmali. Bakalim, ne odul alabilirsin? "
gameforge.main_quest_lv3._190_say = "Odul olarak sana biraz Yang verecegim, duzgun bir[ENTER]zirh satin alabilesin. Bu yeter, degil mi?[ENTER]Tesekkur ederim. Bir gun tekrar yardima[ENTER]ihtiyacim olursa, sana haber veririm. Yeni bir[ENTER]zirha ihtiyacin olursa, bana gel. Dukkanim her[ENTER]zaman acik! "
gameforge.main_quest_lv3._200_sayReward = "850 tecrube puani aliyorsun.[ENTER]5000 Yang aliyorsun.[ENTER]20 Mavi Iksir aliyorsun. "
gameforge.main_quest_lv3._20_say = "Bence ilk gorev bir eglenceydi. Bir rahatlama![ENTER]Baska gorev icin yalvarmana gerek yok. Daha[ENTER]tecrubeli oldugunda geri don, o zaman sana bir[ENTER]sonraki gorevi verecegim. "
gameforge.main_quest_lv3._30_sendLetter = "Sehir Muhafizindan Haberler "
gameforge.main_quest_lv3._40_sayReward = "Avlanmayi bitir ve Sehir Muhafizi'na git. Senin[ENTER]icin baska gorevleri var. "
gameforge.main_quest_lv3._50_say = "Geldigine sevindim. Muhtemelen Genel Satici'yi[ENTER]zaten taniyorsun, degil mi? Sanirim senin[ENTER]yardimina ihtiyaci var. Tam olarak ne oldugunu[ENTER]ogrenebilir misin? Eminim ona yardim[ENTER]edebilirsin. "
gameforge.main_quest_lv3._60_say = "Bilgi: Genel Satici yenileyici iksirler ve[ENTER]gelecekte isine yarayabilecek diger esyalari[ENTER]satiyor. Ona iyi bir izlenim birakmak zarar[ENTER]vermez. Simdi git. "
gameforge.main_quest_lv3._70_targetVid = "Genel Satici'yi bul "
gameforge.main_quest_lv3._80_sendLetter = "Genel Satici'ya yardim et "
gameforge.main_quest_lv3._90_sayReward = "Genel Satici'ya git, senin yardimina ihtiyaci[ENTER]var. "
gameforge.main_quest_lv30 = {}
gameforge.main_quest_lv30._100_say = "Tas Anit'ta oyulmus yazilar var. Hizlica onlari[ENTER]not aliyorsun. "
gameforge.main_quest_lv30._10_targetVid = "Uriel'i bul "
gameforge.main_quest_lv30._110_say = "Uriel hakliydi: Tas Anit'ta gercekten bir yazit[ENTER]vardi. Onu okuyamadin ama en azindan bir kopyasini[ENTER]aldin. Uriel'e gotur. "
gameforge.main_quest_lv30._120_say = "Hasun'un Tas Anitini mi buldun? Oh, hatta yazinin[ENTER]bir kopyasina mi sahipsin, harika! Bu tarihi[ENTER]olcekte bir kesif! Goster bakalim.[ENTER]Hmm... Gorunuse gore bu gercekten Metin Taslari[ENTER]hakkinda bilgi. Ne yazik ki her seyi cozemiyorum.[ENTER]Bu yazi cok kadim, bazi harfler neredeyse antik[ENTER]gorunuyor. Simdi ne yapacagiz? "
gameforge.main_quest_lv30._130_say = "Ah, bir fikrim var! Seungryong Vadisi'ni biliyor[ENTER]musun? Orada kadim zamanlardan kalma gizemli bir[ENTER]makine var. Orada eski yazitlar bulursan, belki[ENTER]onlarin yardimiyla eksik harflerin anlamini[ENTER]tahmin edebilirim. Seungryong Vadisi'ne git ve[ENTER]Seul Rong'un Tas Anitini bul! "
gameforge.main_quest_lv30._140_targetVid = "Seungryong Vadisi'ndeki Tablet "
gameforge.main_quest_lv30._150_say = "Bilge Uriel, bilmedigi bazi harflerin anlamini[ENTER]tahmin edebilmek icin daha fazla kadim metne[ENTER]ihtiyac duyuyor.[ENTER]Seungryong Vadisi'ne git ve orada Seul Rong'un[ENTER]Tas Anitindaki yazilari ara. "
gameforge.main_quest_lv30._160_say = "Daha fazla yazi mi buldun? Oh! Sayende yakinda[ENTER]Metin Taslari cevresindeki gizemi cozebilecegim.[ENTER]Dusundugumden cok daha hizli olabilir. Cok, cok[ENTER]tesekkur ederim! Gelecekte tekrar yardimina[ENTER]ihtiyacim olursa, sana haber veririm. Ah, lutfen[ENTER]bunu cabalarin icin odul olarak kabul et! "
gameforge.main_quest_lv30._20_sendLetter = "Metin Taslarinin Sirri "
gameforge.main_quest_lv30._30_say = "Uriel sonunda gizemli Metin taslari hakkinda[ENTER]bazi bilgiler elde etti. Git ve onunla[ENTER]konus. "
gameforge.main_quest_lv30._40_sayTitle = "Uriel: "
gameforge.main_quest_lv30._50_say = "Kaptan seni bana bir kez daha gonderdi. Cok[ENTER]yetenekli gorunuyorsun.[ENTER]Senden bir iyilik istemeliyim.[ENTER]Metin Taslarinin varliginin farkindasin, degil[ENTER]mi? Gokten geldiler. Seytani bir enerjiye sahipler[ENTER]ve bir bela yayiyorlar, hayvanlar yuzlerinden[ENTER]vahsilesiyor. Dunyamiza nasil girdiklerini ya da[ENTER]iclerinde ne oldugunu bilmiyoruz. Bu arastirmayi[ENTER]daha da zorlastiriyor.[ENTER]Son zamanlarda Metin Taslarinin sirrina dair bir[ENTER]anahtar buldum. "
gameforge.main_quest_lv30._60_say = "Kolay Maymun Zindani'nda bulunan, kadim bir[ENTER]kralliktan kalma bir tablet var. Sanirim bu[ENTER]tabletteki bilgiler Metin Taslarinin sirrini[ENTER]iceriyor. Bu bilgileri bana getirirsen, belki[ENTER]Metin Taslarinin sirrini kesfedebilirim. Lutfen[ENTER]bana Kolay Maymun Zindani'ndaki tabletten bu[ENTER]bilgileri getir! "
gameforge.main_quest_lv30._70_sayReward = "122.000 Tecrube Puani aldin.[ENTER]20.000 Yang aldin.[ENTER]Gumus Bilezik aldin. "
gameforge.main_quest_lv30._80_targetVid = "Kolay Maymun Zindani'ndaki Tas Anit "
gameforge.main_quest_lv30._90_say = "Gorunuse gore Bilge Uriel, Metin Taslarinin[ENTER]sirrini cozmesine yardimci olacak bir ize rastladi.[ENTER]Kolay Maymun Zindani'na git ve orada Hasun'un Tas[ENTER]Anitini bul. "
gameforge.main_quest_lv32 = {}
gameforge.main_quest_lv32._100_sayReward = "Ipucu: At sirtinda seyahat edersen, oraya cok[ENTER]daha hizli ve rahat ulasirsin. "
gameforge.main_quest_lv32._10_sendLetter = "Gizemli Kitap "
gameforge.main_quest_lv32._110_npcChat = "Gizemli Kitabin Sayfalari "
gameforge.main_quest_lv32._120_sayTitle = "Gezgin Satici: "
gameforge.main_quest_lv32._130_say = "Dunya kargasaya suruklendiginden beri, ticaret[ENTER]daha da zorlasti. Ne satin almak istiyorsun?[ENTER]Ah, seni Bilge Uriel mi gonderdi? O duzenli bir[ENTER]musteri. Farkli yerlerden eski kitaplar ariyor.[ENTER]Bunu oldukca eglenceli buluyorum.[ENTER]Hahaha. Eski kitaplar hakkinda bir seyler ogrenmek[ENTER]mi istiyorsun?[ENTER]Hmmm... Eski kitaplar hakkinda... "
gameforge.main_quest_lv32._140_say = "Birkac gun once bir sey duydum, ama bunu sana[ENTER]bedava soylemeyecegim! Istegimi yerine getirirsen,[ENTER]bu bilgiyi sana veririm. Son zamanlarda silah[ENTER]ticareti canlaniyor. Ama bu kadar cok miktari tek[ENTER]basima saglayamiyorum. Herkes silah satin almak[ENTER]istiyor! Oyle bos bos durmak yerine, bana 20[ENTER]Gumus Kilic+0 bul. Bana onlari getirdiginde,[ENTER]seninle belli bir Eski Kitap hakkinda bilgi[ENTER]paylasacagim. "
gameforge.main_quest_lv32._150_targetVid = "Gezgin Satici'ya git "
gameforge.main_quest_lv32._160_sayTitle = "20 Gumus Kilic+0'in var "
gameforge.main_quest_lv32._170_say = "Gezgin Satici Eski Kitap hakkinda bir seyler[ENTER]biliyor. Ona 20 Gumus Kilic+0 getir, sana bildigini[ENTER]soyleyecek. "
gameforge.main_quest_lv32._180_sayTitle = "20 Gumus Kilic+0 Elde Et "
gameforge.main_quest_lv32._190_say = "Eski Kitap hakkinda bir seyler bilen Gezgin[ENTER]Satici, bu bilgiyi bedava paylasmak istemiyor.[ENTER]Karsiliginda 20 Gumus Kilic+0 istiyor.[ENTER]20 Gumus Kilic+0 elde et ve ona gotur. "
gameforge.main_quest_lv32._200_npcChat = "Kiliclarim var "
gameforge.main_quest_lv32._20_targetVid = "Bilge Uriel'i ara "
gameforge.main_quest_lv32._210_say = "Guzel. Dusundugumden daha yeteneklisin.[ENTER]Yardimin sayesinde isim yakinda daha fazla kar[ENTER]getirecek.[ENTER]O Sayfaya gelince... birkac gun once, yaninda[ENTER]bir heykel duran bir koskun onunden geciyordum.[ENTER]Orada dinlenmek icin durdum ve heykelin[ENTER]kaidesinde yirtik bir kagit parcasi fark ettim. "
gameforge.main_quest_lv32._220_say = "O zaman hicbir sey dusunmemistim. Ama simdi[ENTER]bunun aradigin sayfalardan biri olabilecegini[ENTER]dusunuyorum. Heykelin adi? Hmm... acaba Woel[ENTER]Aniti miydi? Evet, tam olarak oyleydi. Komsu[ENTER]koyun yakinindaki Woel Aniti. Orada aramalisin! "
gameforge.main_quest_lv32._230_sayTitle = "Gezgin Satici: "
gameforge.main_quest_lv32._240_say = "Bana 20 Gumus Kilic+0 getir, seninle eski bir[ENTER]Sayfa hakkinda bilgi paylasayim. "
gameforge.main_quest_lv32._250_sendLetter = "1. Sayfa Arayisi "
gameforge.main_quest_lv32._260_targetVid = "Koskun yanindaki anit "
gameforge.main_quest_lv32._270_say = "Gezgin Satici, anitin yakinindaki koskte[ENTER]dinlenirken Woel Aniti'nin kaidesinde eski bir[ENTER]kitap Sayfasi gormus.[ENTER]Ilk koyun yakinindaki Woel Aniti'na git ve[ENTER]aradigin sayfalardan biri olup olmadigini kontrol[ENTER]et. "
gameforge.main_quest_lv32._280_npcChat = "Woel Aniti "
gameforge.main_quest_lv32._290_say = "EVET! Bu Woel Aniti! Sonunda![ENTER]Iste burada! Ilk Sayfayi buldum! "
gameforge.main_quest_lv32._300_sendLetter = "Ilk Sayfa "
gameforge.main_quest_lv32._30_say = "Bilge Uriel senin yardimina ihtiyac duyuyor. Su[ENTER]anda cok eski, gizemli bir kitap arastiriyor. Ona[ENTER]git ve nasil yardimci olabilecegini sor. "
gameforge.main_quest_lv32._310_targetVid = "Bilge Uriel'i ara "
gameforge.main_quest_lv32._320_sayTitle = "Ilk Sayfayi Buldun. "
gameforge.main_quest_lv32._330_say = "Gezgin Satici'nin tavsiyesine uydun ve eksik[ENTER]sayfalardan ilkini buldun. Onu Bilge Uriel'e[ENTER]gotur. "
gameforge.main_quest_lv32._340_say = "Demek Eski bir Sayfa mi buldun?[ENTER]Oh, bir tane var, harika! Bakalim orada ne[ENTER]yaziyor. Hmmm...[ENTER]Bu bir gunluk gibi gorunuyor. Dinle! "
gameforge.main_quest_lv32._350_sayTitle = "Kitabin Ilk Sayfasi: "
gameforge.main_quest_lv32._360_sayReward = "Taejo Kralligi'ndan Lee Seop, sayisiz fetihle[ENTER]topraklarini genisletiyor. Askerlerinin yardimiyla[ENTER]tum topraklari gucle fethetmek istiyor. Ne[ENTER]pahasina olursa olsun ona engel olmali ve[ENTER]Kralligimiza saldirmayacagindan emin olmaliyiz.[ENTER]Olanaklarimiz sinirli. Bu yuzden yasak buyuyu[ENTER]kullanmaya karar verdik! "
gameforge.main_quest_lv32._370_sayTitle = "Kitabin Ilk Sayfasi: "
gameforge.main_quest_lv32._380_sayReward = "Bu hayatta kalmak icin tek sansimiz.[ENTER]Basaracagimizi bilmiyoruz ama kesinlikle[ENTER]denemeliyiz. Bize saldirmadan once, yasak buyu[ENTER]hakkinda bilgi edinmeliyiz.[ENTER]Muhtemelen eski efsanelerde kadim buyu hakkinda[ENTER]bilgi bulacagiz. Efsanelere gore, bu bilgiyi[ENTER]Ejderha Vadisi'nde bulabiliriz, oradan baslamaliyiz. "
gameforge.main_quest_lv32._390_say = "Metinlerden anlasildigina gore, bu ulkede eski[ENTER]zamanlarda garip bir din varmis. Taejo Kralligindan[ENTER]Lee Seop tum kitayi birlestirmeden once, her ulke[ENTER]farkli bir din ve farkli inananlarla[ENTER]karakterizeydi. Bu metnin yazari suphesiz bir[ENTER]bilgindi. Muhtemelen bir loncaya aitti, hatta belki[ENTER]bir liderdi. Loncalar sadece toplumun ust[ENTER]tabakalarindan insanlarca kuruluyordu. "
gameforge.main_quest_lv32._400_say = "Ejderha Vadisi'ndeki eski hikayeler hakkinda[ENTER]bircok konusma donuyor. Ben bile bu tur birkac[ENTER]hikaye biliyorum. Muhtemelen ilginc bilgiler[ENTER]edinme ya da hatta daha fazla Gunluk Sayfasi bulma[ENTER]sansimiz hala var. Ne yazik ki Ejderha Vadisi'ne[ENTER]nasil ulasilacagini bilmiyorum, hic orada[ENTER]bulunmadim. Komsu koydeki Avci Yang-Shin'e git,[ENTER]o kesinlikle oraya nasil gidilecegini biliyor.[ENTER]Belki nereden aramaya baslamamiz gerektigini de[ENTER]bilir. "
gameforge.main_quest_lv32._40_say = "Selamlar.[ENTER]Gecen sefer bana verdigin sey cok yardimci oldu.[ENTER]Yardiminla arastirmamda buyuk bir ilerleme[ENTER]kaydedebildim. Ama simdi bir sorunum var...[ENTER]Gizemli taslar ve gizemli kadin hakkinda bilgi[ENTER]ararken, belli bir Eski Kitap bulmayi basardim.[ENTER]Kitap kadim bir dilde yazildigi icin, okumak kolay[ENTER]degil. Sanirim orada degisimin nedenini aciklayan[ENTER]onemli bilgiler var. "
gameforge.main_quest_lv32._410_say = "Bu cok heyecan verici! Oh, unutmadan: iste[ENTER]Ilk Sayfa icin odulun! "
gameforge.main_quest_lv32._420_sayReward = "1.000.000 Tecrube Puani aldin. "
gameforge.main_quest_lv32._430_sayReward = "50.000 Yang aldin. "
gameforge.main_quest_lv32._440_sayReward = "Tanricanin Gozyasi aldin. "
gameforge.main_quest_lv32._450_sendLetter = "Avciya Git "
gameforge.main_quest_lv32._460_targetVid = "Avci Yang-Shin'i bul. "
gameforge.main_quest_lv32._470_sayTitle = "Yang-Shin'e Ejderha Vadisi'ni sor "
gameforge.main_quest_lv32._480_say = "Gizemli Kitabin ilk sayfasinda Ejderha[ENTER]Vadisi'nden bahsediliyor. Uriel efsanelerini[ENTER]biliyor, ama nerede aranacagini bilmiyor. Komsu[ENTER]koye git ve Avci Yang-Shin'e bu konuda daha fazla[ENTER]bir sey bilip bilmedigini sor. "
gameforge.main_quest_lv32._490_sayReward = "Ipucu: Avci komsu koyde. "
gameforge.main_quest_lv32._500_npcChat = "Ejderha Vadisi Hakkinda Bilgi "
gameforge.main_quest_lv32._50_say = "Sorun su ki, sayfalar cok yirtik. Bu yuzden[ENTER]okumak cok zor. Muhtemelen, Kitap elden ele[ENTER]dolastigi icin bu kadar hasar gordu. Biri ondan[ENTER]13 Sayfa koparmis. Onlari benim icin bulabilir[ENTER]misin? Muhtemelen uzerlerinde savasi nasil[ENTER]bitirebilecegimizi soyleyen bilgiler var. "
gameforge.main_quest_lv32._510_sayTitle = "Yang-Shin: "
gameforge.main_quest_lv32._520_say = "Ejderha Vadisi hakkinda bir seyler mi ogrenmek[ENTER]istiyorsun? Hmmm. Neden bu kadar tehlikeli bir[ENTER]yere gitmek istiyorsun? Vadi Orklarla ve Gizemli[ENTER]Tarikat uyeleriyle dolu. Ben bile, buyuk bir avci[ENTER]olmama ragmen, oraya gitmeyi sevmiyorum. Vadiden[ENTER]uzak durmak daha iyi olur. "
gameforge.main_quest_lv32._530_say = "Ne? Eski Sayfalar mi ariyorsun?[ENTER]Hm! Bir keresinde baska bir avcidan Elit Ork[ENTER]Buyucusunun garip kagitlari oldugunu duymustum.[ENTER]Ama dogru mu? Bu kadar merakliysan, git ve kendin[ENTER]kontrol et. Zaten tehlikeli bir yer oldugunu[ENTER]soylemistim. Kendine dikkat et! "
gameforge.main_quest_lv32._540_sendLetter = "Ikinci Sayfa Arayisi "
gameforge.main_quest_lv32._550_say = "Avcinin bahsettigi gibi, Ejderha Vadisi'ndeki[ENTER]Elit Ork Buyucusunu bulmalisin. Muhtemelen ikinci[ENTER]Sayfaya sahip olan o. Bu Ork'u oldur ve ikinci[ENTER]Sayfayi al. Onu elde ettiginde, Uriel'e git. "
gameforge.main_quest_lv32._560_sendLetter = "Ikinci Sayfa "
gameforge.main_quest_lv32._570_sayTitle = "Ikinci Sayfayi Buldun "
gameforge.main_quest_lv32._580_say = "Elit Ork Buyuculerini avlamak basariyla sonuclandi.[ENTER]Gizemli Kitabin Ikinci Sayfasini buldun.[ENTER]Onu Bilge Uriel'e gotur. "
gameforge.main_quest_lv32._590_say = "Bu Ikinci Sayfa mi? Bakalim. Hmm.[ENTER]Okumak kolay degil. Icerige gore... "
gameforge.main_quest_lv32._600_sayTitle = "Ikinci Sayfa: "
gameforge.main_quest_lv32._60_say = "Bu eksik Sayfalari bulur bulmaz, bana mumkun[ENTER]oldugunca cabuk getir. Onlari cozmeye calisacagim.[ENTER]Hmmm... Aramaya nereden baslamalisin? Bir sure[ENTER]once, komsu koyde bir Sayfa bulan bir Gezgin[ENTER]Satici'dan bahsedildigini duymustum. Ona git ve[ENTER]bir sey ogrenip ogrenemeyecegini kontrol et. "
gameforge.main_quest_lv32._610_sayReward = "Kara buyu kullanan buyuculeri bulduk. Ejderha[ENTER]Vadisi'nde saklaniyorlardi. Nesilden nesile[ENTER]aktarilan yasak buyuyu iyi biliyorlardi. Sayfalari[ENTER]okuyup inceledikten sonra, bir rituel yapilmasi[ENTER]gerektigi acikca ortaya cikti. Bu yer kesinlikle[ENTER]kotu enerjiyle dolu olmali.[ENTER]Boyle bir yer var mi? Vakit yok. Uygun yeri[ENTER]mumkun oldugunca cabuk bulmaliyim. "
gameforge.main_quest_lv32._620_say = "Hmmm, yasak rituel kotu enerjiyle dolu bir yer[ENTER]gerektiriyor! Her seyin kotu enerjiye donustugu[ENTER]bir yer? Boyle bir yer nerede olabilir? Hmm...[ENTER]Bu kesinlikle Karanlik Tapinagi. Burasi sadece[ENTER]insanlarin degil, hayvanlarin bile gitmek[ENTER]istemedigi bir yer. Gizli gucun canavarlari ele[ENTER]gecirdigi bir yer. "
gameforge.main_quest_lv32._630_say = "Ayrica, yasak rituel ile gizemli guc arasinda bir[ENTER]bag olusmus. Hwang Tapinagi'nda bir ipucu[ENTER]bulmalisin. Orada ne oldugunu arastir ve baska[ENTER]Gunluk Sayfalari bulmaya calis! Iste ikinci Sayfa[ENTER]icin odulun... "
gameforge.main_quest_lv32._640_sayReward = "1.000.000 Tecrube Puani aldin. "
gameforge.main_quest_lv32._650_sayReward = "50.000 Yang aldin. "
gameforge.main_quest_lv32._660_sayReward = "10 Beyaz Bayrak aldin. "
gameforge.main_quest_lv32._670_sendLetter = "Ücuncu Sayfa "
gameforge.main_quest_lv32._680_say = "Iki Sayfa zaten bulundu.[ENTER]Bir sonraki Sayfa Hwang Tapinagi'nda. "
gameforge.main_quest_lv32._690_sayReward = "Ipucu: Bu seriden sonraki gorevler ancak[ENTER]40. seviyeye ulastiginda mevcut olacak. "
gameforge.main_quest_lv32._70_targetVid = "Gezgin Satici'ya git "
gameforge.main_quest_lv32._80_sayTitle = "Gizemli Kitabin Sayfalarini Bul "
