gameforge.main_quest_lv50._160_sayTitle = "Eski Kagit Kutusunu Arayis "
gameforge.main_quest_lv50._170_say = "Bir zamanlar Sohan Dagi'nda korkunc bir savas[ENTER]yasandi. Orada Gunlugun diger sayfalarini veya[ENTER]savasin seyrine dair yazili kanitlari ara. "
gameforge.main_quest_lv50._180_npcChat = "Eski Kagit Kutusu! "
gameforge.main_quest_lv50._190_say = "Bunlar askeri planlar, notlar ve Gunlugun[ENTER]yeni bir sayfasi! Bunlarin hepsini Uriel'e[ENTER]goturmeliyim. "
gameforge.main_quest_lv50._200_sendLetter = "Onuncu Sayfa "
gameforge.main_quest_lv50._20_say = "Onceki arastirmalara gore izler Orumcek[ENTER]Zindanlarina cikiyor. Oraya git, Orumcek[ENTER]Zindani'ndaki Kibirli Zehirli Asker Orumcekleri[ENTER]oldur ve eski Kitabin yeni bir sayfasini[ENTER]bulursan Uriel'e teslim et. "
gameforge.main_quest_lv50._210_sayTitle = "Onuncu Sayfayi Buldun "
gameforge.main_quest_lv50._220_say = "Buz Colu'nde gizemli Gunlugun onuncu sayfasini[ENTER]buldun. Sayfa Eski Kagit Kutusunun icindeydi.[ENTER]Onu Uriel'e gotur. "
gameforge.main_quest_lv50._230_say = "Ah, harika! Gunlugun onuncu sayfasini buldun.[ENTER]Hikayenin sonuna yaklasiyoruz. Her seyin kayit[ENTER]altina alinmis olmasi ne guzel, yoksa hicbir sey[ENTER]ogrenemezdik. Bakalim neler ogrenecegiz. "
gameforge.main_quest_lv50._235_sayTitle = "Kitabin Onuncu Sayfasi: "
gameforge.main_quest_lv50._240_sayReward = "Ilk saldiriyi puskurtmeyi basardik. Ancak yeni[ENTER]bir dalga yakinda gelecektir. Arazi, Lee Seop'un[ENTER]agir suvarilerinin ilerlemesini zorlastirsa da[ENTER]sayilari gittikce artiyor. Kazanamayacagiz.[ENTER]Tek bir sansimiz kaldi: Karanlik rituel uzerindeki[ENTER]arastirmayi tamamlamak. Gecenin karanligindan faydalanip[ENTER]dusman hatlarini yararak Orumcek Magaralarina[ENTER]donecegiz. Dua ediyorum... zafer icin degil, sadece[ENTER]birazcik umut icin... "
gameforge.main_quest_lv50._250_say = "Ooooh. Sanirim hedefimize cok yaklastik! Sonunda[ENTER]bu yasak rituel hakkinda daha fazla sey[ENTER]ogrenecegiz. Sabirsizlaniyorum![ENTER]Orumcek Zindani'na geri don. On birinci sayfa[ENTER]oradaki bir yerlerde olmali. "
gameforge.main_quest_lv50._260_say = "Iste hak ettigin odul! "
gameforge.main_quest_lv50._270_sayReward = "5.500.000 Deneyim Puani kazandin. "
gameforge.main_quest_lv50._280_sayReward = "137.500 Yang kazandin. "
gameforge.main_quest_lv50._290_sayReward = "Kahin Kralin Eldiveni kazandin. "
gameforge.main_quest_lv50._300_sayTitle = "Penceli Zehirli Orumcek Oldur "
gameforge.main_quest_lv50._30_sendLetter = "Dokuzuncu Sayfa "
gameforge.main_quest_lv50._310_say = "Yasak rituelle ilgili arastirmalar Orumcek[ENTER]Zindani'nda devam ediyor. Oraya git, birkac[ENTER]Penceli Zehirli Orumcek oldur ve gerekli[ENTER]bilgileri ele gecir. "
gameforge.main_quest_lv50._320_sendLetter = "On Birinci Sayfa "
gameforge.main_quest_lv50._330_targetVid = "Uriel'e Don. "
gameforge.main_quest_lv50._335_sayTitle = "On Birinci Sayfa Bulundu "
gameforge.main_quest_lv50._340_say = "Orumcek Zindani'nda gizemli Gunlugun on birinci[ENTER]sayfasini buldun. Onu Uriel'e gotur. "
gameforge.main_quest_lv50._350_say = "Yasak rituelle ilgili bir haber var mi?[ENTER]Aha, on birinci sayfa! Bir bakalim. Ah evet,[ENTER]oldukca basit. Artik bu tur yazilari cozmede cok[ENTER]iyiyim. Simdi dinle! "
gameforge.main_quest_lv50._355_sayTitle = "Kitabin On Birinci Sayfasi: "
gameforge.main_quest_lv50._360_sayReward = "Buyu basarisiz oldu. Tum hazirliklarimiza ragmen[ENTER]aceleciligimiz sonumuz oldu. Simdi bircogumuz[ENTER]yarali, hatta bazilarimiz aklini yitirdi.[ENTER]Kara buyu gercekten cok kotu. Lee Seop'un[ENTER]suvarileri bizi koseye sikistirdi ama artik bunun bir[ENTER]onemi yok. Kendimizi savunacak kadar adamimiz kalmadi.[ENTER]Zaten olecegiz. "
gameforge.main_quest_lv50._365_sayTitle = "Kitabin On Birinci Sayfasinin Devami: "
gameforge.main_quest_lv50._370_sayReward = "Kalan birligimizi bir arada tutan ve bize guc[ENTER]veren son bir amac var: Ejderha Vadisi'ndeki[ENTER]muhbirlerimiz bize yalan soyledi. Yasak rituelin[ENTER]korkunc yan etkileri konusunda bizi bilerek[ENTER]uyarmadilar. Yapacagimiz son sey bu olsa bile,[ENTER]bunun bedelini odeyecekler. "
gameforge.main_quest_lv50._380_say = "Heh, sonunda her sey onlarin istediginden biraz[ENTER]farkli gelismis. Üzucu bir hikaye. Ancak kara[ENTER]buyuyle oyle ya da boyle baglantisi olan birine[ENTER]asla guvenilmez. Bunu dusunmeleri gerekirdi.[ENTER]Bu metnin yazarinin boylesine yasak bir rituele[ENTER]nasil ulastigi tuhaf gorunuyor. Muhbirlerin amaci[ENTER]neydi kim bilir. Cok tehlikeli olsa bile bu[ENTER]sorusturmayi tamamlamaliyiz. O kadar cok sey[ENTER]ogrendik ki vazgecmek yazik olur. "
gameforge.main_quest_lv50._390_say = "Seungryong Vadisi'nde zaten bulundun. Orada daha[ENTER]fazla bilgi bulabilecegimizi sanmiyorum. Hmm...[ENTER]baska nerede arayabiliriz diye dusunuyorum... buldum![ENTER]Sorusturmamizda Anitlar cok onemli bir rol oynadi.[ENTER]Cevrede henuz incelemedigimiz Anitlar var.[ENTER]Diger Kralliklardakiler! Orasi son derece[ENTER]tehlikelidir. Muhtemelen surekli saldiriya[ENTER]ugrayacaksin. Bu yuzden iyi hazirlan ve hazir[ENTER]oldugunda geri don. "
gameforge.main_quest_lv50._400_say = "Iste on birinci sayfa icin odulun. "
gameforge.main_quest_lv50._40_targetVid = "Uriel'e Git "
gameforge.main_quest_lv50._410_sayReward = "Ipucu: Bir sonraki gorev icin en az 55. seviyede[ENTER]olmalisin. "
gameforge.main_quest_lv50._50_sayTitle = "Dokuzuncu Sayfayi Buldun. "
gameforge.main_quest_lv50._60_say = "Orumcek Zindani'nda dokuzuncu sayfayi buldun.[ENTER]Onu Uriel'e gotur. "
gameforge.main_quest_lv50._70_say = "Eski buyunun izini mi buldun? Vay canina, bu[ENTER]dokuzuncu sayfa! Orada ne yaziyor? Bu buyunun[ENTER]ise yarayip yaramadigini cok merak ediyorum, acele[ENTER]edelim... "
gameforge.main_quest_lv50._75_sayTitle = "Kitabin Dokuzuncu Sayfasi: "
gameforge.main_quest_lv50._80_sayReward = "Lee Seop'un saldirisi basladi. H�l� yasak ritueli[ENTER]nasil kullanacagimizi bilmiyoruz. Cok tedirginim.[ENTER]Kralligimizi korumaya calisarak cephedeyiz ama[ENTER]gucumuz yetersiz. Dusman askerlerinin gucu cok[ENTER]buyuk, savasi kaybedebiliriz. Daha iyi bir yer[ENTER]bulmaliyiz! Belki de Buz Colu'ne gitmeli ve[ENTER]dusmanlarimiza oradan mi saldirmaliyiz? Biraz[ENTER]sansimiz varsa o zamana kadar ritueli daha iyi[ENTER]ogrenebiliriz. Tanrim, bize yardim et... "
gameforge.main_quest_lv50._90_say = "Hmm... Bu buyunun ne oldugunu ogrenemeden[ENTER]saldiriya ugramislar. Insanlar eski buyuyu[ENTER]arastirmaya devam edebilmek icin Buz Diyari'na[ENTER]barikat kurmuslar. Baska izler arayabiliriz.[ENTER]Sohan Dagi'na git ve herhangi bir ipucu ara. "
gameforge.main_quest_lv55 = {}
gameforge.main_quest_lv55._100_say = "On ikinci sayfayi Joan'in merkezinde buldun.[ENTER]Sayfayi Yongan'daki Uriel'e gotur. "
gameforge.main_quest_lv55._10_sendLetter = "Anit Arayisi "
gameforge.main_quest_lv55._110_say = "On ikinci sayfayi Yongan'in merkezinde buldun.[ENTER]Sayfayi Pyungmoo'daki Uriel'e gotur. "
gameforge.main_quest_lv55._120_say = "Seni tekrar gordugume sevindim! Seni bu kadar[ENTER]cok farkli yere gondermek zorunda kaldigim icin[ENTER]uzgunum ama basarimiz tahminlerimizi dogruladi.[ENTER]Bakalim orada neyin var. Umarim buna degmistir. "
gameforge.main_quest_lv55._130_sayTitle = "Gunlugun On Ikinci Sayfasi: "
gameforge.main_quest_lv55._140_sayReward = "Muhbirleri bulduk, yalanlarinin bedelini[ENTER]hayatlariyla odediler. Ancak daha onemlisi,[ENTER]onlardan ek bilgi almayi basardik: Orumcek[ENTER]Zindani'na degil, Karanlik Tapinak'a ihtiyacimiz[ENTER]var. Kadim inananlarin yasak rituelleri yaptigi[ENTER]yer orasiydi. Burasi dogrudan devasa bir guc[ENTER]kaynagina bagli olan bir yerdir. "
gameforge.main_quest_lv55._145_sayTitle = "On Ikinci Kitap Sayfasinin Devami: "
gameforge.main_quest_lv55._150_sayReward = "Lee Seop'u durdurmaya cok az kaldi. Yasak ritueli[ENTER]gerceklestirmek icin Karanlik Tapinak'a[ENTER]gitmeliyiz. Pek fazla kisi kalmadik ve son birkac[ENTER]ay bizi cok yipratti. Ancak yorgun bir avuc insan[ENTER]bile tum dunyanin kaderini degistirebilir. Cok[ENTER]yakinda herkes siki calismamizin sonucunu[ENTER]gorecek. Ilerleyelim. "
gameforge.main_quest_lv55._160_say = "Ah, sonunda dogru yeri bulmuslar. Icime dogan[ENTER]his dogru cikti! Burasi gercekten de Hwang[ENTER]Tapinagi. Cok fazla kotu enerjinin bulundugu o[ENTER]karanlik yeri mutlaka hatirliyorsundur. Gizli[ENTER]ritueller burada yapilirdi. Bu ayinler genellikle[ENTER]savas temelliydi. Burasi tamamen masum kurbanlarin[ENTER]enerjisiyle dolu. "
gameforge.main_quest_lv55._170_say = "Simdi tapinagin icinde sadece canavarlar yasiyor.[ENTER]Cok uzun zamandir orada canli bir insan gorulmedi.[ENTER]Burasi son derece tehlikeli bir yer. Kalan son ipucu[ENTER]tam olarak oraya isaret ediyor. Tapinakta en yeni[ENTER]bilgileri ara. Iyi sanslar! Oh, bir saniye bekle,[ENTER]iste on ikinci sayfa icin odulun. "
gameforge.main_quest_lv55._200_sendLetter = "Son Sayfa "
gameforge.main_quest_lv55._20_say = "Uriel, ihtiyacimiz olan bilgilerin henuz bizim[ENTER]tarafimizdan incelenmemis olan anitlarin yakininda[ENTER]bulunabilecegini dusunuyor. Chunjo Kralligi'na[ENTER]git ve Joan bolgesindeki anitlari arastir. "
gameforge.main_quest_lv55._210_sayTitle = "Tapinaktaki Heyulayi Oldur "
gameforge.main_quest_lv55._220_say = "Simdiye kadar on uc sayfadan on ikisini buldun.[ENTER]Geriye sadece tek bir adim kaldi. Uriel, kara[ENTER]buyunun Hwang Tapinagi'nda yapildigini soyluyor.[ENTER]Oraya gitmeli ve arastirmaya baslamalisin.[ENTER]Ipuclarini Heyula adli canavarlarda ara. "
gameforge.main_quest_lv55._230_say = "Tapinagin derinliklerine gitmeliyim! "
gameforge.main_quest_lv55._240_sendLetter = "Karanlik Tapinak "
gameforge.main_quest_lv55._250_sayTitle = "Tapinagin Kotu Enerjisi "
gameforge.main_quest_lv55._260_sayReward = "Tapinakta biraz zaman gecirdikten sonra, golgelerde[ENTER]gizlenen korkunc yaratiklarin her kosede seni[ENTER]pusuda bekledigi hissine kapiliyorsun. Merkeze ne[ENTER]kadar yaklasirsan enerji o kadar gucleniyor.[ENTER]Kaynak bu tapinaktir. Her sey burada baslayacak... "
gameforge.main_quest_lv55._270_say = "Tapinagin merkezine yaklastikca havadaki kotu[ENTER]enerjinin guclendigini fark ettin. Ipuclarini[ENTER]tapinagin merkezinde aramamalisin. Kotulugun[ENTER]kaynagi orada olmali. "
gameforge.main_quest_lv55._280_npcChat = "Gum Aniti "
gameforge.main_quest_lv55._290_say = "Gum Aniti tapinagin merkezindedir. Yavasca[ENTER]yaklasiyorsun ve Gunlugun son Sayfasini[ENTER]buluyorsun. "
gameforge.main_quest_lv55._300_say = "Tapinakta gizemli Gunlugun son sayfasini buldun.[ENTER]Uriel'e git ve buldugun sey hakkinda onu[ENTER]bilgilendir. "
gameforge.main_quest_lv55._30_say = "Uriel, ihtiyacimiz olan bilgilerin henuz bizim[ENTER]tarafimizdan incelenmemis olan anitlarin yakininda[ENTER]bulunabilecegini dusunuyor. Jinno Kralligi'na[ENTER]git ve Pyungmoo bolgesindeki anitlari arastir. "
gameforge.main_quest_lv55._310_say = "Iste burada, sonuncu, on ucuncu sayfa! Sana nasil[ENTER]tesekkur edecegimi bilemiyorum. Ellerime bak,[ENTER]titriyorlar. O kadar heyecanliyim ki sayfaya[ENTER]bakamiyorum bile. Daha fazla beklemeyelim, bu garip[ENTER]hikayenin nasil bittigini gorelim. "
gameforge.main_quest_lv55._320_sayTitle = "Gunlugun On Ücuncu Sayfasi: "
gameforge.main_quest_lv55._330_sayReward = "Nihayet ulastik.[ENTER]Tum zorluklarin ustesinden geldik, gorevimiz[ENTER]sudur: Lee Seop'un saltanatina son vermeli ve[ENTER]yasak buyuyu etkinlestirmeliyiz. Umarim gucumuz[ENTER]yeter. Bitkin durumdayiz, yolculuk cok uzundu ve[ENTER]arkamizda surekli dusman askerleri vardi.[ENTER]Denemek zorundayiz, yoksa Kralligimiz yok olacak. "
gameforge.main_quest_lv55._335_sayTitle = "On Ücuncu Kitap Sayfasinin Devami: "
gameforge.main_quest_lv55._340_sayReward = "Geriye sadece yedi kisi kaldi. Simdi pacavra gibi[ENTER]gorunseler de en guzel giysilerimizi giydik.[ENTER]Yasak gucu cagirmak icin bir daire olusturup el[ENTER]ele tutusacagiz. Sonra rituelin daha fazla kurbana[ENTER]ihtiyac duymamasi umuduyla efsunu okumaya[ENTER]baslayacagiz.[ENTER][ENTER]... "
gameforge.main_quest_lv55._350_sayReward = "... Son...[ENTER]Cok umut verici baslamisti. Oda buyu enerjisi ve[ENTER]efsun sozleriyle doldu, gercekten cok garipti.[ENTER]Alti yoldasim dizlerinin uzerine coktu. Tapinak[ENTER]sallanmaya basladi. Sonra bir yildirim carpti ve[ENTER]geriye savrulduk. Cember bozuldu...[ENTER]Simdi inanilmaz bir sessizlik hakim. Arkadaslarim[ENTER]yerde olu yatiyor. Buyu ise yaramadi. Basarisiz[ENTER]olduk. "
gameforge.main_quest_lv55._360_say = "Ne? Hepsi bu kadar mi?!?[ENTER]Bu delilik! Butun emegimiz bosa mi gitti? Buna[ENTER]inanamiyorum. Seyahat ettik, savastik, garip[ENTER]metinler tercume ettik, tum bunlara devasa zaman[ENTER]harcadik. Ve hic ugruna! Eskiden ne kadar[ENTER]akilliysak simdi de o kadariz. Tek ogrendigimiz sey[ENTER]kara buyuden uzak durmanin daha iyi oldugu.[ENTER]Zaten hep boyle dusunurdum. Hikayenin boyle[ENTER]bitmesi buyuk bir utanc. Kimse boyle bir son[ENTER]beklemiyordu, degil mi? "
gameforge.main_quest_lv55._370_say = "Once biraz ara verelim. Basim agriyor ve sen de[ENTER]epey yorulmus olmalisin. Tum bunlar uzerine biraz[ENTER]dusunmem gerekiyor. Isim bittiginde konusuruz.[ENTER]Yine de bana buyuk bir iyilik yaptin. Bu asla[ENTER]unutulmayacak! "
gameforge.main_quest_lv55._40_say = "Uriel, ihtiyacimiz olan bilgilerin henuz bizim[ENTER]tarafimizdan incelenmemis olan anitlarin yakininda[ENTER]bulunabilecegini dusunuyor. Shinsoo Kralligi'na[ENTER]git ve Yongan bolgesindeki anitlari arastir. "
gameforge.main_quest_lv55._50_npcChat = "Iste burada! "
gameforge.main_quest_lv55._60_say = "Uriel'in aradigi anit bu! Katlanmis Gunluk[ENTER]Sayfasi anitin altinda duruyor.[ENTER]Onu hemen Uriel'e teslim etmeliyim. "
gameforge.main_quest_lv55._70_sendLetter = "On Ikinci Sayfayi Buldun "
gameforge.main_quest_lv55._80_targetVid = "Uriel'e Git "
gameforge.main_quest_lv55._90_say = "On ikinci sayfayi Pyungmoo'da buldun.[ENTER]Sayfayi Joan'daki Uriel'e gotur. "
gameforge.main_quest_lv6 = {}
gameforge.main_quest_lv6._100_sayReward = "Demirci'ye git. Yardimina ihtiyaci var. "
gameforge.main_quest_lv6._10_targetVid = "Sehir Bekcisi'ne git. "
gameforge.main_quest_lv6._110_say = "Kimsin sen? Cok mesgulum, lutfen beni rahatsiz[ENTER]etme. Seni Sehir Bekcisi mi gonderdi? Kimsenin[ENTER]gelmeyecegini saniyordum. Cok zor bir gorev degil[ENTER]ve fazla vaktini almaz. Genc bir maceraci icin tam[ENTER]bicilmis kaftan. "
gameforge.main_quest_lv6._120_say = "Depocu'dan bir paket almis olmam gerekirdi ama[ENTER]h�l� gelmedi. Lutfen Depocu'ya git ve paketi sor.[ENTER]Acele et. Bu teslimat olmadan isime devam edemem. "
gameforge.main_quest_lv6._130_targetVid = "Depocu'yu Bul. "
gameforge.main_quest_lv6._140_sendLetter = "Depocu'ya Git "
gameforge.main_quest_lv6._150_sayReward = "Demirci acil bir paket bekliyor. Depocu'ya git[ENTER]ve Demirci icin Domuz Burnu'nu sor. "
gameforge.main_quest_lv6._160_sayTitle = "Depocu: "
gameforge.main_quest_lv6._170_say = "Merhaba. Ben bu koyun Depocusuyum.[ENTER]Üzerinde cok fazla esya varsa, onlari depomda[ENTER]saklayabilirim. Cok kullanislidir. "
gameforge.main_quest_lv6._180_say = "Merhaba! Bir sey mi saklamak istiyorsun...?[ENTER]Ah, Demirci seni Domuz Burnu icin mi gonderdi! "
gameforge.main_quest_lv6._190_say = "Korkarim yavas yavas yaslaniyorum ve unutkanlik[ENTER]basladi. Al bakalim, iste Domuz Burnu. Onu derhal[ENTER]Demirci'ye gotur. Gorusmek uzere! "
gameforge.main_quest_lv6._200_sendLetter = "Demirci'ye Geri Don "
gameforge.main_quest_lv6._20_sayReward = "Bekcinin senin icin yeni bir gorevi var. Yanina[ENTER]git ve meselenin ne oldugunu ogren. "
gameforge.main_quest_lv6._210_sayReward = "Depocu paketi tamamen unutmustu. Nihayet Domuz[ENTER]Burnu'nu sana verdi. Daha fazla beklememesi icin[ENTER]onu hemen Demirci'ye gotur. "
gameforge.main_quest_lv6._220_say = "Dusundugumden hizli dondun! Boyle devam et, bu[ENTER]hiz gelecekte kesinlikle isine yarayacaktir.[ENTER]Simdi beni dikkatle dinle, cunku cok onemli bir[ENTER]bilgim var. "
gameforge.main_quest_lv6._230_say = "Gelistirme (arti basma) hakkinda bir sey biliyor[ENTER]musun? Elbette hayir! Henuz genc bir[ENTER]maceracisin! Sana durumu aciklayayim: Zirhinin[ENTER]bir parcasini bana verirsen, ufak bir Yang[ENTER]karsiliginda onu gelistirebilirim. "
gameforge.main_quest_lv6._240_say = "Esyalari +3'e kadar gelistirmek icin sadece bir[ENTER]miktar Yang odemen gerekir. Ancak +4 ve uzeri[ENTER]seviyelerde, bir seyi gelistirmek istediginde ek[ENTER]bir esya gerekebilir. Paketteki Domuz Burnu bir[ENTER]esyayi yukseltmek icin bana lazimdi. Dikkatli[ENTER]olmali ve yukseltmeye calistigin esyayi kaybetme[ENTER]ihtimaline hazirlikli olmalisin. Ne kadar iyi[ENTER]olsam da her zaman aksilik cikabilir. Vaktin[ENTER]oldugunda ugra, sana harika silahlar yapabilirim! "
gameforge.main_quest_lv6._250_sayReward = "%s Deneyim Puani kazandin. "
gameforge.main_quest_lv6._260_sayReward = "%s Yang kazandin. "
gameforge.main_quest_lv6._270_sayReward = "Kurt Postu+ kazandin. "
gameforge.main_quest_lv6._30_say = "Hey, sehirde bos bos dolasip yapacak bir sey[ENTER]yok deme! Antrenmana devam etmelisin! Gunumuzun[ENTER]zorlu kosullarinda hayatta kalmanin tek yolu[ENTER]egitimdir! "
gameforge.main_quest_lv6._40_say = "Madem buradasin, sana bir gorevim var: Demirci[ENTER]az once yanimdaydi ve Domuz Burnu teslimatinda[ENTER]sorunlar yasadigindan sikayet ediyordu. Sanirim[ENTER]yardima ihtiyaci var.[ENTER]Demirci'ye git ve seni benim gonderdigimi soyle.[ENTER]Hadi! "
gameforge.main_quest_lv6._50_sayReward = "Demirci'ye yardim edersen bir odul alacaksin. "
