gameforge.main_quest_lv90._010_sendLetter = "Karanlik Ejderha Kayasi "
gameforge.main_quest_lv90._020_say = "Yolculuk uzun ve zahmetli olsa da nihayet hedefine[ENTER]ulastin: Karanlik Ejderha Kayasi.[ENTER]Amiral Angmur'u bul. Onu Ejderha Atesi Burnu'nda[ENTER]bulacaksin. "
