gameforge.main_quest_lv90._450_say = "Mektup coktan General'in ellerine gecmis.[ENTER]Onu bizim icin halleder misin? Ama dikkatli ol,[ENTER]gnollar saldirgan yaratiklardir. Once saldirir,[ENTER]sonra sorarlar. "
gameforge.main_quest_lv90._460_say = "Gittim bile. "
gameforge.main_quest_lv90._470_say = "Sag ol. Sana guvenebilecegimizi biliyordum. "
