gameforge.main_quest_lv91._410_2_notice = "Onu Yon-I-Walker'a gotur. "
gameforge.main_quest_lv91._420_sendLetter = "Mantikor Mektubu Desifre Edildi "
gameforge.main_quest_lv91._430_say = "Yon-I-Walker seni ariyor. Yanina git ve mektubu[ENTER]desifre edip edemedigini ogren. "
gameforge.main_quest_lv91._440_say = "*mirildanir* ... Ah, geldin! Yardimin sayesinde[ENTER]mektubun buyuk kismini cozebildim. Ne yazik ki son[ENTER]kismin ustesinden gelemiyorum. Korkarim senden bir[ENTER]kez daha yardim istemek zorundayim. Acilen Karapaks[ENTER]Tozu'na ihtiyacim var. Onu Kabuklular kabilesinden[ENTER]General Istakoz veya Kral Yengec'te bulabilirsin. "
gameforge.main_quest_lv91._450_say = "Karapaks Tozu "
gameforge.main_quest_lv91._460_say = "Evet, sadece Kabuklular kabilesinde bulunur. Dikkat[ENTER]et ama, bu tozun kucuk bir dozu bile olumculdur![ENTER]Üc doz toz yeterli olacaktir. Basarilar. "
gameforge.main_quest_lv91._470_say = "Derhal yola cikiyorum. "
gameforge.main_quest_lv91._480_sayTitle = "Karapaks Tozu "
gameforge.main_quest_lv91._490_say = "Kabuklular kabilesinden General Istakoz ve Kral[ENTER]Yengec ile yuzles ve uc doz Karapaks Tozu elde et. "
gameforge.main_quest_lv91._500_say = "Karapaks Tozu olumcul derecede zehirlidir. Etkisinin[ENTER]zayiflamasi icin bir gun beklemem gerekiyor.[ENTER]Yarin bana ugra, o zaman belki sana daha fazlasini[ENTER]soyleyebilirim. "
gameforge.main_quest_lv91._510_say = "Karapaks Tozu sende! "
gameforge.main_quest_lv91._520_say = "Iyi is. Artik nihayet mektubun sifresini[ENTER]cozebilirim. Lutfen odul olarak bunu al. "
gameforge.main_quest_lv91._530_say = "Bana %d adet daha getir. "
gameforge.main_quest_lv91._540_say = "Bu Karapaks Tozu kirlenmis.[ENTER]Lutfen bana yeni bir doz getir. "
gameforge.main_quest_lv91._550_1_notice = "Karapaks Tozu bulmayi basardin. "
gameforge.main_quest_lv91._550_2_notice = "Onu Yon-I-Walker'a gotur. "
gameforge.main_quest_lv91._560_sendLetter = "Zehirlendi! "
gameforge.main_quest_lv91._570_say = "Amiral Angmur seni ariyor. Ne istedigini ogren. "
gameforge.main_quest_lv91._580_say = "Ejderha Tanrisi adina, nihayet buradasin![ENTER]Yon-I-Walker Karapaks Tozu ile zehirlendi. "
gameforge.main_quest_lv91._590_say = "Sadece acele etti ve dikkatsiz davrandi. Üstelik[ENTER]sanssizligimiza sifali bitki stoklarimiz tukendi.[ENTER]Kaya Cicekleri ara - kokleri zehri notralize[ENTER]edebilir. Bak, bu haritada nerede yetistiklerini[ENTER]isaretledim. "
gameforge.main_quest_lv91._600_say = "Elbette. "
gameforge.main_quest_lv91._610_say = "Sana guvenilebilecegini biliyordum. Lutfen acele[ENTER]et, fazla vaktimiz kalmadi. "
gameforge.main_quest_lv91._620_sayTitle = "Yon-I-Walker'i Kurtar! "
gameforge.main_quest_lv91._630_say = "Zehirlenen Yon-I-Walker'i iyilestirmek icin Kaya[ENTER]Cicegi Koku bul! "
gameforge.main_quest_lv91._640_1_notice = "Kaya Cicegi Koku'nu Yon-I-Walker'a gotur. "
gameforge.main_quest_lv91._650_say = "*nefes nefese*[ENTER]*oksurur*[ENTER]Oh, geldin. Cok kotu hissediyorum. Kaya Cicegi[ENTER]Koku buldun mu? "
gameforge.main_quest_lv91._660_say = "Evet, burada bende. "
gameforge.main_quest_lv91._670_say = "Oh, cok daha iyi hissediyorum. Vaktim henuz[ENTER]gelmemis. Tesekkur ederim. Al bakalim, iste[ENTER]odulun.[ENTER]Simdi isimi bitirecegim. Mektubu cozer cozmez[ENTER]Amiral Angmur seni derhal bilgilendirecektir. "
gameforge.main_quest_lv91._680_say = "Yon-I-Walker seninle konusmak istiyor. "
gameforge.main_quest_lv91._760_say = "Kalan "
gameforge.main_quest_lv91._770_say = {}
gameforge.main_quest_lv91._780_say = "92. seviyeye ulastiginda maceraya devam[ENTER]edebilirsin. "
gameforge.main_quest_lv92 = {}
gameforge.main_quest_lv92._010_sendLetter = "Kirmizi Hirsizlar Mektubu "
gameforge.main_quest_lv92._020_say = "Karanlik Vassallari'nin son mektubu Kirmizi[ENTER]Hirsizlar Cetesi'nde. Amiral Angmur'un senin icin[ENTER]daha fazla bilgisi var. "
gameforge.main_quest_lv92._030_say = "Karanlik Vassallari'nin komplo sirrini cozmeye[ENTER]yaklasiyoruz. Son mektup Kirmizi Hirsizlar[ENTER]Cetesi'nin elinde. "
gameforge.main_quest_lv92._040_say = "Kirmizi Hirsizlar Cetesi mi? "
gameforge.main_quest_lv92._050_say = "Karanlik Ejderha Kayasi'na surgun edilmis bir grup[ENTER]suclu. Ama bu cetede en tuhaf olan sey, iblislerle[ENTER]birlesmis olmalaridir. "
gameforge.main_quest_lv92._060_say = "Iblislerin insanlari yemek yerine onlarla birlesmesi[ENTER]mi? Gercekten de bu cok tuhaf. "
gameforge.main_quest_lv92._070_say = "Onlari ortak bir hedef birlestirdi: Altin. Kirmizi[ENTER]Hirsizlar Cetesi'nin kampi buradan uzakta degil.[ENTER]Kirmizi Cellat ve Kara General'i hakla. Mektup[ENTER]onlardan birinin elinde. "
gameforge.main_quest_lv92._080_say = "Ne yazik ki onceden uyarildilar ve mektubu dort[ENTER]parcaya bolduler. Mektubun tum yirtik parcalarini[ENTER]bulmaliyiz. "
gameforge.main_quest_lv92._090_say = "Tamam. "
gameforge.main_quest_lv92._100_say = "Tesekkur ederim! "
gameforge.main_quest_lv92._110_sayTitle = "Kirmizi Hirsizlar Mektubu "
gameforge.main_quest_lv92._120_say = "Kirmizi Cellat ve Kara General ile yuzles.[ENTER]Mektubun dort parcasini da bul. "
gameforge.main_quest_lv92._130_say = "Mektup henuz tamamlanmadi. Mektubun tum[ENTER]parcalarini bul. "
gameforge.main_quest_lv92._140_1_notice = "Kirmizi Hirsizlar Mektubu'nun tum parcalarini[ENTER]bulmayi basardin. "
gameforge.main_quest_lv92._140_2_notice = "Onu Amiral Angmur'a goster. "
gameforge.main_quest_lv92._150_say = "Amiral Angmur ile konus. "
gameforge.main_quest_lv92._160_say = "Harika. Minnettarligimin bir kaniti olarak bunu al. "
gameforge.main_quest_lv92._170_sendLetter = "Kirmizi Hirsizlar Mektubu "
gameforge.main_quest_lv92._180_say = "Amiral Angmur'un yardimina ihtiyaci var. "
gameforge.main_quest_lv92._190_say = "Burada olman ne iyi. Bir sorunumuz var. "
gameforge.main_quest_lv92._200_say = "Sorun nedir? "
gameforge.main_quest_lv92._210_say = "Kirmizi Hirsizlar Mektubu'nun bir de besinci[ENTER]parcasi var. O olmadan diger parcalar ise yaramaz.[ENTER]En cesur savascim Bae-Yong'u gondermistim ama[ENTER]basina bir sey gelmis olmali. Coktan donmus[ENTER]olmaliydi. Onu bulur musun, olur mu? "
gameforge.main_quest_lv92._220_say = "Onu bulurum. Su an nerede olabilecegini biliyor[ENTER]musun peki? "
gameforge.main_quest_lv92._230_say = "Sanirim Nefrit Korfezi'ne gitme niyetindeydi.[ENTER]Ama oraya varabildi mi, bilmiyorum. "
gameforge.main_quest_lv92._240_say = "O halde ise koyulalim! "
gameforge.main_quest_lv92._250_sayTitle = "Kayip Asker "
gameforge.main_quest_lv92._260_say = "Mektubun besinci parcasini bul. Ancak once[ENTER]Nefrit Korfezi'nde Bae-Yong'u bulmalisin. "
gameforge.main_quest_lv92._270_say = "Bae-Yong'u h�l� bulamadin mi? Bu bir olum kalim[ENTER]meselesi! Lutfen vazgecme, aramaya devam et. "
gameforge.main_quest_lv92._280_say = "*agir agir solur*[ENTER]Beni buldugun icin tesekkurler. Agir yaralandim ve[ENTER]korkarim pek fazla vaktim kalmadi...[ENTER]Bu kagit parcasini Kirmizi Cete'den birinin elinden[ENTER]kopardim.[ENTER]Onu Amiral Angmur'a gotur. Haydi! Acele et![ENTER]Ben basimin caresine bakarim...[ENTER](Kollarinda can verir). "
gameforge.main_quest_lv92._290_1_notice = "Bae-Yong son nefesini vermeden once mektubun eksik[ENTER]parcasini sana teslim etti. "
gameforge.main_quest_lv92._290_2_notice = "Simdi Amiral Angmur'a geri don. "
gameforge.main_quest_lv92._300_say = "Geldin! Bae-Yong'u bulmayi basardin mi? "
gameforge.main_quest_lv92._310_say = "Evet ama... "
gameforge.main_quest_lv92._320_say = "Ama mi?[ENTER]Olamaz! Oldu mu? "
gameforge.main_quest_lv92._330_say = "Onun icin artik yapilabilecek hicbir sey yoktu.[ENTER]Bassagligi dileklerimi kabul edin. Cesur bir[ENTER]savasciydi; mektubun son parcasi ugruna canini[ENTER]verdi. Iste burada. "
gameforge.main_quest_lv92._340_say = "Bae-Yong'un kaybindan oturu hepimiz buyuk aci[ENTER]cekiyoruz. Ama onunla gurur duyuyoruz. Gorevini[ENTER]sonuna kadar yerine getirdi; artik mektubun tum[ENTER]parcalarina sahibiz. "
gameforge.main_quest_lv92._350_say = "Her sey icin tesekkur ederim. Buyur, iste odulun.[ENTER]Simdi Bae-Yong icin bir mum yakacagim.[ENTER]Daha sonra sana basvururum. "
gameforge.main_quest_lv92._360_say = "Amiral Angmur'a git. "
gameforge.main_quest_lv92._370_sendLetter = "Kirmizi Hirsizlar Mektubunu Desifre Et "
gameforge.main_quest_lv92._380_say = "Amiral Angmur'un Kirmizi Hirsizlar Mektubu hakkinda[ENTER]onemli bilgileri var.[ENTER]Soyleyeceklerini dinle. "
gameforge.main_quest_lv92._390_say = "Ah, geldin. Karanlik Vassallari basimi agritiyor.[ENTER]Mektup sifreli. Onu Yon-I-Walker'a gotur. "
gameforge.main_quest_lv92._400_say = "Tamamdir. "
gameforge.main_quest_lv92._410_say = "Sifreli mektubu Yon-I-Walker'a gotur. "
gameforge.main_quest_lv92._420_say = "Hey, her zaman boyle sessizce yaklasmak zorunda[ENTER]misin?[ENTER]Sana nasil yardimci olabilirim? "
gameforge.main_quest_lv92._430_say = "Kirmizi Hirsizlar Mektubu elimde. Ne yazik ki[ENTER]digerleri gibi bu da sifreli. "
gameforge.main_quest_lv92._440_say = "Bir bakayim. Hm, bana Triton dilinin harfleri[ENTER]gibi geldi. Bunlari cozmek kolaydir. "
gameforge.main_quest_lv92._450_say = "Harika. Ne kadar surer? "
gameforge.main_quest_lv92._460_say = "O kadar acele etme. Sifre pek karmasik olmasa[ENTER]da bunun icin bazi yardimci araclara ihtiyacim var. "
gameforge.main_quest_lv92._470_say = "Elbette. Cok basit olmasi beklenemezdi zaten. "
gameforge.main_quest_lv92._480_say = "Gordugum kadariyla mizah anlayisini kaybetmemissin,[ENTER]hihi.[ENTER]Mektubu desifre edebilmek icin Oin Pulu'na ihtiyacim[ENTER]var. Maalesef bu nadir pullar sadece General Kappa[ENTER]ve Triton kabilesinin krali Triton'da bulunur.[ENTER]10 adet getir. "
gameforge.main_quest_lv92._490_say = "Hemen yola cikiyorum. "
gameforge.main_quest_lv92._500_sayTitle = "Oin Pulu Bul! "
gameforge.main_quest_lv92._510_say = "Pullarla sadece Triton kabilesinin krali Triton[ENTER]ve General Kappa kaplidir. "
gameforge.main_quest_lv92._520_say = "Pullar olmadan mektubu cozemem. Onlara sahip[ENTER]olmaliyim. "
gameforge.main_quest_lv92._530_1_notice = "Triton Oin Pullarini bulmayi basardin. "
gameforge.main_quest_lv92._530_2_notice = "Onlari cabucak Yon-I-Walker'a gotur. "
gameforge.main_quest_lv92._540_say = "Iyi is cikardin. Mektubu cozer cozmez Amiral[ENTER]Angmur'u bilgilendirecegim. Bu sirada sen dinlen.[ENTER]Lutfen bunu minnettarligimin bir nisanesi olarak al. "
gameforge.main_quest_lv92._550_say = "Yon-I-Walker seninle konusmak istiyor. "
gameforge.main_quest_lv92._560_sendLetter = "Karanlik Planlar "
gameforge.main_quest_lv92._570_say = "Karanlik Vassallari'nin mektubu desifre edildi.[ENTER]Amiral Angmur seni onlarin karanlik planlarina dahil[ENTER]edecek. "
gameforge.main_quest_lv92._580_say = "Gizli mesaji tamamen desifre etmeyi basardik.[ENTER]Gnoll Mektubu'nu hatirliyor musun? Orada adanin[ENTER]kalbinin derinliklerinde uyuyan ejderhalardan ve[ENTER]onlari nasil uyandirip ofkelendirebileceklerinden[ENTER]bahsediliyordu. Simdi Karanlik Vassallari'nin bunu[ENTER]nasil kullanmak istediklerini ogreniyoruz. "
gameforge.main_quest_lv92._590_say = "Ejderhayi, zihni cehennemin ucurumu kadar[ENTER]karardiginda oldurmek gerekiyor; o zaman Gece[ENTER]Incileri kusacaktir. Bu inciler araciligiyla[ENTER]Sung Mahi'nin akil almaz gucleri dunyamiza[ENTER]cagrilacak. Demek karanlik planlari buymus! "
gameforge.main_quest_lv92._600_say = "Bir sonraki adimi dikkatlice dusunmeliyiz. Senin[ENTER]icin yeni bilgilerim oldugunda seni cagiririm.[ENTER]Her sey icin tesekkur ederim. "
gameforge.main_quest_lv92._610_say = "93. seviyeye ulastiginda maceraya devam[ENTER]edebilirsin. "
gameforge.main_quest_lv93 = {}
gameforge.main_quest_lv93._010_sendLetter = "Guc Topla I "
gameforge.main_quest_lv93._020_say = "Amiral Angmur seninle konusmak istiyor. "
gameforge.main_quest_lv93._030_say = "Artik Karanlik Vassallari'nin ensesindeyiz. "
gameforge.main_quest_lv93._040_say = "Onlari yenebilmek icin gucunu artirmaliyiz.[ENTER]Ic Isik'in ne oldugunu biliyor musun? O yogunlasmis[ENTER]bir enerjidir. Bazi mistik yaratiklarda veya[ENTER]bitkilerde bulunur. Yon-I-Walker ondan guclendirici[ENTER]bir madde hazirlayabilir. Yanina git. "
gameforge.main_quest_lv93._050_say = "Anlastik. "
gameforge.main_quest_lv93._060_say = "Ah, iste kurtaricim![ENTER]Ic Isik, oh evet... Guclendirici ilacim sayesinde[ENTER]guc olarak Karanlik Vassallari'na denk olacaksin. "
gameforge.main_quest_lv93._070_say = "Bunun icin Tepegozlerin (Kikloplarin) ve Devlerin[ENTER]Ic Isigi'na ihtiyacim var. Ama unutma, onu sadece[ENTER]bu kabilelerin liderleri tasir. Once Tepegozlerle[ENTER]ilgilen. "
gameforge.main_quest_lv93._080_say = "Anlastik. "
gameforge.main_quest_lv93._090_sayTitle = "Ic Isik I "
gameforge.main_quest_lv93._100_say = "Tepegozler Krali Polyphemos'u yen ve Ic Isigini[ENTER]ondan al. "
gameforge.main_quest_lv93._110_say = "Ellerin bos mu geliyorsun? Bu sekilde sana yardim[ENTER]edemem. Bana Ic Isigi getir! "
gameforge.main_quest_lv93._120_1_notice = "Ic Isigi bulmayi basardin. Onu Yon-I-Walker'a[ENTER]gotur. "
gameforge.main_quest_lv93._130_say = "Yon-I-Walker ile konus. "
gameforge.main_quest_lv93._140_say = "Demek Ic Isik buymus... Üzerinde islem yapmadan[ENTER]once onu arindirmam gerek. Bu kesinlikle biraz[ENTER]vakit alacaktir. Hazir oldugumda sana haber[ENTER]veririm. "
gameforge.main_quest_lv93._150_sendLetter = "Guc Topla II "
gameforge.main_quest_lv93._160_say = "Yon-I-Walker seni ariyor. "
gameforge.main_quest_lv93._170_say = "Polyphemos'un Ic Isigi arindirildi. Devlerin Isigi'na[ENTER]da ihtiyacimiz var.[ENTER]Onu elde etmek icin Kral Voba'yi yenmelisin. "
gameforge.main_quest_lv93._180_say = "Derhal yola cikiyorum. "
gameforge.main_quest_lv93._190_sayTitle = "Ic Isik II "
gameforge.main_quest_lv93._200_say = "Devler Krali Voba'yi yen ve Ic Isigini ondan al. "
gameforge.main_quest_lv93._210_say = "Ellerin bos mu geliyorsun? Bu gorevin altindan[ENTER]kalkamazsan cok sasiririm. Tekrar dene! "
gameforge.main_quest_lv93._220_1_notice = "Devlerin Ic Isigini ellerinde tutuyorsun. "
gameforge.main_quest_lv93._220_2_notice = "Onu Yon-I-Walker'a gotur. "
gameforge.main_quest_lv93._230_say = "Yon-I-Walker ile konus. "
gameforge.main_quest_lv93._240_say = "Kral Voba'nin Ic Isigi devasa bir guce sahip.[ENTER]Sanirim o cusseden kaynaklaniyor. Simdi sadece onu[ENTER]arindirmam gerek. Bu da biraz surebilir. "
gameforge.main_quest_lv93._250_sendLetter = "Guc Topla III "
gameforge.main_quest_lv93._260_say = "Yon-I-Walker seni ariyor. "
gameforge.main_quest_lv93._270_say = "Cok iyi. Yardimina ihtiyacim var. Guclendirme[ENTER]Iksirimin tam olarak etki gostermesi icin bir[ENTER]bilesene daha ihtiyaci var: Milenyum Ozu. "
gameforge.main_quest_lv93._280_say = "Milenyum Ozu mu? Adini hic duymamistim. "
gameforge.main_quest_lv93._290_say = "Cesitli bitki ozlerinden yapilmis guclu bir[ENTER]karisimdir. Octavio'yu taniyor musun? Anakara'da[ENTER]yasiyor ve Milenyum Ozu'nu hazirlayabilen tek[ENTER]kisi o. Yanina git. Umarim bize yardim eder.[ENTER]Bazen inatcidir... "
gameforge.main_quest_lv93._300_say = "Anlastik. "
gameforge.main_quest_lv93._310_sayTitle = "Octavio ile Konus! "
gameforge.main_quest_lv93._320_say = "Octavio'yu bul. Anakara'da yasiyor ve Milenyum[ENTER]Ozu'nu hazirlayabilen tek kisi o. "
gameforge.main_quest_lv93._330_say = "Selam! Sana ne getireyim? Belki bir samgyetang[ENTER]corbasi? Evin spesiyali... "
gameforge.main_quest_lv93._340_say = "Octavio, leziz yemeklerin icin burada degilim![ENTER]Baska bir seye ihtiyacim var: Milenyum Ozu. "
gameforge.main_quest_lv93._350_say = "Ssst, o kadar yuksek sesle soyleme! Milenyum[ENTER]Ozu... Hayir, bu soz konusu bile olamaz. Onu[ENTER]kimden ogrendin? Bahsedebilecegi devasa gucle cok[ENTER]az kisi basa cikabilir. Bu cok riskli. Simdi kis kis,[ENTER]baskalari duymadan... "
gameforge.main_quest_lv93._360_say = "Octavio, bekle ve beni dinle! Beni Karanlik Ejderha[ENTER]Kayasi'ndan Yon-I-Walker gonderdi. Bu oze kesinlikle[ENTER]ihtiyacimiz var. O olmadan Karanlik Vassallari'ni[ENTER]yenemeyiz. Ve su an bildigimiz dunya yok olur.[ENTER]Onu sadece sen hazirlayabilirsin.[ENTER]Lutfen! "
gameforge.main_quest_lv93._370_say = "Yon-I-Walker mi dedin? Hm, o benim eski dostumdur.[ENTER]Gece sohbetlerimizde az mi kaliteli sarap tukettik[ENTER]birlikte. Dusunmem lazim. Yarin yanima gel, kabul[ENTER]edip etmedigimi soylerim. "
gameforge.main_quest_lv93._380_say = {}
gameforge.main_quest_lv93._390_say = "Henuz karar vermedim. Daha sonra gel. "
gameforge.main_quest_lv93._400_npcChat = "Milenyum Ozu "
gameforge.main_quest_lv93._410_say = "Octavio seninle konusmak istiyor. "
gameforge.main_quest_lv93._420_say = "Butun gece ricani dusundum. Ve bu riski almaya[ENTER]karar verdim. Bunun dogru bir karar oldugunu[ENTER]biliyorum. Evet, sana yardim edecegim. "
gameforge.main_quest_lv93._430_say = "Harika! "
gameforge.main_quest_lv93._440_say = "Ancak elimde hazirda yok. Bana birkac malzeme[ENTER]getirir misin? O zaman senin icin hazirlarim. "
gameforge.main_quest_lv93._450_say = "Elbette. Neye ihtiyacin var? "
gameforge.main_quest_lv93._460_say = "Gango Koku, Tue Mantari ve Alp Gulu'ne ihtiyacim[ENTER]var. Her bir malzemeden 200'er adet. "
gameforge.main_quest_lv93._470_say = "Derhal yola koyuluyorum. Bu malzemeleri nerede[ENTER]bulabilirim? "
gameforge.main_quest_lv93._480_say = "Bu bitkileri Anakara'nin cesitli yerlerinde[ENTER]bulabilirsin.[ENTER]Sen malzemeleri ararken ben de hazirliklara[ENTER]baslayayim. "
gameforge.main_quest_lv93._490_sayTitle = "Milenyum Tarifi "
gameforge.main_quest_lv93._500_say = "Gango Koku, Tue Mantari ve Alp Gulu ara.[ENTER]Her birinden 200'er adet gerekiyor. "
gameforge.main_quest_lv93._510 = "Bu bitkileri Anakara'nin cesitli yerlerinde[ENTER]bulabilirsin.[ENTER]Sen malzemeleri ararken ben de hazirliklara[ENTER]baslayayim. "
gameforge.main_quest_lv93._520_say = "Ah, harika, dondun. Ve gereken her sey var.[ENTER]O zaman ise koyuluyorum. Simdi sessizlige ihtiyacim[ENTER]var. Yarin ayni saatte gel. Umarim o zamana kadar[ENTER]oz hazir olur. "
gameforge.main_quest_lv93._530_say = "Pekala. Yarina kadar gorusmek uzere. "
gameforge.main_quest_lv93._540_say = "Acelen oldugunu anliyorum ama biraz daha[ENTER]beklemen gerek. Daha sonra gel. "
gameforge.main_quest_lv93._550_say = "Octavio seni ariyor. "
gameforge.main_quest_lv93._560_say = "Bak sen, tam vaktinde geldin. Az once Milenyum[ENTER]Ozu'nun hazirlanisini tamamladim![ENTER]Simdi onu Yon-I-Walker'a goturebilirsin. "
gameforge.main_quest_lv93._570_say = "Tesekkurler! "
gameforge.main_quest_lv93._580_sendLetter = "Milenyum Ozu "
gameforge.main_quest_lv93._590_say = "Yon-I-Walker seni ariyor. "
gameforge.main_quest_lv93._600_say = "Milenyum Ozu sende! Artik Guclendirme Iksirim[ENTER]icin gereken tum malzemelere sahibim. Onu hazirlar[ENTER]hazirlamaz seni cagiracagim. "
gameforge.main_quest_lv93._610_say = "Tamamdir. "
gameforge.main_quest_lv93._620_say = "94. seviyeye ulastiginda maceraya devam[ENTER]edebilirsin. "
gameforge.main_quest_lv93._630_say = "%s: %d adet, %s: %d adet,[ENTER]%s: %d adet "
gameforge.main_quest_lv93._640_say = "Yapacak islerim var, meyhanemle ilgilenmeliyim[ENTER]ve vakit kaybedemem. Eksik malzemeleri bana getir[ENTER]- ve acele et! "
