gameforge.main_quest_lv94._250_say = "Artik Yildirim Daglari'ndaki durum hakkinda bir[ENTER]fikre sahipsin.[ENTER]Amiral Angmur'a rapor ver. "
gameforge.main_quest_lv94._260_say = "Amiral Angmur'a geri don. "
gameforge.main_quest_lv94._270_say = "Ah, nihayet geldin! Harika, simdi sagladigin[ENTER]bilgileri analiz edecegiz ve bir strateji[ENTER]gelistirecegiz. "
