gameforge.main_quest_lv94._300_say = "Amiral Angmur seni ariyor. "
gameforge.main_quest_lv94._310_say = "Dogrudan bir saldiri su an icin bana cok riskli[ENTER]gorunuyor. Saldiri harekatina gecmeden once[ENTER]dusman guclerini zayiflatmaliyiz. "
gameforge.main_quest_lv94._320_say = "Yildirim Daglari'nda su gruplarla karsilasacaksin:[ENTER]Devler, Tepegozler ve Kirmizilar.[ENTER]Baslangicta Kirmizi Hirsizlar Cetesi'ni hedef aliyoruz! "
