gameforge.main_quest_lv94._360_say = "Haklisin. Ama ona karsi koyabilecek biri varsa,[ENTER]o da muhakkak sensin. Basarilar! "
gameforge.main_quest_lv94._370_sayTitle = "Kirmizi Sef "
gameforge.main_quest_lv94._380_say = "Kirmizi Sef'i yen ve pelerinini al. "
gameforge.main_quest_lv94._390_say = "... yenilgi mi? Hayir, inanamiyorum. Bu kadar cabuk[ENTER]pes etme. Tekrar dene, bu sefer kesinlikle onun[ENTER]hakkindan geleceksin! "
