gameforge.main_quest_lv95._130_say = {}
gameforge.main_quest_lv95._140_say = "Lanet olsun! Kaptan Hook Kara Altin'i Banshee'ye[ENTER]teslim etmis. Fakat son cumleyi anlamiyorum:[ENTER]Yasam Laneti, zamanin sisli ucurumlarindan[ENTER]karanligin ordusunu cagiracaktir. "
gameforge.main_quest_lv95._150_say = "Bu sevkiyati durdurmaliyiz! Banshee'nin siginagi[ENTER]batida bir yerlerde, Gautama Ucurumu'nda. Orasi[ENTER]ebedi sisle kapli korkunc bir issizliktir. Orada[ENTER]Ogreler ve Lemurlar yasar. "
gameforge.main_quest_lv95._160_say = {}
gameforge.main_quest_lv95._170_say = "Kara Altin sevkiyatinin hangi rotayi izledigini[ENTER]ogrenir ogrenmez sana haber veririm. "
