gameforge.main_quest_lv95._200_say = "Gozculerim, Kara Altin'in ogrelerin lideri Kaptan[ENTER]Shrack tarafindan Gautama Ucurumu'na tasindigini[ENTER]ogrendi. Kemerinde tasidigi bir kesede gizli.[ENTER]Onu ele gecir! "
gameforge.main_quest_lv95._210_say = {}
gameforge.main_quest_lv95._220_say = "Sorun degil, hemen yola cikiyorum. "
