gameforge.main_quest_lv95._240_say = "Kaptan Shrack'i bul ve Banshee'ye ulasmadan once[ENTER]Kara Altin dolu torbayi elinden al. "
gameforge.main_quest_lv95._250_say = "Sey, Kaptan Shrack hafif siklet sayilmaz... ama[ENTER]tekrar dene. Bu sefer onun hakkindan gelecegini[ENTER]biliyorum! "
gameforge.main_quest_lv95._260_1_notice = "Torba alindi. "
gameforge.main_quest_lv95._260_2_notice = "Amiral Angmur'a geri don. "
gameforge.main_quest_lv95._270_say = "Ganimetini Amiral Angmur'a gotur. "
gameforge.main_quest_lv95._280_say = "Eee? Bu torbada Kara Altin var, degil mi? Ha?[ENTER]Burada sadece bir kagit parcasi goruyorum... "
gameforge.main_quest_lv95._290_say = "Kara Altin sevkiyati, cevher tamamen islendiginde[ENTER]gerceklesecektir. "
gameforge.main_quest_lv95._300_say = "Tuh be! Kara Altin h�l� yanlis ellerde. En[ENTER]azindan Banshee onu kullanmadan once bir sekilde[ENTER]islenmesi gerektigini biliyoruz. "
gameforge.main_quest_lv95._310_say = "Demek ki henuz cok gec degil. Kara Altin'in su an[ENTER]kimde oldugunu ve islenip islenmedigini[ENTER]ogrenecegim. Bu bilgileri alir almaz seni[ENTER]cagiririm. Lutfen zahmetlerin icin bunu kabul et.[ENTER]Simdilik hosca kal! "
gameforge.main_quest_lv95._320_sendLetter = "Isleme Surecini Kesintiye Ugrat "
gameforge.main_quest_lv95._330_say = "Amiral Angmur'a git. Kara Altin hakkinda yeni[ENTER]bilgileri var. "
gameforge.main_quest_lv95._340_say = "Kara Altin isleme surecinin Ogre Maximus[ENTER]tarafindan denetlendigi ve is bittikten sonra[ENTER]onu Banshee'ye ulastiracagi bilgisini aldik. "
gameforge.main_quest_lv95._350_say = "Su anda Gautama Ucurumu civarinda bulunuyor.[ENTER]Kara Altin'in hedefine ulasmasina izin verme.[ENTER]Cabuk ol, henuz cok gec olmadan! "
