gameforge.main_quest_lv95._380_say = "Ogre liderini yen ve Kara Altin isleme surecini[ENTER]durdur. "
gameforge.main_quest_lv95._390_say = "Her dakika onemli! Ogre Maximus'u durdur! "
gameforge.main_quest_lv95._400_notice = "Ogre Maximus oldu. "
gameforge.main_quest_lv95._410_say = "Bizi durduramazsiniz! Banshee Kara Altin[ENTER]teslimatini coktan aldi bile. Cok gec kaldiniz[ENTER]aptallar! "
gameforge.main_quest_lv95._420_say = "Durum giderek daha tehlikeli hale geliyor. Amiral[ENTER]Angmur'a don ve ona rapor ver. "
gameforge.main_quest_lv95._430_say = "Amiral Angmur ile konus. "
gameforge.main_quest_lv95._440_say = "Hizli ciktin! Kara Altin sende mi? "
gameforge.main_quest_lv95._450_say = "Hayir, her sey bosuna... Kara Altin Banshee'ye[ENTER]coktan ulasti. "
gameforge.main_quest_lv95._460_say = "Ejderha Tanrisi bize merhamet etsin! Ama oyle[ENTER]kolayca pes etmeyecegiz. Banshee'nin siginagini[ENTER]bulmalari icin gozculerimi gonderecegim. Daha[ENTER]fazlasini ogrenir ogrenmez seni cagirtirim. Bu[ENTER]arada yeni guc topla ve bu odulu kabul et. "
gameforge.main_quest_lv95._470_sendLetter = "Yasam Laneti "
gameforge.main_quest_lv95._480_say = "Amiral Angmur yeni bilgilere sahip. Yanina git. "
gameforge.main_quest_lv95._490_say = "Artik bu yasam lanetinin ve karanlik ordusunun ne[ENTER]oldugunu biliyoruz. Karanlik Ejderha Kayasi'nda bir[ENTER]zamanlar kotu kalpli bir buyucu yasarmis. Tum[ENTER]kitanin yonetimini ele gecirmek istemis ve bu amaca[ENTER]ulasmak icin kelimenin tam anlamiyla cesetleri[ENTER]cignemis: Yasam Laneti adli karanlik buyuyu[ENTER]kullanarak oluler ordusunu diriltmis. "
gameforge.main_quest_lv95._500_say = {}
gameforge.main_quest_lv95._510_say = "Oluleri diriltmek mi... Sadece bunu dusunmek bile[ENTER]kalbimi yerinden oynatiyor. Karanlik Vassallari,[ENTER]koca bir yasayan oluler ordusu kurmak icin Kara[ENTER]Altin'i kullaniyor. Onlari durdurmaliyiz! "
gameforge.main_quest_lv95._520_say = "Gautama Ucurumu bolgesindeki eski harabelere git[ENTER]ve orada Lemur Buyucusu'nu bul. Bu lanet hakkinda[ENTER]bir seyler biliyor. Ondan guzelce rica edersen[ENTER]sana yardim edecektir. "
gameforge.main_quest_lv95._530_say = "Anladim, o zaman ondan kendi yontemimle rica[ENTER]edecegim. "
gameforge.main_quest_lv95._540_sayTitle = "Yasam Laneti "
gameforge.main_quest_lv95._550_say = "Lemur Buyucusu'nu yen ve Yasam Laneti ile olulerin[ENTER]diriltilmesi hakkinda bilgi edin. "
gameforge.main_quest_lv95._560_say = "Kaybedecek vaktimiz yok. Lemur Buyucusu'nu yen ve[ENTER]ondan Yasam Laneti hakkindaki bilgileri sokup al. "
gameforge.main_quest_lv95._570_1_notice = "Lemur Buyucusu oldu ve ardinda uzeri oyulmus tas[ENTER]bir tablet birakti. "
gameforge.main_quest_lv95._570_2_notice = "Onu Amiral Angmur'a goster. "
