gameforge.main_quest_lv95._590_say = "Ay, Lemur Buyucusu'nun uzerinde bu tablet mi[ENTER]vardi? Goster, goster... "
gameforge.main_quest_lv95._600_sayReward = "Olulerin diriltilmesi icin uc sey vazgecilmezdir:[ENTER]1. Insan bedeni[ENTER]2. ...[ENTER]Lemur Tableti bu kisimdan kirilmis.[ENTER]Yazitin geri kalani eksik. "
gameforge.main_quest_lv95._610_say = "Korkarim tekrar yola koyulman gerekecek. Bu[ENTER]tabletin kalan iki parcasina kesinlikle ihtiyacimiz[ENTER]var. Mutlaka! "
gameforge.main_quest_lv95._620_say = "Iste simdiye kadarki tum cabalarin icin odulun.[ENTER]Simdi Lemur Tableti'nin kalan parcalarini aramaya[ENTER]koyul! "
gameforge.main_quest_lv95._630_sendLetter = "Yazit "
gameforge.main_quest_lv95._640_sayTitle = "Lemur Tabletini Bul! "
gameforge.main_quest_lv95._650_say = "Lemur Buyuculerini maglup et ve tabletin kalan[ENTER]parcalarini bul. "
gameforge.main_quest_lv95._660_say = "Lutfen, bu yazitin ne soyledigini bilmemiz gerek.[ENTER]Pes etme! "
gameforge.main_quest_lv95._670_say = "Lemur Tableti'nin kalan iki parcasini Amiral[ENTER]Angmur'a gotur. "
gameforge.main_quest_lv95._680_say = "Ay, seni gormek ne guzel! Simdi gel, Lemur[ENTER]Tableti'ni birlestirelim ve yaziti okuyalim. "
gameforge.main_quest_lv95._690_sayReward = "Olulerin diriltilmesi icin uc sey vazgecilmezdir:[ENTER]1. Insan bedeni[ENTER]2. Kara Altin[ENTER]3. Agac Varliklarinin Kabugu[ENTER]Sadece olaganustu yeteneklere sahip bir buyucu[ENTER]Yasam Laneti buyusunu yapabilir. Ancak o oldugunde,[ENTER]onunla birlikte tum yasayan oluler ordusu da yok[ENTER]olur. "
gameforge.main_quest_lv95._700_say = "Demek son zamanlarda mezarliklarimizin bu kadar sik[ENTER]yagmalanmasi ve cesetlerin cikarilmasi bu[ENTER]yuzdendi. Karanligin ordusuna katilmak uzere[ENTER]diriltilecek olanlar tam da bu cesetler. Ne[ENTER]igrenc bir dusunce! "
gameforge.main_quest_lv95._710_say = "Bu saygisiz eylemleri durdurmaliyiz! "
gameforge.main_quest_lv95._720_say = "Ay, ne yazik ki zaman aleyhimize isliyor. Yalnizca[ENTER]Banshee bu buyuyu yapabilecek kadar guclu ama su[ENTER]anda nerede saklandigi hakkinda hicbir fikrimiz[ENTER]yok. Bu karanlik bas rahibenin siginagini bulmalari[ENTER]icin tum adamlarimi seferber edecegim. Daha fazlasini[ENTER]ogrenir ogrenmez seni cagirtirim. "
