gameforge.main_quest_lv96._050_say = {}
gameforge.main_quest_lv96._060_say = "Olulerin ruhlarinin bedenlerini terk etmesi icin[ENTER]bir araciya (medyuma) ihtiyac vardir. Bu, Devlerin[ENTER]cuval icinde depoladigi Kutsanmis Toprak'tir.[ENTER]Bu cuvallardan 100 tanesini calmayi basarirsan,[ENTER]Yasam Laneti'nin yapilmasini engelleyebiliriz. "
gameforge.main_quest_lv96._070_say = "O halde ise koyulalim! "
