gameforge.main_quest_lv96._120_say = "Amiral Angmur'a rapor ver. "
gameforge.main_quest_lv96._130_say = "Sana guvenilebilecegini biliyordum! Tesekkurler.[ENTER]Lutfen odul olarak bunu kabul et. "
