gameforge.main_quest_lv96._160_say = "Ogreler de oluleri diriltmek icin bir tur araciyi[ENTER]koruyorlar ama maalesef neye benzedigini[ENTER]bilmiyoruz. Bu yuzden onlarin yanina git ve supheli[ENTER]gorunen ne varsa topla. "
gameforge.main_quest_lv96._170_say = {}
gameforge.main_quest_lv96._180_say = {}
gameforge.main_quest_lv96._190_say = "Anlastik. "
gameforge.main_quest_lv96._200_sayTitle = "Ogrelerin Aracisi "
gameforge.main_quest_lv96._210_say = "Ogreleri yen ve aracilarinin neye benzedigini[ENTER]ogren. "
gameforge.main_quest_lv96._220_say = "Elinizde neredeyse hic ipucu olmadigini biliyorum.[ENTER]Ama orada kesinlikle bir seyler bulacaksin! "
gameforge.main_quest_lv96._230_1_notice = "Madeni Para Kesesi ve Altin Nisan bulundu. "
gameforge.main_quest_lv96._230_2_notice = "Her iki esyayi da Amiral Angmur'a gotur. "
gameforge.main_quest_lv96._240_say = "Amiral Angmur'a rapor ver. "
gameforge.main_quest_lv96._250_say = "Iyi is! Yon-I-Walker'dan bu esyalari analiz[ENTER]etmesini isteyecegim. "
gameforge.main_quest_lv96._260_say = "Yon-I-Walker'i bul ve analiz sonuclarini sana[ENTER]iletmesini iste. "
gameforge.main_quest_lv96._270_say = "Ah, geldin! Ogrelerde bulmayi basardigin esyalari[ENTER]inceledim bile. "
gameforge.main_quest_lv96._280_say = {}
gameforge.main_quest_lv96._290_say = "Kesedeki Altin Paralar guclu, karanlik bir aura[ENTER]yayiyor. Paralar bir tur araci gorevi goruyor.[ENTER]Bunu Angmur'a ilet. "
gameforge.main_quest_lv96._300_sendLetter = "Laneti Durdur "
gameforge.main_quest_lv96._310_say = "Amiral Angmur'a git. "
gameforge.main_quest_lv96._320_say = "Lutfen bu Altin Arayici Bandi'ni al. Onu ogrelerin[ENTER]para kesesini bulmak icin kullan. "
gameforge.main_quest_lv96._330_say = "100 altin paraya ihtiyacimiz var. Ama korkarim[ENTER]eline gecenlerin hepsi araci olarak kullanilamaz.[ENTER]Seni epey bir is bekliyor. "
gameforge.main_quest_lv96._340_say = "Sorun degil. "
gameforge.main_quest_lv96._350_sayTitle = "Altin Arayisi "
gameforge.main_quest_lv96._360_say = "Ogrelerle savasa gir ve Para Keseleri topla. Tum[ENTER]paralar araci gorevi gormez, ancak Yon-I-Walker[ENTER]hangilerinin karanlik aurayla isaretlendigini[ENTER]anlayabilir. "
gameforge.main_quest_lv96._370_say = "Evet, karanlik enerjiyi tam olarak hissedebiliyorum. "
gameforge.main_quest_lv96._380_say = "Fantastik, artik araci olarak kullanilabilecek tum[ENTER]altin paralara sahibiz. Bu mendebur Banshee'nin hic[ENTER]hosuna gitmeyecek, hem de hic! Al bakalim, iste[ENTER]odulun. Siradaki gorevi Angmur'dan alacaksin. "
gameforge.main_quest_lv96._390_say = "H�l� altin paralar eksik, tam olarak %d adet. "
gameforge.main_quest_lv96._400_sendLetter = "Laneti Durdur "
gameforge.main_quest_lv96._410_say = "Amiral Angmur seni ariyor. "
gameforge.main_quest_lv96._420_say = "Karanlik Vassallari'nin Agac Varliklarinin Kabugu'nu[ENTER]ele gecirmesine izin veremeyiz. "
gameforge.main_quest_lv96._430_say = "Agac Varliklari dunyamizin en gizemli yaratiklari[ENTER]arasindadir ve kimsenin emri altina girmezler.[ENTER]Sung Mahi'nin bile onlar uzerinde bir hukmu yoktur.[ENTER]Gautama Ucurumu cevresinde uc farkli tur bulacaksin:[ENTER]Aku-Boku, Arboretum ve Sycomor.[ENTER]Kabuklarini soy onlarin! "
gameforge.main_quest_lv96._440_say = {}
gameforge.main_quest_lv96._450_say = "Anlastik. "
gameforge.main_quest_lv96._460_sayTitle = "Agac Varliklarini Yakala "
gameforge.main_quest_lv96._470_say = "Aku-Boku, Arboretum ve Sycomor'un kabugunu soy. "
gameforge.main_quest_lv96._480_counterName = "Kalan "
gameforge.main_quest_lv96._490_say = {}
gameforge.main_quest_lv96._500_say = "Zaman daraliyor. Agac varliklarini avla ve[ENTER]Karanlik Vassallari davranmadan once kabuklarini soy. "
gameforge.main_quest_lv96._510_1_notice = "Agac yaratiklarini katletmeyi basardin ama ne[ENTER]yazik ki birisi senden once davranip kabuklarini[ENTER]soymus bile. "
gameforge.main_quest_lv96._510_2_notice = "Bunu Amiral Angmur'a bildir. "
gameforge.main_quest_lv96._520_say = "Amiral Angmur'a rapor ver. "
gameforge.main_quest_lv96._530_say = "Geldin! Ne oldu? Yaratiklarin kabugunu almayi[ENTER]basardin mi? Ne?! Baskasi coktan soymus mu?[ENTER]Demek Vassallar bizden once davrandi. "
gameforge.main_quest_lv96._540_say = {}
gameforge.main_quest_lv96._550_say = "Kabuk ellerinde olduguna gore Yasam Laneti'ni[ENTER]yapmanin bir yolunu mutlaka bulacaklardir. O halde[ENTER]savasa hazirlanmaktan baska caremiz yok. Banshee[ENTER]h�l� bizimle saklambac oynuyor ama adamlarim[ENTER]onun ensesinde. Yeni bir sey ogrenir ogrenmez seni[ENTER]cagirtirim. "
gameforge.main_quest_lv96._560_sayTitle = "Maceranin devami 97. seviyeye ulastiginda "
gameforge.main_quest_lv96._570_counterName = "Kalan "
gameforge.main_quest_lv96._580_sayReward = "%s: %d adet "
gameforge.main_quest_lv96._590_say = "Demek altin paralar araci olarak kullanilacak.[ENTER]Guzel, o zaman sonraki adimlarimiz konusunda[ENTER]Yon-I-Walker ile istisare edecegim. Her seyi[ENTER]belirledigimizde sana haber veririm. "
