gameforge.main_quest_lv97 = {}
gameforge.main_quest_lv97._010_sendLetter = "Banshee'yi Durdur "
gameforge.main_quest_lv97._020_say = "Banshee'nin siginagi kesfedildi! Bu konuda daha[ENTER]fazlasini ogrenmek icin Amiral Angmur'a git. "
gameforge.main_quest_lv97._030_say = "Adamlarim nihayet Gautama Ucurumu'nda Banshee'nin[ENTER]siginagini kesfetti. Cevre ormanlarin derinliklerine[ENTER]cekilmis ve orada kara buyusunu uygulamaya devam[ENTER]ediyor. Ayrica ejderha tarikatinin eski Tapinak[ENTER]Rahibesi'ni yeniden uyandirdi. Ve onunla birlikte[ENTER]Yasam Laneti'ni cagirmayi planliyor. "
gameforge.main_quest_lv97._040_say = "Onun yardimi olmadan laneti surduremez. Tapinak[ENTER]Rahibesi Mu-Shu'yu alt et ve yoldaslarimizin[ENTER]bedenleri bize karsi dirilmeden once ruhlarini[ENTER]huzura kavustur. "
gameforge.main_quest_lv97._050_say = "Tapinak Rahibesi'ne seni fark etmeden ve saldirmadan[ENTER]yaklasmak neredeyse imkansizdir. Sansini, o[ENTER]buyusune adeta transa gececek kadar derin daldigi[ENTER]anda denemeye calis. "
gameforge.main_quest_lv97._060_say = "Tamamdir. "
gameforge.main_quest_lv97._070_say = "Kendine dikkat et! Yasarken bas rahibenin ilk[ENTER]muhafizlarindan biriydi; sadece buyu konusunda[ENTER]degil, kilic kullanmada da ustaydi. "
gameforge.main_quest_lv97._080_sayTitle = "Tapinak Rahibesi "
gameforge.main_quest_lv97._090_say = "Gautama Ucurumu'nda Banshee'nin Tapinak Rahibesi[ENTER]Mu-Shu'yu maglup et. "
gameforge.main_quest_lv97._100_notice = "Olumcul darbe alan Tapinak Rahibesi yere yigilir. "
gameforge.main_quest_lv97._110_say = "Ne kadar da aptalsiniz! Banshee'nin attigi yemi[ENTER]kendi rizanizla yuttunuz.[ENTER]O, gercek Tapinak Rahibesi Yah-Ki ile birlikte[ENTER]laneti gerceklestirmek icin hazirliklara coktan[ENTER]baslamisken siz burada benimle vakit kaybettiniz.[ENTER]Basarmalari icin dua ediyorum. "
gameforge.main_quest_lv97._120_say = "Kopyasi sizi yanlis ize yonlendirmis! Üzerini[ENTER]aradiktan sonra daha once Martyaxwar'da bulunan kolyeye[ENTER]benzer bir kolye buluyorsun. Ic cebinde bir belge[ENTER]var. "
gameforge.main_quest_lv97._130_say = "Amiral Angmur'a rapor ver. "
gameforge.main_quest_lv97._140_say = "Dondun bile. Tapinak Rahibesi'ni yenmeyi basardin mi? "
gameforge.main_quest_lv97._150_say = "Hayir, bir dublor tarafindan kandirildik. Gercek[ENTER]rahibe rahatca oluleri diriltme hazirliklarini[ENTER]yapabildi. Ama bu belgeyi bulmayi basardim. "
gameforge.main_quest_lv97._160_say = "Lanet olsun! Nasil boyle kandirilabildik?![ENTER]Lutfen belgeyi bana goster. "
gameforge.main_quest_lv97._170_say = {}
gameforge.main_quest_lv97._180_say = {}
gameforge.main_quest_lv97._190_say = "Hm, sifreli. Ama belki de gercek uslerinin nerede[ENTER]oldugunu buradan ogrenebiliriz. Bu harfleri daha[ENTER]once bir yerde gormustum... Sanirim saray muhafizi[ENTER]Yak-Hwan gecenlerde bana benzer bir sey gostermisti.[ENTER]Yanina git. O bu belgeye bir goz atsin. "
gameforge.main_quest_lv97._200_sendLetter = "Belgeyi Desifre Et "
gameforge.main_quest_lv97._210_say = "Yak-Hwan'a git ve sifreli belgeyi ona goster. "
gameforge.main_quest_lv97._220_say = "Selam! Adim Yak-Hwan. Seninle tanismak benim icin[ENTER]buyuk bir onur. Yaptiklarin simdiden bir efsane![ENTER]Sana nasil yardim edebilirim? Ah, sifreli bir mesaj.[ENTER]Goster bakalim. "
gameforge.main_quest_lv97._230_say = "Bu belgeyi desifre edebilirim ama bunun icin Taslasmis[ENTER]Toprak'a ihtiyacim var. Simyaci'da h�l� bir parca[ENTER]olmali. Lutfen ona bir sor. "
gameforge.main_quest_lv97._240_say = {}
gameforge.main_quest_lv97._250_say = {}
gameforge.main_quest_lv97._260_say = "Elbette. "
gameforge.main_quest_lv97._270_sayTitle = "Taslasmis Toprak "
gameforge.main_quest_lv97._280_say = "Simyaci'ya git ve Taslasmis Toprak iste. "
gameforge.main_quest_lv97._290_say = "Bir sey unutmadin mi? Senden bana Taslasmis[ENTER]Toprak getirmeni rica etmistim. "
gameforge.main_quest_lv97._300_notice = "Simyaci sana Taslasmis Toprak verdi. Simdi[ENTER]Yak-Hwan'a geri don. "
gameforge.main_quest_lv97._310_say = "Ah, Taslasmis Toprak. Cok guzel. O zaman ise[ENTER]koyuluyorum. Sonucu Amiral'e iletecegim. "
gameforge.main_quest_lv97._320_sendLetter = "Arka Kapidan "
gameforge.main_quest_lv97._330_say = "Amiral Angmur seni ariyor. "
gameforge.main_quest_lv97._340_say = "Tapinak Rahibesi Yah-Ki'nin bulundugu yeri artik[ENTER]biliyoruz. Ne yazik ki bu us devasa bir kaleyi[ENTER]andiriyor - muhafiz birlikleri surekli cevrede[ENTER]devriye geziyor. Su anda onden dogrudan bir saldiri[ENTER]bizim icin intihar olur. "
gameforge.main_quest_lv97._350_say = "Bu yuzden pusu kurarak saldirmak istiyoruz.[ENTER]Adamlarim uygun bir yer ariyor bile. Daha fazla zaman[ENTER]kazanmamiz icin muhafizlarin dikkatini baska yone cek. "
gameforge.main_quest_lv97._360_say = {}
gameforge.main_quest_lv97._370_say = "Muhafiz birliklerinden biri en tehlikelisidir.[ENTER]Kendilerine Kara Olum Tugayi diyorlar. Tugay Moghu,[ENTER]Carnifex ve General Albus'tan olusuyor. Liderleri[ENTER]ise Iskeletor.[ENTER]Gozcu birligimi kesfetmeden once hepsini ortadan kaldir. "
gameforge.main_quest_lv97._380_say = "Tamam. "
gameforge.main_quest_lv97._390_sayTitle = "Kara Olum Tugayi "
gameforge.main_quest_lv97._400_say = "Moghu, Carnifex, General Albus ve Iskeletor'dan[ENTER]olusan Kara Olum Tugayi'ni maglup et. "
gameforge.main_quest_lv97._410_say = "Gozcu birligini kesfetmeden once Kara Olum[ENTER]Tugayi uyelerini saf disi birak. "
gameforge.main_quest_lv97._420_say = "Amiral Angmur'a rapor ver. "
gameforge.main_quest_lv97._430_say = "Planimiz ise yaradi! Kara Olum Tugayi'ni uzaklastirmayi[ENTER]basardin ve bu sirada adamlarim pusu saldirisi icin[ENTER]uygun yeri buldular.[ENTER]Saldiri stratejimizi belirler belirlemez seni[ENTER]cagiracagim. "
gameforge.main_quest_lv97._440_sendLetter = "Tapinak Rahibesi "
gameforge.main_quest_lv97._450_say = "Amiral Angmur'un yardimina ihtiyaci var! "
gameforge.main_quest_lv97._460_say = "Burada olman ne iyi. Iskeletor hayatta kaldi ve[ENTER]ussu basmak istedikleri sirada adamlarima saldirdi.[ENTER]Kimseyi gecirtmedi. "
gameforge.main_quest_lv97._470_say = {}
gameforge.main_quest_lv97._480_say = "Onu daha once yenmeyi basarmistin. Bu yuzden lutfen[ENTER]Gautama Ucurumu'ndaki adamlarima yardim et! Iskeletor[ENTER]ile yuzles. Ardindan usse saldir ve Tapinak Rahibesi[ENTER]Yah-Ki'yi oldur. "
gameforge.main_quest_lv97._490_say = "Anlastik. "
gameforge.main_quest_lv97._500_say = {}
gameforge.main_quest_lv97._510_sayTitle = "Yah-Ki'yi Yok Et "
gameforge.main_quest_lv97._520_say = "Tapinak Rahibesi Yah-Ki'yi maglup et ve oluler[ENTER]ordusunu cagirmasini engelle. "
gameforge.main_quest_lv97._530_say = "Karar gunu geldi catti. Olursek tum dunya bizimle[ENTER]birlikte yok olacak. Ancak kazanirsak, sanli[ENTER]zaferlerimiz bin yil boyunca sarkilarda soylenecek.[ENTER]Karanlik Vassallari'ni durdur. Tapinak Rahibesi[ENTER]Yah-Ki'yi yok et! "
gameforge.main_quest_lv97._540_say = "Neden buradasin? Savas henuz bitmedi. Tapinak[ENTER]Rahibesi Yah-Ki'yi maglup et. Butun umudumuzu sana[ENTER]bagladik. "
gameforge.main_quest_lv97._550_1_notice = "Rakibini dizlerinin uzerine cokturdun.[ENTER]Zafer senindir! "
gameforge.main_quest_lv97._550_2_notice = "Dinlenmeye vaktin yok - Tapinak Rahibesi Yah-Ki[ENTER]seni bekliyor. "
gameforge.main_quest_lv97._560_notice = "Kazandin! Korkunc bir ciglikla Yah-Ki yere yigilir. "
gameforge.main_quest_lv97._570_say = "Ah! Bu imkansiz! Bir insan tarafindan maglup[ENTER]edilmek... Ah, Banshee, beni affet! Seni hayal[ENTER]kirikligina ugrattim! Gorevimi yerine getireme... "
gameforge.main_quest_lv97._580_say = "Cesedini ariyorsun ve Muhurlu bir Mektup buluyorsun.[ENTER]Onu Amiral Angmur'a gotur. "
gameforge.main_quest_lv97._590_say = "Ejderha Tanrisi'na sukurler olsun! Dondun. Tapinak[ENTER]Rahibesi'ni yenmeyi basardin! "
gameforge.main_quest_lv97._600_say = "O igrenc yilan ciktigi yere geri dondu - cehenneme![ENTER]Can cekisirken Banshee'yi hayal kirikligina[ENTER]ugrattigi icin af diliyordu. Bakin, uzerinde bu[ENTER]vardi. "
gameforge.main_quest_lv97._610_say = "Muhurlu bir Mektup. Goster! "
gameforge.main_quest_lv97._620_sayReward = "Hanimim, sonunda tuzagimiza dustuler. Planiniz[ENTER]ise yaradi! Oluler ordusunun diriltilmesi devam[ENTER]ediyor ve artik bizi kimse durduramaz. Ruhsuz[ENTER]bedenler dirildiginde derhal Ejderha Atesi Burnu'na[ENTER]yuruyecek ve oradaki tum sakinleri kilictan[ENTER]gecirecegiz. Sonra Anakara'ya gecip sizinle Ates[ENTER]Diyari'nda bulusacagiz. Butun dunyayi yok edecegiz,[ENTER]ayaklarimizin altinda toprak alev alacak.[ENTER]Derin saygilarimla, sadik rahibeniz "
gameforge.main_quest_lv97._630_say = "Banshee icin bir mesaj! O lanet cadi Ates[ENTER]Diyari'nda bosuna karanlik ordusunu bekleyecek.[ENTER]Sana tesekkur ederim. Yardimin olmasaydi burun ve[ENTER]halki yasayan oluler ordusu tarafindan yerle bir[ENTER]edilirdi. Sadece bizi kurtarmakla kalmadin, ayni[ENTER]zamanda atalarimizin ruhlarina da huzur getirdin.[ENTER]Butun cephenin bir temsilcisi olarak sana bu odulu[ENTER]takdim etmekten onur duyarim. "
gameforge.main_quest_lv97._640_sayTitle = "98. seviyeye ulastiginda maceraya devam[ENTER]edebilirsin. "
gameforge.main_quest_lv97._650_say = "Üssu bulmak uzun zamanimizi aldi. Artik[ENTER]kaybedecek bir animiz bile yok! "
