gameforge.new_christmas = {}
gameforge.new_christmas._010_npcChat = "Ho ho ho! "
gameforge.new_christmas._020_say = "Ah, sen misin![ENTER]Gorusmeyeli uzun zaman oldu.[ENTER]Neredeyse bir yil olmustur, ho ho![ENTER]Muhtemelen neden tekrar size geldigimi merak[ENTER]ediyorsundur.[ENTER]Hemen her seyi aciklayayim... "
gameforge.new_christmas._030_say = "Icinde yasadigimiz bu zamanlar zor zamanlar.[ENTER]Kimse kitap veya baska bir sey satin almak istemiyor.[ENTER]Ve benim yasimda artik butun gun kizakla kapi kapi[ENTER]dolasamam. Bu yuzden bu yil kutlamalari burada,[ENTER]koyde yapmaya karar verdim. "
gameforge.new_christmas._040_say = "Baska sorun varsa cekinmeden sor.[ENTER]Mutlu Yillar! "
gameforge.new_christmas._050_npcChat = "Sicak sarap icer misin? "
gameforge.new_christmas._060_say = "Ho ho ho! Bunun ne oldugunu bildigini saniyorum,[ENTER]ha? Sert bir kis icin bundan daha iyi bir icecek[ENTER]yoktur! Guzel sarap, bir tutam tarcin, birkac[ENTER]karanfil... dik kafaya! "
gameforge.new_christmas._070_say = "Bu ayaza karsi sadece bir yudum sicak sarap care[ENTER]olur! Sana guc ve canlilik verir. Denemek ister[ENTER]misin? Sorun degil, bir saniye bekle. "
gameforge.new_christmas._080_say = "Tadini begendigini goruyorum, ho ho![ENTER]Seni isitan o sicakligi hissediyor musun? Ve o tat,[ENTER]oyle tatli ve meyvemsi ki. Mutlu Yillar! "
gameforge.new_christmas._090_npcChat = "Daha fazla sicak sarap lutfen! "
gameforge.new_christmas._100_say = "Ah, bir saniye![ENTER]Kucuk bir ayrintiyi unuttum![ENTER]Sana gunde sadece bir sise sicak sarap kaynatabilirim,[ENTER]daha fazlasina maalesef gucum yetmez. Bu sicak sarap[ENTER]20 saat boyunca tuketime uygundur. Bir sise 6 porsiyon[ENTER]icerir ve bir yudumu 30 dakika boyunca etkilidir.[ENTER]Hepsini birden kafaya dikme sakin! "
gameforge.new_christmas._110_say = "Buyur lutfen! Bu olaganustu icecek sana kanat[ENTER]takacak, ho ho ho! Afiyet olsun ve Mutlu Yillar! "
gameforge.new_christmas._120_say = "Ne, daha fazlasi mi?[ENTER]Kusura bakma ama bugunluk bu kadari yeter gibi.[ENTER]Son sicak sarap porsiyonunun uzerinden henuz bir[ENTER]gun gecmedi. Aliskanlik yapsin istemezsin, degil mi?[ENTER]Bir sure sonra tekrar ugra.[ENTER]Mutlu Yillar! "
