gameforge.new_christmas_sock = {}
gameforge.new_christmas_sock._010_npcChat = "Bu coraplarin olayi nedir? "
gameforge.new_christmas_sock._020_say = "Coraplar! Neredeyse onlari tamamen unutuyordum![ENTER]Hediyelerimi sominelerin uzerinde asili olan[ENTER]coraplara saklamak istemistim ama bazi yaratiklar[ENTER]onlari coktan calmis bile![ENTER]Onlari geri almama yardim et! "
gameforge.new_christmas_sock._030_say = "Bu coraplarin izini surmek o kadar kolay bir is[ENTER]degil. Bunu basarmak icin bir Ren Geyigi Yavrusuna[ENTER]ihtiyacin var. "
gameforge.new_christmas_sock._040_say = "Cok tatli degil mi?[ENTER]Üstelik mukemmel bir koku alma duyusuna sahiptir.[ENTER]O profesyonel bir corap takipcisidir![ENTER]2 saat boyunca seninle kalacak ve arayisinda sana[ENTER]yardim edecek. Ancak daha sonra 24 saat dinlenmesi[ENTER]gerekir.[ENTER]Bu kadar uzun sure beklemek istemiyorsan, sol alttaki[ENTER]donen paraya bir goz at - orada seni ikinci bir[ENTER]Ren Geyigi bekliyor. Yine de yarin beni tekrar[ENTER]ziyaret edersen sevinirim! "
gameforge.new_christmas_sock._050_npcChat = "Sana corap getirdim! "
gameforge.new_christmas_sock._060_say = "Bana en az 5 corap getirirsen odulunu alirsin.[ENTER]Urrgh, eskimis coraplarin kokusu resmen igrenc![ENTER]Yeterli miktari topladiginda geri don.[ENTER]Mutlu Yillar! "
gameforge.new_christmas_sock._070_say = "Ho ho ho, goruyorum ki yeterince corabin var,[ENTER]hemen onlari kontrol edeyim.[ENTER]Urrrgh, bu koku... Evet, tam da bahsettigim[ENTER]coraplar bunlardi![ENTER]Mutlu Yillar! "
gameforge.new_christmas_sock._080_npcChat = " - Ren Geyigi Yavrusu "
gameforge.new_christmas_sock._090_say = "Bugun sana zaten bir Ren Geyigi Muhru verdim.[ENTER]Evcil hayvaninin simdi biraz dinlenmesi gerek. Yarin[ENTER]yine ayakta olacaktir. Bu kadar uzun sure beklemek[ENTER]istemiyorsan sol alttaki donen paraya bir bak,[ENTER]arkasinda bir Ren Geyigi daha bulacaksin. Yine de[ENTER]yarin beni tekrar ziyaret edersen sevinirim! "
gameforge.new_christmas_sock._100_say = "Bugun bana coraplarini zaten getirdin.[ENTER]Unutma, onlari sadece 24 saatte bir teslim edebilirsin. "
