gameforge.new_quest_lv17._020_say_title = "Chaegirab Icin Hediye "
gameforge.new_quest_lv17._021_say = "Amcam Chaegirab hayatini bilime adadi ve tum[ENTER]Yang'ini arastirmalara harciyor. Bana her zaman iyi[ENTER]davrandi, bu yuzden ona kucuk bir surpriz yapip[ENTER]bir hediye vermek istiyorum. Uriel'e gidip amcama[ENTER]ne hediye edebilecegim konusunda bir fikri olup[ENTER]olmadigini sorabilir misin? O amcamin eski[ENTER]ogretmenidir ve onu avucunun ici gibi bilir. "
gameforge.new_quest_lv17._030_say = "Ama amcama hicbir sey soyleme! "
gameforge.new_quest_lv17._031_say = "Bana yardim eder misin? "
gameforge.new_quest_lv17._039_say_title = "Uriel: "
gameforge.new_quest_lv17._040_say_title = "Uriel ile Konus "
gameforge.new_quest_lv17._040_target = "Uriel: "
gameforge.new_quest_lv17._041_say = "Uriel ile eski ogrencisi Chaegirab hakkinda konus. "
gameforge.new_quest_lv17._042_say = "Uriel burada bulunuyor: %s. "
gameforge.new_quest_lv17._050_say_title = "Wonda-Rim, Chaegirab'a hediye vermek istiyor... "
gameforge.new_quest_lv17._051_say = "Bir arastirmacinin tum sevinci arastirma yapabilme[ENTER]imkanidir. Calismalarinda ona yardim edersen[ENTER]Chaegirab'i mutlu edersin. Mu-Rang kurdu ulkemizde[ENTER]nadir gorulen bir konuktur ve postu her biyolog icin[ENTER]paha bicilmez bir hazinedir. 5 adet Post yeterli[ENTER]olacaktir. Bunu Wonda-Rim'e ilet. "
gameforge.new_quest_lv17._052_say = "Boyle bir Post Biyolog uzerinde kesinlikle etki[ENTER]birakacaktir. "
