gameforge.new_quest_lv17._076_say_reward = "Simdiye kadar 5 Posttan %s tanesini elde ettin. "
gameforge.new_quest_lv17._081_say_title = "Wonda-Rim Icin Postlar "
gameforge.new_quest_lv17._082_say = "Yeterli miktarda Post elde ettin bile. Simdi[ENTER]onlari Wonda-Rim'e teslim et. "
gameforge.new_quest_lv17._092_say_reward = "Zaten %s Kurt Postu elde ettin. "
gameforge.new_quest_lv17._110_say = "Bunlar gercekten cok guzel Postlar. Cok tesekkur[ENTER]ederim. Onlari amcam Chaegirab'a goturebilir misin? "
gameforge.new_quest_lv17._120_target = "Chaegirab Amca "
gameforge.new_quest_lv17._121_say = "Wonda-Rim, Kurt Postlarini Chaegirab'a goturmeni[ENTER]istedi. "
gameforge.new_quest_lv17._122_say = "Chaegirab burada bulunuyor: %s. "
gameforge.new_quest_lv17._130_say = "Aha. Demek simdi bunu yapmaya calisiyor. "
gameforge.new_quest_lv17._131_say = "Bu postlar kimden? Wonda-Rim'den mi, ama kurtlari[ENTER]onun yerine sen mi oldurdun?[ENTER]Baskalarinin kendisi yerine calismasina izin veren[ENTER]yegenimden utaniyorum. Bu yuzden postlari kabul[ENTER]etmeyecegim; onca zamanini ve emegini harcadigin[ENTER]icin uzgunum. "
gameforge.new_quest_lv17._132_say_reward = "Wonda-Rim'e onu cozdugumu soyle! Beni mutlu etmek[ENTER]istiyorsa bizzat kendisi ava ciksin. "
gameforge.new_quest_lv17._140_say = "Chaegirab Postlari kabul etmedi ve Wonda-Rim'in[ENTER]davranisindan oturu hayal kirikligina ugradi. Seni[ENTER]Wonda-Rim'e geri gonderdi. "
gameforge.new_quest_lv17._141_say = "Amcam ne dedi? Umarim hediyeyi begenmistir? "
gameforge.new_quest_lv17._142_1_select = "Evet, cok sevindi! "
gameforge.new_quest_lv17._142_2_select = "Hayir, hic begenmedi. "
gameforge.new_quest_lv17._143_say = "Cok sevindim! Baskalarina nese kaynagi olmak[ENTER]harika bir duygu. Elbette odullendirileceksin.[ENTER]Lutfen bunu kabul et! "
gameforge.new_quest_lv17._144_say_reward_b = "Wonda-Rim'e yalan soyledin ve bu yuzden Derece[ENTER]Puani kaybettin! "
gameforge.new_quest_lv17._145_say = "Postlari kabul etmedi mi? Hmm, seni ava gondermek[ENTER]pek iyi bir fikir degildi, kendim gidebilirdim.[ENTER]Bir dahaki sefere farkli davranacagim. "
gameforge.new_quest_lv17._146_say_reward = "Butun emegin bosa gidemez ya. En iyisi Yang-Shin'e[ENTER]gitmen. Postlari senden iyi bir fiyata satin[ENTER]alacaktir. "
gameforge.new_quest_lv17._147_say = "Ne kadar da hayal kirikligina ugradim. En azindan[ENTER]postlar h�l� sende. Yayang'da bulunan avci[ENTER]Yang-Shin'e git ve postlari ona sat. "
gameforge.new_quest_lv17._148_say = "Ne kadar da hayal kirikligina ugradim. En azindan[ENTER]postlar h�l� sende. Bokjung'da bulunan avci[ENTER]Yang-Shin'e git ve postlari ona sat. "
gameforge.new_quest_lv17._149_say = "Ne kadar da hayal kirikligina ugradim. En azindan[ENTER]postlar h�l� sende. Bakra'da bulunan avci[ENTER]Yang-Shin'e git ve postlari ona sat. "
gameforge.new_quest_lv17._151_say = "Mu-Rang postlari mi? Kesinlikle isime yarar.[ENTER]Kendime bunlardan yeni bir iclik yaparim. Al[ENTER]bakalim, emegin icin bir kese dolusu Yang. Bak,[ENTER]dun eski bir parsomen bulmustum, belki isine yarar. "
