gameforge.new_quest_lv22._018_say_title = "Baek-Go: "
gameforge.new_quest_lv22._019_say_title = "Seytan Kulesi Bekcisi "
gameforge.new_quest_lv22._021_say = "Seytan Kulesi Bekcisi olan kardesim icin[ENTER]endiseleniyorum. Bir suredir pek iyi hissetmiyordu[ENTER]ve simdi ciddi sekilde hasta. Basi agriyor ve[ENTER]cildi kizarmis durumda ama maalesef gorevini[ENTER]terk edemiyor. Ona Baek-Go'dan bir ilac temin[ENTER]edebilir misin? "
gameforge.new_quest_lv22._022_say = "Kendim giderdim ama Seytan Kulesi, Seungryong[ENTER]Vadisi'nin ortasindaki Hwang Tapinagi alaninda yer[ENTER]aliyor. Orasi sadece tehlikeli yaratiklarla dolu... "
gameforge.new_quest_lv22._023_say = "Dondun bile. Belirtileri unuttun mu? Birisi sana[ENTER]bir sey soylediginde daha dikkatli dinlemelisin.[ENTER]Kardesimin basi agriyor ve cildinde kizarikliklar[ENTER]var. Bunu Baek-Go'ya ilet! "
gameforge.new_quest_lv22._024_select = "Kardese yardim et "
gameforge.new_quest_lv22._025_say_title = "Baek-Go'dan Ilac "
gameforge.new_quest_lv22._026_say = "Seytan Kulesi Bekcisi icin Baek-Go ile ilac[ENTER]hakkinda konus. "
gameforge.new_quest_lv22._027_say = "Baek-Go burada bulunuyor: %s. "
gameforge.new_quest_lv22._030_target = "Baek-Go: "
gameforge.new_quest_lv22._031_say = "Ilaca mi ihtiyacin var? Boyle koru korune ilac[ENTER]almak tehlikeli sonuclar dogurabilir. Bana[ENTER]hastaligin belirtilerinin neler oldugunu soylemelisin. "
gameforge.new_quest_lv22._032_1_select = "Bas agrisi ve ciltte kizariklik "
gameforge.new_quest_lv22._032_2_select = "Bogaz agrisi ve kramplar "
gameforge.new_quest_lv22._032_3_select = "Bilmiyorum. "
gameforge.new_quest_lv22._035_say = "Bana iblis uyuzu gibi geldi. Bu hastalik orumceksi[ENTER]parazit bulasmis canavarlardan kapilabilir. Yine de[ENTER]ona kesinlikle yardimci olacak bir ilac yapabilirim.[ENTER]Sadece birkac malzeme topla. "
gameforge.new_quest_lv22._040_say = "Ihtiyacim olanlar: "
gameforge.new_quest_lv22._041_say_reward = "Avlaman gerekenler: "
gameforge.new_quest_lv22._042_say = "Ayrica suna da ihtiyacim var: "
gameforge.new_quest_lv22._043_say = "Boyle bir hastaligi daha once hic duymamistim.[ENTER]Seytan Kulesi Bekcisi'nin sana dogru belirtileri[ENTER]verdiginden emin misin? En iyisi ona bir kez daha[ENTER]sorman. "
gameforge.new_quest_lv22._044_say = "Belirtileri bilmeden dogru teshis koyamam.[ENTER]Git ve bir kez daha sor. "
gameforge.new_quest_lv22._050_set_title = "Ilac "
gameforge.new_quest_lv22._056_notice = "Guzel, geriye sadece %s demet bitki kaldi. "
gameforge.new_quest_lv22._057_notice = "Bunlar sanirim butun Bitkiler. Simdi cabucak[ENTER]Baek-Go'ya geri donelim. "
