gameforge.new_quest_lv22._065_say = "Ilaci hazirlamak icin gereken tum malzemelere[ENTER]sahipsin. Baek-Go'ya git ve malzemeleri ona teslim[ENTER]et. "
gameforge.new_quest_lv22._066_say = "Baek-Go'nun Ilaci hazirlamak icin ihtiyac duydugu[ENTER]malzemeleri topla: "
gameforge.new_quest_lv22._070_say = "Tesekkur ederim, artik iblis uyuzu icin Ilaci[ENTER]hazirlayabilirim. "
gameforge.new_quest_lv22._071_say = "Hazir! Iste Ilac. Ancak unutma ki taze malzemelerle[ENTER]hazirladim, bu yuzden hastaya %s dakika icinde[ENTER]ulastirmalisin! "
gameforge.new_quest_lv22._072_say = "Seytan Kulesi Bekcisi'nin kardesini Hwang[ENTER]Tapinagi'nin ortasinda bulacaksin. Yine de dikkatli[ENTER]ol - Seungryong Vadisi tehlikeli yaratiklarla[ENTER]doludur! "
gameforge.new_quest_lv22._073_say = "Hepsi bu kadar degil. Yolda bazi malzemeleri mi[ENTER]kaybettin? Butun malzemelerin elimde olmasi gerek,[ENTER]yoksa sana yardim edemem. "
gameforge.new_quest_lv22._080_target = "Seytan Kulesi Bekcisi "
gameforge.new_quest_lv22._082_set_clock = "Kalan sure "
gameforge.new_quest_lv22._083_say = "H�l� vaktin var ama biraz acele etmelisin.[ENTER]Ilac tamamen bozulmadan once Seungryong'a,[ENTER]Seytan Kulesi Bekcisi'ne dogru yola cik. "
gameforge.new_quest_lv22._084_say = "Cok yavas davrandin ve sure doldu. Yine de Ilaci[ENTER]Seytan Kulesi Bekcisi'ne teslim et, belki h�l� ise[ENTER]yarar. "
