gameforge.new_quest_lv26._020_set_title = "Firari "
gameforge.new_quest_lv26._021_say = "Avci Yang-Shin iyi bir av bulmakta zorlaniyor.[ENTER]Yanina git ve ona bir sekilde yardim edip[ENTER]edemeyecegini ogren. "
gameforge.new_quest_lv26._025_say = "Metin Taslari ortaya ciktigindan beri etraftaki her[ENTER]sey degisti. Bircok bolgede artik avlanilamiyor[ENTER]cunku vahsi hayvanlar kudurmus gibi davraniyor.[ENTER]Fakat buralarda bir yerde Gezgin Nakajima yasiyor[ENTER]ve onun nerede h�l� iyi avlanilabilecegini bildiginden[ENTER]eminim. Onu bul ve sor. "
gameforge.new_quest_lv26._030_target = "Nakajima: "
gameforge.new_quest_lv26._031_say = "Demek nerede avlanmanin en iyi oldugunu bilmek[ENTER]istiyorsun? O kadar acele etme. Bunu sana[ENTER]soylememi istiyorsan bana bir iyilik yapmalisin. "
gameforge.new_quest_lv26._032_say = "Bunu bilmelisin... Burada kendi rizamla yasamiyorum.[ENTER]Ordunun acimasizligindan kactigim icin saklaniyorum.[ENTER]Sevgili karim Ah-Yu'nun yasadigimi bilmesini o[ENTER]kadar cok isterdim ki. Bu haberi ona iletebilir[ENTER]misin?[ENTER]Ama unutma, bunu sadece Ah-Yu'ya soyle! Karsiliginda[ENTER]onu ilk kez optugum yeri sana soylesin - onunla[ENTER]orada bulusmak istiyorum ve aradigin avi da orada[ENTER]bulacaksin. "
gameforge.new_quest_lv26._034_say_title = "Nakajima: "
gameforge.new_quest_lv26._035_say_title = "Ah-Yu: "
gameforge.new_quest_lv26._036_say_title = "Nakajima'yi Bul "
gameforge.new_quest_lv26._037_say = "Nakajima nerede iyi bir av yakalanabilecegini[ENTER]biliyor olmali. "
gameforge.new_quest_lv26._038_say = "Nakajima burada bulunuyor: %s. "
gameforge.new_quest_lv26._040_say = "Nakajima sen misin? Beni Yang-Shin gonderdi![ENTER]Avlanmak icin iyi bir yer ariyor. Neresinin[ENTER]guvenli oldugunu biliyor musun acaba? "
gameforge.new_quest_lv26._050_target = "Ah-Yu: "
gameforge.new_quest_lv26._051_say = "Nakajima bir firaridir ve ordudan saklanmak[ENTER]zorundadir. Karisi Ah-Yu onun savasta oldugunu[ENTER]saniyor. Nakajima'nin hayatta oldugu mujdesini ona[ENTER]ilet. "
gameforge.new_quest_lv26._052_say = "Ah-Yu burada bulunuyor: %s. "
gameforge.new_quest_lv26._057_say = "Nakajima... yasiyor mu? Sevgili kocam yasiyor mu?[ENTER]Ah, bu harika haber icin sana tesekkur ederim![ENTER]Bahsettigi yer Yonjang Vadisi'dir. Onunla orada[ENTER]bulusmak icin hemen yola cikiyorum. "
gameforge.new_quest_lv26._058_say = "Bulusmamizi sagladigin icin tesekkur ederim.[ENTER]Lutfen bu gulu kabul et... belki de onu sevdigin[ENTER]birine hediye edersin? Simdi... beni bagisla ama[ENTER]acele etmem gerek! "
gameforge.new_quest_lv26._061_say = "Nakajima'nin Ah-Yu'yu ilk kez optugu yer olan[ENTER]Yonjang Vadisi h�l� harika bir avlanma alanidir. "
gameforge.new_quest_lv26._062_say = "Yang-Shin haberi duydugunda cok sevinecektir.[ENTER]%s bolgesine git ve edindigin bilgileri ona ilet. "
gameforge.new_quest_lv26._063_say = "Yonjang Vadisi mi? Dogru olabilir. Simdiye kadar[ENTER]oraya bir Metin Tasi'nin dustugunu ve topraklari[ENTER]zehirledigini hic duymadim. Yakinda harika bir av[ENTER]yakalayacagimdan eminim! Iste hak ettigin odul. "
gameforge.new_quest_lv28 = {}
gameforge.new_quest_lv28._010_target = "Yu-Hwan: "
gameforge.new_quest_lv28._011_say = "Muzisyen Yu-Hwan'in yardimina ihtiyaci var. Neler[ENTER]olup bittigini kontrol etmek icin derhal yola koyul! "
gameforge.new_quest_lv28._015_npcChat = "Ah-Yu'nun Endiseleri "
gameforge.new_quest_lv28._016_say = "Gorunuse gore Ah-Yu bir sey icin endiseleniyor ama[ENTER]Yu-Hwan'a icini dokmek istemiyor. Yanina git, belki[ENTER]sana soyler. "
gameforge.new_quest_lv28._017_say = "Ah-Yu burada bulunuyor: %s. "
gameforge.new_quest_lv28._018_select = "Hemen Ah-Yu ile konusacagim! "
gameforge.new_quest_lv28._019_say_title = "Ah-Yu: "
gameforge.new_quest_lv28._020_say_title = "Yu-Hwan: "
gameforge.new_quest_lv28._021_say = "Ah-Yu'yu taniyor musun? Iksirlerim icin bitki[ENTER]toplar. Simdiye kadar her zaman neseli ve hayat doluydu[ENTER]ama dunden beri bir sey icin fena halde endiselendigini[ENTER]hissediyorum. Ne yazik ki dertlerini benimle[ENTER]paylasmak istemiyor, belki de benim icin calistigi[ENTER]icindir? Lutfen yanina git ve nasil oldugunu ogren.[ENTER]Belki sana icini doker. "
gameforge.new_quest_lv28._022_say = "Yu-Hwan'in benim icin endiselenmesi cok ince bir[ENTER]davranis. Evet, yuregimde bir agirlik var... bundan[ENTER]bahsetmek istemiyordum ama artik daha fazla[ENTER]saklayamayacagim! Mesele su avci Yang-Shin; kocam[ENTER]Nakajima'nin firari oldugunu ogrendiginden beri bana[ENTER]santaj yapiyor. Yang-Shin onu ihbar etmekle tehdit[ENTER]ediyor! Onu oldururler... "
gameforge.new_quest_lv28._023_say = "Simdi suskunlugu karsiliginda Ayi Safrasi (Pencesi)[ENTER]talep ediyor. Ama ben ava gidemem ki. Yang-Shin'in[ENTER]istediklerini elde etmemde bana yardim eder misin? "
gameforge.new_quest_lv28._024_set_title = "Ayi Avi "
gameforge.new_quest_lv28._025_notice = "Ava cikalim![ENTER]Yari-Tanri ayi Bera'yi avlamak Ayi Safrasi[ENTER]elde etmenin en iyi yoludur. "
gameforge.new_quest_lv28._026_notice = "Bir Ayi Safrasi elde ettim! "
gameforge.new_quest_lv28._027_notice = "Hepsi bu kadar. Simdi Yang-Shin'e! "
gameforge.new_quest_lv28._028_notice = "Bu ayinin parcasi ise yaramazdi. "
gameforge.new_quest_lv28._029_say = "H�l� %s x Ayi Safrasi'na ihtiyacin var. "
gameforge.new_quest_lv28._031_say_reward = "Avlaman gerekenler: "
gameforge.new_quest_lv28._032_say = "Ah-Yu, Yang-Shin'in talebini yerine getirmeni rica[ENTER]etti. "
gameforge.new_quest_lv28._032_say_reward = "H�l� %s x Ayi Safrasi'na ihtiyacin var.[ENTER]Onlari elde etmek icin Yari-Tanri ayi Bera'yi[ENTER]avla."
gameforge.new_quest_lv28._035_target = "Yang-Shin: "
gameforge.new_quest_lv28._036_say = "Istenen Ayi Safralarini elde ettin. Onlari[ENTER]Yang-Shin'e gotur ve Ah-Yu'nun borcunu ode. "
gameforge.new_quest_lv28._037_say = "Yang-Shin burada bulunuyor: %s. "
gameforge.new_quest_lv28._038_say_title = "Yang-Shin: "
gameforge.new_quest_lv28._040_npcChat = "Santaj "
gameforge.new_quest_lv28._041_say_title = "Ayi Safralari "
gameforge.new_quest_lv28._042_say = "Bana Ayi Safrasi mi getirdin? Lutfen hakkimda kotu[ENTER]dusunme! Zor zamanlarda yasiyoruz ve iki yakami bir[ENTER]araya getirmem gerekiyor. Ozellikle yaban hayvanlarinin[ENTER]azaldigi veya Metin Taslari yuzunden zalim[ENTER]canavarlara donustugu su gunlerde avcilik cok[ENTER]tehlikeli bir hal aldi. "
gameforge.new_quest_lv28._043_say = "Lutfen Ah-Yu'ya artik hicbir seyden korkmasina[ENTER]gerek olmadigini ilet. Bundan emin olabilir.[ENTER]En azindan ben tekrar bir seye ihtiyac duyana[ENTER]kadar... hahaha! "
gameforge.new_quest_lv28._044_say = "Ne, beni basindan savmak mi istiyorsun? Peki benim[ENTER]ganimetim nerede? Ben taze Ayi Safrasi istemistim. "
gameforge.new_quest_lv28._045_say_reward = "Ah-Yu'ya yardim etmen ne hos. Ancak bu senin icin[ENTER]bana itaat etmen gerektigi anlamina gelir. Ava cik[ENTER]ve bana iki Ayi Safrasi getirmeden gozume gozukme! "
gameforge.new_quest_lv28._046_say = "Ah-Yu'ya, senin yardimin sayesinde Yang-Shin'in[ENTER]ona santaj yapmayi biraktigi mujdesini ver. "
gameforge.new_quest_lv28._051_say = "Sen bizim kurtaricimizsin! Sana omrum boyunca[ENTER]minnettar kalacagim. Al lutfen, bu benim Yang'im.[ENTER]Cok fazla olmasa da bunu fazlasiyla hak ettin. "
gameforge.new_quest_lv28._055_1_select = "Tesekkurler, isime yarar! "
gameforge.new_quest_lv28._055_2_select = "Bunu kabul edemem. "
gameforge.new_quest_lv28._056_say = "Butun varim yogum bu. Ama bu sayede o somurucuden[ENTER]sonsuza dek kurtulacaksam buna deger. "
gameforge.new_quest_lv28._057_say = "Ah, tesekkur ederim! Yaptiklarinla Ejderha Tanrisi'nin[ENTER]yaninda kendine bir yer edineceksin! "
gameforge.new_quest_lv28._070_say = "Ihtiyacim olanlar: "
gameforge.new_quest_lv29 = {}
gameforge.new_quest_lv29._010_target = "Yonah: "
gameforge.new_quest_lv29._015_npcChat = "Kirik Porselen "
gameforge.new_quest_lv29._020_say_title = "Yonah: "
gameforge.new_quest_lv29._021_say = "Benim sevgili Seladon Porselenim! Üc nesildir[ENTER]ailemizdeydi ve simdi uc degerli vazo kirilmis.[ENTER]Gecenlerde o hayta Taurean'in depoya suzuldugunu[ENTER]gordum. Kesinlikle onun marifeti oldugundan eminim! "
gameforge.new_quest_lv29._022_say = "Bu onun ilk vukuati degil ama bu sefer haddini[ENTER]asti. Birisi artik ona iyi bir dayak cekmeli![ENTER]Buna vaktin var mi? "
gameforge.new_quest_lv29._023_1_select = "Zevkle! "
gameforge.new_quest_lv29._023_2_select = "Beni ilgilendirmez. "
gameforge.new_quest_lv29._024_say = "Yaramaz veletleri terbiye edecek vaktim yok.[ENTER]Onu kendin yakalamalisin. Ama basarabileceginden[ENTER]de supheliyim... "
gameforge.new_quest_lv29._030_target = "Taurean: "
gameforge.new_quest_lv29._031_say = "Yonah'in paha bicilmez aile yadigari olan uc muhtesem[ENTER]Seladon Porselen Vazosu biri tarafindan kirilmis.[ENTER]Yonah bunun Taurean'in isi olduguna inaniyor.[ENTER]Taurean'a git ve dogru olup olmadigini ogren. "
gameforge.new_quest_lv29._032_say = "Taurean burada bulunuyor: %s. "
gameforge.new_quest_lv29._033_say_title = "Taurean: "
gameforge.new_quest_lv29._034_say_reward = "Bana neden oyle ters ters bakiyorsun? Ben kotu bir[ENTER]sey yapmadim ki... "
gameforge.new_quest_lv29._035_say_reward = "Yonah'in Vazolarina ne yaptin? "
gameforge.new_quest_lv29._036_say_reward = "Vazolara mi? Yonah mi? Neden bahsettigini cidden[ENTER]bilmiyorum... "
gameforge.new_quest_lv29._037_say_reward = "O zaman ucunun neden kirik oldugunu acikla bakalim. "
gameforge.new_quest_lv29._038_say_reward = "Yemin ederim bugun ne vazolari ne de Yonah'i[ENTER]gozum gordu. Butun gun Harang ile gurestim.[ENTER]Hatta beni saman yigininin icine birkac saatligine[ENTER]kilitledi! Yanina git ve sor! Yalan soylemiyorum! "
gameforge.new_quest_lv29._040_target = "Harang: "
gameforge.new_quest_lv29._041_say = "Taurean masum oldugunu iddia ediyor. Butun gun[ENTER]Harang ile oynadigini, bu yuzden o Vazolari kirma[ENTER]firsati olmadigini soyledi. Harang'a git ve dogru[ENTER]olup olmadigini sor. "
gameforge.new_quest_lv29._042_say_reward = "Harang, bugun Taurean'i gordun mu? "
gameforge.new_quest_lv29._043_say_title = "Harang: "
gameforge.new_quest_lv29._044_say_reward = "Taurean mi? Elbette, butun gun oyun oynadik.[ENTER]Bir sorun mu var? "
gameforge.new_quest_lv29._045_say_reward = "Yonah, Taurean'in uc Vazoyu kirdigini iddia ediyor. "
gameforge.new_quest_lv29._046_say_reward = "Yonah cok alcak biri. Yanina yaklasir yaklasmaz[ENTER]beni ve Taurean'i hemen kovalar. Surekli porselenleri[ENTER]icin endiselenir. O degerli Vazolara sadece seyis[ENTER]olan dostu dokunabilir. Belki o kirmistir?! "
gameforge.new_quest_lv29._047_say = "Harang burada bulunuyor: %s. "
gameforge.new_quest_lv29._050_target = "Seyis: "
gameforge.new_quest_lv29._051_say = "Harang, Taurean'in sozlerini dogruladi. O masum[ENTER]ama belki de aralarinda anlasmislardir. Birini[ENTER]suclamadan once Yonah'in seyis olan dostuna da[ENTER]bir danis. "
gameforge.new_quest_lv29._052_say = "Ah, iyi kalpli Yonah. Porselenleri icin endiselenip[ENTER]koyun cocuklarindan supheleniyor. Oysa asil suclu[ENTER]Metin Taslari; ulkemizi zehirlediklerinden beri ham[ENTER]maddelerimiz eskisi gibi degil. Porselen bile daha[ENTER]kirilgan hale geldi. Ama Yonah bunu duymak istemiyor... "
gameforge.new_quest_lv29._053_say = "Onun icin biraz Saman toplarsan, porselen sandigini[ENTER]onunla doseyebilir. Boylece onun gonlunu yeniden[ENTER]almis olursun. "
gameforge.new_quest_lv29._054_say = "Seyis surada bulunuyor:[ENTER]%s veya %s. "
gameforge.new_quest_lv29._061_say = "Yonah'in Porselenlerinin kirilmasi Taurean'in[ENTER]sucu degil. Metin Taslarindan yayilan radyasyon her[ENTER]seyin bu kadar kirilgan olmasina neden oluyor.[ENTER]Yonah'in porselenlerini daha guvenli saklayabilmesi[ENTER]icin Saman topla! Koy sakinlerinden birkaci sana[ENTER]biraz vermeyi kabul edecektir. "
gameforge.new_quest_lv29._062_say = "Koyun girisinde %s ve %s bulacaksin.[ENTER]Baslarinda hasir sapkalar var, bunlardan kesinlikle[ENTER]yeterli Saman elde edebilirsin. "
gameforge.new_quest_lv29._063_notice = "Bu guzel bir Saman demeti olacak. Simdi geriye[ENTER]sadece %s kaldi. "
gameforge.new_quest_lv29._064_notice = "Sapka samandan degil Hindistan cevizi lifinden[ENTER]yapilmis. Bunlar hicbir isime yaramaz. "
gameforge.new_quest_lv29._065_1_say = "Gordugum kadariyla epey Samanin var. Yonah'a[ENTER]biraz verirsen kesinlikle sakinlesecektir. "
gameforge.new_quest_lv29._065_notice = "Sapka Samandan degil Hindistan cevizi lifinden[ENTER]yapilmis. Üstelik fena halde hasar gormus... "
gameforge.new_quest_lv29._066_say = "Yabani Piyadeleri veya Guclu Yabani Piyadeleri[ENTER]oldurebilirsin; onlarin sapkalarindan Saman elde[ENTER]edersin. "
gameforge.new_quest_lv29._067_say_reward = "Simdiye kadar %s demet Samandan %s tanesini topladin. "
gameforge.new_quest_lv29._068_notice = "Biraz Saman elde ettin. "
gameforge.new_quest_lv29._070_npcChat = "Saman Yigini "
gameforge.new_quest_lv29._071_say_reward = "Taurean, daha once saman yigininda oldugunu[ENTER]soylemistin. Yanina kazara biraz Saman aldin mi? "
gameforge.new_quest_lv29._072_say_reward = "Haha, bir bakalim... Saclarimda ve ayakkabilarimdaydi.[ENTER]Goruyor musun? Burada biraz daha var, al bunlari! "
gameforge.new_quest_lv29._073_notice = "Pek fazla saman degil ama kucuk bir demet icin[ENTER]yeterli. Simdi %s tane daha bulmaliyim. "
gameforge.new_quest_lv29._074_say_reward = "O ben degildim! Harang sana saman yigininda[ENTER]oynadigimizi soylemedi mi? "
gameforge.new_quest_lv29._075_say_reward = "Daha once saman yiginindaydin degil mi? Yanina hic[ENTER]Saman almadin mi? "
gameforge.new_quest_lv29._076_say_reward = "Saman yiginini nereden biliyorsun? Kiyafetlerimde[ENTER]h�l� saman mi var? Oh evet, burada birazcik var! "
gameforge.new_quest_lv29._077_say_reward = "Onlari alabilir miyim? "
gameforge.new_quest_lv29._078_say_reward = "Onemsiz... "
gameforge.new_quest_lv29._079_say_reward = "Su an vaktim yok. Taurean'a gitmeli ve Vazo meselesi[ENTER]yuzunden onu sakinlestirmeliyim! "
gameforge.new_quest_lv29._080_npcChat = "Yonah Icin Saman "
gameforge.new_quest_lv29._081_say_reward = "Ahirda Yonah'a goturebilecegim saman kaldi mi? "
gameforge.new_quest_lv29._082_say_title = "Seyis: "
gameforge.new_quest_lv29._083_say_reward = "Cok fazla Samanimiz yok. Yaban hayvanlari ve koyun[ENTER]disindaki haydutlar yenisini bicmemize engel oluyor. "
gameforge.new_quest_lv29._084_say_reward = "Ama sana biraz verebilirim! "
gameforge.new_quest_lv29._085_notice = "Gercekten cok az ama en azindan bir demete yeter.[ENTER]Simdi bana %s tane daha lazim. "
gameforge.new_quest_lv29._086_say_reward = "Korkarim senin icin daha fazlasini yapamam. "
gameforge.new_quest_lv29._090_send_letter = "Dayak Yerine Saman "
gameforge.new_quest_lv29._091_say = "Yonah icin gereken miktarda Saman topladin. Git ve[ENTER]onlari buraya gotur: %s. "
gameforge.new_quest_lv29._101_say_reward = "Bu Taurean'in sucu degil. Metin Taslarindan cikan[ENTER]radyasyon porselenin bu kadar kirilgan olmasina yol[ENTER]acti. "
gameforge.new_quest_lv29._102_say_title = "Yonah: "
gameforge.new_quest_lv29._103_say_reward = "Ne dedin? Sacmalik! O kucuk tembel velet sana yalan[ENTER]soylemis. "
gameforge.new_quest_lv29._104_say_reward = "Taurean butun gun Harang ile birlikte saman[ENTER]yigininda oynadi. "
gameforge.new_quest_lv29._105_say_reward = "Dostun olan seyisin sana selami var, ayrica[ENTER]Vazolari daha iyi koruyabilmen icin sana biraz[ENTER]Saman getirdim. "
gameforge.new_quest_lv29._106_say_reward = "Itiraf etmeliyim ki bu sekilde davrandigim icin[ENTER]utaniyorum. Ama bilmelisin ki Porselen ailemden[ENTER]kalan paha bicilmez bir yadigardir. Vazolardan biri[ENTER]kirildiginda bu benim icin kayip bir esyadan cok[ENTER]daha fazlasini ifade ediyor... "
gameforge.new_quest_lv29._107_say_reward = "Senden ve Taurean'dan ozur dilemeliyim. Al bunu,[ENTER]emeklerin icin kucuk bir odul. "
gameforge.new_quest_lv29._108_notice = "%s Deneyim Puani bonusu kazandin! "
gameforge.new_quest_lv29._109_say_reward = "Dostun olan seyisin sana selami var, ayrica[ENTER]Vazolari daha iyi koruyabilmen icin sana biraz[ENTER]Saman getirdim. "
gameforge.new_quest_lv29._110_say_reward = "Cok incesin ama bana %s demet daha Saman getirebilir[ENTER]misin? Vazolarimin iyi korundugundan emin olmak[ENTER]istiyorum. "
gameforge.new_quest_lv29._111_say_reward = "Daha fazla Saman bulmanin zor olacagini tahmin[ENTER]ediyorum. Ama Vazolarim benim icin kutsaldir.[ENTER]Bunun icin sana cok minnettar kalirim ve benden[ENTER]biraz Yang alirsin. "
gameforge.new_quest_lv29._112_say_reward = "O cocuk Harang kesinlikle Taurean ile is birligi[ENTER]icinde. "
gameforge.new_quest_lv29._113_say_reward = "Deponun yakininda cocugu gordugumu soylersem[ENTER]gorunuse gore burada bana kimse inanmayacak. "
gameforge.new_quest_lv29._114_say_reward = "Unut gitsin artik. Iste emeginin karsiligi. "
gameforge.new_quest_lv29._115_say_reward = "Buyur, %s Yang. "
gameforge.new_quest_lv42 = {}
gameforge.new_quest_lv42._010_send_letter = "Gurulllllduyor "
gameforge.new_quest_lv42._020_target = "Octavio: "
gameforge.new_quest_lv42._021_say = "Karnim zil caliyor. Belki de Octavio'ya ugramaliyim.[ENTER]O dunyadaki en lezzetli balik corbasini pisirir. "
gameforge.new_quest_lv42._022_say_title = "Octavio: "
gameforge.new_quest_lv42._023_say = "Balik corbasi mi istiyorsun? Hani su butun balik[ENTER]kafalariyla olanindan mi? Ah, cok uzgunum ama[ENTER]birkac gundur mutfagimda balik pisirmiyorum.[ENTER]Normalde Balikci corbam icin bana kaliteli baliklar[ENTER]getirirdi. "
gameforge.new_quest_lv42._024_say = "Ama bir suredir onu goremedim. Yanina gidip basina[ENTER]ne geldigini ogrenebilir misin? "
gameforge.new_quest_lv42._025_say = "Octavio burada bulunuyor: %s. "
gameforge.new_quest_lv42._026_select = "Balikciyi aramaya gidiyorum! "
gameforge.new_quest_lv42._030_target = "Rybak: "
gameforge.new_quest_lv42._031_say = "Denizdeki huzurlu gunler geride kaldi! Her gun[ENTER]balikcilar iz birakmadan kayboluyor! Korkunc bir[ENTER]sey! Metin Taslari denize dustugunden beri o uysal[ENTER]balinalar kana susamis deniz canavarlarina[ENTER]donustu. Balik tutmak artik cok tehlikeli bir hal[ENTER]aldi. "
gameforge.new_quest_lv42._032_say = "Zipkinlarimizla artik balinalari yaralayamiyoruz[ENTER]bile. Derileri bir ogreninkinden bile daha sertlesti! "
gameforge.new_quest_lv42._033_say = "Belki Yonah ne yapilmasi gerektigini bilir. Vaktiyle[ENTER]kendisi de denize acilir ve balina avlardi. "
gameforge.new_quest_lv42._034_say_title = "Balikci: "
gameforge.new_quest_lv42._035_say = "Octavio derinliklerden gelecek ozel bir baligi[ENTER]bekliyor. Balikci'ya teslimatin neden geciktigini[ENTER]sor. "
gameforge.new_quest_lv42._036_say = "Balikci burada bulunuyor: %s. "
gameforge.new_quest_lv42._037_send_letter = "Ofkeli Deniz Canavarlari "
gameforge.new_quest_lv42._038_say = "Balikci, kotu Balinalari nasil avlayacagin konusunda[ENTER]Yonah'tan tavsiye almani istedi. "
gameforge.new_quest_lv42._039_say = "Yonah burada bulunuyor: %s. "
gameforge.new_quest_lv42._040_target = "Yonah: "
gameforge.new_quest_lv42._041_say = "Balinalarin basina gelenleri duydum. Balikcilar[ENTER]icin bu korkunc bir durum olmali. Denize acilmaya[ENTER]cesaret etseler bile Zipkinlari balinalarin sert[ENTER]derisini delmek icin cok zayif kaliyor. Ben balikci[ENTER]teknelerinde calisirken, derisi yaslanmis ve[ENTER]yara izleriyle kaplanmis balinalari avlamak icin[ENTER]ozel bir silah kullanirdik. O silah her seyi delip[ENTER]gecebilirdi... "
gameforge.new_quest_lv42._042_say = "Ozel bir teknikle sertlestirilmis Balina Zipkini[ENTER]soz konusu ve boyle bir Zipkini yalnizca Demirci[ENTER]yapabilir. "
gameforge.new_quest_lv42._043_say_reward = "Demirci'ye git. "
gameforge.new_quest_lv42._044_say_title = "Yonah: "
gameforge.new_quest_lv42._045_say = "Balina avi icin Yonah ozellikle sert ve keskin bir[ENTER]Zipkin oneriyor. Demirci'ye git ve boyle bir zipkin[ENTER]yapip yapamayacagini sor. "
gameforge.new_quest_lv42._050_target = "Demirci. "
gameforge.new_quest_lv42._051_say = "Evet, bu zipkinlari duymustum ve onlari yapabilirim[ENTER]ama bu sertlige ulasmak icin Elmas Tasi'na[ENTER]ihtiyacim var. "
