gameforge.new_quest_lv42._say_drop_fail = "Basarisiz oldu! Daha sert vurmaliyim, cok sert bir tas!"
gameforge.new_quest_lv42._063_say = "Ihtiyacin olan her seye sahipsin.[ENTER]Simdi cabucak Demirci'ye. "
gameforge.new_quest_lv42._064_say = "Harika, butun ihtiyacim olan bu. Zipkinlari almak[ENTER]icin yarin ayni saatte gel. Boyle bir demirin iyi[ENTER]dovulmesi gerekir! "
gameforge.new_quest_lv42._065_say = "Elmas Damarini Kazma ile kirarsan Elmas Taslari[ENTER]bulursun. "
gameforge.new_quest_lv42._066_say = "Demirci ozel Balina Zipkinlarini yapmak icin Elmas[ENTER]Taslarina ihtiyac duyuyor. Elmas Taslari cikarmak[ENTER]icin bir Elmas Damari bul. Kazman yoksa Deokbae'den[ENTER]satin alabilirsin. "
