gameforge.new_quest_lv42._070_set_title = "Zipkinlar "
gameforge.new_quest_lv42._071_set_clock = "Bekleme suresi: %s "
gameforge.new_quest_lv42._072_say = "Demirci siparisini tamamlamis olmali. Yanina git[ENTER]ve ozel Balina Zipkini'ni teslim al. "
gameforge.new_quest_lv42._073_say = "Ne yazik ki Zipkinlar henuz hazir degil. Biraz[ENTER]daha sabir lutfen. "
gameforge.new_quest_lv42._074_say = "Iste Zipkinlar. Onlari Balikci'ya gotur. "
gameforge.new_quest_lv42._075_say = "Zipkinlar hazir olana kadar beklemeni rica etmistim.[ENTER]Daha sonra gel. "
gameforge.new_quest_lv42._079_say = "Demirci'den Balina Zipkinlarini aldin.[ENTER]Onlari Balikci'ya teslim et. "
gameforge.new_quest_lv42._080_say = "Harika! Zipkinlar gercekten cok etkileyici! Artik[ENTER]nihayet Balinalara karsi kendimizi savunabiliriz.[ENTER]Octavio'ya yakinda taze balik bekleyebilecegini[ENTER]soyle! "
gameforge.new_quest_lv42._081_say_reward = "500.000 Yang kazandin. "
gameforge.new_quest_lv42._082_say_reward = "Takdir nisanesi olarak 3x kazandin: "
gameforge.new_quest_lv42._083_say = "Balinayi kovalamak icin cok az Zipkinimiz var.[ENTER]Bununla sadece karnini gidiklariz onun! "
gameforge.new_quest_lv42._084_say_reward = "Lutfen Demirci'ye bir kez daha git ve daha fazla[ENTER]Zipkin yapmasini rica et. "
gameforge.new_quest_lv42._090_say = "Balikcilar artik iyi donanimli ve ava cikabilirler.[ENTER]Octavio'ya git ve onu rahatlat; yakinda taze[ENTER]teslimat alacagini soyle. "
gameforge.new_quest_lv42._095_say = "Ne dedin? Uysal Balinalar kana susamis deniz[ENTER]canavarlarina mi donustu? Korkunc... Balikcilara[ENTER]yardim ettigin icin tesekkur ederim. Yemeklerimin[ENTER]cogu onlarin getirdiklerine bagli. "
gameforge.new_quest_lv42._096_say = "Guruldayan karnina donecek olursak, ne yazik ki sana[ENTER]henuz balik corbasi pisiremem ama susiye ne dersin? "
gameforge.new_quest_lv42._098_say_reward = "750.000 Deneyim Puani kazandin.[ENTER]2 porsiyon Susi kazandin. "
