gameforge.new_quest_lv52._040_say = "Yuzbasi geceleri uyuyamiyor. Baek-Go'ya git ve[ENTER]Yuzbasi icin daha guclu bir Uyku Ilaci iste. "
gameforge.new_quest_lv52._041_say = "Yuzbasi icin Uyku Ilaci mi? Üzgunum ama elimde daha[ENTER]guclu bir sey yok. Sadece Yu-Hwan bitkilerden daha[ENTER]guclu bir sey hazirlayabilir. "
gameforge.new_quest_lv52._042_say = "Ah, Mektubumu aldin. Gercekten ne yapacagimi[ENTER]sasirdim. Geceleri uyuyamiyorum. Lutfen bana yardim[ENTER]et. Baek-Go'ya danis. "
gameforge.new_quest_lv52._042_select = "O halde Yu-Hwan'a gitsem daha iyi olur! "
gameforge.new_quest_lv52._043_say = "Baek-Go burada bulunuyor: %s. "
gameforge.new_quest_lv52._044_say_title = "Baek-Go: "
gameforge.new_quest_lv52._045_say = "Yu-Hwan burada bulunuyor: %s. "
gameforge.new_quest_lv52._046_say = "O zaman Yuzbasi'ya git ve ona yardim edemeyecegini[ENTER]soyle. "
gameforge.new_quest_lv52._049_say_title = "Yu-Hwan: "
gameforge.new_quest_lv52._050_target = "Yu-Hwan: "
gameforge.new_quest_lv52._051_say = "Baek-Go'nun ecza dolabinda daha guclu bir Uyku[ENTER]Ilaci yok ama uykuya yardimci olan Bitkileri biliyorsa[ENTER]belki Yu-Hwan yardim edebilir. "
gameforge.new_quest_lv52._052_say = "Yuzbasi'yi cok iyi tanirim. Kesinlikle bildigin[ENTER]gibi uzun zamandir onun icin gizli gorevler[ENTER]yurutuyorum. Bu yuzden Bitkilerin ona yardim[ENTER]etmeyecegini kesinlikle soyleyebilirim. "
gameforge.new_quest_lv52._053_say = "Yuzbasi'nin uyku sorunlari cekmesinin baska bir[ENTER]sebebi var. Inan bana, nedenini kendisi cok iyi[ENTER]biliyor ama bu onun bizzat cozmesi gereken bir mesele,[ENTER]ben bunu yapamam. Yanina git ve bu konuda onunla konus. "
gameforge.new_quest_lv52._054_say_title = "Yuzbasi "
gameforge.new_quest_lv52._055_say_reward = "Ah, Mektubumu aldin. Gercekten ne yapacagimi artik[ENTER]bilemiyorum. Lutfen Baek-Go'ya git ve sonunda butun[ENTER]gece uyuyabilmem icin ondan tavsiye iste. "
gameforge.new_quest_lv52._055_select = "Emredersiniz! "
gameforge.new_quest_lv52._056_say = "Tesekkur ederim! "
gameforge.new_quest_lv52._056_say_reward = "Bunu zaten yaptim ama ecza dolabinda daha guclu[ENTER]bir Ilaci yok. Yine de soz veriyorum, Yu-Hwan'i bulup[ENTER]yardim edip edemeyecegini soracagim. "
gameforge.new_quest_lv52._060_target = "Yuzbasi "
gameforge.new_quest_lv52._061_say = "Yu-Hwan bir sey soylemek istemiyor, muhtemelen hos[ENTER]olmayan bir durum soz konusu. Ama caresi yok,[ENTER]bunu Yuzbasi ile konusmalisin. Bir cozum bulabilmek[ENTER]icin once uykusuzlugun nedenlerini ogrenmeliyiz.[ENTER]Hemen yola koyul: %s. "
gameforge.new_quest_lv52._062_say_reward = "Daha etkili bir Uyku Ilaci yok ama uykusuzlugunuzun[ENTER]sebebini bilirsem belki yardimci olabilirim, Yuzbasim. "
gameforge.new_quest_lv52._063_say_reward = "Bu senin gibi genc bir adama anlatmaktan hoslanacagim[ENTER]bir sey degil. "
gameforge.new_quest_lv52._064_say_reward = "Bu senin gibi genc bir kadina anlatmaktan hoslanacagim[ENTER]bir sey degil. "
gameforge.new_quest_lv52._065_say_reward = "Ama yakinda adamakilli uyuyamazsam delirecegim.[ENTER]Gorunuse gore mecburum... Ama unutma, sana simdi[ENTER]anlatacaklarim yalnizca senin kulaklarin icindir.[ENTER]Her gece hayaletler beni ziyaret ediyor... Bu henuz[ENTER]o kadar korkunc degil... Onlarin olumunden ben[ENTER]sorumluyum. "
gameforge.new_quest_lv52._066_say_reward = "Dort asker bunlar. Seungryong Vadisi'ndeki Cagiricilar[ENTER]ve Iskenceciler tarafindan iskence gorduklerini,[ENTER]sonra da oldurulduklerini soylediler. Onlari oraya[ENTER]cagiran bendim - olume gonderen! "
gameforge.new_quest_lv52._067_say_reward = "Bu hayaletlerden kurtulmak icin ne yapmak gerek? "
gameforge.new_quest_lv52._068_say_reward = "Intikam istiyorlar! Ne yapmali? Intikam almaya[ENTER]gidersem koy lidersiz kalir ve harap edilir. Ama[ENTER]gitmezsem yakinda aklimi kaciracagim. "
gameforge.new_quest_lv52._069_say_reward = "Koyun guvenliginden sorumlu olmasaydim hic[ENTER]dusunmez, derhal yola cikardim. Tek bir cikis yolu[ENTER]goruyorum: "
gameforge.new_quest_lv52._070_say_reward = "Birisi benim yerime gidip intikami almali! Ama[ENTER]insanlari tekrar kesin bir olume nasil gonderebilirim?![ENTER]Boyle bir seyi nasil talep eder ve geceleri rahat[ENTER]uyuyabilirim? "
gameforge.new_quest_lv52._071_say_reward = "Boyle bir karari vermek kolay degil. "
gameforge.new_quest_lv52._080_1_select = "Koyun iyiligi... "
gameforge.new_quest_lv52._080_2_select = "Kolay olmayacak... "
gameforge.new_quest_lv52._080_3_select = "Boyle bir sey talep edilemez! "
gameforge.new_quest_lv52._081_say_reward = "...vicdan azabindan daha onemlidir. Askerlerin[ENTER]intikamini alacagim! Ve geri donmezsem, bu gece[ENTER]gorusuruz... "
gameforge.new_quest_lv52._082_say_reward = "...Cagiricilar ve Iskencecilerle hesaplasacagim.[ENTER]Ama soz veriyorum Yuzbasim, bu gece rahat[ENTER]uyuyacaksiniz! "
gameforge.new_quest_lv52._083_say_reward = "Cagiricilar ve Iskenceciler ile kavgaya tutusmak[ENTER]neredeyse intihardir. Yuzbasim, burada size ne kadar[ENTER]cok ihtiyac duyuldugunu hayaletlere anlatmaya calisin. "
gameforge.new_quest_lv52._084_say_reward = "Haklisin. Yine de gonullu olarak one cikacagini[ENTER]ve bana ve tum koye buyuk bir iyilik yapacagini[ENTER]ummustum. "
gameforge.new_quest_lv52._090_1_select = "Pekala o zaman... "
gameforge.new_quest_lv52._090_2_select = "Bunu basaramam! "
gameforge.new_quest_lv52._091_say_reward = "...eger son umut bensem, Cagiricilar ve[ENTER]Iskencecilerle hesaplasacagim! "
gameforge.new_quest_lv52._092_say_reward = "Denersem, kesinlikle Yuzbasi'ya musallat olacak[ENTER]bir hayalet daha cikacaktir ortaya. "
gameforge.new_quest_lv52._093_say_reward = "Pekala. Yine de emegin karsiligi olarak sana biraz[ENTER]Yang vermeme izin ver. "
gameforge.new_quest_lv52._093_say_reward_exp = "20.000 Deneyim Puani kazandin. "
gameforge.new_quest_lv52._093_say_reward_gold = "25.000 Yang kazandin. "
gameforge.new_quest_lv52._100_notice = "Konusma sona erdi. "
gameforge.new_quest_lv52._110_say_reward = "Boyle bir sey soyleyecegini umuyordum. Ne yazik ki[ENTER]onlari tam olarak hangi Cagirici veya Iskencecinin[ENTER]oldurdugunu bilmiyorum. Ruhlardan birinin huzura[ENTER]erdigini hissedecegimi umuyorum. "
gameforge.new_quest_lv52._111_say_reward = "Sana bir Mektup gonderecegim. Hayaletler bana[ENTER]intikamin Ejderha Tanrisi Ücgeni'nde alinmasi[ENTER]gerektigini soyledi. Orada ucgenin koselerini[ENTER]olusturan uc sutun var. "
gameforge.new_quest_lv52._120_set_title = "4 Sehidin Intikamini Al "
gameforge.new_quest_lv52._125_say_title = "Yuzbasi'dan Mektup "
gameforge.new_quest_lv52._130_say_reward = "Daha 3 askerin intikamini al! "
gameforge.new_quest_lv52._131_say = "Gorunuse gore basarili olmussun. Az once oldurulen[ENTER]askerlerimden birinin sesini duydum. Beni affettigini[ENTER]ve olumunun intikaminin alindigini soyledi. Ve bu[ENTER]tamamen senin basarin! "
gameforge.new_quest_lv52._132_say = "Lutfen diger sehit askerlerin de intikamini al[ENTER]ve Karanlik Iskencecileri, Karanlik Cagiricilari ve[ENTER]Kibirli Karanlik Iskencecileri oldur. Ancak onlari[ENTER]yalnizca Ejderha Tanrisi'nin Üc Sutun Ücgeni'nde[ENTER]huzura kavusturabilecegini unutma. "
gameforge.new_quest_lv52._140_say_reward = "Daha 2 askerin intikamini al! "
gameforge.new_quest_lv52._141_say = "Askerlerimin katillerinden birini daha ortadan[ENTER]kaldirdin! Alacakaranlikta sehitlerden birinin[ENTER]bana veda selami verdigini gorur gibi oldum. "
gameforge.new_quest_lv52._150_say_reward = "Daha 1 askerin intikamini al! "
gameforge.new_quest_lv52._151_say = "Inanilmazsin! Az once sehit dusen askerlerden[ENTER]birinin ruhu yanimda duruyor ve bana veda ediyordu.[ENTER]Son katili bulmanin zor olacagini tahmin ediyorum. "
gameforge.new_quest_lv52._160_say = "Yuzbasi'ya musallat olan hayaletler, gorevlerini[ENTER]yerine getirirken sehit dusen genc askerlerin[ENTER]ruhlaridir. Karanlik Iskenceciler, Karanlik[ENTER]Cagiricilar, Kibirli Karanlik Iskenceciler ve Kibirli[ENTER]Karanlik Cagiricilar tarafindan katledildiler. "
gameforge.new_quest_lv52._161_say = "Askerlerin intikamini almak icin Ejderha Tanrisi'nin[ENTER]Üc Sutun Ücgeni'nde sorumlu Iskencecileri ve[ENTER]Cagiricilari ortadan kaldirmalisin. "
gameforge.new_quest_lv52._162_say = "Ejderha Tanrisi Ücgeni, Seungryong Vadisi'nin[ENTER]ortasinda yer almaktadir. "
