gameforge.new_quest_lv52._171_send_letter = "Ikinci askerin intikami alindi "
gameforge.new_quest_lv52._172_send_letter = "Ücuncu askerin intikami alindi "
gameforge.new_quest_lv52._173_send_letter = "Tum askerlerin intikami alindi "
gameforge.new_quest_lv52._180_say_reward = "Tum 4 askerin intikamini aldin! "
gameforge.new_quest_lv52._181_say = "Katillerin sonuncusunu da buldun! Az once dort[ENTER]sehit askerin son ruhu bana gorundu ve cesaretin[ENTER]icin sana tesekkur etmemi istedi. "
gameforge.new_quest_lv52._182_say = "Odulunu almak icin yanima gel. Seni surada[ENTER]bekliyorum: %s. "
