gameforge.new_quest_lv24._030_say = "Ek ikmal maddelerinde sikinti yasarken birliklerimizi[ENTER]motive etmek cok zor. Onemli bir tedarikcimiz olan[ENTER]Satici, birkac haftadir bize cok az miktarda iksir[ENTER]sagliyor. "
gameforge.new_quest_lv24._031_say_reward = "Lutfen Satici'ya git ve neler oldugunu ogren. "
gameforge.new_quest_lv24._032_select = "Size o icecekleri ayarlayacagim! "
gameforge.new_quest_lv24._040_say_title = "Satici: "
gameforge.new_quest_lv24._040_set_title = "Ek Tedarik "
gameforge.new_quest_lv24._050_target = "Satici: "
gameforge.new_quest_lv24._051_say = "Evet, son zamanlarda ek tedarik teslimatinda cok[ENTER]sorun yasiyorum. Ticaret yollari tehlikeli bir hal[ENTER]aldi, buralarda giderek daha sik haydutlar ve vahsi[ENTER]yaratiklar peydah oluyor. Gezgin tuccarlarin yolda[ENTER]yirtici Kaplanlar belirdiginde hic sanslari kalmiyor. "
gameforge.new_quest_lv24._052_say = "Belki Yuzbasi askerleriyle yardim edebilir.[ENTER]Lutfen yanina git ve tuccarlari korumak icin[ENTER]askerlerini gonderip gonderemeyecegini sor. "
gameforge.new_quest_lv24._054_say = "Satici'ya git ve ek iksir tedariki teslimatindaki[ENTER]gecikmelerin nedenini ogren. "
gameforge.new_quest_lv24._055_say = "Satici burada bulunuyor: %s. "
gameforge.new_quest_lv24._056_say_title = "Yuzbasi "
gameforge.new_quest_lv24._060_say = "Ticaret yollarini guvenceye almak mi? Evet...[ENTER]aslinda bunu seve seve yapardim ama diger kralliklardan[ENTER]gelen gezgin tuccarlari korumak icin yeterli askerim[ENTER]yok. "
gameforge.new_quest_lv24._061_say = "Ayrica askerlerin Kaplan avlamasi yasaktir; bu hakka[ENTER]yalnizca avci loncasindaki avcilar sahiptir. Bu yasanin[ENTER]ihlal edilmesi koydeki barisi korumaya yaramaz. "
gameforge.new_quest_lv24._062_say_reward = "Bu yuzden Yang-Shin'e basvurmalisin. O avcilar[ENTER]loncasinin bir uyesidir. Belki Kaplanlarla basa[ENTER]cikmanda sana yardim eder. "
gameforge.new_quest_lv24._064_say = "Yuzbasi'ya git ve ticaret yollarini Kaplanlara[ENTER]karsi guvence altina almasi icin onu ikna etmeye[ENTER]calis. "
gameforge.new_quest_lv24._065_say = "Yuzbasi burada bulunuyor: %s. "
gameforge.new_quest_lv24._070_target = "Yang-Shin: "
gameforge.new_quest_lv24._071_say = "Avcilarimin cogu savasci olarak cepheye cagrildi[ENTER]ve can verdi. Yaban hayati populasyonunda dengeyi[ENTER]korumak imkansizlasti. Ozellikle yirtici kediler[ENTER]bolgelerini genisletiyor ve yolculari tehdit ediyor. "
gameforge.new_quest_lv24._072_say = "Bu konuda bize yardim edersen, sehit dusen yoldasim[ENTER]Mi-Song'a ait olan degerli bir Kitap alacaksin.[ENTER]Bunun karsiliginda Kaplan populasyonunu ciddi[ENTER]sekilde seyreltmelisin. "
gameforge.new_quest_lv24._073_say = "Ozellikle Lanetli Beyaz Kaplanlar fazlasiyla cogaldi. "
gameforge.new_quest_lv24._074_say = "Kanit olarak sunlara ihtiyacim var: "
gameforge.new_quest_lv24._075_say = "Avlaman gerekenler: "
gameforge.new_quest_lv24._076_say = "Yang-Shin'i bul ve ticaret yollarini Kaplanlara[ENTER]karsi korumasi icin onu ikna etmeye calis. "
gameforge.new_quest_lv24._077_say_title = "Yang-Shin: "
gameforge.new_quest_lv24._078_say = "Yang-Shin burada bulunuyor: %s. "
gameforge.new_quest_lv24._080_set_title = "Kaplan Postu "
gameforge.new_quest_lv24._081_notice = "Ah, kusursuz bir ornek. Sadece %s adet kaldi! "
gameforge.new_quest_lv24._082_notice = "Bitti! Simdi cabucak Yang-Shin'e geri don. "
gameforge.new_quest_lv24._083_notice = "Bu Kaplan Postu ise yaramaz. "
gameforge.new_quest_lv24._084_say = "H�l� %s x Parlak Kaplan Postu'na ihtiyacim var. "
gameforge.new_quest_lv24._085_say = "Lanetli Beyaz Kaplanlardan Parlak Kaplan Postlari[ENTER]elde et. "
gameforge.new_quest_lv24._090_npcChat = "Kaplan Postum var. "
gameforge.new_quest_lv24._091_say = "Yollarin guvenli oldugunu nereden bilecegim?[ENTER]Bu birkac Post bir kanit sayilmaz. "
gameforge.new_quest_lv24._092_say = "Sonunda Postlar bana iyi kazanc saglayacak... ohom![ENTER]H�l� burada misin? Sayende yollar yeniden guvenli![ENTER]Yuzbasi'nin seni krallar gibi odullendireceginden[ENTER]eminim. "
gameforge.new_quest_lv24._093_say = "Simdi kaybol buradan! Postlari temizlemem gerek. "
gameforge.new_quest_lv24._094_say = "Ah, Yuzbasi sana odul vermeyecek mi? Bu beni[ENTER]ilgilendirmez. Bana ihanet etmeye kalkisirsan[ENTER]Postlari unutabilirsin. Onlari asla eline[ENTER]geciremeyeceksin! "
gameforge.new_quest_lv24._095_say_reward = "Bu eski, tuhaf, ucgen nesneye artik ihtiyacim yok. "
gameforge.new_quest_lv24._096_say = "Odul: "
gameforge.new_quest_lv24._097_say_reward = "Kaplan Kalkan+3 kazandin. "
gameforge.new_quest_lv24._098_say = "Ne, beni bu degersiz Postlarla mi kandiracaksin?[ENTER]Bu sekilde borcum... bana oyle geliyor ki yollar[ENTER]asla guvenli olmayacak. "
gameforge.new_quest_lv24._099_say_reward = "%s Post elde edene kadar avlanmaya devam et! "
gameforge.new_quest_lv24._100_say = "Hepsi bu kadar, simdi cabucak Yang-Shin'e. "
gameforge.new_quest_lv24._101_say_reward = "3.750.000 Deneyim Puani kazandin. "
gameforge.new_quest_lv24._102_say_reward = "125.000 Yang kazandin. "
