gameforge.new_quest_lv7._125_notice = "Burasi dogru Krallik, Yasli Kadin'in kiz kardesi[ENTER]burada olmali. "
gameforge.new_quest_lv7._129_say = "Bu dogru krallik, Octavio'yu burada bulurum. "
