gameforge.new_quest_lv7._134_say_reward = "Shinsoo Kralligi'ndaki Yayang'a gitmelisin. "
gameforge.new_quest_lv7._135_say = "Shinsoo Kralligi'ndaki Yongan'da bulunan Octavio'ya git. "
gameforge.new_quest_lv7._136_say = "Chunjo Kralligi'ndaki Joan'da bulunan Octavio'ya git. "
gameforge.new_quest_lv7._137_say = "Jinno Kralligi'ndaki Pyungmoo'da bulunan Octavio'ya[ENTER]geri don. "
gameforge.new_quest_lv7._140_say = "Iste Octavio'nun kizinin yaklasan dugunu icin[ENTER]Cicekler. Kutsama sirasinda geline verilecekler.[ENTER]Ciceklerin kimden geldigini o zaten anlayacaktir. "
gameforge.new_quest_lv7._141_say = "Bunlar muhtesem Cicekler! Gelin bunlarin arasinda[ENTER]isil isil parlayacak. Toren hazirliklari tamamlandi.[ENTER]Simdi Octavio'ya dugun davetiyesini ilet. Cok[ENTER]sevinecegini biliyorum. "
gameforge.new_quest_lv7._142_say = "Simdi Octavio'ya git, ne bekliyorsun? "
gameforge.new_quest_lv7._143_say = "Octavio'nun kizinin dugunu icin cicek mi getirdin?[ENTER]Ne kadar naziksin! Ama... neredeler peki?[ENTER]Yolda onlari kaybettin mi yoksa? "
gameforge.new_quest_lv7._144_say_reward = "Kendi Kralligina git ve dugun icin yeni bir Cicek[ENTER]Buketi elde et. "
gameforge.new_quest_lv7._145_say = "Butun cicekler solmadan once Yasli Kadin'in kiz[ENTER]kardesine git. "
gameforge.new_quest_lv7._150_say = "Neden kurbagali sigir eti corbasi gibi kokuyorsun?[ENTER]Neyse bos ver, en onemlisi iyi haberler getiriyor[ENTER]olman. "
gameforge.new_quest_lv7._151_say = "Tesekkur ederim. Kizimin dugununde bulunabilecegim[ENTER]icin cok mutluyum! "
gameforge.new_quest_lv7._152_say = "Al bakalim, iste odulun: "
gameforge.new_quest_lv7._153_say_reward = "Bu gercek bir Dovus Ustasi icin dovulmus bir silahtir.[ENTER]Ona iyi bak! "
gameforge.new_quest_lv7._154_say_reward = "%s Deneyim Puani kazandin. "
gameforge.new_quest_lv7._155_say_reward = "%s Yang kazandin. "
gameforge.new_quest_lv7._160_say = "Sanirim beni uzak bir akrabamla karistirdin.[ENTER]Kizim yok ve dugun yapacak kadar Yang'im da yok. "
gameforge.new_quest_lv7._165_say = "Misafirim olup kurbagali sigir corbami tatmak[ENTER]istemez misin? Teyzemin eski tarifine gore pisirdim. "
gameforge.new_quest_lv75 = {}
gameforge.new_quest_lv75._010_target = "Heuk-Young: "
gameforge.new_quest_lv75._020_set_title = "Bir Efsanenin Gunlugu "
gameforge.new_quest_lv75._021_say = "Bu savascinin kalintilarini buldum. Heuk-Young'un[ENTER]aradigi Sura bu mu bilmiyorum ama kesinlikle[ENTER]ilgisini cekecektir. "
gameforge.new_quest_lv75._022_say = "Burada olen tek bir Sura degildi. Kalintilarini[ENTER]gordum. Acaba aralarinda o efsanevi savasci da[ENTER]var mi? Geri donup bunu Heuk-Young ile konusmaliyim. "
gameforge.new_quest_lv75._023_say = "Yeralti Buz Golemi'nin icinde donmus bir sayfa[ENTER]parcasi buldum. Guclukle okuyabiliyorum ama bu[ENTER]kesinlikle Heuk-Young'un ilgisini cekecek onemli[ENTER]bir ipucu olabilir. "
gameforge.new_quest_lv75._024_say = "Heuk-Young'un ilgisini cekebilecek pek cok sey[ENTER]buldum. Simdi yanina gitmeli ve bu kagit parcasini[ENTER]gostermeliyim. Cesetten de bahsedecegim. "
gameforge.new_quest_lv75._025_say = "Heuk-Young gozlerimi dort acip efsanevi Sura'nin[ENTER]izlerini aramami istedi. Maalesef neye ozellikle[ENTER]dikkat etmem ve ne aramam gerektigi konusunda hicbir[ENTER]fikrim yok... "
gameforge.new_quest_lv75._030_say = "Efsanevi savasci Akuma'yi ariyorum. Muhtemelen[ENTER]bu topraklara ayak basmis en unlu Sura oydu.[ENTER]Imparatorun bizzat kendisine bile meydan okuduguna[ENTER]dair efsaneler dolasir. Savasci Akuma binlerce yil[ENTER]once tam da bu noktadan kayboldu. Bu yuzden gozlerini[ENTER]dort ac ve varligini kanitlayan izler ara. "
gameforge.new_quest_lv75._040_say = "kukla "
gameforge.new_quest_lv75._050_npcChat = "Dusmus Savascilari Incele "
gameforge.new_quest_lv75._060_say = "Bir savascinin kalintilari soz konusu. Sol kol[ENTER]insana benzemiyor... Bir Sura'ya ait olmali.[ENTER]Bu kesfi mutlaka Heuk-Young'a bildirmeliyim. "
gameforge.new_quest_lv75._070_notice = "Bir sayfa... Yeralti Buz Golemi'nde donmus... "
gameforge.new_quest_lv75._090_say = "Tam olarak ne aradigimizi sana soyleyemem.[ENTER]Sadece etrafa bakin ve ilginc bir sey gorursen[ENTER]bana goster. "
gameforge.new_quest_lv75._100_say = "Orada neyin var? Bir bakayim! "
gameforge.new_quest_lv75._105_say = "O not... Bu nasil bir yazi? Cok eski olmali.[ENTER]Sanirim onemli bir sey buldun. Bunu daha once bir[ENTER]yerde gormus gibiyim. Bir kitabin parcasi gibi[ENTER]duruyor. "
gameforge.new_quest_lv75._109_say = "Birkac Sayfa daha bulabilseydik her sey kesinlikle[ENTER]anlam kazanirdi.[ENTER]Yeni ipuclari ara! "
gameforge.new_quest_lv75._110_say = "Yine sen. Ilginc bir sey buldun mu?[ENTER]Soylesene! "
gameforge.new_quest_lv75._115_say = "Bir Sura iskeleti... Belki kendisi, belki de[ENTER]savascilarindan biridir. Tamamen emin olmak icin[ENTER]daha fazla kanita ihtiyacimiz var. Baska ipuclari[ENTER]ara... Belki bir silah, taki, notlar ya da[ENTER]kimligi konusunda bizi ikna edecek bir sey. "
gameforge.new_quest_lv75._120_say = "Bir Sura iskeleti ve gunluk sayfasi mi? Bir goz[ENTER]atayim... Hmm, belki de gercekten Akuma'nin[ENTER]kalintilarini bulmussundur. Yine de daha fazla[ENTER]kanit lazim. Iyi is cikardin ama biraz daha etrafa[ENTER]bakin, belki daha fazlasini bulursun. "
gameforge.new_quest_lv75._130_say = "Bir seyler buldum ama efsanevi Sura'nin burada[ENTER]bulunduguna tam olarak ikna olmadim. Daha fazla[ENTER]bilgiye ihtiyacim var. "
gameforge.new_quest_lv75._140_1_select = "Guzel "
gameforge.new_quest_lv75._140_2_select = "Buzul Yaratigi "
gameforge.new_quest_lv75._140_3_select = "Caresizligin Esiginde "
gameforge.new_quest_lv75._140_4_select = "Karanlik Dehset "
gameforge.new_quest_lv75._140_5_select = "Olumun Kiyisinda "
gameforge.new_quest_lv75._140_6_select = "Savascinin Kaderi "
gameforge.new_quest_lv75._140_7_select = "Hayir, ilgilenmiyorum. "
gameforge.new_quest_lv75._150_say = "Bu cumle kirintilarindan hicbir sey okuyamiyorum.[ENTER]Saray hayati ve asiri macera tutkusu hakkinda bir[ENTER]seyler... "
gameforge.new_quest_lv75._160_1_say = "Sararmis parsomendeki yari yariya solmus yazi tam[ENTER]olarak okunamiyor. Yasli veya cok zayif biri[ENTER]tarafindan yazilmis gibi gorunuyor, harfler cok[ENTER]belirsiz ve titreyen bir elle yazilmis: '...[ENTER]Buzul Yaratiklari. Ben cesur bir Sura olmama ragmen[ENTER]onlarin kokunu tamamen kaziyamadim. Birkaci h�l�[ENTER]dunyada kol geziyor. Simdiye kadar siginagim guvenli[ENTER]bir barinakti ama yakinda...' Harfler bu noktada[ENTER]solmus. "
gameforge.new_quest_lv75._160_2_say = "Bu sayfa da solmus ve sararmis. Üst kosede h�l�[ENTER]bir tarih secilebiliyor, bunun cok eski bir gunluk[ENTER]oldugunu buradan anlayabiliyorsun: 'Bu Magarayi[ENTER]ararken zamani geri alip farkli davranmayi ilk[ENTER]kez istemiyorum. Gururluydum, kibirliydim ve kendime[ENTER]asiri guveniyordum! Bu ozellikler beni buraya,[ENTER]olumle burun buruna getirdi...' Son kelimenin alti[ENTER]birkac kez cizilmis. "
gameforge.new_quest_lv75._160_3_say = "Gunlugun parsomen sayfasi cok hasar gormus, kismen[ENTER]yirtilmis. Mesajin sadece bazi kisimlarini[ENTER]okuyabiliyorsun: '... imparatorluk sarayi... bilginler[ENTER]bana icten ice arzuladigim seyi gosterdiler... yani[ENTER]portali nasil acacagimi, ancak... karanliktaki[ENTER]olum ve dehset...' Sayfa ne yazik ki burada yirtilmis[ENTER]ve devamini senden gizliyor. "
gameforge.new_quest_lv75._160_4_say = "Kagidin uzerinde gulumseyen bir kadin cizimi var.[ENTER]Cizimin altinda daha once gordugun el yazisiyla[ENTER]bir seyler yazilmis. Ancak harfler titreyen bir[ENTER]elle, kararsizca ve daha da okunaksiz yazilmis:[ENTER]'Olumun penceleri var - dun bunu anladim. O vahsi[ENTER]yaratiklara tek bir bakis attim ve cilginca bir[ENTER]korkuyla gerisingeri kactim. Ah, sevgili Sunmi'm,[ENTER]beni neyin bekledigini onceden bilseydim, dunyada[ENTER]hicbir sey icin buraya adim atmazdim!' "
gameforge.new_quest_lv75._160_5_say = "Hee-Se hanedanligi doneminde Akuma adinda efsanevi[ENTER]bir Sura yasarmis. Cok cesur ve yetenekli bir[ENTER]savasciymis; zamanla onunla dovusmeye cesaret eden[ENTER]tek bir yigit bile kalmamis. Akuma bu yuzden surekli[ENTER]yeni meydan okumalar ararmis. Bir gun eline erisilmez[ENTER]ve gizemli bir yeri anlatan notlar gecmis. Ne[ENTER]pahasina olursa olsun orayi bulmaya karar vermis.[ENTER]Hatta kadim portallari nasil bulup etkinlestirecegini[ENTER]bile ogrenmis. Yola cikarken sevgilisine orayi bulur[ENTER]bulmaz hemen donecegine soz vermis... ancak o gunden[ENTER]sonra kendisinden bir daha haber alinamamis. "
gameforge.new_quest_lv75._170_say = "Yazi cok eski gorunuyor... Üstelik titreyen bir[ENTER]elle yazilmis, sanki yazanin mecali kalmamis gibi... "
gameforge.new_quest_lv75._171_say = "Bunun hicbir anlami yok ki. Daha fazla ayrintiya[ENTER]ihtiyacimiz var. "
gameforge.new_quest_lv75._172_say = "Burada ne oldugunu yavas yavas anlamaya basliyorum[ENTER]ama henuz her sey tamamen net degil. "
gameforge.new_quest_lv75._173_say = "Ayrintilari ogrenmek ister misin? "
gameforge.new_quest_lv75._174_say = "Bir sayfa daha! Birisi gercekten cok caresiz[ENTER]kalmis olmali. Orada ne yazdigini sana ozetleyeyim[ENTER]mi? "
gameforge.new_quest_lv75._175_say = "Bazi sayfalar o kadar kotu durumda ki uzerlerinde[ENTER]ne yazdigini ancak tahmin edebiliyorum. Yine de[ENTER]yapbozun tum parcalari yavas yavas birleserek cok[ENTER]uzun zaman once bu Odada yasanmis ilginc bir[ENTER]hikayeyi olusturuyor. "
gameforge.new_quest_lv75._176_say = "Artik fazla bir sey kalmadi. Simdiye kadar[ENTER]ogrendiklerimi duymak ister misin? "
gameforge.new_quest_lv75._177_say = "Gorunuse gore geriye pek fazla sayfa kalmamis. "
gameforge.new_quest_lv75._178_say = "Simdiye kadar ogrendiklerimi duymak ister misin? "
gameforge.new_quest_lv75._180_notice = "Yeralti Buz Golemlerinde son Sayfayi buldum. "
gameforge.new_quest_lv75._185_send_letter = "Butun sayfalar bunlar olmali! "
gameforge.new_quest_lv75._190_notice = "Yeralti Buz Golemi'nde gunlukten bir sayfa buldum. "
gameforge.new_quest_lv75._195_send_letter = "Bir sayfa buldum! "
gameforge.new_quest_lv75._200_npcChat = "Dusmus Savascilari Ara "
gameforge.new_quest_lv75._210_say = "Insan kalintilarinin yaninda 3 adet parsomen kagidi[ENTER]duruyor. Gorunuse gore birisi onlari kitaptan[ENTER]koparmis. Ancak yazi coktan solmus ve ne yazdigini[ENTER]okumak guc. "
gameforge.new_quest_lv75._220_say = "Sanirim bu yeterli. Bulduklarimi Heuk-Young'a[ENTER]goturecegim. "
gameforge.new_quest_lv75._230_say = "Burada hayatini noktalayan kimdi acaba? Her[ENTER]halukarda gunumuzde kullanilabilecek hicbir seyi[ENTER]yoktu yaninda. "
gameforge.new_quest_lv75._240_send_letter = "Kagitlar bende! "
gameforge.new_quest_lv75._250_say = "Heuk-Young'a geri donmeliyim. Belki bu yapbozu o[ENTER]bir araya getirebilir. "
gameforge.new_quest_lv75._270_say = "Bu magaralarda bu kadar cok sey bulmus olman cok[ENTER]garip. Bu Sayfalar bir kitaptan gelmis gibi duruyor.[ENTER]Üzerine yazilmis bilgiler gercekten cok ilginc[ENTER]gorunuyor. Bildigim hikayeleri hesaba katarsak her[ENTER]sey mantikli bir butun haline geliyor... Bana boyle[ENTER]Sayfalar getirirsen kitabi yeniden birlestirmeye[ENTER]calisirim. Surgun Magarasi'nda isine yarayacagini[ENTER]dusunuyorum. Senin icin ise yaramazsa onu senden[ENTER]satin alacak birini buluruz. "
gameforge.new_quest_lv75._280_say = "Bak, senin icin bir kitap hazirladim. Butun[ENTER]sayfalari birbirine diktim ve kendi notlarimdan da[ENTER]birkacini ekledim. Belki isine yarar. Istersen[ENTER]hikayenin sonunu sana anlatirim. "
gameforge.new_quest_lv75._290_1_select = "Evet, daha fazlasini anlat! "
gameforge.new_quest_lv75._290_2_select = "Hayir, ilgilenmiyorum! "
gameforge.new_quest_lv75._310_say = "Benden ne istiyorsun? Dusuncelere daldigimi[ENTER]gormuyor musun? Gunluk meselesi bana huzur vermiyor. "
gameforge.new_quest_lv75._320_say = "Soon: "
gameforge.new_quest_lv75._330_say = "Elinde tuttugun gunluk ilginc gorunuyor. Nereden[ENTER]aldin onu? Bakabilir miyim? "
gameforge.new_quest_lv75._340_say = "Bunlar Surgun Magarasi'ndan notlar. Hakliyim, degil[ENTER]mi? Cok eski gorunuyorlar. Yazi alisilmisin disinda[ENTER]ve uslup cok eski... Boyle bir seyi elde etmek[ENTER]sana cok cabaya mal olmus olmali. Tabii ki onu senden[ENTER]seve seve satin alirim. Ilgilenir misin? "
gameforge.new_quest_lv75._350_1_select = "Evet "
gameforge.new_quest_lv75._350_2_select = "Hayir "
gameforge.new_quest_lv75._360_say = "Efsanevi Gunluk icin ne kadar istiyorsun? "
gameforge.new_quest_lv75._370_say = "Haha... sakacisin sen. Seninle iyi ticaret yapilmaz.[ENTER]Iste teklifim: Efsanevi Gunluk icin 500.000 Yang[ENTER]alirsin. Ne dersin? Ya teklif ettigimi alirsin ya[ENTER]da ticaret falan yapmayiz! "
gameforge.new_quest_lv75._380_1_select = "500.000 Yang'i alirim. "
gameforge.new_quest_lv75._380_2_select = "O zaman anlasamayacagiz! "
gameforge.new_quest_lv75._390_say = "Keyfin bilir! "
gameforge.new_quest_lv75._400_say = "Hayir, benim icin cok pahali. Üzgunum! "
gameforge.new_quest_lv75._410_say = "Onun icin sana %s Yang veririm. "
gameforge.new_quest_lv75._420_say = "Kabul ediyor musun? "
gameforge.new_quest_lv75._425_say = "Bu benim son teklifim! "
gameforge.new_quest_lv75._430_1_select = "Bana %s Yang ver. "
gameforge.new_quest_lv75._430_2_select = "Sanirim bir uzlasmaya varamayacagiz. "
gameforge.new_quest_lv75._440_say = "Nasil istersen... "
gameforge.new_quest_lv75._450_say = "Pek ucuz sayilmaz ama ben cok comert biriyimdir. "
gameforge.new_quest_lv75._460_say = "Benimle pazarlik yapilmaz. Efsanevi Gunluk icin[ENTER]sana 500.000 Yang veririm. "
gameforge.new_quest_lv75._470_say = "Ya sana teklif ettigimi alirsin ya da bu is yatar! "
gameforge.new_quest_lv75._480_say = "Keyfin bilir! "
gameforge.new_quest_lv75._490_say = "Yazik oldu. Belki bir kez daha dusunursun. "
