gameforge.new_quest_lv80._330_npcChat = "Kara Buz'u Ada! "
gameforge.new_quest_lv80._340_say = "Sunaga yaklasirken etrafindaki havanin giderek[ENTER]karardigini hissediyorsun. Hayaletsi sesler ebedi[ENTER]azaplari fisildiyor. Burasi kesinlikle Tanri'nin terk[ENTER]ettigi bir yer. Icinde kotu bir his var. Kara Buz'u[ENTER]gercekten adamak istiyor musun? "
