gameforge.new_quest_lv80._460_say = "%s mi?! Bunun nasil olabilecegini hayal bile[ENTER]edemiyorum... Hemen Kitap'ta bu konuyu arastiracagim. "
gameforge.new_quest_lv80._470_say = "Kara Buz'u adayamazdim... bunu yaparken kendimi hic[ENTER]iyi hissetmiyorum! Soon'a gidip bu gorevi kabul[ENTER]edemeyecegimi soyleyecegim. "
