gameforge.skill_reset2._10_npcChat = "Beceri sifirlama. "
gameforge.skill_reset2._110_say = "Gelecekte fikrini degistirirsen bana geri donmen[ENTER]yeterli. "
gameforge.skill_reset2._120_say = "Cok az Yang'in var. Sana yardim edemem.[ENTER]Sonucta benim de yasamam gerek! "
gameforge.skill_reset2._130_say = "Bu esya sinifini (ogretini) degistirmene olanak[ENTER]saglar. Ancak onu kullanabilmek icin en az 31.[ENTER]seviyede olmalisin. Sinif degistirmek bircok yeni[ENTER]firsat sunar! Seni buraya getiren becerilerden[ENTER]kurtulmak istiyor musun? "
gameforge.skill_reset2._135_say = "Hicbir ogretiyi takip etmiyorsun ve geri alinabilecek[ENTER]hic beceri puanin yok! "
gameforge.skill_reset2._140_say = "Bu esya 31. seviyeden itibaren kullanilabilir. "
gameforge.skill_reset2._20_say = "Henuz egitime baslamamissin! Henuz hic Beceri Puani[ENTER]harcamadiysan onlari sifirlayamazsin. Becerilerini[ENTER]gelistirirken bir hata yaptiginda tekrar gel, sana[ENTER]seve seve yardim ederim. "
gameforge.skill_reset2._30_say = "Seviyen %s.[ENTER]Üzgunum, maalesef sana yardim edemem.[ENTER]Bu seviyede artik becerilerine etki edemem. Sadece[ENTER]30. seviyenin altindaki oyunculara becerilerini[ENTER]sifirlamada yardimci olabilirim. "
gameforge.skill_reset2._40_say = "Hicbir ogretiyi takip etmiyorsun ve geri alinabilecek[ENTER]hic beceri puanin yok! "
gameforge.skill_reset2._50_say = "Merhaba, dogru yere geldin.[ENTER]Gozlerinde cok fazla huzun goruyorum.[ENTER]Insanlarin gecmislerini unutmasini sagliyorum,[ENTER]yeniden baslayabilirler...[ENTER]Becerilerini sifirlamak istiyor musun?[ENTER]Maliyeti %s Yang. "
gameforge.skill_reset2._60_select = "Sifirlama "
gameforge.skill_reset2._70_say = "Ha ha, pek iyi hissetmiyor musun?[ENTER]Yardima ihtiyaci olan birine benziyorsun.[ENTER]Becerilerinden memnun degil misin?[ENTER]Sana yardim edebilecegim buyulu bir yol biliyorum.[ENTER]Becerilerini sifirlayabilirim. "
gameforge.skill_reset2._80_say = "Bu, baska beceriler secebilecegin anlamina gelir.[ENTER]Ancak sifirlamaya karar verirsen, Beceri Kitaplari[ENTER]sayesinde kazandigin puanlari kaybedersin.[ENTER]Her seye gercekten bastan baslamak istiyor musun?[ENTER]Maliyeti %s Yang. "
gameforge.skill_reset2._90_select = "Becerileri Sifirla "
gameforge.spider_dungeon_2floor = {}
gameforge.spider_dungeon_2floor._10_npcChat = "1. Kata Don "
gameforge.spider_dungeon_2floor._15_sayTitle = "Pung-Ho: "
gameforge.spider_dungeon_2floor._20_say = "Orumcek Zindani'nin 1. Katina gercekten donmek[ENTER]istiyor musun? "
gameforge.spider_dungeon_2floor._30_say = "Akillica bir karar. Daha uzun sure kalmak icin[ENTER]burasi cok tehlikeli.[ENTER]Git ve yaralarini sar.[ENTER]Gorusmek uzere! "
gameforge.spider_dungeon_2floor._40_say = "Tamam, nasil istersen oyle olsun...[ENTER]Lutfen kendine dikkat et![ENTER]Burasi gercekten cok tehlikeli. "
gameforge.spider_dungeon_3floor_boss = {}
gameforge.spider_dungeon_3floor_boss._100_say = "Orumcek Zindani'ni aramak icin cesaretinin[ENTER]yetmedigini soylemeyeceksin herhalde? Oysa savasta[ENTER]epey tecruben var, yani birkac beyinsiz orumcek senin[ENTER]icin buyuk bir sorun teskil etmemeli. Ancak bu[ENTER]magaraya girmek icin bir Gecit Biletine ihtiyacin[ENTER]oldugunu biliyorsun, degil mi? "
gameforge.spider_dungeon_3floor_boss._10_npcChat = "Barones Yuvasi Girisi "
gameforge.spider_dungeon_3floor_boss._110_sendLetter = "Yeni Bir Tehlike "
gameforge.spider_dungeon_3floor_boss._120_say = "Yazitin kusursuz bir kopyasini cikarmayi basardin.[ENTER]Onu Yuzbasi'ya goster. "
gameforge.spider_dungeon_3floor_boss._130_say = "Harika, iyi is! Bir bakayim... hmmm,[ENTER]bu isaretleri cikaramadim, hicbir sey anlamiyorum.[ENTER]Belki de Bilge Uriel'e sormak gerekir? "
gameforge.spider_dungeon_3floor_boss._140_say = "Bilge Uriel'e git ve yaziti ona goster.[ENTER]O bunu kesinlikle desifre edebilecektir. "
gameforge.spider_dungeon_3floor_boss._150_say = "Yuzbasi bu gizemli yaziti tercume etmemi mi istiyor?[ENTER]Sorun degil, boyle meydan okumalara bayilirim.[ENTER]Ver bakalim... Bu... bu inanilmaz! Bekle, sana hemen[ENTER]ceviriyi yazayim. Al! Bunu en kisa surede Yuzbasi'ya[ENTER]gotur, sonra da yanima don. Eger bu yazit dogruyu[ENTER]soyluyorsa hepimiz korkunc bir tehlike icindeyiz.[ENTER]Kos cabuk, kos! "
gameforge.spider_dungeon_3floor_boss._160_say = "Yuzbasi'ya henuz ulasamadin mi? Lutfen acele et,[ENTER]durum cok ciddi! Yuzbasi bu mektubu mutlaka[ENTER]okumali. "
gameforge.spider_dungeon_3floor_boss._170_sayTitle = "Uriel'in Mektubunu Ilet "
gameforge.spider_dungeon_3floor_boss._180_say = "Ah, su inatci yasli geveze... En azindan bir[ENTER]'tesekkurler' diyebilirdi. Ama neyse. Bu bilgilerin[ENTER]cok onemli oldugunu soyluyor, bu yuzden onlari bir[ENTER]an once Yuzbasi'ya teslim etsem iyi olur. "
gameforge.spider_dungeon_3floor_boss._190_npcChat = "Uriel'in Mektubu "
gameforge.spider_dungeon_3floor_boss._200_say = "Lanet olsun! Orumcek Zindani'nin ucuncu katina[ENTER]guclu bir orumcek iblisi yerlesmis - Orumcek[ENTER]Baronesi! Yazita gore bu gizli magaraya girmek[ENTER]icin ozel bir anahtar gerekiyor. Uriel'e git ve bu[ENTER]anahtari sor. Sonra deneyimli savascilardan olusan[ENTER]bir ekip topla ve Orumcek Baronesi'nin yuvasina[ENTER]birlikte saldirin! Al, senin icin bir Gecit Biletim[ENTER]daha var. "
gameforge.spider_dungeon_3floor_boss._20_say = "Bu kapi yalnizca Orumcek Anahtari ile acilabilir. "
gameforge.spider_dungeon_3floor_boss._210_npcChat = "Orumcek Anahtari "
gameforge.spider_dungeon_3floor_boss._220_say = "Yapacak bir sey yok, bir an once Uriel'e gitmek[ENTER]gerek. "
gameforge.spider_dungeon_3floor_boss._230_say = "Ah, dondugun iyi oldu. Demek Yuzbasi sana Orumcek[ENTER]Baronesi'ni oldurme emri verdi? Ancak yuvasinin[ENTER]girisi kapali ve sadece Orumcek Anahtari ile[ENTER]acilabilir. Boyle bir anahtar yapmak cok karmasiktir.[ENTER]Ama bana Orumcek Zehri Kesesi, Orumcek Yumurta[ENTER]Kesesi, Orumcek Agi, Orumcek Gozleri, Orumcek[ENTER]Bacaklari ve Kralice Orumcek Zehri getirirsen bunu[ENTER]basarabilirim. "
gameforge.spider_dungeon_3floor_boss._240_say = "Senin icin bir Orumcek Anahtari yapmami istiyor[ENTER]musun? Bunun icin Orumcek Zehri Kesesi, Orumcek[ENTER]Yumurta Kesesi, Orumcek Agi, Orumcek Gozleri,[ENTER]Orumcek Bacaklari ve Kralice Orumcek Zehri'ne[ENTER]ihtiyacim var. Butun malzemeleri bulabildin mi? "
gameforge.spider_dungeon_3floor_boss._250_say = "Harika! Butun malzemeler sende! Biraz bekle, cok[ENTER]uzun surmeyecek... "
gameforge.spider_dungeon_3floor_boss._260_say = "Iste oldu! Orumcek Baronesi'nin yuvasina girmeni[ENTER]saglayacak Orumcek Anahtari burada. Sana ve[ENTER]arkadaslarina bu uzun bacakli canavarla savasta[ENTER]basarilar dilerim. Ancak acele etmelisiniz, cunku[ENTER]bu anahtar cok dengesizdir ve 24 saat sonra yok[ENTER]olur. "
gameforge.spider_dungeon_3floor_boss._270_say = "Ve... ah, ne yazik ki bu anahtari yapma sureci cok[ENTER]karmasiktir ve her zaman basarili olmaz. Ufak bir[ENTER]hata butun isi mahvetmeye yeter. Maalesef anahtarla[ENTER]birlikte senden aldigim tum malzemeler de heba oldu.[ENTER]Zahmetli toplama isinin bosa gitmesine uzuldum. Bir[ENTER]dahaki sefere kesinlikle ise yarayacaktir! "
gameforge.spider_dungeon_3floor_boss._280_say = "Hayir, henuz butun malzemelere sahip degilsin,[ENTER]hatirlatmak gerekirse: Orumcek Zehri Kesesi, Orumcek[ENTER]Yumurta Kesesi, Orumcek Agi, Orumcek Gozleri,[ENTER]Orumcek Bacaklari ve Kralice Orumcek Zehri lazim. "
gameforge.spider_dungeon_3floor_boss._300_say = "Grup liderin zindana girdi. Ona katilmak istiyor[ENTER]musun? "
gameforge.spider_dungeon_3floor_boss._30_npcChat = "SD3 Gorevini Sifirla "
gameforge.spider_dungeon_3floor_boss._310_say = {}
gameforge.spider_dungeon_3floor_boss._320_say = "Barones'in yuvasinda su anda Orumcek Baronesi'ne[ENTER]saldiran baska bir grup var. "
gameforge.spider_dungeon_3floor_boss._330_say = "Giris ancak icerideki grup gorevini tamamladiktan[ENTER]sonra mumkun olacaktir. %s dakika sonra tekrar gel. "
gameforge.spider_dungeon_3floor_boss._340_say = "Barones Yuvasi kapisinin tekrar acilabilmesi icin[ENTER]kalan sure: "
gameforge.spider_dungeon_3floor_boss._350_say = "%s dakika. "
gameforge.spider_dungeon_3floor_boss._360_say = "Senden once magaraya giren savasci 10 saniye[ENTER]boyunca hareketsiz kaldi. Bir saniye bekle. "
gameforge.spider_dungeon_3floor_boss._370_say = "Fethi baslatmak istiyor musun? Bunun icin 20[ENTER]dakikan var. Bu sure dolmadan hic kimse Barones'in[ENTER]yuvasini terk edemez.[ENTER]Yeni bir fetih bir saat sonra baslatilabilir. "
gameforge.spider_dungeon_3floor_boss._380_say = "Girisi acmak icin Orumcek Anahtari'na ihtiyacin[ENTER]var. "
gameforge.spider_dungeon_3floor_boss._390_say = "Orumcek Anahtari sadece grup lideri tarafindan[ENTER]kullanilabilir. "
gameforge.spider_dungeon_3floor_boss._400_say = "Orumcek Baronesi katledildi! Üc dakika icinde[ENTER]tum savascilar magaradan disari isinlanacaktir. "
gameforge.spider_dungeon_3floor_boss._40_say = "Anahtar yapilmadan once "
gameforge.spider_dungeon_3floor_boss._410_say = "Basarisiz oldu. Tekrar dene! "
gameforge.spider_dungeon_3floor_boss._420_notice = "Dikkat: Orumcek Baronesi ofke krizine giriyor![ENTER]Saldirilari gucleniyor ama savunmasi zayifliyor. "
gameforge.spider_dungeon_3floor_boss._50_npcChat = "Orumcek Zindani 3 "
gameforge.spider_dungeon_3floor_boss._60_say = "Ah, burada olman ne iyi. Sana onemli haberlerim[ENTER]var. Gozculerimiz Orumcek Zindani'nda ucuncu bir kat[ENTER]kesfetti. Bu yeni magara simdiye kadar bildiklerimizden[ENTER]daha kucuk ancak soylentilere gore oraya son derece[ENTER]tehlikeli orumcekler yerlesmis. Ayrica orada uzerine[ENTER]yazit kazinmis eski bir mezar tasi bulundu ama yazi[ENTER]cozulemedi. O mezar tasini aramaya cik ve yazitin[ENTER]bir kopyasini bana getir. Al, bu gecit bileti Orumcek[ENTER]Zindani'na girmene imkan verecektir. "
gameforge.spider_dungeon_3floor_boss._70_sendLetter = "Yazit "
gameforge.spider_dungeon_3floor_boss._80_say = "Orumcek Zindani'nin ucuncu katinda uzerinde yazit[ENTER]kazinmis eski bir mezar tasi buluyorsun. Yazitin[ENTER]bir kopyasini cikar ve Yuzbasi'ya gotur. "
gameforge.spider_dungeon_3floor_boss._90_say = "Harika, eski mezar tasini bulmayi ve yazitinin[ENTER]kopyasini cikarmayi basardin! Yuzbasi'ya geri don[ENTER]ve kopyayi ona teslim et. "
