gameforge.subquest_01._290_sayTitle = "Satici: "
gameforge.subquest_01._300_say = "Tesekkurler. Umarim siseyi almak senin icin cok[ENTER]zahmetli olmamistir. Bunu sana tesekkurum olarak[ENTER]veriyorum. Tekrar cok tesekkurler! "
gameforge.subquest_01._30_say = "Beni bagisla, eger su anda mesgul degilsen benim[ENTER]icin bir sey yapabilir misin? Kirmizi Iksirim icin[ENTER]Bos Sise'ye ihtiyacim var. "
