gameforge.subquest_02._10_targetVid = "Ogle Yemegi "
gameforge.subquest_02._110_say = "Bu yemek sohbeti karnimi aciktirdi; guvec eti,[ENTER]bira, lahana ve iki yumurtayi oyle bir canim cekti[ENTER]ki sorma. "
gameforge.subquest_02._120_say = "Babam ogle yemeginde ne yemek istedigini soyledi[ENTER]mi? "
gameforge.subquest_02._121_select = "Domuz eti, bira, lahana ve yumurta. "
gameforge.subquest_02._122_select = "Guvec eti, bira, lahana ve yumurta. "
gameforge.subquest_02._123_select = "Guvec eti, bira, lahana ve iki yumurta "
gameforge.subquest_02._124_select = "Ee... unuttum... "
gameforge.subquest_02._130_say = "Bu bilgiyi bana bu kadar cabuk getirdigin icin[ENTER]tesekkur ederim.[ENTER]Iste odulun. "
gameforge.subquest_02._140_sayReward = "1000 Deneyim Puani kazandin.[ENTER]1500 Yang kazandin. "
gameforge.subquest_02._150_say = "Satici:[ENTER]Yemegin adi cok uzundu, degil mi?[ENTER]Ona tekrar sorabilir misin? "
gameforge.subquest_02._160_say = "Satici:[ENTER]Bunu gercekten soyledi mi? Ne garip![ENTER]Bu yemegi hic sevmezdi... Tekrar sorabilir[ENTER]misin?[ENTER]O yemegi dusundugunden supheliyim. "
gameforge.subquest_02._20_say = "Zirh satan babami taniyor musun? Onun icin ogle[ENTER]yemegi hazirlamak istiyorum ama ne yemek istedigini[ENTER]bilmiyorum. Yanina gidip ne hazirlanmasini istedigini[ENTER]sorabilir misin? Bu zahmetin icin seni kesinlikle[ENTER]odullendirecegim. "
gameforge.subquest_02._30_sayReward = "Satici, babasi Zirh Saticisi'nin ogle yemeginde[ENTER]ne yemek istedigini ogrenmek istiyor. "
gameforge.subquest_02._40_sayReward = "Zirh Saticisi'na git ve ona sor. "
gameforge.subquest_02._50_say = "Merhaba![ENTER][ENTER]Seni kilic ve bicak saldirilarindan koruyacak[ENTER]zirhlarim var. "
gameforge.subquest_02._60_say = "Ah, seni kizim mi gonderdi? Muhtemelen ogle[ENTER]yemeginde ne hazirlamasi gerektigini dusunuyordur.[ENTER]Bir dusuneyim, hmm... Baharatli guvec eti, bira,[ENTER]mis kokulu lahana ve iki yumurta isterdim. Bu uzun[ENTER]zamandir bekledigim bir yemek! "
gameforge.subquest_02._70_targetVid = "Ogle Yemegi "
gameforge.subquest_02._80_sayReward = "Satici, babasi Zirh Saticisi'nin ogle yemeginde[ENTER]ne yemek istedigini ogrenmek istiyor. "
gameforge.subquest_02._90_sayReward = "Ona geri don ve ogrendiklerini haber ver. "
