gameforge.subquest_04._140_npcChat = "Demirci'den Mektup. "
gameforge.subquest_04._150_sayTitle = "Deokbae: "
gameforge.subquest_04._160_say = "Hos geldin sefa getirdin misafir! Elimde guzel[ENTER]baltalar var. Bir tane almak ister misin? Ne?[ENTER]Ihtiyacin yok mu? O zaman neden yanima geldin?[ENTER]Ah! Demirciden mektup. Tesekkurler. Bildigin gibi[ENTER]ben oduncuyum ama sadece balta degil, kazma ve[ENTER]diger aletleri de satarim. Zaman zaman onlari[ENTER]demirciye siparis ederim. Boylece iyi arkadas olduk. "
gameforge.subquest_04._170_say = "Onunla Seo-Pyung meyhanesinde tekrar bir seyler[ENTER]icmeliyim mutlaka. Bu mektubu getirdigin icin[ENTER]tesekkurler. Demirci'ye selamlarimi ilet. "
gameforge.subquest_04._180_say = "Demirciden mektup mu? Dostum, bu cok zaman onceydi.[ENTER]Nerede o? Yolda kaybetmedin degil mi? "
gameforge.subquest_04._190_select = "Iste burada. "
gameforge.subquest_04._200_select = "Ee, yanimda yok. "
gameforge.subquest_04._20_say = "Selam yeni maceraci! Bir ricada bulunmak[ENTER]istemistim. Deokbae adinda bir adam taniyor musun?[ENTER]Oduncudur ve benim iyi bir dostumdur. Belki biraz[ENTER]sikici biridir ama canla basla calisan son[ENTER]odunculardandir. "
gameforge.subquest_04._210_say = "Gorevi iptal etmek mi istiyorsun? "
gameforge.subquest_04._220_say = "Guzel... yakinda geri don. "
gameforge.subquest_04._230_say = "Kaybettin mi? Cekil git buradan. "
gameforge.subquest_04._240_say = "Demirci'ye git ve mektubu al.[ENTER]Tekrar kaybetme sakin. "
gameforge.subquest_04._250_sayReward = "Demirci'ye don ve odulunu al. "
gameforge.subquest_04._260_targetVid = "Demirci'ye Geri Don "
gameforge.subquest_04._270_npcChat = "Mektubu teslim ettim. "
gameforge.subquest_04._280_say = "Eee, Deokbae nasilmis? Hehe.[ENTER]Zerre degismemis. Sag ol! Bunu odul olarak al.[ENTER]Cok fazla degil ama ileride isine yarayacagini[ENTER]dusunuyorum. Tekrar tesekkurler. "
gameforge.subquest_04._290_sayReward = "4000 Deneyim Puani kazandin.[ENTER]3000 Yang kazandin. "
gameforge.subquest_04._30_say = "Uzun zamandir onu gormedim ve her seyin yolunda[ENTER]olup olmadigini sormak icin ona bir mektup yazdim...[ENTER]Bu mektubu ona ulastirmani istiyorum. Bugunlerde[ENTER]koyde pek cok sorun var. Bu yuzden dikkatli ol.[ENTER]Ve lutfen mektubu kaybetme! "
gameforge.subquest_04._40_say = "Ee, bir sonraki koye nasil gidecegini bilmiyor[ENTER]musun? Mini haritayi acmak icin M tusuna bas.[ENTER]Koy, haritada mavi bir nokta ile isaretlenmistir;[ENTER]bu nokta komsu bolgeye gecmeni saglayan portali[ENTER]gosterir. Ikinci koy orada yer aliyor. "
gameforge.subquest_04._50_select = "Yaparim. "
gameforge.subquest_04._60_select = "Hayir, kalsin. "
gameforge.subquest_04._70_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_04._80_say = "En kisa surede geri don... "
gameforge.subquest_04._90_say = "Yazik oldu, yine de tesekkurler. "
