gameforge.subquest_05._280_say = "Bunu duymak hic iyi degil... Cek git basimdan... "
gameforge.subquest_05._290_say = "Harika, cok guzel. Tekrar ugra. "
gameforge.subquest_05._300_say = "Siralamanin dogru oldugundan emin misin? "
gameforge.subquest_05._30_sayTitle = "Soon: "
gameforge.subquest_05._310_select = "Evet, eminim. "
gameforge.subquest_05._320_select = "Hayir, pek sayilmaz... "
