gameforge.subquest_06._110_say = "Sag ol! Demirci'ye git ve Zirhimin durumunun nasil[ENTER]gittigini sor. "
gameforge.subquest_06._120_sayReward = "Demirci'ye git ve Zirh Saticisi'nin siparis ettigi[ENTER]zirhi ne zaman bitirecegini sor. "
gameforge.subquest_06._130_npcChat = "Zirh Saticisi Icin Zirh "
gameforge.subquest_06._140_say = "Bu sefer ne var? Neden beni rahatsiz ediyorsun?[ENTER]Ah, seni Zirh Saticisi mi gonderdi? O yasli adam[ENTER]gercekten cok sabirsiz. Yapmak istemedigimden[ENTER]degil. Sadece gereken malzemelerim yok. Onlari benim[ENTER]icin bulabilir misin? Zirhi yapmak icin Demir[ENTER]Cevheri, Deri ve Komure ihtiyacim var. Demir[ENTER]Cevherini Uriel'den, Deriyi Octavio'dan, Komuru ise[ENTER]Yonah'tan alabilirsin. "
gameforge.subquest_06._150_select = "Malzemeleri toplayacagim. "
gameforge.subquest_06._160_select = "Hayir, simdi degil. "
gameforge.subquest_06._170_say = "Bu gorevi yapmaktan gercekten vazgecmek istiyor[ENTER]musun? "
gameforge.subquest_06._180_say = "Bu gorevi daha sonra da yapabilirsin pekala. Ama[ENTER]fazla bekleme, acil bir mesele! "
gameforge.subquest_06._190_say = "Pekala, bu durumda onlari kendim bulmam gerekecek[ENTER]sanirim. Kendine iyi bak. "
gameforge.subquest_06._200_say = "O zaman yola cik da biraz huzurla calisabileyim... "
gameforge.subquest_06._20_npcChat = "Zirh siparisi. "
