gameforge.subquest_06._260_npcChat = "Zirh icin Demir Cevheri "
gameforge.subquest_06._270_say = "Kitabimi getirdigin icin tesekkur ederim! Artik[ENTER]arastirmami tamamlayabilirim. Al bakalim, biraz[ENTER]Demir Cevheri. Onu al ve faydali bir iste kullan. "
gameforge.subquest_06._280_say = "Demir Cevherine mi ihtiyacin var? Sana biraz[ENTER]verebilirim. Ancak kucuk bir ricam var. Gecenlerde[ENTER]bir Yabani Kopek surusu tarafindan kovalanirken[ENTER]Kitabimi kaybettim. Sanirim o Yabani Kopekler h�l�[ENTER]ona sahip. O Kitabi bana getirirsen sana biraz[ENTER]Demir Cevheri veririm. "
gameforge.subquest_06._285_say = "- Yabani Kopeklerden Kitabini getirirsen Uriel[ENTER]sana Demir Cevheri verecektir. "
gameforge.subquest_06._290_npcChat = "Zirh icin Demir Cevheri "
gameforge.subquest_06._300_say = "Daha fazla mi Demir Cevherine ihtiyacin var?[ENTER]Sana zaten biraz vermistim.[ENTER]Elimde daha fazlasi yok. "
gameforge.subquest_06._30_say = "Kizima yardim ettigin icin tesekkur ederim. Simdi de[ENTER]senden bir iyilik isteyecegim. Koydeki Demirci'ye[ENTER]bir zirh ismarlamistim ama ondan hic haber alamadim.[ENTER]Siparisin durumunu ogrenebilir misin? "
gameforge.subquest_06._310_npcChat = "Biraz Deriye ihtiyacim var. "
gameforge.subquest_06._320_sayTitle = "Octavio: "
gameforge.subquest_06._330_say = "Safra icin tesekkurler! Sonunda o enfes lezzetteki[ENTER]yemeklerimi pisirebilecegim! Nefis... nefis...[ENTER]tam bir ziyafet. Al bakalim, iste odulun. Minnettarligimin[ENTER]bir ifadesi olarak bu Deriyi al. "
gameforge.subquest_06._340_say = "Sana biraz deri verebilirim.[ENTER]Ama bu dunyada hicbir sey bedava degildir.[ENTER]Takasa ne dersin? Bana ayi safrasi getirirsen[ENTER]benden biraz deri alirsin. En sevdigim lezzetleri[ENTER]pisirmek icin sik sik safraya ihtiyacim olur.[ENTER]Bana yardim etmek istemiyorsan, eh, bir sekilde[ENTER]kendi basimin caresine bakarim. "
gameforge.subquest_06._345_say = "- Ayilardan safra getirirsen Octavio sana deri[ENTER]verecektir. "
gameforge.subquest_06._350_npcChat = "Biraz Deriye ihtiyacim var. "
gameforge.subquest_06._360_say = "Sana Deriyi zaten verdim. Kaybettin mi yoksa?[ENTER]Daha fazlasi yok bende... "
gameforge.subquest_06._370_npcChat = "Biraz Komure ihtiyacim var. "
gameforge.subquest_06._380_say = "Kil icin tesekkurler. Bir elin nesi var iki elin[ENTER]sesi var, degil mi? Iste Komur. Yakinda gorusmek[ENTER]uzere. "
gameforge.subquest_06._390_say = "Ne var ne yok? Biraz Komur icin mi geldin? Bende[ENTER]cok var. Ama bedavaya olmaz. Benim icin bir sey[ENTER]yaparsan sana biraz veririm. "
gameforge.subquest_06._395_say = "- Yonah'a kil getirirsen sana komur verecektir.[ENTER]Bunun icin Kirmizi Yaban Domuzlarini avlamalisin. "
gameforge.subquest_06._400_say = "Pek fazla Kil'im kalmadi. Bana birazcik Kil[ENTER]getirirsen sana Komur veririm. Ister inan ister[ENTER]inanma kil yiyen birkac Kirmizi Yaban Domuzunu[ENTER]oldursen cok iyi olur. Simdiden tesekkurler! "
gameforge.subquest_06._40_select = "Evet, yaparim. "
gameforge.subquest_06._410_npcChat = "Biraz Komure ihtiyacim var. "
gameforge.subquest_06._420_say = "Ne? Sana Komuru zaten verdim ya! Benimle kafa mi[ENTER]buluyorsun sen? "
gameforge.subquest_06._430_npcChat = "Tum malzemelerin var. "
gameforge.subquest_06._440_say = "Gorunuse gore Demir Cevherin yok. Uriel'e git. "
gameforge.subquest_06._450_say = "Derin yok. Octavio'ya git... "
gameforge.subquest_06._460_say = "H�l� Komurun yok mu? Onu Yonah'tan getir. "
