gameforge.subquest_07._100_say = "Bir saniye bekle, dogru Kitap oldugundan emin[ENTER]olmaliyim... Hmm, evet, gercekten harika bir Yemek[ENTER]Kitabi. Bu yemegi kesinlikle pisirecegim! Sag ol! "
gameforge.subquest_07._10_targetVid = "En Iyi Yemek Kitabi "
gameforge.subquest_07._110_say = "Hmm, ama suna ihtiyacim var... Bekle dostum![ENTER]Senden bir iyilik daha isteyebilir miyim? Bu yemek[ENTER]icin neredeyse tum malzemelerim var ama Gri Kurt[ENTER]Bagirsagim eksik. Bunlari elde etmek kolay degildir.[ENTER]Lutfen bana bir tane getir. "
gameforge.subquest_07._120_sayReward = "Octavio icin Gri Kurt Bagirsagi temin et. Onu Gri[ENTER]Kurtlardan elde edebilirsin. "
gameforge.subquest_07._130_npcChat = "Kurt Bagirsagim var. "
gameforge.subquest_07._140_say = "Sayende bu nadide yemegi nihayet pisirebilirim.[ENTER]Iste bu gercek bir ziyafet olacak! Yardimini takdir[ENTER]ediyorum. Al lutfen, emegin icin mutevazi bir odul. "
gameforge.subquest_07._150_sayReward = "12.000 Deneyim Puani kazandin.[ENTER]5.000 Yang kazandin.[ENTER]Kurt Tirnagi kazandin. "
gameforge.subquest_07._160_say = "Gri Kurt Bagirsagi'na ihtiyacim var.[ENTER]Lutfen bana bir tane getir. "
gameforge.subquest_07._20_npcChat = "En Iyi Yemek Kitabi "
gameforge.subquest_07._30_say = "Hm, Soon'u taniyor musun? Zamanini sadece kitap[ENTER]okuyarak geciren bir kitap kurdudur.[ENTER]Soon'un harika bir Yemek Kitabi oldugunu duydum.[ENTER]Lutfen gidip gercekten oyle olup olmadigina bir bak.[ENTER]Bu Kitabin ogrenmek istedigim nadir ve egzotik[ENTER]tariflerle dolu oldugu soyleniyor. "
gameforge.subquest_07._40_targetVid = "Soon'a Sor "
gameforge.subquest_07._50_sayReward = "Soon'a yabanci Yemek Kitabi olup olmadigini sor. "
gameforge.subquest_07._60_npcChat = "Ozel bir Yemek Kitabin var mi? "
gameforge.subquest_07._70_say = "Bidi bidi... Ah! Yine sen, ne haber? Evet, egzotik[ENTER]yemeklerin oldugu bir Yemek Kitabim var. Al senin[ENTER]olsun, benim isime yaramiyor. Ama lutfen kitap[ENTER]okurken beni bir daha rahatsiz etme! "
gameforge.subquest_07._80_targetVid = "Soon yabanci Yemek Kitabini sana sorunsuzca verdi.[ENTER]Onu Octavio'ya gotur. "
gameforge.subquest_07._85_say = "Kurt Bagirsagini buldun.[ENTER]Onu Octavio'ya gotur. "
gameforge.subquest_07._90_npcChat = "Iste Yemek Kitabi! "
