gameforge.subquest_08._100_sayReward = "Silah Saticisi'na git ve nereden Pirinc Keki satin[ENTER]alinabilecegini sor. "
gameforge.subquest_08._10_targetVid = "Pirinc Keki "
gameforge.subquest_08._110_npcChat = "Pirinc Kekleri hakkinda ne biliyorsun? "
gameforge.subquest_08._120_sayTitle = "Silah Saticisi: "
gameforge.subquest_08._130_say = "Ohom, ne? Pirinc Keki mi? Bunu neden soruyorsun?[ENTER]Boyle bir silahi ilk kez duyuyorum. Anlamadim...[ENTER]Ah, Pirinc Keki, yiyecek bir sey. Onu Octavio'ya[ENTER]sormalisin, o yemekler hakkinda her seyi bilir. "
gameforge.subquest_08._140_makequestbutton = "Pirinc Keki "
gameforge.subquest_08._150_sayReward = "Octavio'ya git ve Pirinc Kekleri hakkinda ne[ENTER]bildigini sor. "
gameforge.subquest_08._160_say = "Hmm, kirmizi visneli ve sekerli su yumusak kek,[ENTER]degil mi? Evet, bir keresinde bu lezzeti tatma[ENTER]firsatim olmustu. Onu ikinci koyde dolasan bir[ENTER]saticidan alabilirsin. "
gameforge.subquest_08._170_select = "Hayir, buna vaktim yok. "
gameforge.subquest_08._180_say = "Onunde uzun bir yol var. Gorusmek uzere. "
gameforge.subquest_08._190_say = "Seni temin ederim bir seyler kacirdin... Yazik.[ENTER]Gorusmek uzere! "
gameforge.subquest_08._200_say = "Goreceksin, degecek. Iyi yolculuklar. "
gameforge.subquest_08._20_say = "Affedersiniz, bana yardim edebilir misiniz?[ENTER]Duydugunuz gibi bebegim agliyor ve onu bir turlu[ENTER]susturamiyorum. Ne yapacagimi bilmiyorum. Pirinc[ENTER]Keklerini cok sevdigini biliyorum ve boyle bir[ENTER]kekin ise yarayacagini dusunuyorum. Sanirim Silah[ENTER]Saticisi onlari nereden bulabilecegimi biliyor.[ENTER]Ona sorabilir misiniz? "
gameforge.subquest_08._210_makequestbutton = "Yu-Rang'i Bul "
gameforge.subquest_08._220_targetVid = "Pirinc Keki "
gameforge.subquest_08._230_sayReward = "Pirinc Keki Saticisi Yu-Rang'a git. Onu bir sonraki[ENTER]koyde bulacaksin. "
gameforge.subquest_08._240_sayTitle = "Yu-Rang: "
gameforge.subquest_08._250_say = "Nasil yardimci olabilirim? Oh! Pirinc Kekleri.[ENTER]Elbette sana boyle bir kek verebilirim! Ama...[ENTER]Taurean adinda bir cocuk sik sik buraya gelip bana[ENTER]satasiyor. Nedenini bilmiyorum ama bana bulasip[ENTER]hemen kaciyor. Taurean'a bir ders verirsen benden[ENTER]bir Pirinc Keki alirsin, tamam mi? "
gameforge.subquest_08._260_makequestbutton = "Taurean'i Bul. "
gameforge.subquest_08._270_sayReward = "Taurean surekli Yu-Rang'a satasiyor. Onu cezalandir,[ENTER]karsiliginda ondan bir Pirinc Keki alacaksin. "
gameforge.subquest_08._280_npcChat = "Neden Yu-Rang'a satasiyorsun? "
gameforge.subquest_08._290_say = "Kime satasiyormusum? Ah, Pirinc Keki satan kiza[ENTER]mi? Sadece onunla oynamak istemistim. Ne demek[ENTER]istedigimi anliyor musun? Dusundugun gibi degil![ENTER]Ona satasmak istemedim! Canim sikiliyordu,[ENTER]gorunuse gore onun da yapacak fazla isi yoktu,[ENTER]ben de sadece onu eglendirmek istedim. Canini yakmak[ENTER]istemedim. Bir daha yapmayacagim, soz veriyorum! "
gameforge.subquest_08._300_makequestbutton = "Yu-Rang'a Don "
gameforge.subquest_08._30_select = "Kabul et "
gameforge.subquest_08._310_targetVid = "Pirinc Keki "
gameforge.subquest_08._320_sayReward = "Taurean artik Yu-Rang'i rahatsiz etmeyecek. Yanina[ENTER]git ve soz verdigi Pirinc Kekini al. "
gameforge.subquest_08._330_say = "Hehe, Taurean'a dersini verdin mi?[ENTER]Sag ol, iste sana Pirinc Keki.[ENTER]Onunla ne yaparsin bilmem ama afiyet olsun. "
