gameforge.subquest_08._370_npcChat = "Iste bebegin icin Pirinc Keki. "
gameforge.subquest_08._380_say = "Bana Pirinc Keki getirdin! Cok tesekkur ederim.[ENTER]Oh! Bak, bebegim aglamayi kesti. Ise yaradi![ENTER]Yardimin icin tesekkurler! "
gameforge.subquest_08._390_sayReward = "26.000 Deneyim Puani kazandin.[ENTER]10.000 Yang kazandin. "
gameforge.subquest_08._40_say = "Ama... buradan ayrilamam... ve cocuk aglamasiyla[ENTER]butun mahalleyi inletiyor... Cok surmez! Bana yardim[ENTER]etmek icin gercekten vaktiniz yok mu? "
gameforge.subquest_08._50_say = "Mesgul musun? Lutfen tekrar ugra.[ENTER]Sss, aglama kucugum benim... "
gameforge.subquest_08._60_say = "O zaman baskasina sormam gerekecek.[ENTER]Basarilar! "
