gameforge.subquest_09._120_npcChat = "Iste Altin Balta. "
gameforge.subquest_09._130_say = "Tesekkur ederim, sana borclandim. Artik bir dahaki[ENTER]sefer Deokbae ile karsilastigimda ona ne diyecegimi[ENTER]dusunmek zorunda kalmayacagim! "
gameforge.subquest_09._140_sayReward = "36.000 Deneyim Puani kazandin.[ENTER]10.000 Yang kazandin.[ENTER]Sus Esyasi kazandin. "
gameforge.subquest_09._20_npcChat = "Altin Balta "
gameforge.subquest_09._30_say = "Dostum Deokbae'yi hatirliyor musun? Onun icin bir[ENTER]Balta yapacagima soz vermistim ama bir anlik[ENTER]dikkatsizligimde bir Yeminli Asker onu caldi.[ENTER]O Baltayi benim icin geri alabilir misin? Yeminli[ENTER]Askerde olmali. Baltayi kolayca taniyabilirsin,[ENTER]onlardan cok az var. Bunun icin seni odullendirecegim. "
gameforge.subquest_09._40_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_09._50_sayTitle = "Demirci. "
gameforge.subquest_09._60_say = "O Baltaya fena halde ihtiyacim var...[ENTER]Tekrar gorusur muyuz? Gorusmek uzere... "
gameforge.subquest_09._70_say = "Onu benim icin geri almak istemene sevindim.[ENTER]Dikkatli ol, Yeminliler tehlikeli olabilir. "
gameforge.subquest_09._80_say = "Onu benim icin geri almak istemene sevindim.[ENTER]Dikkatli ol, Yeminliler tehlikeli olabilir. "
