gameforge.subquest_10 = {}
gameforge.subquest_10._100_sayReward = "Demirci'ye Tokanin nerede oldugunu sor. "
gameforge.subquest_10._10_targetVid = "Sac tokasini bul "
gameforge.subquest_10._110_npcChat = "Calinan Toka. "
gameforge.subquest_10._120_say = "Ne? Tokasini benim caldigimi mi saniyor?[ENTER]Bu... bu inanilmaz! Benim hakkimda ne dusunuyor[ENTER]boyle? Atolyemde calisiyordum ben! Hm, belki sana[ENTER]bunu soylememeliyim ama Silah Saticisi az once[ENTER]Satici'nin dukkaninda dolaniyordu. "
gameforge.subquest_10._130_makequestbutton = "Calinan Toka. "
gameforge.subquest_10._140_sayReward = "Silah Saticisi'na Toka hakkinda bir sey duyup[ENTER]duymadigini sor. "
gameforge.subquest_10._150_say = "Ne? Satici'nin Tokasini benim caldigimi mi saniyorsun?[ENTER]Hayir, asla. Bunu yapmadim! Gercekten![ENTER][ENTER]Satici'yi ziyaret etmek icin oradaydim! Ama kendisi[ENTER]yoktu, yerine bir Yeminli Okcu ile karsilastim.[ENTER]Beni gordugu an kacti.[ENTER]Belki calinan Sac Tokasi ondadir? "
gameforge.subquest_10._160_sayReward = "Sac Tokasini Yeminli Okcudan geri al! "
gameforge.subquest_10._170_sendLetter = "Sac Tokasini Buldun "
gameforge.subquest_10._180_targetVid = "Satici'ya git. "
gameforge.subquest_10._190_npcChat = "Sac Tokan bende. "
gameforge.subquest_10._200_say = "Oh, cok tesekkur ederim. Cok mutluyum, sonunda[ENTER]sevgili Tokama kavustum! Son zamanlarda bana cok sik[ENTER]yardim ediyorsun. Hakkini nasil oderim? Bir Binicilik[ENTER]Biletim var. Kucuk bir sey ama artik eskisi kadar[ENTER]sik dukkandan ayrilmayacagim icin ona ihtiyacim[ENTER]kalmadi. Bunu minnettarligimin bir kaniti olarak al.[ENTER]Tesekkur ederim. "
gameforge.subquest_10._20_say = "Lutfen beni dinle... cok kotu durumdayim.[ENTER]Onemli bir is icin dukkandan bir anligina ayrildim.[ENTER]Yoklugum sirasinda biri Tokami caldi. "
gameforge.subquest_10._210_sayReward = "60.000 Deneyim Puani kazandin.[ENTER]10.000 Yang kazandin.[ENTER]Binicilik Bileti kazandin. "
gameforge.subquest_10._220_say = "Tokayi henuz bulamadin mi?[ENTER]Umarim gunun birinde bulursun. "
gameforge.subquest_10._230_select = "Vazgec "
gameforge.subquest_10._240_say = "Gercekten vazgecmek istiyor musun? "
gameforge.subquest_10._250_say = "Dogru, inatci rakiplerdir... Dinlenip daha sonra[ENTER]tekrar denemek ister misin? "
gameforge.subquest_10._260_say = "En sevdigim sac tokam nerede acaba?[ENTER]Bana yardim etmeyeceksin sanirim... Hosca kal. "
gameforge.subquest_10._270_say = "Sana cok tesekkur ederim. O benim icin cok sey[ENTER]ifade ediyor. "
gameforge.subquest_10._30_say = "Babam o harika Tokayi dogum gunumde vermisti ve[ENTER]onu cok seviyorum. Artik dukkanimi terk edemem,[ENTER]yoksa daha degerli bir seyler kaybolabilir... Benim[ENTER]icin onu arayabilir misin? Demirci'den supheleniyorum[ENTER]cunku bir keresinde oyle bir toka aradigini[ENTER]soylemisti. "
gameforge.subquest_10._40_select = "Onu arayacagim. "
gameforge.subquest_10._50_say = "Gercekten vazgecmek istiyor musun? "
gameforge.subquest_10._60_say = "Daha sonra gorusmek uzere. Iyi eglenceler! "
gameforge.subquest_10._70_say = "Tokam nerede? Hosca kal... "
gameforge.subquest_10._80_say = "Arayacak misin? Oh, bu harika! "
gameforge.subquest_10._90_targetVid = "Demirci'ye git. "
gameforge.subquest_11 = {}
gameforge.subquest_11._100_targetVid = "Muzisyen Yu-Hwan'a Mirine'nin kardesini sor. "
gameforge.subquest_11._10_targetVid = "Kardesimi bul "
gameforge.subquest_11._110_npcChat = "Mirine'nin kardesini gordun mu? "
gameforge.subquest_11._120_say = "Sevginin ayrilik anlamina geldigini bilmeden asik[ENTER]oldum... Kimi ariyorsun? Mirine'nin kardesini mi?[ENTER]Nadir bitkiler aramak icin Daglara gitmeden once[ENTER]biraz konustuk... Su an nerede oldugunu bilmiyorum.[ENTER]Bu koyun avcisi sik sik Daglara cikar. Neden ona[ENTER]sormuyorsun?[ENTER]La, la, la, ask huzunlu ama cok guzeldir... "
gameforge.subquest_11._130_targetVid = "Yang-Shin'e Mirine'nin kardesini sor. "
gameforge.subquest_11._140_say = "Kim? Mirine'nin kardesi mi? Daglarda nadir bitkiler[ENTER]ariyordu. Gercekten essiz birkac ornek buldugu icin[ENTER]cok mutluydu. Satilan bitkilerden elde ettigi Yang[ENTER]ile kiz kardesine yeni giysiler almak istiyordu.[ENTER]Cok ince biridir. Birkac gune kalmaz doner, sence[ENTER]de oyle degil mi? "
gameforge.subquest_11._150_targetVid = "Mirine'ye haberleri ilet. "
gameforge.subquest_11._160_npcChat = "Mirine'nin Kardesi Hakkinda Haberler. "
gameforge.subquest_11._170_say = "Oh! Kardesimden bir mektup aldim! Cok fazla bitkinin[ENTER]yetistigi bir yer buldugunu, bu yuzden donmesinin[ENTER]biraz zaman alacagini yaziyor. Ozur dilerim, senden[ENTER]bunu istememeliydim. Fazla bir sey degil ama lutfen[ENTER]bunu kabul et ve beni bagisla. Geldigin icin[ENTER]tesekkurler! "
gameforge.subquest_11._180_sayReward = "122.000 Deneyim Puani kazandin.[ENTER]5.000 Yang kazandin. "
gameforge.subquest_11._20_npcChat = "Kardesimi bul "
gameforge.subquest_11._30_say = "Senden bir iyilik isteyebilir miyim? Kardesim[ENTER]evden cok uzun suredir uzakta ve ondan hicbir haber[ENTER]alamiyorum. Endiselenmeye basladim. Vaktin olursa[ENTER]onu arayabilir misin? "
gameforge.subquest_11._40_say = "Kardesim komsu koydeki muzisyen Yu-Hwan'i ziyaret[ENTER]etmek istiyordu. Yanina gidersen kardesim hakkinda[ENTER]kesinlikle bilgin olacaktir. Simdiden tesekkurler. "
gameforge.subquest_11._50_select = "Evet, yaparim. "
gameforge.subquest_11._60_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_11._70_say = "Tesekkur ederim.[ENTER]Lutfen onu ara.[ENTER]Cok endiseliyim.[ENTER]Gorusmek uzere... "
gameforge.subquest_11._80_say = "Bana yardim etmemen ne yazik...[ENTER]Gorusmek uzere. "
gameforge.subquest_11._90_say = "Onu arayacak misin?[ENTER]Cok tesekkurler! Onun icin cok endiseleniyorum.[ENTER]Iyi sanslar! "
