gameforge.subquest_12._170_npcChat = "Mi-Jung'u oldurdum. "
gameforge.subquest_12._180_say = "Oh! Gercekten de duydugum kadar iyisin.[ENTER]Sasirtici derecede yeteneklisin. Sayende Yeminli[ENTER]Klani ile olan sorunlarin cozumu cok daha kolaylasti.[ENTER]Iyi is! "
gameforge.subquest_12._190_sayReward = "122.000 Deneyim Puani kazandin.[ENTER]20.000 Yang kazandin.[ENTER]Gumus Bilezik kazandin. "
gameforge.subquest_12._20_say = "Bir saniye buraya gel. Sen iyi bir savascisin.[ENTER]Yuzbasi'dan senin hakkinda cok sey duydum. "
gameforge.subquest_12._30_say = "Bize bunca sorun cikaran Beyaz Yeminliler[ENTER]Klani'ndan Mi-Jung'un pesine dusebilir misin?[ENTER]Koyu ve sakinlerini Beyaz Yeminlilerin[ENTER]saldirilarindan korumak cok zor. Liderlerinden[ENTER]biri olan Mi-Jung'u oldurursek durum degisir.[ENTER]Koyun guvenligi senin ellerinde. Sana guveniyorum. "
