gameforge.subquest_13._100_targetVid = "Ariyoung'a git "
gameforge.subquest_13._10_targetVid = "Silah Yapim Malzemeleri. "
gameforge.subquest_13._110_targetVid = "Ah-Yu'ya git. "
gameforge.subquest_13._120_sayReward = "Silah Saticisi'nin yardimina ihtiyaci var. Onun[ENTER]icin Uriel'den Demir Cevheri ve Ariyoung'dan Kumas[ENTER]elde et. "
gameforge.subquest_13._130_npcChat = "Silah icin Demir Cevheri "
gameforge.subquest_13._140_say = "Demir Cevherine mi ihtiyacin var?[ENTER]Bir iyilik karsiliginda sana verebilirim. "
gameforge.subquest_13._150_say = "Kaplanlar cantami caldi.[ENTER]Kacarak canimi kurtarmak zorunda kaldim ancak[ENTER]cantada benim icin onemli bilgiler var.[ENTER]Onlari geri alamazsam Metin Taslarini arastirmaya[ENTER]devam edemem. Paketimi bana getir, karsiliginda[ENTER]sana biraz Demir Cevheri vereyim. "
gameforge.subquest_13._160_npcChat = "Paketin bende. "
gameforge.subquest_13._170_say = "Tesekkurler![ENTER]Senden cok sik iyilik istiyorum.[ENTER]Al lutfen, iste biraz Demir Cevheri.[ENTER]Umarim isine yarar. "
gameforge.subquest_13._180_say = "Ne? Daha fazla mi Demir Cevherine ihtiyacin var?[ENTER]Agacta yetismedigini biliyorsun degil mi?![ENTER]Sana biraz Demir Cevheri veririm ama bana ufak bir[ENTER]iyilik yapmalisin.[ENTER]Kaplanlar paketimi caldi.[ENTER]Kacarak canimi kurtarmak zorunda kaldim ve o pakette[ENTER]benim icin onemli belgeler var.[ENTER]Onlar olmadan Metin Taslari arastirmalarina devam[ENTER]edemem. Lutfen Kaplanlarin caldigi paketi geri al. "
gameforge.subquest_13._190_say = "Sana onu zaten vermistim![ENTER]Bunu unuttun mu?! "
gameforge.subquest_13._200_sayTitle = "Paket Bulundu "
gameforge.subquest_13._20_npcChat = "Silah malzemeleri "
gameforge.subquest_13._210_say = "Uriel'in Paketini buldun![ENTER]Ona geri don. "
gameforge.subquest_13._220_npcChat = "Biraz Kumasa ihtiyacim var. "
gameforge.subquest_13._230_say = "Kumasa mi ihtiyacin var? Onu Ah-Yu'ya verdim.[ENTER]Ama bir saniye bekle![ENTER]Madem onunla goruseceksin, lutfen su mektubu ona[ENTER]ilet. O benim iyi bir arkadasimdir ve cok uzun[ENTER]zamandir gorusemedik. Bu mektubu ona ulastir ve[ENTER]Kumasimi almani rica ettigimi soyle.[ENTER]Ona benden kesinlikle cok selam soyle. "
gameforge.subquest_13._240_say = "Ariyoung:[ENTER]Ah-Yu'dan Kumasi coktan aldin. "
gameforge.subquest_13._250_npcChat = "Ariyoung'un Mektubu "
gameforge.subquest_13._260_say = "Ariyoung'dan mektup mu? Ne kadar da ince bir[ENTER]davranis. Eskiden sohbet etmek icin sik sik[ENTER]bulusurduk ama son zamanlarda bu zorlasti. Lutfen[ENTER]bir saniye bekle. Demek sana Kumasi vermemi istiyor?[ENTER]Sorun degil. Mektubu getirdigin icin tekrar tesekkurler.[ENTER]Ben de hemen bir cevap yazmaya koyulayim... "
gameforge.subquest_13._270_qSetTitle = "Silah Saticisi'na Git "
gameforge.subquest_13._280_targetVid = "Silah Saticisi'na git. "
gameforge.subquest_13._290_sayTitle = "Malzemeleri Teslim Et "
gameforge.subquest_13._300_sayReward = "Butun malzemelerim tam![ENTER]Silah Saticisi'na git. "
gameforge.subquest_13._30_say = "Hey sen! Bana biraz yardim edebilir misin?[ENTER]Yeni silah turleri yaratmaya calisiyorum.[ENTER]Uygun malzemeleri bulmak cok zor. Cok fazla[ENTER]siparisim var ve onlari kendim arayamam.[ENTER]Onlari benim icin toplayabilir misin? Lutfen... "
gameforge.subquest_13._310_say = "Iyi is. Gercekten cok iyi ve hizlisin.[ENTER]Simdi bu silah uzerinde calismama izin ver![ENTER]*Cekic darbeleri*[ENTER]Iste yeni silah.[ENTER]Elimden gelenin en iyisini yaptim, umarim yeni[ENTER]silahi begenirsin. Iyi eglenceler! "
gameforge.subquest_13._320_sayTitle = "Odul: "
gameforge.subquest_13._330_sayReward = "122.000 Deneyim Puani kazandin.[ENTER]20.000 Yang kazandin. "
gameforge.subquest_13._340_sayReward = "Genis Kilic+3 kazandin. "
gameforge.subquest_13._350_sayReward = "Makas Hancer+3 kazandin. "
gameforge.subquest_13._360_sayReward = "Tavuskusu Yelpaze+3 kazandin. "
gameforge.subquest_13._40_say = "Elbette bunun icin seni odullendirecegim.[ENTER]Silah biter bitmez sana bir tane verecegim.[ENTER]Su malzemelere ihtiyacim var: Demir Cevheri ve[ENTER]Kumas. Ilkini Uriel'den, Kumasi ise Ariyoung'dan[ENTER]alabilirsin. Hepsini topladiginda bana haber ver. "
gameforge.subquest_13._50_say = "Bana gercekten yardim edemez misin? "
gameforge.subquest_13._60_say = "Gorunuse gore bu gorev seni asti.[ENTER]Daha fazla vaktin oldugunda gel! "
gameforge.subquest_13._70_say = "Bana yardim etmek istemiyorsan yapabilecegimiz[ENTER]bir sey yok. Gorusmek uzere. "
gameforge.subquest_13._80_say = "Cok guzel![ENTER]Silah tamamlanir tamamlanmaz bir tanesini alacaksin.[ENTER]Iyi sanslar. "
gameforge.subquest_13._90_sendLetter = "Malzeme Arayisi "
gameforge.subquest_15 = {}
gameforge.subquest_15._100_targetVid = "Sehir Bekcisi'ne Don "
gameforge.subquest_15._10_targetVid = "Yeminliler Klani'ndan Eun-Jung "
gameforge.subquest_15._110_sayReward = "Yeminliler Klani'ndan Eun-Jung'u oldurdun. Koy[ENTER]Koruyucusu'na git ve durumu bildir. "
gameforge.subquest_15._120_say = "Sen en iyisisin! Bekledigimden de iyi is cikardin.[ENTER]Sen olmasaydin bunun ustesinden gelemezdik.[ENTER]Yeminliler Klani'nin iki liderini bu kadar kolay[ENTER]yendin ya! Inanilmaz bir sey bu. "
gameforge.subquest_15._130_say = "Bu inanilmaz. Layik oldugun odulu alacaksin.[ENTER]Lutfen bunu al, umarim Kralligimiz icin calismaya[ENTER]devam edersin! "
gameforge.subquest_15._20_say = "Bir saniyeligine buraya gel.[ENTER]Yuzbasi'dan senin hakkinda pek cok guzel sey duydum.[ENTER]Korkusuz birine benziyorsun. Tam da bu yuzden[ENTER]yardimina ihtiyacim var: Yeminliler Klani[ENTER]eskisinden bile daha beter davraniyor. "
gameforge.subquest_15._30_say = "Yeminlilerin lideri Mi-Jung'u yendin.[ENTER]Ancak h�l� tehlikedeyiz! Beyaz Yeminliler Klani'ndan[ENTER]gelen tehdit azalmadi, simdi durum daha da kotu! "
gameforge.subquest_15._40_say = "Buna son vermek icin asil bas komutanlari Eun-Jung'u[ENTER]oldurmeliyiz. Gerisi sorun cikarmayacaktir. Git ve[ENTER]Eun-Jung'u oldur! Kaderimiz senin ellerinde! "
gameforge.subquest_15._50_sayTitle = "Muhafiz: "
gameforge.subquest_15._60_say = "Daha sonra donecek misin? Bu gorev icin tam[ENTER]bicilmis kaftansin. "
gameforge.subquest_15._70_say = "Bunu yapamaz misin? Pekala, kendine iyi bak. "
gameforge.subquest_15._80_say = "Bize yardim edecegini biliyordum![ENTER]Eun-Jung'u oldur, gerisini biz hallederiz.[ENTER]Iyi sanslar! "
gameforge.subquest_15._90_sayReward = "Lider Eun-Jung'u oldur. O zaman Yeminliler bu[ENTER]kadar sorun cikaramayacaktir. "
gameforge.subquest_16 = {}
gameforge.subquest_16._100_qSetTitle = "Yu-Hwan'a Sor "
gameforge.subquest_16._10_targetVid = "Zirhli Suvari Arayisi "
gameforge.subquest_16._110_targetVid = "Yu-Hwan'a git "
gameforge.subquest_16._120_say = "Hayat ne kadar da guzel... Ah ask, o harika ask...![ENTER]Yine mi sen? Bu sefer ne istiyorsun?[ENTER]Zirhli Suvariler hakkinda bilgi mi?[ENTER]Neden bunu soruyorsun?[ENTER]Yuzbasi'nin iddiali planlari var herhalde? "
gameforge.subquest_16._130_sayTitle = "Yu-Hwan: "
gameforge.subquest_16._140_say = "O zamanlardan gunumuze cok az ozgun metin kalmistir[ENTER]ama Zirhli Suvariler hakkinda birkac sarki bilirim.[ENTER]Bir saniye, enstrumanimi akort edeyim...[ENTER]Ah, acelen mi var? Gunumuzde insanlarin dinlemeye[ENTER]tahammulu kalmamis...[ENTER]Pekala, ozet geceyim. Isups'un Suvarileri neredeyse[ENTER]yenilmezdi. Kusursuz egitimli askerler, agir metal[ENTER]zirhlar ve buna ragmen hizli ve ceviklerdi. "
gameforge.subquest_16._150_say = "Bu, kitada simdiye kadar yurumus en muazzam[ENTER]ordu idi. Pek cok ulke boyun egmek zorunda kaldi,[ENTER]cunku hicbir sey bu suvarileri durduramiyordu.[ENTER]Bugun de farkli olmazdi. Ancak boyle bir orduyu[ENTER]kurmak icin agir bir egitim ve en yuksek kalitede[ENTER]bol miktarda metal sarttir. Seyyar Satici'ya ve[ENTER]Bilgin Uriel'e sormalisin. Kesinlikle daha fazla[ENTER]ayrinti biliyorlardir. "
gameforge.subquest_16._160_makequestbutton = "Seyyar Satici'ya "
gameforge.subquest_16._170_qSetTitle = "Zirhli Suvari. "
gameforge.subquest_16._180_targetVid = "Seyyar Satici: "
gameforge.subquest_16._190_sayReward = "Muzisyen Yu-Hwan, Seyyar Satici ve Bilge Uriel'in[ENTER]Zirhli Suvariler hakkinda bilgi sahibi olabilecegini[ENTER]soyluyor. Once Seyyar Satici'ya git. "
gameforge.subquest_16._200_sayTitle = "Seyyar Satici: "
gameforge.subquest_16._20_npcChat = "Zirhli Suvari. "
gameforge.subquest_16._210_say = "Benim gibi gariban bir Seyyar Satici'dan ne[ENTER]istiyorsun? Zirhli Suvarilerin Demir Zirhlari mi?[ENTER]Bunlar eski masallar. Bugun kimi ilgilendirir ki[ENTER]bu? Hayatimi kazanmam gerek ve butun gun dedikodu[ENTER]yapacak vaktim yok! "
gameforge.subquest_16._220_say = "Iki yakayi bir araya getirmek giderek zorlasiyor.[ENTER]O taslar gokten dusmeye basladigindan beri... Ne[ENTER]demistin? Ha evet, Suvariler.[ENTER]Bildigim kadariyla uretimi olaganustu beceriler[ENTER]gerektiren ozel zirhlar giyerlerdi. Bunlar tum[ENTER]zamanlarin en iyi zirhlaridir! Siradan bicaklar,[ENTER]hatta oklar bile uzerlerinden sekip giderdi! "
gameforge.subquest_16._230_say = "Zirhli Suvarilerin zirhlarinin ozel bir sey[ENTER]oldugu, bu Suvarileri kurmak icin gereken para[ENTER]miktarindan bile anlasilabilir. Butun kralliklarin[ENTER]hazinelerini tukettigi soylenir! Boyle zirhlar[ENTER]satiyor olsaydim bir daha asla para icin endiselenmem[ENTER]gerekmezdi! "
gameforge.subquest_16._240_say = "Gunumuzde Metin Taslarindan bile zirh dovulebiliyor.[ENTER]Bu yeni zirh teknigi sayesinde ikinci bir Zirhli[ENTER]Suvari Birligi kurmak hic de imkansiz gorunmuyor![ENTER]Ama cok konustum. Gitmem gerek artik. Hosca kal! "
gameforge.subquest_16._250_sayTitle = "Zirhli Suvari. "
gameforge.subquest_16._260_say = "Seyyar Satici, Zirhli Suvarilerin metal zirhlari[ENTER]hakkinda bir seyler biliyordu. Simdi komsu koydeki[ENTER]Bilge Uriel'e git ve ona egitim surecini sor. "
gameforge.subquest_16._270_sayTitle = "Uriel: "
gameforge.subquest_16._280_say = "Bu sefer gelisinin sebebi nedir? Zirhli Suvariler[ENTER]mi? Elbette onlar hakkinda bilgim var, herkesin[ENTER]vardir. Bu ordu sonsuza kadar tarihin en iyisi[ENTER]olarak anilacaktir![ENTER]Insanlarin anlattiklarinin cogu muhtemelen abartidir[ENTER]ama bu suvariler gercekten inanilmaz bir dehset[ENTER]saciyordu. Ve bu sebepsiz degildi. "
gameforge.subquest_16._290_say = "Zirhli Suvariler diger tum ordulardan ustundu.[ENTER]Bu her seyden once insanustu derecede agir[ENTER]egitimlerinin eseriydi. Sadece en iyiler egitimi[ENTER]tamamlayabilirdi, pek cogu denerken can verdi.[ENTER]Ayni egitim yontemlerini cagimizda uygulayacak[ENTER]olsaydik tek bir askerin bile hayatta kalamayacagini[ENTER]tahmin ediyorum. "
gameforge.subquest_16._300_say = "Egitim yontemlerinden bazilari korunmustur.[ENTER]Etkilerini bizzat gorebilmen icin sana birkac ipucu[ENTER]verecegim.[ENTER]Korkunc savaslarin surdugunu biliyorum ama boylesine[ENTER]guclu bir orduyu yeniden kurmanin iyi bir fikir olup[ENTER]olmadigindan emin degilim. "
gameforge.subquest_16._30_say = "Senin icin yeni bir gorevim var. Zirhli Suvariler[ENTER]hakkinda bilgi toplama emri aldin. Vaktiyle butun[ENTER]kitayi birlestiren kurucu Kral Isup'un ordusunun en[ENTER]onemli parcasiydi. Zirhli Suvariler olaganustu[ENTER]hizlari ve saldiri gucleri nedeniyle diger uluslar[ENTER]icin bir kabustu. "
gameforge.subquest_16._310_say = "Yuzbasi'ya git ve Zirhli Suvariler hakkinda[ENTER]ogrendigin her seyi ona anlat. "
gameforge.subquest_16._320_makequestbutton = "Yuzbasi'ya Git. "
gameforge.subquest_16._330_npcChat = "Zirhli Suvariler Raporu. "
gameforge.subquest_16._340_sayTitle = "Yuzbasi "
gameforge.subquest_16._350_say = "Faydali bilgiler edinebildin mi? Anlat bakalim![ENTER]...[ENTER]Hm, bu cok ilginc. Sadece guclu zirhlar ve siki[ENTER]bir egitim gerekiyor, baska bir sey degil mi?[ENTER]O halde bu yapilabilir! Boyle bir ordu uc kralligi[ENTER]yeniden birlestirebilir! "
gameforge.subquest_16._360_say = "Ancak cok fazla paraya, cok sayida yetenekli[ENTER]demirciye ve en iyinin de iyisi olmak icin cehennemden[ENTER]gecmeye gonullu acemilere ihtiyacim olacak![ENTER]Yok yok, bana oyle bakma. Endiselenme, simdilik[ENTER]yeterince sey yaptin. "
gameforge.subquest_16._370_say = "Lutfen bu odulu al ve dinlen.[ENTER]Daha sonra gorusuruz! "
gameforge.subquest_16._40_say = "Topladigin bilgiler sayesinde birliklerimizin vurus[ENTER]gucunu artirabiliriz. Once muzisyen Yu-Hwan'i[ENTER]ziyaret et. Zirhli Suvariler hakkinda kesinlikle[ENTER]bazi bilgilere sahip oldugundan eminim. "
gameforge.subquest_16._50_say = "Hm, nasil istersen. O halde gorusmek uzere! "
gameforge.subquest_16._60_say = "Gunun birinde boyle bir suvari birligine komuta[ENTER]edebilecek miyim acaba? Kendine dikkat et. "
gameforge.subquest_16._70_say = "Tesekkur ederim. Kendine iyi bak. "
gameforge.subquest_16._80_sayTitle = "Zirhli Suvari. "
gameforge.subquest_16._90_sayReward = "Yuzbasi, kurucu kral Isup'un efsanevi suvarileri[ENTER]hakkinda bilgi ariyor. Muzisyen Yu-Hwan bu konuda bir[ENTER]seyler biliyor olmali. Git ve ona sor. "
gameforge.subquest_17 = {}
gameforge.subquest_17._100_targetVid = "Satici ile Konus. "
gameforge.subquest_17._10_targetVid = "Ariyoung'un Kocasinin Hikayesi "
gameforge.subquest_17._110_say = "Satici'ya git ve Ariyoung'un kocasini sor. "
gameforge.subquest_17._120_npcChat = "Ariyoung'un Kocasi "
gameforge.subquest_17._130_say = "Bu cok uzucu bir hikaye. Kocasina ne oldugunu henuz[ENTER]bilmiyor mu? Hic kimsenin geri donemedigi bir yerde[ENTER]o artik...[ENTER]Mallarla koye donerken Siyah Ruzgar Cetesi tarafindan[ENTER]yakalandi ve katledildi. "
gameforge.subquest_17._140_say = "Bunu ogrendiginde cok kahrolacagindan korkuyorum.[ENTER]Birbirlerini oyle cok severlerdi ki...[ENTER]Yine de bunu bilmeli, aksi takdirde bu belirsizlik[ENTER]onu bitirecek. "
gameforge.subquest_17._150_targetVid = "Aci Haber "
gameforge.subquest_17._160_sayTitle = "Ariyoung: "
gameforge.subquest_17._170_say = "Satici'nin kotu bir haberi var. Ariyoung'a git ve[ENTER]kocasinin olum haberini ona ilet. "
gameforge.subquest_17._180_npcChat = "Kocan hayatta degil... "
gameforge.subquest_17._190_say = "Ne... ne diyorsun sen?! Siyah Ruzgar Cetesi'nden[ENTER]biri tarafindan mi oldurulmus? Olamaz... oldu ha...[ENTER]Onsuz ben ne yapacagimi bilemiyorum! "
gameforge.subquest_17._200_say = "Bana kocamin cesedini getirebilir misin? Lutfen,[ENTER]en azindan onunla vedalasabilirdim. Eger bu mumkun[ENTER]degilse esyalarindan herhangi biri de yeter.[ENTER]Kocama ait bulabilecegin her sey. Siyah Ruzgar[ENTER]Cetesi'nden Goo-Pae'de kesinlikle ona ait bir seyler[ENTER]vardir. Lutfen bana bir sey getir. "
gameforge.subquest_17._20_say = "Kocamdan bir haber almayali cok uzun zaman oldu.[ENTER]Onun icin endiseleniyorum, umarim basina kotu bir[ENTER]sey gelmemistir.[ENTER][ENTER]Endiselenmenin iyi bir fikir olmadigini biliyorum[ENTER]ama yuregim bu aciya zor dayaniyor. Bir turlu[ENTER]sakinlesemiyorum. "
gameforge.subquest_17._210_select = "Evet, sana yardim edecegim. "
gameforge.subquest_17._220_say = "Bunu dusundugunde yanima don. Lutfen... "
gameforge.subquest_17._230_say = "Hicbir sey bulamadin mi? Yine de tesekkurler...[ENTER]Ah, o kadar uzgunum ki! "
gameforge.subquest_17._240_say = "Sana ne kadar minnettar oldugumu bilemezsin.[ENTER]Senin icin dua edecegim. "
gameforge.subquest_17._250_sendLetter = "Goo-Pae'yi Oldur "
gameforge.subquest_17._260_say = "Siyah Ruzgar Cetesi Ariyoung'un kocasini oldurdu[ENTER]ve soydu. Ariyoung'un kocasindan bir hatira elde[ENTER]edene kadar Goo-Pae'yi oldur. "
gameforge.subquest_17._270_npcChat = "Kocan yuzunden... "
gameforge.subquest_17._280_say = "Nasil gitti? Kocamdan bir hatira bulmayi basardin[ENTER]mi? O benim her seyimdi. Ne durumdayiz? "
gameforge.subquest_17._290_select = "Henuz degil. Aramaya devam ediyorum! "
gameforge.subquest_17._300_say = "Siyah Ruzgar Cetesi'nden Goo-Pae cetindir.[ENTER]Biraz dinlen. Yardimin icin tesekkur ederim. "
gameforge.subquest_17._30_say = "Umarim Satici kocam hakkinda bir seyler duymustur.[ENTER]Bir seyler bilebilecek cok sayida musterisi var. "
gameforge.subquest_17._310_say = "Bana yardim edecek baska bir kahramani beklemem[ENTER]gerekecek.[ENTER]Hosca kal. "
gameforge.subquest_17._320_say = "Ah, cok naziksin. Lutfen bana kocama ait olan[ENTER]bir sey getir. "
gameforge.subquest_17._330_sendLetter = "Ariyoung'un Yuzugu "
gameforge.subquest_17._340_targetVid = "Ariyoung'a Git "
gameforge.subquest_17._350_sayTitle = "Ariyoung'a Git "
gameforge.subquest_17._360_say = "Oldurulen Goo-Pae'lerden birinin uzerinde Ariyoung'un[ENTER]kocasinin Alyansini buldun. Bu onun kocasi icin[ENTER]harika bir hatira. Alyansi Ariyoung'a teslim et. "
gameforge.subquest_17._370_npcChat = "Bu Yuzugu buldum. "
gameforge.subquest_17._380_say = "Bu... bu yuzuk... benim Alyansim! Artik kocam[ENTER]huzur icinde yatabilir... Bu Yuzugu benden gelen[ENTER]mektupla birlikte saklayacagim. Artik hayatimi[ENTER]tek basima surdurecegim. En azindan Alyansima[ENTER]kavustum. Bu guzel bir his. Sana cok minnettarim. "
gameforge.subquest_17._390_sendLetter = "Gorev tamamlandi! "
gameforge.subquest_17._400_say = "Ariyoung'a yardim ettigin haberi yayiliyor.[ENTER]Bircok kisi yardimini ovguyle karsiliyor. "
gameforge.subquest_17._40_select = "Satici'ya gidecegim. "
gameforge.subquest_17._410_sayReward = "300.000 Deneyim Puani kazandin. "
gameforge.subquest_17._420_sayReward = "10.000 Yang kazandin. "
gameforge.subquest_17._50_select = "Hayir, buna vaktim yok. "
gameforge.subquest_17._60_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_17._70_say = "Bunu dusundugunde yanima don. Lutfen... "
gameforge.subquest_17._80_say = "Bu kadar kolay bir gorevi yapmaya vaktin yok mu?[ENTER]Pekala, bu durumda... "
gameforge.subquest_17._90_say = "Iyiligin icin tesekkur ederim. Tanrim, kocam[ENTER]nerede acaba... "
gameforge.subquest_18 = {}
gameforge.subquest_18._100_say = "Pacavralar giymis ve siirler okuyan bir adam ara.[ENTER]Yanina git. "
gameforge.subquest_18._10_targetVid = "Nerede saklaniyor? "
gameforge.subquest_18._110_npcChat = "Kocan nerede? "
gameforge.subquest_18._120_say = "Nereye saklandigini bilmiyorum. Artik bunu o kadar[ENTER]iyi yapiyor ki onu bulmak cok zor. Belki de Satici'nin[ENTER]tavsiye ettigi gibi boynuna gercekten bir cingirak[ENTER]takmaliydim. "
gameforge.subquest_18._130_npcChat = "Soon'u Bul! "
gameforge.subquest_18._140_say = "Guzel bir siir duyuyorsun. Sozlerden etkilenerek[ENTER]sesin pesinden gidiyorsun ve sonunda yirtik pirtik[ENTER]giysiler icinde bir adamin onunde duruyorsun.[ENTER][ENTER]Bu Aranyo'nun kocasi olmali![ENTER][ENTER]Tam Aranyo'ya donmek icin arkana donecekken adam[ENTER]seni omzundan yakaliyor. "
gameforge.subquest_18._150_say = "Burali degilsin. Seni karim mi gonderdi?[ENTER][ENTER]Olamaz! Kim oldugumu anladi! Ona ne cevap vermeli? "
gameforge.subquest_18._153_select = "Heh, tesadufen buradayim... "
gameforge.subquest_18._157_select = "Pekala... "
gameforge.subquest_18._160_say = "Ohom, tanistigimiza memnun oldum. Hava ne guzel,[ENTER]degil mi? Son zamanlarda hic guzel bir kitap okudun[ENTER]mu? Ben su anda Oja'nin yazdigi bir kitabi[ENTER]okuyorum. Kesinlikle okumalisin. "
gameforge.subquest_18._170_say = "Hakliyim, degil mi? Karim bana oyle cok dirdir[ENTER]ediyor ki evde huzur icinde okuyamiyorum. Beni hic[ENTER]anlamiyor. Beni burada bulmus olabilirsin ama baska[ENTER]bir yere de gidebilirim. Ona hicbir sey soylememeye[ENTER]ne dersin? Karsiliginda sana avcilik hakkinda iyi[ENTER]bir tavsiye veririm. "
gameforge.subquest_18._180_sendLetter = "Aranyo'ya Don. "
gameforge.subquest_18._190_say = "Aranyo'ya don ve Soon'u bulamadigini soyle. "
gameforge.subquest_18._200_npcChat = "Soon'un Sirri. "
gameforge.subquest_18._20_sayTitle = "Aranyo: "
gameforge.subquest_18._210_say = "Onu bulamadin mi? Tuzaklar bile kurmustum.[ENTER]Nereye saklandi bu adam? O kadar mesgulum ki.[ENTER]Ne bahtsiz bir kader. "
gameforge.subquest_18._220_sendLetter = "Soon'a Donus "
gameforge.subquest_18._230_say = "Soon'a don ve basardigini ona ilet. "
gameforge.subquest_18._240_npcChat = "Iste geldim. "
gameforge.subquest_18._250_say = "Her sey planimiza gore gitti mi? Hayatimi kurtardin![ENTER]Al bunu, maceraci. Soz verdigim gibi odulunu[ENTER]veriyorum. "
gameforge.subquest_18._260_sayReward = "7.000 Deneyim Puani kazandin. "
gameforge.subquest_18._270_sayReward = "10.000 Yang kazandin. "
gameforge.subquest_18._280_say = "Aranyo'ya don ve Soon'un nerede oldugunu soyle. "
gameforge.subquest_18._290_npcChat = "Saklanmak zor is... "
gameforge.subquest_18._300_say = "Beni ele vermedigin icin tesekkurler.[ENTER]Karimdan saklanmak gercekten cok zor.[ENTER]Sadece burada ders calismak istiyorum... Huzur[ENTER]icinde... "
gameforge.subquest_18._30_say = "En buyuk aciyi bana kocam cektiriyor. Kendine bir[ENTER]de bilgin diyor! Biz her gun yiyecek bir seyler[ENTER]icin didinirken o sadece kitap okuyor. Onu hic[ENTER]gordun mu? Neden bir kitap kurduyla evlendim ki... "
gameforge.subquest_18._310_npcChat = "Soon nerede? "
gameforge.subquest_18._320_say = "Onu buldun mu? Cok, cok tesekkur ederim![ENTER]Fark edildigini anlarsa kacabilir. Hemen oraya[ENTER]gidiyorum. Bu sefer elimden kurtulamayacak![ENTER]Sen de minnettarligimin kaniti olarak bunu kabul[ENTER]et. Bekle sen beni, seni gidi kerata...! "
gameforge.subquest_18._33_select = "Sana yardim edecegim. "
gameforge.subquest_18._37_select = "Buna vaktim yok. "
gameforge.subquest_18._40_say = "Bu gorevden vazgecmek istiyor musun? "
gameforge.subquest_18._50_say = "Guzel... Belki daha sonra onu aramak icin biraz[ENTER]vakit bulursun... "
gameforge.subquest_18._60_say = "Belki onu bir sekilde kendim bulurum... "
gameforge.subquest_18._70_say = "Cok minnettar kalirim. Kotu bir yazar gorursen bana[ENTER]haber ver. Koyde tek olduguna eminim. Belki de yeni[ENTER]bir siir dusunuyor ve bu yuzden bir kosede tek[ENTER]basina oturuyordur. Onu aradigimi duyarsa kacabilir.[ENTER]Bu yuzden dikkatli ol. "
gameforge.subquest_18._80_sendLetter = "Soon'u Bul. "
gameforge.subquest_18._90_sayTitle = "Soon'u Bul! "
