gameforge.subquest_19._10_npcChat = "Gri Kurt Postu Bul. "
gameforge.subquest_19._110_sayTitle = "Kurt Postu Bul "
gameforge.subquest_19._120_sayReward = "Yasli Kadin'in evi temizleyebilmesi icin bir Kurt[ENTER]Postu temin et.[ENTER]Onu Gri Kurtlardan elde edebilirsin. "
gameforge.subquest_19._130_targetVid = "Yasli Kadin'a don. "
gameforge.subquest_19._140_npcChat = "Kurt Postunu Teslim Et "
gameforge.subquest_19._150_say = "Bu sey... Oh, hayir. Bu dogru Kurt Postu degil.[ENTER]Bir kez daha aramalisin. Lutfen bu sefer bana dogru[ENTER]Postu getir. "
gameforge.subquest_19._160_say = "Gercek bir Gri Kurt Postuna ihtiyacim var.[ENTER]Üzgunum ama bununla hicbir sey yapamam. "
gameforge.subquest_19._170_select = "Tekrar deneyecegim. "
gameforge.subquest_19._180_select = "Istemiyorum... "
gameforge.subquest_19._190_say = "Bu gorevden gercekten vazgecmek istiyor musun? "
gameforge.subquest_19._200_say = "Daha sonra ugra o halde. "
gameforge.subquest_19._20_say = "Evladim, bu oksuruk beni bitirecek. Evi[ENTER]tozlayabilecegim hicbir seyim yok... Bu yuzden tum[ENTER]toz iceride kaliyor. Neden bir toz bezim yok?[ENTER]Oglum bir silahi temizlemek icin onu ise goturdu.[ENTER]Kendi etim canim beni olduruyor resmen. "
gameforge.subquest_19._210_say = "Zor oldugunu biliyorum ama lutfen tekrar dene. "
gameforge.subquest_19._220_say = "Bununla ilgilenmek istedigin icin tesekkur ederim. "
gameforge.subquest_19._230_say = "Sen bir macera avcisisin! H�l� cok fena[ENTER]oksuruyorum. Duydugun gibi o feci oksuruk devam[ENTER]ediyor. Ev tozla dolu. Oh, bana bir Kurt Postu mu[ENTER]getirdin? Evet! Aradigim tam olarak bu![ENTER]Cok tesekkur ederim. Lutfen burada bir saniye bekle. "
gameforge.subquest_19._240_say = "Bir iki, bir iki. Adim adim...[ENTER]Pekala, geri geldim. Sayende sonunda evimi iyice[ENTER]temizleyebildim. Temizlik sirasinda sana hediye[ENTER]etmek istedigim bir sey buldum. Bir degeri var mi[ENTER]bilmiyorum ama belki isine yarar. Tekrar tesekkurler.[ENTER]Gorusmek uzere! "
gameforge.subquest_19._250_sendLetter = "Tozlu bir sey "
gameforge.subquest_19._260_say = "Odul olarak hurdaya benzeyen bir sey aldin.[ENTER]Merakina yenik dusup uzerindeki tozu siliyorsun. "
gameforge.subquest_19._270_say = "Bu eski ve degerli bir Zirh. Demirci'nin yaptigi[ENTER]en iyi zirhlardan biri. "
gameforge.subquest_19._280_say = "Eski ama h�l� kullanilabilir. Hic yoktan iyidir! "
gameforge.subquest_19._290_say = "Bu bir Zirh ama buyuk umutlarina ragmen tamamen[ENTER]kullanilamaz durumda. "
gameforge.subquest_19._300_sayReward = "15.000 Deneyim Puani kazandin. "
gameforge.subquest_19._30_select = "Sana yenisini verecegim. "
gameforge.subquest_19._40_say = "(oksurur)(oksurur) Her yer toz icinde...[ENTER]Toz almak icin bir seye ihtiyacim var.[ENTER]Bana yardim edebilir misin? "
gameforge.subquest_19._50_say = "Epey zaman gecti ama rahmetli kocamin, topragi bol[ENTER]olsun, Kurt Postundan bir toz alma fircasi yaptigini[ENTER]hatirliyorum. Yasli, gariban bir kadin icin boyle[ENTER]bir Post bulabilir misin? Onu Gri Kurtlardan elde[ENTER]edebilirsin.[ENTER]Bana cok buyuk bir yardimi dokunurdu. "
gameforge.subquest_19._60_say = "Gorevden gercekten vazgecmek istiyor musun? "
gameforge.subquest_19._70_say = "Uh, yazik... Bana yardim edecegini sanmistim.[ENTER]Belki bir kez daha dusunur ve bana geri donersin? "
gameforge.subquest_19._80_say = "Boyle yasli ve yoksul bir kadindan kim nasil bir[ENTER]odul bekleyebilir ki zaten? "
gameforge.subquest_19._90_say = "Kurt Postu bulmak o kadar kolay degil. Yine de[ENTER]deneyecegim. Sonucta bir gun buyuk bir kahraman[ENTER]olmak istiyorum! "
