gameforge.subquest_20._10_targetVid = "Ah-Yu'ya Yardim Et! "
gameforge.subquest_20._110_say = "Tamam, biraz bos vaktin oldugunda geri gel. "
gameforge.subquest_20._120_say = "Korkaksin sen. O Yabanileri gorunce zaten kacardin.[ENTER]Git buradan! "
gameforge.subquest_20._130_say = "Bana yardim etmek istedigin icin tesekkur ederim.[ENTER]Mesele uc Kargi. "
