gameforge.subquest_20._170_say = "Ah-Yu'nun kocasina ait uc Karginin hepsini buldun.[ENTER]Ona geri don. "
gameforge.subquest_20._180_sayTitle = "Kargilari Bul! "
gameforge.subquest_20._190_say = "Yabani Piyade, Yabani Usak, Yabani Okcu, Yabani[ENTER]General: Kargilari calanlar bunlar. Onlari geri[ENTER]almaya calis. "
gameforge.subquest_20._200_sayReward = "Üc Kargiyi bulup Ah-Yu'ya goturmelisin.[ENTER](Kargi Sayisi: %s) "
gameforge.subquest_20._20_npcChat = "Kocadan Kalan Hatira. "
gameforge.subquest_20._210_npcChat = "Kargilari nerede bulurum? "
gameforge.subquest_20._220_say = "Kocamin Kargilarinin Yabanilerde olmasi cok[ENTER]muhtemel. Kim bilir. Sadece onlari yok etmemis[ENTER]olmalarini umuyorum. Onlar cok iyi Kargilardi.[ENTER][ENTER]Aramaya devam edilsin mi? "
gameforge.subquest_20._230_select = "Evet, aramaya devam ediyorum. "
gameforge.subquest_20._240_say = "Sen bir korkaksin! Tamam, o zaman kendim yaparim.[ENTER][ENTER]Aramaktan gercekten vazgecmek istiyor musun? "
gameforge.subquest_20._250_select = "Evet. "
gameforge.subquest_20._260_say = "Kendim yapardim ama bebegime bakmak zorundayim.[ENTER]Tum Kargilari buldugunda geri gel! "
gameforge.subquest_20._270_say = "Ah-Yu'nun kocasinin Kargilarini aramaktan vazgectin. "
gameforge.subquest_20._280_say = "Cok tesekkur ederim. Kesinlikle yakinda onlari[ENTER]bulacaksin! "
gameforge.subquest_20._290_npcChat = "Kargilari Geri Al. "
gameforge.subquest_20._300_sayTitle = "Ah-Yu: "
gameforge.subquest_20._30_say = "Aman Tanrim. Aglama bebegim.[ENTER]Annenin de morali cok bozuk zaten.[ENTER]Surekli aglarsan her sey daha da kotulesecek.[ENTER]Lutfen aglamayi kes. "
gameforge.subquest_20._310_say = "Bana bir Kargi getirmis olman bile benim icin[ENTER]harika bir sey. Kalanlari da arayabilir misin?[ENTER]Onlar bir takim halinde olmali. Tesekkurler. "
gameforge.subquest_20._320_select = "Tekrar deneyecegim. "
gameforge.subquest_20._330_select = "Pes ediyorum. "
gameforge.subquest_20._340_say = "Ah-Yu'nun kocasinin Kargilarini aramaktan vazgectin. "
gameforge.subquest_20._350_say = "Vazgecmedigin icin tesekkur ederim! "
gameforge.subquest_20._360_say = "Oh, onlari geri aldin! Cok mutluyum, tesekkur[ENTER]ederim. Fazla Yang degil ama al lutfen. "
gameforge.subquest_20._370_sayReward = "300.000 Deneyim Puani kazandin.[ENTER]20.000 Yang kazandin. "
gameforge.subquest_20._40_say = "Bugun seni taniyamiyorum. Normalde her zaman cok[ENTER]neselisin! Bir sey mi oldu? "
gameforge.subquest_20._50_say = "Kocam her zaman cevresindeki herkesle ilgilenir ve[ENTER]basima kotu bir sey gelmemesini saglardi. Ama artik[ENTER]aramizda degil, savasta oldu. Ondan bana kalan tek[ENTER]sey bebegim ve Kargilari. "
gameforge.subquest_20._60_say = "Ben ise gittigimde birisi o Kargilari caldi.[ENTER]Komsular Yabanileri sucluyor. Kucuk bir bebegim[ENTER]oldugu icin onlari kendim arayamiyorum. "
gameforge.subquest_20._70_say = "O Kargilari benim icin geri alabilir misin?[ENTER]Onlari kesinlikle Yabanilerde bulacaksin. "
gameforge.subquest_20._80_select = "Tamam, arayacagim. "
gameforge.subquest_20._90_select = "Vaktim yok. "
gameforge.subquest_21 = {}
gameforge.subquest_21._100_say = "Sana tesekkur ederim dostum![ENTER]Umarim basarili olursun! "
gameforge.subquest_21._10_targetVid = "Balso? "
gameforge.subquest_21._110_sendLetter = "Balso Icin Ilac "
gameforge.subquest_21._120_targetVid = "Balso'ya git "
gameforge.subquest_21._130_sayReward = "Bilinmeyen bir hastaliga yakalanan Balso icin ilaci[ENTER]buldun. Bu ilaci Balso'ya teslim et. "
gameforge.subquest_21._140_sayTitle = "Ilaci Bul "
gameforge.subquest_21._150_say = "Uzun kacisi sirasinda Balso bilinmeyen bir hastaliga[ENTER]yakalandi. Sohan Dagi'ndaki Hastalikli Adam'dan[ENTER]Ilaci ele gecir. "
gameforge.subquest_21._160_npcChat = "Ilac bende! "
gameforge.subquest_21._170_say = "Oh, cok tesekkur ederim. Bir multeci hayati yasamak[ENTER]cok zor. Turlu turlu hastaliklara maruz kaliyorsun.[ENTER]Sayende artik iyilesebilirim. Sag ol! "
gameforge.subquest_21._180_sayTitle = "Odul: "
gameforge.subquest_21._190_sayReward = "1.900.000 Deneyim Puani kazandin.[ENTER]30.000 Yang kazandin. "
gameforge.subquest_21._20_npcChat = "O kadar cok kasiniyor ki... "
gameforge.subquest_21._30_sayTitle = "Hain Balso: "
gameforge.subquest_21._40_say = "Senden bir iyilik isteyebilir miyim? Bildigin gibi[ENTER]ben bir hainim ve hain olarak bu devirde yasamak[ENTER]cok zor. Eskiden refah icinde yasardim ama simdi[ENTER]tam tersi... O zamandan beri hep kaciyorum ve dinlenemiyorum.[ENTER]Üstelik pek cok hastalikla temas ediyorum. "
gameforge.subquest_21._50_say = "Birkac gun once Sohan Dagi bolgelerindeydim ve[ENTER]nasil olduysa bir Hastalikli Adam'a denk geldim.[ENTER]Neyse ki kacmayi basardim. Ancak simdi cildine[ENTER]temas etmemin bana korkunc bir hastalik bulastirdigini[ENTER]goruyorum. Bana yardim edip bir Ilac bulabilir[ENTER]misin? Yanlarinda kesinlikle vardir. Bunu yapmaktan[ENTER]hoslanmiyorum ama lutfen, bana yardim edebilir misin? "
gameforge.subquest_21._60_select = "Evet, sana yardim edecegim. "
gameforge.subquest_21._70_say = "Aramaktan vazgecmek istiyor musun? "
gameforge.subquest_21._80_say = "Bu hep basima geliyor. Her yerde benden nefret[ENTER]ediyorlar. Fikrini degistirirsen beni tekrar ziyaret[ENTER]et. "
gameforge.subquest_21._90_say = "Yikil karsimdan! Ve sakin buraya geri donme![ENTER]Hep ayni hikaye... "
gameforge.subquest_22 = {}
gameforge.subquest_22._100_say = "Sag ol. Sana guveniyorum! Baltayi bana cabucak[ENTER]geri getir. "
gameforge.subquest_22._10_targetVid = "Deokbae'nin Altin Baltasi "
gameforge.subquest_22._110_targetVid = "Deokbae'yi Ziyaret Et "
gameforge.subquest_22._120_sayTitle = "Altin Baltayi Buldun "
gameforge.subquest_22._130_say = "Altin Baltayi ele gecirdin. Onu Deokbae'ye teslim[ENTER]et. "
gameforge.subquest_22._140_sayTitle = "Altin Balta Arayisi. "
gameforge.subquest_22._150_say = "Deokbae'nin cok sevdigi Altin Baltasini Yabani[ENTER]Generallerden geri al. "
gameforge.subquest_22._160_npcChat = "Altin Baltani buldum! "
gameforge.subquest_22._170_sayTitle = "Deokbae: "
gameforge.subquest_22._180_say = "Yardimin olmasaydi bu Baltayi asla geri alamazdim.[ENTER]Cok tesekkurler. Gelecekte daha dikkatli olacagim[ENTER]ve onu her zaman yanimda tasiyacagim. "
gameforge.subquest_22._190_sayReward = "400.000 Deneyim Puani kazandin. "
gameforge.subquest_22._200_sayReward = "30.000 Yang kazandin. "
gameforge.subquest_22._20_npcChat = "Altin Baltan ile ilgili olarak... "
gameforge.subquest_22._30_sayTitle = "Deokbae: "
gameforge.subquest_22._40_say = "Olamaz, olamaz! Baltami kaybettim. Hangi baltadan[ENTER]bahsettigimi biliyor musun? Oh evet... Biliyor[ENTER]musun?[ENTER]Demirci'den aldigim Altin Balta bu. Yabaninin biri[ENTER]onu benden caldi! "
gameforge.subquest_22._50_say = "Demirci ogrenirse kuplere biner ve bir daha baltalarimi[ENTER]tamir etmez. Üstelik gercekten cok iyi bir Baltaydi.[ENTER]Onu benim icin geri alabilir misin? "
gameforge.subquest_22._60_select = "Reddet. "
gameforge.subquest_22._70_say = "Aramaktan vazgecmek istiyor musun? "
gameforge.subquest_22._80_say = "Oh, biraz vaktin oldugunda geri gel. "
gameforge.subquest_22._90_say = "Senin icin cok mu zor? O zaman benim elimden hic[ENTER]bir sey gelmez. Kendine dikkat et... "
gameforge.subquest_23 = {}
gameforge.subquest_23._100_sendLetter = "Yu-Hwan'i Ara "
gameforge.subquest_23._10_targetVid = "Mirine'nin Agabeyini Arayis! "
gameforge.subquest_23._110_targetVid = "Yu-Hwan'a git. "
gameforge.subquest_23._120_say = "Mirine'nin agabeyi yine ortadan kayboldu. Uzun[ENTER]suredir yasam belirtisi yok. Gecenlerde ona teslim[ENTER]ettigin mektup son temasti. Yu-Hwan'a git ve[ENTER]Mirine'nin agabeyini ara. "
gameforge.subquest_23._130_npcChat = "Mirine'nin kardesini gordun mu? "
gameforge.subquest_23._140_say = "Mirine'nin kardesi mi? Hayir, maalesef sana yardim[ENTER]edemem. Uzun suredir onunla irtibatim yok. Onu en[ENTER]son ne zaman gordugumu bile hatirlamiyorum sanirim.[ENTER]Ben de endiseleniyorum. Acaba bir sey mi oldu?[ENTER]Avci Yang-Shin'e sor. O cok gezer ve onunla[ENTER]karsilasmis olmasi muhtemeldir. "
gameforge.subquest_23._150_sendLetter = "Yang-Shin'i Ara "
gameforge.subquest_23._160_targetVid = "Avci Yang-Shin'e git. "
gameforge.subquest_23._170_say = "Avci Yang-Shin cok seyahat eder. Mirine'nin agabeyi[ENTER]ile bir yerlerde karsilasmis olabilir. "
gameforge.subquest_23._180_npcChat = "Mirine'nin kardesini gordun mu? "
gameforge.subquest_23._190_say = "Mirine'nin agabeyi mi? Onunla en son karsilastigimda,[ENTER]sifali bitkiler toplamak icin Seungryong Vadisi'ne[ENTER]gidiyordu. Sasirmistim cunku orasi cok tehlikeli[ENTER]bir yerdir. Yine de pek ustelemedim. "
gameforge.subquest_23._200_say = "Onu durdurmaliydim. H�l� donmediyse buyuk ihtimalle[ENTER]basina bir sey gelmistir. En iyisi Seungryong[ENTER]Vadisi'ne gidip onu araman. "
gameforge.subquest_23._20_npcChat = "Neden agliyorsun? "
gameforge.subquest_23._210_select = "Aramayi baslat "
gameforge.subquest_23._220_say = "Aramayi iptal etmek mi istiyorsun? "
gameforge.subquest_23._230_say = "Mirine gercekten cok uzgundu.[ENTER]Daha sonra donecegim. "
gameforge.subquest_23._240_say = "Mirine'nin agabeyinden yasam belirtisi olmamasi[ENTER]basina bir sey geldigi anlamina gelmez. Sirf bir kiz[ENTER]rica etti diye o tehlikeli Vadiye gitmek zorunda[ENTER]degilsin. "
gameforge.subquest_23._250_say = "Gorev gorundugu kadar basit degil. Seungryong[ENTER]Vadisi tehlikeli bir yer. Ama soz verdim, bu yuzden[ENTER]yapacagim. "
gameforge.subquest_23._260_sendLetter = "Kayip Agabey "
gameforge.subquest_23._270_targetVid = "Agabeyi Seungryong Vadisi'nde ara. "
gameforge.subquest_23._280_sayTitle = "Mirine'nin kardesini ara "
gameforge.subquest_23._290_say = "Mirine'nin agabeyi Seungryong Vadisi'nde sifali[ENTER]bitkiler ariyor. Oraya git ve her seyin yolunda olup[ENTER]olmadigini kontrol et. Kestirme ariyorsan Isinlayiciyi[ENTER]kullan. "
gameforge.subquest_23._300_npcChat = "Bir Ceset! "
gameforge.subquest_23._30_say = "Bir saniye lutfen... Bana bir keresinde kardesimden[ENTER]bir mektup vermistin, degil mi? Sana cok minnettarim.[ENTER]Ama simdi yine onunla iletisimim koptu. Kardesim h�l�[ENTER]evden uzakta. Bitki ariyor. "
gameforge.subquest_23._310_say = "Orada bir adamin cesedi yatiyor. Genc ve zayif biri,[ENTER]gorunuse gore bitki topluyormus. Korkarim bu[ENTER]Mirine'nin agabeyi olabilir. Boynunda kolye ucu olan[ENTER]bir kolye var. Onu cikarip Mirine'ye goturecegim. "
gameforge.subquest_23._say_item = "Mirine'nin Tilsimini ve Yesim Tasi Kolye+2 kazandin. Iki esyayi da Mirine'ye gotur."
gameforge.subquest_23._320_sendLetter = "Mirine'ye Git. "
gameforge.subquest_23._330_sayTitle = "Aci Haber "
gameforge.subquest_23._340_say = "Seungryong Vadisi'nde bulunan cesedin uzerinde[ENTER]Mirine'nin adinin kazindigi bir Tilsim vardi.[ENTER]Mirine'ye git ve bulunan Yesim Tasi Kolye+2 ile[ENTER]Tilsimi ona ver. "
gameforge.subquest_23._350_npcChat = "Bu kolyeyi taniyor musun? "
gameforge.subquest_23._360_say = "Oh, bu kolye... Kardesim onu her zaman takardi.[ENTER]Bende de benzer bir kolye var. Birbirimizi her zaman[ENTER]hatirlamak ve hep bulabilmek icin bu kolyeleri[ENTER]takardik.[ENTER]Ama... kardesim artik burada yanimda degil...[ENTER]sadece kolyenin kendisi geri dondu... "
gameforge.subquest_23._370_say = "Benim garip kardesim...[ENTER]Hepsi savas yuzunden. Kardesim sifali otlar satardi,[ENTER]tek gelir kaynagimiz buydu. Bu sayede yiyecek ekmek[ENTER]bulurduk. Ben ac kalmayayim diye kardesim hep cok[ENTER]calisirdi. Ve simdi hayatta degil. Hem de benim[ENTER]yuzumden... "
gameforge.subquest_23._380_say = "Bu kolyeyi bana getirdigin icin tesekkur ederim.[ENTER]Artik basina ne geldigini biliyorum. Yardimin[ENTER]olmasaydi neler oldugunu asla ogrenemezdim. "
gameforge.subquest_23._390_say = "Kardesimin kolye ucunu ben saklayacagim, kolyenin[ENTER]kendisini ise lutfen tesekkurum olarak sen sakla.[ENTER]Kesinlikle isine yarayacaktir.[ENTER][ENTER]Yardimin icin tesekkur ederim.[ENTER]Artik cennettedir kesin, sence de oyle degil mi? "
gameforge.subquest_23._400_sayReward = "600.000 Deneyim Puani kazandin.[ENTER]35.000 Yang kazandin. "
gameforge.subquest_23._40_say = "Onun icin endiseleniyorum, benimle hicbir temasi[ENTER]yok. Ozur dilerim ama kardesimi tekrar arayabilir[ENTER]misin? Belki Yu-Hwan bir seyler biliyordur.... "
gameforge.subquest_23._50_select = "Reddet. "
gameforge.subquest_23._60_say = "Vazgecmek mi istiyorsun? "
gameforge.subquest_23._70_say = "Oh...[ENTER]Burada bekleyecegim... belki daha sonra? Lutfen? "
gameforge.subquest_23._80_say = "Vaktim yok![ENTER]Kardesine bol sans dilerim. "
gameforge.subquest_23._90_say = "Kederli bir kiza yardim etmek asil bir davranistir.[ENTER]Üstelik cok fazla yorulmam da gerekmeyecek.[ENTER]O halde yola cikalim! "
gameforge.subquest_24 = {}
