gameforge.subquest_24._10_targetVid = "Yu-Rang'in Pirinc Kekleri "
gameforge.subquest_24._110_say = "Daha sonra vaktin olursa lutfen tekrar ugra.[ENTER]Pirinc Keki satisi olmadan nasil hayatta kalacagiz[ENTER]bilmiyorum. "
gameforge.subquest_24._120_say = "Her sey hep Yang'i su gibi harcayan zenginlerin[ENTER]etrafinda donuyor. Biz ise masaya ne koyacagimizi[ENTER]bilemiyoruz! Defol buradan! "
gameforge.subquest_24._130_say = "Tesekkur ederim. Cok naziksin.[ENTER]Donusunu bekleyecegim. "
gameforge.subquest_24._140_sendLetter = "Calinan Pirinc Keki "
gameforge.subquest_24._150_say = "Coldeki Orumceklerden Yu-Rang'in Pirinc Keklerini[ENTER]geri al. Acele etmezsen Orumcekler onlari yiyecek[ENTER]veya kekler guneste kuruyacaktir. Lutfen acele et! "
gameforge.subquest_24._160_sayReward = "Yongbi Colu'nde Yavru Orumcekleri oldur. "
gameforge.subquest_24._170_npcChat = "Pirinc Kekin ile ilgili olarak... "
gameforge.subquest_24._180_say = "Ne oldu? Orumcekler Pirinc Kekini yedi mi? Olamaz![ENTER]Yoksa kurudu mu? Lutfen bana her seyin bittigini[ENTER]soyleme! "
gameforge.subquest_24._190_select = "Hayir, her sey yolunda. "
gameforge.subquest_24._200_select = "Pes ediyorum. "
gameforge.subquest_24._20_npcChat = "Calinan Pirinc Kekin... "
gameforge.subquest_24._210_say = "Yine de bununla ilgilenmez misin? O Pirinc Keki[ENTER]benim icin cok onemli. Sana yalvariyorum.[ENTER][ENTER]Colde Yu-Rang'in Pirinc Kekini bulma gorevinden[ENTER]vazgecmek istiyor musun? "
gameforge.subquest_24._220_select = "Tekrar deneyecegim. "
gameforge.subquest_24._230_select = "Üzgunum, bu cok zor. "
gameforge.subquest_24._240_say = "Buna inanamiyorum. Simdi bize kim yardim edecek? "
gameforge.subquest_24._250_say = "Hadi ama! Lutfen yardim et! "
gameforge.subquest_24._260_say = "Demek aramaya devam edeceksin? Tesekkurler![ENTER]Lutfen Pirinc Kekini olabildigince cabuk bul! "
gameforge.subquest_24._270_say = "Hayir, cok gec. Onlari bulsan bile kesinlikle tum[ENTER]Kekler coktan kurumus ve satilamaz hale gelmistir... "
gameforge.subquest_24._280_say = "Yere bakiyorsun ve Orumceklerin biraktigi Pirinc[ENTER]Keklerini goruyorsun. Cok gec. Coktan kurumuslar. "
gameforge.subquest_24._290_sayReward = "Cok fazla zaman kaybettin, Kekler coktan kurudu.[ENTER]Gorev basarisizlikla sonuclandi. "
gameforge.subquest_24._300_sendLetter = "Yu-Rang'a Don "
gameforge.subquest_24._30_say = "Merhaba, annen nasil? "
gameforge.subquest_24._310_targetVid = "Yu-Rang'a Don "
gameforge.subquest_24._320_say = "Yu-Rang'in Pirinc Kekini orumceklerden kurtarmayi[ENTER]basardin. Onu ona gotur. "
gameforge.subquest_24._330_npcChat = "Sansin varmis. Iste Pirinc Kekin. "
gameforge.subquest_24._340_say = "Gercekten harikasin. Ne diyecegimi bilemiyorum...[ENTER]Artik onlari yarin pazarda satabilirim! Cok[ENTER]tesekkurler! "
gameforge.subquest_24._350_sayReward = "900.000 Deneyim Puani kazandin. "
gameforge.subquest_24._360_sayReward = "25.000 Yang kazandin. "
gameforge.subquest_24._40_say = "Oh, daha iyi. Sordugun icin tesekkurler. "
