gameforge.subquest_24._60_say = "Burada her gun Pirinc Keki satarim ama bugun[ENTER]korkunc bir sey oldu. Devasa orumcekler geldi ve[ENTER]Kekimi caldi. Cok korktum ve karsi koyamadim.[ENTER]Simdi satacak hic Pirinc Kekim kalmadi. Ben simdi[ENTER]nasil gecinecegim? Ailemin baska geliri yok... "
gameforge.subquest_24._70_select = "Senin icin onlari bulurum. "
gameforge.subquest_24._80_select = "Üzgunum, vaktim yok. "
