gameforge.subquest_25._100_npcChat = "Seni ne mutlu edebilir? "
gameforge.subquest_25._10_targetVid = "Huahn-So "
gameforge.subquest_25._110_say = "Sey, kocami savasta kaybettigimden beri kendimi[ENTER]cok yalniz hissediyorum. Beni ne daha iyi hissettirebilir[ENTER]ki? Kocam bana her zaman guzel Cicekler getirirdi. "
gameforge.subquest_25._120_say = "Koyumuzden cok uzakta yetisen Ciceklerdi bunlar.[ENTER]Tehlikeli olmasina ragmen onlari benim icin getirirdi.[ENTER]Artik o Cicekleri goremiyorum, artik kocam yasamiyor.[ENTER]Boyle gunler onu cok ozlememe sebep oluyor. Ohom,[ENTER]ben ne dedim oyle? Buna gerek yoktu... Lutfen[ENTER]soylediklerimi unut gitsin. "
gameforge.subquest_25._130_qSetTitle = "Huahn-So'ya Donus "
gameforge.subquest_25._140_makequestbutton = "Huahn-So'ya Donus "
gameforge.subquest_25._150_targetVid = "Huahn-So "
gameforge.subquest_25._160_say = "Ariyoung, kocasinin ona her zaman getirdigi[ENTER]cicekleri ozluyor. Huahn-So'ya git ve bunu ona[ENTER]anlat. "
gameforge.subquest_25._170_npcChat = "Ariyoung Icin Hediye... "
gameforge.subquest_25._180_say = "Eee, nelerden hoslaniyormus? Ona benden hic bahsetmedin[ENTER]degil mi? Hm, kocasinin ona hep getirdigi Cicekleri[ENTER]seviyor demek? Burasi koyden oldukca uzakta ve onlari[ENTER]elde etmek kolay degil. En azindan benim icin kolay[ENTER]degil... Orada vahsi hayvanlar olabilir sonucta! "
gameforge.subquest_25._190_say = "Hm... Bana yardim edebilir misin? O Cicekleri[ENTER]benim icin toplar misin? Bu ikimiz icin de bir[ENTER]iyilik olur. Bu anlasmaya ne dersin? Hadi ama, onun[ENTER]sevgisini kazanmayi ne kadar cok istedigimi gormuyor[ENTER]musun?[ENTER]Bunun karsiliginda sana bolca Yang verecegim. "
gameforge.subquest_25._200_select = "Reddet "
gameforge.subquest_25._20_npcChat = "Ah benim sevgili Ariyoung'um "
gameforge.subquest_25._210_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_25._220_say = "Kahretsin. Onun icin o Cicekleri nasil bulacagim?[ENTER]Fikrini degistirirsen lutfen geri gel. "
gameforge.subquest_25._230_say = "Sen hic asik olmadin mi? Ariyoung'a karsi neler[ENTER]hissettigimi anlamiyor musun? Ah Ariyoung... "
gameforge.subquest_25._240_say = "Cok tesekkurler! Lutfen o Cicekleri bana getir. "
gameforge.subquest_25._250_qSetTitle = "Cicekleri Topla. "
gameforge.subquest_25._260_targetVid = "Cicekler "
gameforge.subquest_25._270_sayTitle = "Ariyoung Icin Cicekler "
gameforge.subquest_25._280_say = "Huahn-So'nun Ariyoung'a olan hislerini itiraf[ENTER]etmesini kolaylastirmak icin onun adina ozel[ENTER]Cicekler bulmalisin. Onlari ilk koydeki haritanin[ENTER]kosesinde bulacaksin. "
gameforge.subquest_25._290_npcChat = "Cicekleri bulamadim. "
gameforge.subquest_25._300_say = "Kahretsin... Ona olan duygularimi soylemek[ENTER]istiyordum. Onun sevgisini kazanmak cok zor.[ENTER]Benim sevgili Ariyoung'um... "
gameforge.subquest_25._30_say = "Ihm... Ariyoung Hanim'i taniyor musun? Sey, o...[ENTER]evli bir kadindi, yani artik genc kiz degil.[ENTER]Ama bunun onemi yok, artik bir dul. Sey... Ona cok[ENTER]onceden asik olmustum ama o cok genc yasta evlendi...[ENTER]Sanirim sadece sanssizdim... "
gameforge.subquest_25._310_select = "Tekrar deneyecegim. "
gameforge.subquest_25._320_select = "Vazgeciyorum. "
gameforge.subquest_25._330_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_25._340_say = "Eh...[ENTER]Fikrini degistirirsen burada seni bekliyor olacagim.[ENTER]Lutfen bana yardim et... "
gameforge.subquest_25._350_say = "Askim boyle mi son bulacak?[ENTER]Ariyoung... "
gameforge.subquest_25._360_say = "Sana cok tesekkur ederim. Sen de asik olmus[ENTER]olmalisin. Ariyoung'a neler hissettigimi bildigine[ENTER]gore... "
gameforge.subquest_25._370_npcChat = "Ariyoung'un En Sevdigi Cicekler "
gameforge.subquest_25._380_say = "Bu Cicekler Ariyoung'un tarif ettigi gibi gorunuyor.[ENTER]Birkac tane alayim. "
gameforge.subquest_25._390_qSetTitle = "Huahn-So'ya Donus "
gameforge.subquest_25._400_say = "Sonunda Ariyoung'un en sevdigi Cicekleri buldum[ENTER]ve birkac tane kopardim. Ariyoung'a askini itiraf[ENTER]edebilmesi icin onlari Huahn-So'ya goturmeliyim. "
gameforge.subquest_25._40_say = "Simdi kocasi savasta oldu ve genc bir dul kaldi.[ENTER]Evli bir kadin olmasina ragmen... hm... ona neler[ENTER]hissettigimi bilmesini isterdim. Garip bir rica[ENTER]oldugunu biliyorum ama bana yardim edebilir misin? "
gameforge.subquest_25._410_npcChat = "Iste Ariyoung'un en sevdigi Cicekler. "
gameforge.subquest_25._420_say = "Oh, bu Cicekler miydi? Artik ona neler hissettigimi[ENTER]soyleyebilirim! H�l� cok erken mi oldugunu[ENTER]dusunuyorsun? Artik bunun onemi yok. Ona bunu[ENTER]soylemeliyim, yoksa aklimi kaciracagim. Cok tesekkur[ENTER]ederim. Iste odulun! "
gameforge.subquest_25._430_sayReward = "400.000 Deneyim Puani kazandin. "
gameforge.subquest_25._440_sayReward = "12.000 Yang kazandin. "
gameforge.subquest_25._50_say = "Sence yakisikli erkeklerden mi hoslanir? Ya da[ENTER]guzel kiyafetlerden? Once nelerden hoslandigini[ENTER]bilmem gerek. Belki o zaman onunla konusabilirim.[ENTER]Bunu ogrenebilir misin? Ama ona benden hic bahsetme![ENTER]Yalvaririm, seni kesinlikle odullendirecegim. "
gameforge.subquest_25._60_qSetTitle = "Ariyoung'a Git "
gameforge.subquest_25._70_makequestbutton = "Ariyoung'a Git "
gameforge.subquest_25._80_targetVid = "Ariyoung'a git "
gameforge.subquest_25._90_say = "Huahn-So dul kalan Ariyoung'u seviyor.[ENTER]Huahn-So'nun hislerini Ariyoung'a acmasina yardim[ENTER]etmek icin onun nelerden hoslandigini ogrenmelisin.[ENTER]Git ve bunu ona sor. Sadece cok fazla sey belli[ENTER]etmemeye dikkat et. "
