gameforge.subquest_26._140_sayTitle = "Octavio'ya Git "
gameforge.subquest_26._150_say = "Depocu sana yararli bir ipucu verdi: Kurbaga[ENTER]Bacagi Corbasi halsizlik ve yorgunluk icin harikadir.[ENTER]Octavio'ya gidip bu corbayi pisirip pisiremeyecegini[ENTER]sor. "
gameforge.subquest_26._160_npcChat = "Kurbaga Bacagi Corbasi mi? "
gameforge.subquest_26._170_say = "Kurbaga Bacagi Corbasi... Evet, gecmiste yapardim.[ENTER]Ama artik yapmiyorum... Uzun zaman once vahsi[ENTER]hayvanlardan ve canavarlardan korkmazdim, bu yuzden[ENTER]Kurbaga Bacaklarini kolayca elde edebilirdim. "
gameforge.subquest_26._180_say = "Ama simdi... Artik yasli ve yorgunum. Bu corba[ENTER]sayesinde enerjimi geri kazanabilirdim ama kurbagalar[ENTER]kolay bir hedef degil. Bana Kurbaga Bacaklari temin[ENTER]edersen sana dunyanin en iyi corbasini hazirlarim. "
gameforge.subquest_26._190_select = "Elbette, yaparim. "
gameforge.subquest_26._200_select = "Hayir, yapamam. "
gameforge.subquest_26._20_npcChat = "Nasilsin? "
gameforge.subquest_26._210_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_26._220_say = "Mesgul musun? Fikrini degistirdiginde geri gel. "
gameforge.subquest_26._230_say = "Corbam pek bilinmez. Bilseydin kesinlikle yardim[ENTER]ederdin. Eh, hosca kal. "
gameforge.subquest_26._240_say = "O zaman acele et. Kurbaga Bacagi Corbasi icin her[ENTER]seyi hazirlayacagim. "
gameforge.subquest_26._250_sendLetter = "Kurbaga Bacaklarini Aldin "
