gameforge.subquest_26._300_say = "Octavio'nun corbayi hazirlamak icin Kurbaga[ENTER]Bacaklarina ihtiyaci var. Onlari Hwang Tapinagi'nda[ENTER]Agac Kurbagasi Lideri avlayarak elde edebilirsin. "
gameforge.subquest_26._30_sayTitle = "Depocu: "
gameforge.subquest_26._310_npcChat = "Bunu su anda yapamam. "
gameforge.subquest_26._320_say = "Ne var? Senin yasindayken gunde 10 Kurbaga Bacagi[ENTER]getirirdim ben. "
gameforge.subquest_26._330_select = "Tekrar dene "
gameforge.subquest_26._340_say = "Yoruldun mu?[ENTER]Biraz mola verip daha sonra denemeye ne dersin? "
gameforge.subquest_26._350_say = "Kurbaga Bacagi Corbasi cok isime yarardi. Ama[ENTER]gorunuse gore bundan bir sey cikmayacak. Yazik.[ENTER]Simdilik hosca kal! "
gameforge.subquest_26._360_say = "Burada kazik gibi dikilme de yola koyul! Su[ENTER]kayniyor bile ve her sey hazir! "
gameforge.subquest_26._370_targetVid = "Octavio'ya git "
gameforge.subquest_26._380_say = "Vay canina, Kurbaga Bacagi dedigin boyle olur![ENTER]Benim zamanimda biraz daha kucuklerdi. Ama bu da[ENTER]kesinlikle lezzetlidir. Bir saniye bekle...[ENTER]Simdiden harika kokuyor. Bir tutam da tuz... Ha![ENTER]Iste senin porsiyonun. Ha ha ha, artik butun bir[ENTER]hafta calisacak kadar gucum var! "
gameforge.subquest_26._390_say = "Bu Corbanin varligindan kimsenin haberdar[ENTER]olmadigindan emin ol. Ozellikle de Depocu'nun...[ENTER]Bu Corbayi cok nadiren yaparim. Bunu bir sir olarak[ENTER]saklamazsan herkes tatmak isteyecektir. "
gameforge.subquest_26._400_sayReward = "5.000.000 Deneyim Puani kazandin. "
gameforge.subquest_26._40_say = "Son zamanlarda kendimi pek iyi hissetmiyorum.[ENTER]Bedenim artik eskisi gibi degil. Gencken gece gec[ENTER]saatlere kadar calisabilirdim, hem de her gun.[ENTER]Üstune bir de icki icerdim. Simdiyse sabahlari[ENTER]yataktan zor kalkiyorum. Tekrar yeterli enerjiye[ENTER]sahip olmak icin kallavi bir porsiyon Kurbaga Bacagi[ENTER]Corbasi cok iyi gelirdi. "
gameforge.subquest_26._410_sayReward = "50.000 Yang kazandin. "
gameforge.subquest_26._50_say = "Kurbaga Bacagi Corbasi'nin ne oldugunu bilmiyor[ENTER]musun? Bu corbadan bir kase ictiginde aninda zimba[ENTER]gibi olursun ve icine enerji dolar. Hic yorgunluk[ENTER]hissetmeden koca bir hafta calisabilirsin.[ENTER]Octavio bu corbayi yapardi. Ama bilmedigim bir[ENTER]nedenle gecenlerde yapmayi birakti. "
gameforge.subquest_26._60_select = "Gidip Octavio ile konusacagim "
gameforge.subquest_26._70_select = "Mesgulum. "
gameforge.subquest_26._80_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_26._90_say = "Tamam, su an mesgulsen istersen daha sonra ugra. "
