gameforge.subquest_31._90_say = "Bana yine yardim edecek misin? Sen iyi bir[ENTER]dostsun. Ve merak etme, ilk zirh senindir! "
gameforge.subquest_32 = {}
gameforge.subquest_32._100_sendLetter = "Tuccarin Talebi "
gameforge.subquest_32._10_targetVid = "Tuccari Sec "
gameforge.subquest_32._110_targetVid = "Ah-Yu'ya git "
gameforge.subquest_32._120_targetVid = "Satici'ya git. "
gameforge.subquest_32._130_sayReward = "Tuccar Icin Malzemeler "
gameforge.subquest_32._140_sayReward = "Seyyar Satici'nin bir kolye icin birkac malzemeye[ENTER]ihtiyaci var. Onun icin Cesur Ork Buyuculerinden[ENTER]100 Ork Disi, Satici'dan bir mucevher ve Ariyoung'dan[ENTER]Iplik temin et. "
gameforge.subquest_32.letter_tip1 = "Satici icin 10 adet Kaplan Karacigeri ve bir adet Sifali Bitki toplarsan sana Elmas Tas Sus esyasi verecektir. Her iki esyayi da beyaz veya normal Kaplanlardan elde edebilirsin."
gameforge.subquest_32.letter_tip1_done = "Satici yardimin karsiliginda sana Elmas Tas Sus verdi."
gameforge.subquest_32.letter_tip2 = "Ariyoung senin icin Iplik yapacak ancak vakti olmasi icin ona yardim etmeli ve Ah-Yu'ya Kiyafetlerini goturmelisin."
gameforge.subquest_32.letter_tip2_done = "Ariyoung'dan Iplik almayi basardin."
gameforge.subquest_32._150_npcChat = "Iplige ihtiyacim var. "
gameforge.subquest_32._160_say = "Iplik yapmak oldukca basit bir istir. Ancak o zaman[ENTER]kendi isimi yapamam. Bugun Ah-Yu'nun yirtik[ENTER]kiyafetlerini yamiyordum ve tam da onlari ona[ENTER]goturmek uzereydim... "
gameforge.subquest_32._170_say = "Suna ne dersin: Sen Ah-Yu'ya kiyafetlerini goturursun,[ENTER]ben de bu arada senin icin Iplikleri yaparim. Anlastik[ENTER]mi? "
gameforge.subquest_32._180_say = "Gercekten pes etmek istiyor musun? "
gameforge.subquest_32._190_say = "Gercekten cok yakin bir yer. Neden h�l� tereddut[ENTER]ediyorsun? Hazir oldugunda tekrar gel. "
gameforge.subquest_32._200_say = "Ah, vakit bulursun diye ummustum. Bu durumda bunu[ENTER]kendim yapmak zorundayim. Gorusmek uzere! "
gameforge.subquest_32._20_npcChat = "Kolyeler ile ilgili olarak... "
gameforge.subquest_32._210_say = "Harika, cok tesekkur ederim! Benden Ah-Yu'ya selam[ENTER]soyle ve yolda kiyafetlerini burusturmamaya dikkat[ENTER]et! Burada seni bekliyorum. "
gameforge.subquest_32._220_sayTitle = "Ariyoung: "
gameforge.subquest_32._230_say = "Komsu koyden dondugunde Ipliklerin hazir olacak.[ENTER]Ah-Yu'ya kiyafetlerini teslim etmeyi unutmadin,[ENTER]degil mi? Bana gucenirdi yoksa... "
gameforge.subquest_32._240_say = "Ah-Yu Kiyafetlerinden memnun kaldi mi?[ENTER]Oyleyse siki calismaya degdi demektir. Iste[ENTER]Ipliklerin. Bunlar cok guclu Ipliklerdir, bircok[ENTER]sey icin kullanilabilirler. "
gameforge.subquest_32._250_say = "Sana Iplikleri vermistim zaten. Kaybettin mi yoksa? "
gameforge.subquest_32._260_npcChat = "Ariyoung sana bu kiyafetleri gonderdi. "
gameforge.subquest_32._270_sayTitle = "Ah-Yu: "
gameforge.subquest_32._280_say = "Ah, harika. Gercekten cok cabuk oldu. Iyi bir[ENTER]dostlugun kiymetini bilmek gerek, degil mi? Biz sik[ENTER]sik birbirimize yardim ederiz...[ENTER]Kiyafetleri getirdigin icin tesekkurler.[ENTER]Ariyoung'a benden cok selam ilet. "
gameforge.subquest_32._290_npcChat = "Suslu Elmasa ihtiyacim var. "
gameforge.subquest_32._300_say = "Suslu Elmas mi ariyorsun? Bana biraz yardim[ENTER]edersen onu sana verebilirim. Su anda bir agri[ENTER]kesici ilac uzerinde calisiyorum ama bir malzemem[ENTER]eksik. Ilac icin Kaplan Karacigerlerine ihtiyacim[ENTER]var. Onlari elde etmek zordur ve tam 10 tane lazim. "
gameforge.subquest_32._30_say = "Savas zamaninda biz Seyyar Saticilar icin isler[ENTER]hic kolay degil. Her yerde mal sikintisi oldugu[ENTER]dogru ama talep o kadar hizli degisiyor ki ne stok[ENTER]yapacagimi bilemiyorum. Her adimda bir canavarin[ENTER]dikkatsiz yolculari bekledigi o vahsi dogadaki uzun[ENTER]yolculuklardan bahsetmiyorum bile. Biraz Yang[ENTER]kazanmak ister miydin? Yardimina ihtiyacim var. "
gameforge.subquest_32._310_say = "Ayrica iyilestirici ozellikleri olan ozel bir[ENTER]bitkiye de ihtiyacim var. Onu da Kaplanlardan elde[ENTER]edersin; kokusuna bayildiklari icin icinde[ENTER]yuvarlanmayi severler. Bu Sifali Bitkiler ve Kaplan[ENTER]Karacigerleri karsiliginda Suslu Elmas alirsin. "
gameforge.subquest_32._320_say = "Kaplanlari veya Beyaz Kaplanlari avla. "
gameforge.subquest_32._330_say = "Buna ne dersin? Anlastik mi? "
gameforge.subquest_32._340_say = "Gorevim senin icin cok mu zor? Inanmam![ENTER]Fikrini degistirdiginde tekrar gel. "
gameforge.subquest_32._350_say = "Tuccar icin onca yolu geldin ve simdi pes mi[ENTER]ediyorsun? Nasil istersen...[ENTER]Iyi gunler dilerim. "
gameforge.subquest_32._360_say = "Harika. Ikimiz de kazanacagiz, degil mi?[ENTER]Tesekkurler ve bol sans! "
gameforge.subquest_32._370_npcChat = "Artik Suslu Elmasi alabilir miyim? "
gameforge.subquest_32._380_say = "Bir bakayim... 10 Kaplan Karacigeri ve Sifali[ENTER]Bitkiler, hepsi tamam. Sana cok tesekkur ederim![ENTER]Buyur, bu Suslu Elmasi hak ettin. Simdilik hosca[ENTER]kal! "
gameforge.subquest_32._390_qSetTitle = "Seyyar Satici'ya Don "
gameforge.subquest_32._400_targetVid = "Seyyar Satici'ya Don "
gameforge.subquest_32._40_say = "Ork Disi kolyeler su anda cok ragbet goren bir mal.[ENTER]Ork Disleri buyuk ve serttir, turlu turlu susler[ENTER]yapmak icin bicilmis kaftandir. Cesur Ork Buyucusu[ENTER]Disleri ayrica askerler tarafindan muska olarak da[ENTER]kullanilir. Onlari benim icin temin edebilir misin?[ENTER]Baslangic icin 100 tane yeterli olacaktir. "
gameforge.subquest_32._410_sayReward = "Seyyar Satici'ya Don "
gameforge.subquest_32._415_sayReward = "Satici'ya Don "
gameforge.subquest_32._420_sayReward = "Nihayet kolye icin gereken tum malzemeleri buldun.[ENTER]Onlari Seyyar Satici'ya gotur. "
gameforge.subquest_32._430_npcChat = "Tum Malzemeler Elimde "
gameforge.subquest_32._440_sayTitle = "Seyyar Satici: "
gameforge.subquest_32._450_say = "Butun malzemeleri elde etmeyi basardin mi? Goster[ENTER]bakalim... Gercekten de her sey var. Yardimin[ENTER]sayesinde urun yelpazemi genisletebilirim, harika![ENTER]Tesekkur olarak senin icin ozel bir sey hazirladim.[ENTER]Kendin bak ve en cok hangisini begendigini sec."
gameforge.subquest_32.reward_talk = "Harika bir secim! Iste payina dusen.[ENTER]Gule gule kullan![ENTER]Bana gelin ahali, bana gelin! Herkese uygun bir[ENTER]sey var! "
gameforge.subquest_32._460_sayReward = "1.100.000 Deneyim Puani kazandin. "
gameforge.subquest_32._470_sayReward = "Altin Bilezik, Altin Kolye ve Altin Kupe kazandin. "
gameforge.subquest_32._480_say = "Hmm, uzgunum ama h�l� bir seyler eksik.[ENTER]Eksik teslimatlari kabul etmiyorum. Denemeye devam[ENTER]edecek misin? "
gameforge.subquest_32._490_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_32._500_say = "Bu kadar kolay pes etmedigin icin tesekkur ederim.[ENTER]Sans cabalayanin yanindadir! Seni burada bekliyor[ENTER]olacagim. "
gameforge.subquest_32._50_say = "Bir de Suslu Elmas ve Iplige ihtiyacim var.[ENTER]Elmasi Satici'dan, Ipligi ise Ariyoung'dan temin[ENTER]edersin. Bu kadar farkli seyi bulmak kolay degildir[ENTER]ama Kolyelerin satisi cok karli ve seni comert bir[ENTER]odul bekliyor. Ne dersin, ilgilenir misin? "
gameforge.subquest_32._510_say = "Bu gorev seni asti mi yoksa? Neyse, en azindan[ENTER]denedin. Ileride senin icin daha basit bir isim[ENTER]olursa haber veririm. Gorusuruz. "
gameforge.subquest_32._520_say = "Tekrar mi deneyeceksin? Tesekkurler.[ENTER]Seni bekliyor olacagim. "
gameforge.subquest_32._60_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_32._70_say = "Mesgul musun? Sorun degil, anliyorum.[ENTER]Ama lutfen vakit bulur bulmaz tekrar gel. "
gameforge.subquest_32._80_say = "Tuh be, simdi siparislerimi nasil yetistirecegim?[ENTER]Simdilik hosca kal! "
gameforge.subquest_32._90_say = "Harika. Burada seni bekliyor olacagim. "
gameforge.subquest_32._95_say = "Satici icin gereken tum malzemeleri topladin. "
