gameforge.subquest_33._150_sendLetter = "Hazine Haritasi "
gameforge.subquest_33._160_sayTitle = "Tum parcalari buldun! "
gameforge.subquest_33._170_say = "Soon'a don ve ona Hazine Haritasi'nin tum[ENTER]parcalarini buldugunu soyle. "
gameforge.subquest_33._175_npcChat = "Haritanin tum parcalari bende. "
gameforge.subquest_33._180_say = "Oh! Fantastik! Sonunda tum parcalara sahibim.[ENTER]Bunu ruyamda bile goremezdim... Simdi parcalari bir[ENTER]araya getireyim... guzel... "
gameforge.subquest_33._190_say = "Hmm... garip. Harita hazinenin Yasli Adam'in[ENTER]yakinindaki kayaliklarin altina gizlendigini gosteriyor.[ENTER]Buna pek inanasim gelmiyor. Hmm, bu fazla basit olurdu.[ENTER]Bana bir saka gibi geliyor. Kontrol etmek ister misin[ENTER]yoksa haritayi yakayim mi? "
gameforge.subquest_33._200_select = "Kontrol edecegim. "
gameforge.subquest_33._20_npcChat = "Hazine Haritasi meselesi... "
gameforge.subquest_33._210_select = "Yak gitsin. "
gameforge.subquest_33._220_say = "Haritaya ihtiyacin olmadigindan emin misin? "
gameforge.subquest_33._230_say = "Evet, cok sacma bir hikaye! Seni buna bulastirip[ENTER]harita parcalarini aramaya gonderdigim icin uzgunum.[ENTER]Baskalari kanmasin diye her seyi yakacagim. Hepsi[ENTER]bu kadar. Elveda. "
gameforge.subquest_33._240_say = "Neden tereddut ediyorsun? Harita parcalarini coktan[ENTER]topladin, o yuzden git ve kontrol et. Al lutfen,[ENTER]Haritayi yanina al. "
gameforge.subquest_33._250_say = "Nasil istersen. Bir sey bulursan buyuk bir surpriz[ENTER]olacak ama yine de basarilar dilerim! Haritayi[ENTER]unutma! "
gameforge.subquest_33._260_say = "Harita dort parcaya bolunmustu.[ENTER]Onu birlestirmek icin tum parcalara ihtiyacimiz var. "
gameforge.subquest_33._270_select = "Tekrar dene. "
gameforge.subquest_33._280_say = "Pes mi ediyorsun? Pekala, oyle olsun bakalim.[ENTER]Gorusuruz. "
gameforge.subquest_33._290_say = "Vazgecmeyecegini biliyordum.[ENTER]Sana guveniyorum! "
gameforge.subquest_33._300_targetVid = "Yasli Adam'in yanindaki kaya "
gameforge.subquest_33._30_say = "Selam! Koyumuzde bir yerlerde Hazine Haritalarinin[ENTER]saklanmis olabilecegine dair tuhaf bilgilere rastladim.[ENTER]Sehri koruyan tanrilari taniyor musun? Kopek Tanrisi,[ENTER]Kaplan Tanrisi, Ayi Tanrisi ve Domuz Tanrisi. "
gameforge.subquest_33._310_sayTitle = "Hazine Arayisi... "
gameforge.subquest_33._320_say = "Hmm, Yasli Adam'in yakinindaki kayanin altinda...[ENTER]Hicbir fikrim yok. Once Yasli Adam'a sorsam iyi[ENTER]olur. Neden bu kadar uzakta ki? Kahretsin! "
gameforge.subquest_33._330_sayTitle = "Yasli Adam: "
gameforge.subquest_33._340_say = "Ne ariyorsun? Hazine mi? Cok ararsin! Haritayi[ENTER]goster... Hm, surada olmali. Iyi sanslar, hahaha... "
gameforge.subquest_33._350_say = "Burasi olmali. Kahretsin, bu noktadaki toprak[ENTER]olaganustu sert. Hmm...[ENTER][ENTER]Hey, bir Kutu goruyorum! "
gameforge.subquest_33._360_sendLetter = "Hazine gercekten varmis! "
gameforge.subquest_33._370_sayTitle = "Soon'a Donus "
gameforge.subquest_33._380_say = "Hayvan Tanrilarinin Haritasinda isaretlenen yeri[ENTER]kazdin ve gercekten de bir Sandik buldun! Soon'a git[ENTER]ve bu beklenmedik basariyi ona anlat. "
gameforge.subquest_33._390_npcChat = "Hazineyi buldum! "
gameforge.subquest_33._400_say = "Oh! Ne buyuk bir surpriz! Goster... Inanilmaz.[ENTER]Eski kitaplarda Sandik tam olarak boyle tarif[ENTER]ediliyordu. Simdi onu nasil acacagimi ogrenmem gerek.[ENTER]Ama bu artik senin derdin degil. Sag ol! Lutfen bunu[ENTER]minnettarligimin bir nisanesi olarak kabul et. "
gameforge.subquest_33._40_say = "Dort ilahi varlik Haritayi dort parcaya boldu ve[ENTER]simdi onlari koruyorlar. Bu gercekten cok eski bir[ENTER]hikaye, bu yuzden dogru olup olmadigindan emin[ENTER]degilim... Bir kanit aramaya ne dersin? Lutfen.[ENTER]Bu belirsizlige dayanamiyorum... Bana yardim et! "
gameforge.subquest_33._410_sayReward = "1.400.000 Deneyim Puani kazandin. "
gameforge.subquest_33._420_sayReward = "25.000 Yang kazandin. "
gameforge.subquest_33._430_sayReward = "Hayalet Maske Baslik+1 kazandin. "
gameforge.subquest_33._440_sayReward = "Kale Kask+1 kazandin. "
gameforge.subquest_33._450_sayReward = "Celik Kapson+1 kazandin. "
gameforge.subquest_33._460_sayReward = "Gunisigi Sapka+1 kazandin. "
gameforge.subquest_33._470_say = "Eee, nerede o? Benimle dalga mi geciyorsun?[ENTER]Henuz bulamadin, degil mi? "
gameforge.subquest_33._50_say = "Eski Hazine Haritalari ilgini cekmiyor mu? Tuhaf[ENTER]birisin... Kitaplarda ipucu aramaya devam edecegim.[ENTER]Fikrini degistirirsen geri gel. "
gameforge.subquest_33._60_say = "Boyle meydan okumalardan hoslanmiyor musun? O[ENTER]gizemli Haritanin parcalarini simdi nasil bulacagim[ENTER]ben?[ENTER][ENTER]Pekala oyleyse... gule gule. "
gameforge.subquest_33._70_say = "Sen gercek bir dostsun. Onu bulacagina guvenim[ENTER]tam. "
gameforge.subquest_33._80_sendLetter = "Hazine Haritasi. "
gameforge.subquest_33._90_targetVid = "Kitap Kurdu'na git. "
