gameforge.subquest_34._100_say = "Yuzbasi Siyah Ruzgar savascilariyla bas edemiyor.[ENTER]Generalleri Jak-To, To-Su ve Gu-Ryung'u oldur.[ENTER]Belki o zaman nihayet yatisirlar. "
gameforge.subquest_34._10_npcChat = "Peki ya Siyah Ruzgar Cetesi ne olacak? "
gameforge.subquest_34._110_say = "Generalleri oldurdun! "
gameforge.subquest_34._120_select = "Tekrar dene... "
gameforge.subquest_34._130_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_34._140_say = "Kazanmak kolay degil, ozellikle de generallere[ENTER]karsi. Tekrar dene. "
gameforge.subquest_34._150_say = "Dedigim gibi, Siyah Ruzgar gucludur. Elveda. "
gameforge.subquest_34._160_say = "Cok cesursun.[ENTER]Bu Ceteyi yenebilecegini dusunuyorum. "
gameforge.subquest_34._170_targetVid = "Yuzbasi'ya rapor ver "
gameforge.subquest_34._180_say = "Yuzbasi'ya don ve Siyah Ruzgar Cetesi generallerinin[ENTER]olumunu ona bildir. "
gameforge.subquest_34._185_npcChat = "Generalleri oldurdum! "
gameforge.subquest_34._190_say = "Generalleri maglup ettin. Komuta olmadan digerlerinin[ENTER]ustesinden gelmek kolay olacaktir. Onlar yuzunden[ENTER]gercekten basimiz donmustu ama sayende her sey bitti.[ENTER]Iste kucuk bir odul. Umarim tekrar gorusuruz. "
gameforge.subquest_34._200_sayReward = "1.000.000 Deneyim Puani kazandin. "
gameforge.subquest_34._20_sayTitle = "Yuzbasi "
gameforge.subquest_34._210_sayReward = "Lisan Yuzugu kazandin. "
gameforge.subquest_34._30_say = "Siyah Ruzgar Cetesi'nin birkac uyesini yenmis olsan[ENTER]da pes etmiyorlar. Sessizce oturmak yerine vahsi bir[ENTER]guruha donusuyorlar. Onlari yenmek istiyorsak Cete[ENTER]generallerini oldurmeliyiz. "
gameforge.subquest_34._40_say = "Generaller yenilir yenilmez digerleri hizla pes[ENTER]edecektir. Agir bir is olacak ama Siyah Ruzgar[ENTER]Cetesi'ne karsi galip gelmeliyiz. Generallerin[ENTER]isimleri sunlardir: Jak-To, To-Su ve Gu-Ryung.[ENTER]Onlari oldurdugumuzde Cete bize bir daha sorun[ENTER]cikarmayacaktir. Iyi sanslar ve bol avlar. "
gameforge.subquest_34._50_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_34._60_say = "Hazir oldugunda tekrar yanima gel. Senin kadar[ENTER]guclu pek fazla kisi yok. "
gameforge.subquest_34._70_say = "Oylece mi?! Onlari simdi nasil yenecegiz peki? "
gameforge.subquest_34._80_say = "Sana guvenebilecegimi biliyordum! Generaller[ENTER]oldurulur oldurulmez digerleri hemen teslim[ENTER]olacaktir. Basarilar! "
gameforge.subquest_34._90_sendLetter = "Siyah Ruzgar Cetesi generallerini oldur. "
gameforge.subquest_36 = {}
gameforge.subquest_36._100_sayTitle = "Seyis'e Git "
gameforge.subquest_36._10_targetVid = "Yonah: "
gameforge.subquest_36._110_say = "10 balya saman topladin. Atlari besleyebilmesi icin[ENTER]onlari Seyis'e gotur. "
gameforge.subquest_36._120_sayTitle = "Ahir icin saman "
gameforge.subquest_36._130_say = "Ahirlarda yem sikintisi var. 10 balya saman bul ve[ENTER]atlar acliktan telef olmadan once Seyis'e gotur![ENTER]Samani avlanarak elde edebilirsin. "
gameforge.subquest_36._140_npcChat = "Samana ihtiyacin var mi? "
gameforge.subquest_36._150_say = "Seni Yonah gonderdi herhalde?[ENTER]Senin hakkinda cok sey duydum.[ENTER]Ah, atlarimiz yetersiz beslenmeden oturu muzdarip.[ENTER]Hayatta kalmalarini saglamaliyiz. Bana yardim et ve[ENTER]atlar icin Saman bul! "
gameforge.subquest_36._160_say = "Soz sozdur. Ayrica ileride ata binmeyi denemek[ENTER]isterdim. Kesinlikle Saman bulmaliyim! "
gameforge.subquest_36._170_say = "Cok uzgunum. Cabaliyorum ama hicbir yerde Saman[ENTER]yok iste. "
gameforge.subquest_36._180_say = "Bekleyecegim ve basaracagini umuyorum.[ENTER]Kendi isimi senin ustune yikmak hic hos degil.[ENTER]Ama tekrar deneyebilir misin acaba?[ENTER][ENTER]Diger Krallikta birini taniyorum. Cok gucludur.[ENTER]Bana yardim edersen sana yardim etmesini ondan[ENTER]rica ederim. "
gameforge.subquest_36._190_select = "Aramaya devam et "
gameforge.subquest_36._200_say = "Elbette, sana yardim edecegim. O kadar gucum yok. "
gameforge.subquest_36._20_npcChat = "Atlarin basi dertte. "
gameforge.subquest_36._210_say = "O kadar enerjim yok. Yardim etmek isterdim ama[ENTER]yapamam. Yeterince guclu degilim. "
gameforge.subquest_36._220_npcChat = "Atlar icin Samanim var. "
gameforge.subquest_36._230_say = "Saman buldun mu? Oh, tesekkur ederim.[ENTER]Atlar icin yem kalmamisti ve bunu Yonah'a[ENTER]soylemistim. O benim iyi dostumdur. Birinden yardim[ENTER]isteyecegini ummustum. Ama yardimin bu kadar cabuk[ENTER]gelecegini dusunmemistim. Baksana atlar nasil da[ENTER]istahla yiyor! "
gameforge.subquest_36._250_sendLetter = "Yonah'a Donus "
gameforge.subquest_36._260_sayTitle = "Yonah'a Donus "
gameforge.subquest_36._270_say = "Ac atlar icin Seyis'e 10 balya Saman teslim ettin.[ENTER]Basarini Yonah'a bildir. "
gameforge.subquest_36._280_npcChat = "Atlar beslendi! "
gameforge.subquest_36._290_say = "Tekrar hos geldin![ENTER]Bu kadar cok Saman bulmak kesinlikle kolay[ENTER]olmamistir. Vazgecmedigin icin tesekkur ederim![ENTER]Iste senin icin kucuk bir odul. "
gameforge.subquest_36._30_say = "Hey, bir sorum var! Atlarla baskasinin[ENTER]ilgilendigini biliyorum ama o kisinin buyuk bir[ENTER]sorunu var... Atlar savas yuzunden cok bitkin dustu.[ENTER]Butun hayvanlar gibi onlarin da bir seyler yemesi[ENTER]gerek... "
gameforge.subquest_36._40_say = "Cok at var ama az yem var. Bircok at oluyor.[ENTER]Onlar icin yiyecek bir seyler bulabilir misin?[ENTER]Bu gorevi sadece sen yerine getirebilirsin. Atlar[ENTER]icin 10 porsiyon yem topla ve Seyis'e gotur. Seni[ENTER]benim gonderdigimi soylediginde ne oldugunu[ENTER]anlayacaktir. "
gameforge.subquest_36._50_select = "Derhal yola cikiyorum! "
gameforge.subquest_36._60_select = "Hayir, bu is benim onuruma yakismaz. "
gameforge.subquest_36._70_say = "Simdi giderek daha fazla insan ata binmek istiyor.[ENTER]Ancak yetersiz yem yuzunden at yetistiriciligi tam[ENTER]olarak gelistirilemiyor. Atlar acliktan oluyor.[ENTER]Fikrini degistirirsen geri gel. "
gameforge.subquest_36._80_say = "Ahh, atlar aci cekecek...[ENTER]Bununla yasamak zorundasin... "
gameforge.subquest_36._90_say = "Cok mesgul oldugunu biliyorum ve simdiye kadarki[ENTER]yardimlarini takdir ediyorum ama bir istisna yapamaz[ENTER]misin? Atlar su anda cok onemli. Ve Samana[ENTER]gercekten ihtiyacimiz var. "
gameforge.subquest_37 = {}
gameforge.subquest_37._100_say = "Yonah yeni porselenler uretmek icin elinden geleni[ENTER]yapiyor ama ne yazik ki deneylerinde yerinde sayiyor.[ENTER]Uriel'e git ve Seladon Porseleni hakkinda bir sey[ENTER]bilip bilmedigini sor. "
gameforge.subquest_37._10_targetVid = "Seladon porseleninin sirri "
gameforge.subquest_37._110_npcChat = "Seladon Porseleni hakkinda bir sey biliyor musun? "
gameforge.subquest_37._120_sayTitle = "Uriel: "
gameforge.subquest_37._130_say = "Seladon Porseleni mi? Tarihten anlarim ve fizikten[ENTER]genis bir bilgi birikimim vardir ama sanat ilgimi[ENTER]cekmez. Sana Seladon Porseleni hakkinda hicbir sey[ENTER]soyleyemem. Ama belki Soon bir seyler biliyordur...[ENTER]Pek haz etmem kendisinden... ama o kadar cok farkli[ENTER]kitap okuyor ki... onun hakkinda bir seyler biliyor[ENTER]olmasi muhtemeldir. "
gameforge.subquest_37._140_makequestbutton = "Soon'a git. "
gameforge.subquest_37._150_targetVid = "Soon'a git "
gameforge.subquest_37._160_say = "Uriel Seladon Porseleni hakkinda hicbir sey[ENTER]bilmiyor ama Kitap Kurdu Soon cok bilgilidir. Yanina[ENTER]git ve uretim yontemleri hakkinda bir sey bilip[ENTER]bilmedigini sor. "
gameforge.subquest_37._170_sayTitle = "Soon: "
gameforge.subquest_37._180_say = "Ne istiyorsun? Okurken beni rahatsiz etme! Ne?[ENTER]Seladon Porseleni mi? Elbette biliyorum. Ne de olsa[ENTER]porselene adanmis onlarca kitap okudum. Neden[ENTER]soruyorsun? Bosuna bana Kitap Kurdu demiyorlar![ENTER]Kitaplarda ne yaziyorsa hepsini mukemmel anlarim! "
gameforge.subquest_37._190_say = "Seladon Porseleni'nin uretim yontemlerini ezbere[ENTER]biliyorum ama bunlari sana neden aciklayayim ki?[ENTER]Hmm, bekle. Bir fikrim var! Komsu koydeki bir[ENTER]Seyyar Satici'dan ihtiyacim olan bir kitabi istemistim[ENTER]ama kendim gidip almaya vaktim yok. Lutfen onu bana[ENTER]getir, ben de sana porselen konusunda yardim edeyim.[ENTER]Yola cik! "
gameforge.subquest_37._200_makequestbutton = "Seyyar Satici'ya git. "
gameforge.subquest_37._20_sayTitle = "Yonah: "
gameforge.subquest_37._210_targetVid = "Seyyar Satici'ya git "
gameforge.subquest_37._220_say = "Kitap kurdu Soon Seladon Porseleni hakkinda bir[ENTER]seyler biliyor. Ama bunu sana sadece Seyyar[ENTER]Satici'ya siparis ettigi kitabi getirirsen[ENTER]soyleyecektir. Yola koyul! "
gameforge.subquest_37._230_npcChat = "Beni Soon gonderdi... "
gameforge.subquest_37._240_say = "Selam! Bana yardim etmeye mi geldin? Aaa, Soon[ENTER]icin olan kitabi istiyorsun? Yakinda koye gitme[ENTER]niyetindeydim, neyse, o pek sabirsiz biri.[ENTER]Esyalari icin baskalarini gonderiyor. Hmm... Iste[ENTER]Kitap. Bu kagit yigininda bu kadar onemli olan ne[ENTER]anlamiyorum. Oysa Yang kazanmak cok daha onemlidir! "
gameforge.subquest_37._250_qSetTitle = "Soon'a Donus "
gameforge.subquest_37._260_targetVid = "Soon'a Donus "
gameforge.subquest_37._270_say = "Kitabi Seyyar Satici'dan aldin. Soon'a git ve[ENTER]kitabini ver ki sonunda Porselen uretim yontemlerini[ENTER]aciklasin. "
gameforge.subquest_37._280_npcChat = "Kitap Bende! "
gameforge.subquest_37._290_say = "Yasasin! Sonunda Kitabima kavustum! Tesekkur[ENTER]ederim. Henuz okumadigim pek fazla kitap kalmadi[ENTER]zaten... Bu Seladon Porseleni hakkinda bildigim her[ENTER]seyi sana yazacagim. Talimatlara uyarsan harika bir[ENTER]porselen uretirsin. Simdi yeni kitabi okuma zamani.[ENTER]Elveda. "
gameforge.subquest_37._300_makequestbutton = "Yonah'a Donus "
gameforge.subquest_37._30_say = "Hm... bu ise yaramaz. Bu da olmaz... Oh, baksana![ENTER]Araliksiz Porselen uretiyorum ama esyalarin cogu[ENTER]catliyor. Sanirim Porselen uretimi icin yeni bir[ENTER]tarife ihtiyacim var. "
gameforge.subquest_37._310_targetVid = "Notlari Yonah'a teslim et. "
gameforge.subquest_37._320_say = "Soon sozunu tuttu ve senin icin Porselen uretim[ENTER]tarifini yazdi. Onu Yonah'a gotur. "
gameforge.subquest_37._330_say = "Ooooh!!! Seladon Porseleni uretimiyle ilgili her[ENTER]sey burada var! Bu tarif sayesinde porselen ustasi[ENTER]olarak tarihe gececegim. Yardimin icin tesekkurler.[ENTER]Yakinda sana en iyi seramikleri sunacagim! Guven[ENTER]bana. Porselenim caglar boyu ayakta kalacak! "
gameforge.subquest_37._340_sayReward = "2.500.000 Deneyim Puani kazandin. "
gameforge.subquest_37._350_sayReward = "35.000 Yang kazandin. "
gameforge.subquest_37._360_sayReward = "Yesim Tasi Ayakkabi+3 kazandin. "
gameforge.subquest_37._40_say = "Yeni bir yontem deneyecegim... Seladon Porseleni[ENTER]uretmek kolay degildir. Bu yuzden onu nasil[ENTER]yapacagini cok az kisi bilir. Yine de sanatima[ENTER]katmak icin ona ihtiyacim var. Bu durumda... evet,[ENTER]Uriel bana bu konuda yardim edebilir. Lutfen Uriel'e[ENTER]git ve bu Porselenin nasil yapildigini sor. Kesinlikle[ENTER]yardimci olabilecektir! "
gameforge.subquest_37._50_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_37._60_say = "Hm, mesgul musun?[ENTER]Daha fazla vaktin oldugunda beni tekrar ziyaret[ENTER]etmeyi unutma. "
gameforge.subquest_37._70_say = "En iyi porseleni uretmek istiyorum...[ENTER]Anliyorum... Gorusmek uzere! "
gameforge.subquest_37._80_say = "Tesekkur ederim. Uriel kesinlikle yardim edecektir.[ENTER]Simdilik hosca kal! "
gameforge.subquest_37._90_targetVid = "Uriel'e git "
gameforge.subquest_38 = {}
gameforge.subquest_38._100_say = "Avci Yang-Shin'in aile yadigari olan Suslu Yayi[ENTER]calindi.[ENTER]Sangsun Dong'a git ve Yayi hirsiz maymunlardan geri[ENTER]al. "
gameforge.subquest_38._10_targetVid = "Avcinin Hazinesi "
gameforge.subquest_38._110_sendLetter = "Suslu Yayi Buldun! "
gameforge.subquest_38._120_targetVid = "Avci Yang-Shin'e git "
gameforge.subquest_38._125_say = "Avcinin Suslu Yayini buldun.[ENTER]Onu Yang-Shin'e geri ver. "
gameforge.subquest_38._130_npcChat = "Iste Yay... "
gameforge.subquest_38._140_say = "Vay canina, iste burada! Yayim, hayran kaldim![ENTER]Onurum kurtuldu.[ENTER]Huh... Kaybi yuzunden ne kadar uzun sure aci cektim.[ENTER]Yardimin icin cok minnettarim. Bunu sana vermek[ENTER]benim icin bir onurdur. Fazla bir sey olmayabilir[ENTER]ama yurekten geliyor ve en onemlisi de bu. Sayende[ENTER]huzur icinde yasayabilirim. "
gameforge.subquest_38._150_sayReward = "1.500.000 Deneyim Puani kazandin. "
gameforge.subquest_38._160_sayReward = "35.000 Yang kazandin. "
gameforge.subquest_38._170_sayReward = "Cesaret Pelerini kazandin. "
gameforge.subquest_38._180_say = "Yayimi buldun mu? Nerede peki? Yoksa kaybettin[ENTER]mi bile? "
gameforge.subquest_38._190_select = "Aramaya devam edecegim. "
gameforge.subquest_38._200_say = "Oyle olsun bakalim.[ENTER]Kendine dikkat et. "
gameforge.subquest_38._20_say = "Hey, bir dakikan var mi? Gordugun gibi ben bir[ENTER]avciyim, ailem nesillerdir avcilik yapar. Ailemin[ENTER]hepsi avciydi, bu koklu bir gelenektir.[ENTER]Ama ailemin gozunde beni rezil edecek buyuk bir[ENTER]hata yaptim... "
gameforge.subquest_38._210_say = "Bir kez daha deneyecek misin? Tesekkur ederim.[ENTER]Yeteneklerinle kesinlikle basaracaksin. "
gameforge.subquest_38._30_say = "Az once Maymunlar tarafindan calinan Gosterisli[ENTER]Suslu Yay soz konusu. Maymun Zindani'nda avdaydim,[ENTER]sadece bir anligina arkami dondum ve durumu firsat[ENTER]bilip onu benden caldilar. "
gameforge.subquest_38._40_say = "Maymun Zindani'nin derinliklerine hic gitmedim[ENTER]ve oranin nasil bir yer oldugunu bilmiyorum.[ENTER]Yardimina ihtiyacim var. Birkac kisiden cok[ENTER]yetenekli biri oldugunu duydum. Bu yuzden bu iyiligi[ENTER]ozellikle senden istiyorum. O Yay olmadan ailemin[ENTER]karsisina cikamam. "
gameforge.subquest_38._50_sayTitle = "Yang-Shin: "
gameforge.subquest_38._60_say = "Onu hemen geri almaliyim... Lutfen vaktin[ENTER]oldugunda geri gel. Selamlar. "
gameforge.subquest_38._70_say = "Demek oyle...[ENTER]Yolculuklarinda tetikte ol. "
gameforge.subquest_38._80_say = "Onu bulmak zor degildir cunku cok gosterisli bir[ENTER]sekilde suslenmistir. Bunun icin seni iyi[ENTER]odullendirecegim! "
gameforge.subquest_38._90_sayTitle = "Suslu Yayi Bul "
