gameforge.subquest_39._160_sayTitle = "Baek-Go: "
gameforge.subquest_39._170_say = "Oh, sen misin, nasilsin?[ENTER]Bir hastayi mi tedavi ediyorsun? Nesi var peki...[ENTER]Hmm... Simdiye kadar hangi ilaclari aliyordu?[ENTER]Ne dedin? Durumunun kotulesmesine sasmamali! Bu[ENTER]ilaclar tamamen uygunsuz! "
gameforge.subquest_39._180_say = "H�l� hayatta olduguna dua etsin![ENTER]Bir hastayi yanlis tedavi etmek cok tehlikelidir![ENTER]Ama ona nasil yardim edecegimi biliyorum. Vucudu[ENTER]zehirli maddelerden arindiran ve iyilesmeyi[ENTER]destekleyen bir bitki var. Ancak bu bitkiyi elde[ENTER]etmek buyuk bir risk tasir. "
gameforge.subquest_39._190_say = "Bildigim kadariyla bu bitki yalnizca Sangsun[ENTER]Dong'da yetisir. Onu yemeyi cok seven Maymun Lordu[ENTER]icin toplanir hep. Bu bitkiyi alabilmek icin onu[ENTER]oldurmen gerekecek.[ENTER]Onu bana getirirsen ondan uygun ilaci hazirlarim. "
gameforge.subquest_39._200_select = "Guzel, onu bulacagim. "
gameforge.subquest_39._20_npcChat = "Ilacin ile ilgili olarak... "
gameforge.subquest_39._210_select = "Bunu yapamam. "
gameforge.subquest_39._220_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_39._230_select = "Evet "
gameforge.subquest_39._240_say = "O zaman belki daha sonra, daha fazla vaktin[ENTER]oldugunda. Bircok insan hasta ama onlar icin ilac[ENTER]arayan cok az kisi var. "
gameforge.subquest_39._250_say = "Hmm, ne yazik ki durum tam olarak boyle. Kimsenin[ENTER]bu kadar cesareti olmamasi ne aci. Bundan sonra[ENTER]nasil olacak bilmiyorum... "
gameforge.subquest_39._260_say = "Oh, Tesekkur ederim. Gorev kolay degil ama bunu[ENTER]yerine getirerek bircok insana yardim etmis[ENTER]olacaksin! "
gameforge.subquest_39._270_makequestbutton = "Maymun Lordu Bitkisi "
