gameforge.subquest_40._190_say = "Gercekten vazgecmek istiyor musun?[ENTER]Hmm, belki de cok zordur...[ENTER]Baskasina sorarim. Tamam, gorusmek uzere. "
gameforge.subquest_40._200_say = "Aha...[ENTER]Asla pes etmiyorsun, degil mi?[ENTER]O halde, yola cik! "
