gameforge.subquest_41._150_sayTitle = "Octavio: "
gameforge.subquest_41._160_say = "Goster bakalim. Evet, tami tamina yuz adet,[ENTER]mukemmel. Hum, bakalim...[ENTER]Mmhhh, hazir! Tatmak ister misin? Korkma.[ENTER]Seni oldurmez. "
gameforge.subquest_41._170_say = "Hmm, hmm... Ne muazzam bir deneyim! Cok besleyici[ENTER]ama asiri tatli da degil... Gercekten inanilmaz[ENTER]bir lezzet! Buna degecegini biliyordum. Tek basima[ENTER]asla basaramazdim. Yardimin icin cok tesekkurler! "
gameforge.subquest_41._180_sayReward = "2.100.000 Deneyim Puani kazandin. "
gameforge.subquest_41._190_say = "Neden bahsediyorsun sen? Bunlar kesinlikle yuz[ENTER]tane degil, saymadan bile biliyorum! Lutfen benim[ENTER]icin daha fazlasini bul. "
gameforge.subquest_41._200_say = "Bu yemegi yapmayi gercekten cok istiyordum...[ENTER]Bos ver... tesekkurler. Elveda. "
gameforge.subquest_41._20_say = "Selam, nasilsin? Su an Soon'dan aldigim yemek[ENTER]kitabina goz atiyordum. Icinde 'Orumcek Gozu[ENTER]Lezzeti' adinda bir yemek tarifi buldum. Boyle bir[ENTER]seyi hic duymamistim, ya sen? Buyuk olasilikla[ENTER]baska bir ulkeden gelen essiz bir yemektir. "
gameforge.subquest_41._210_say = "Beni zor durumumda yalniz birakmadigin icin[ENTER]tesekkur ederim. Cok naziksin! "
gameforge.subquest_41._30_say = "Bu yemegi tatmayi cok isterdim ama Orumcek[ENTER]Gozlerini tek basima nasil bulurum ki? Gercekten[ENTER]tekrar yardimina ihtiyacim var! Lutfen benim icin[ENTER]Orumcek Gozleri bul. Onlari Yongbi Colu'nde yasayan[ENTER]orumceklerden elde edebilirsin. "
gameforge.subquest_41._40_say = "Bunu benim icin yapabilir misin? Cok minnettar[ENTER]kalirim. Bu yemegi yeterince buyuk bir porsiyonda[ENTER]hazirlayabilmek icin yuz adet goze ihtiyacim var.[ENTER]Gercekten cok heyecanliyim... "
gameforge.subquest_41._50_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_41._60_say = "Bu yemegi hazirlamayi gercekten cok istiyorum.[ENTER]Benim icin vakit buldugunda ugraman yeterli. "
gameforge.subquest_41._70_say = "Hm, o gozleri nereden bulmali peki?[ENTER]Tamam... Gorusmek uzere. "
gameforge.subquest_41._80_say = "Sag ol, sana guvenebilecegimi biliyordum![ENTER]Bunun karsiliginda sana harika bir yemek pisirecegim. "
gameforge.subquest_41._90_sayTitle = "Octavio'ya Don "
gameforge.subquest_42 = {}
gameforge.subquest_42._100_say = "Bunu duyduguma uzuldum. Huzur bulamayan o kadar[ENTER]cok sehidin sesini duyuyorum ki.[ENTER]Onlara gercekten yardim etmeliyiz.[ENTER]Yardim icin baskasina basvuracagim. Elveda. "
gameforge.subquest_42._10_targetVid = "Sehitlerin huzur bulmasini saglayalim... "
gameforge.subquest_42._110_say = "O kadar cesursun ki. Yardimin sayesinde cesur[ENTER]savascilar cok yakinda huzura kavusacak. "
gameforge.subquest_42._120_say = "Korkunc savaslar olen insanlarin sayisini[ENTER]artiriyor. Savascilar cephe hattinda kendileri,[ENTER]aileleri ve Kralliklari icin savasiyorlar.[ENTER]Ancak oldukten sonra bir kismi cennete gidemiyor,[ENTER]bu dunyada kaliyor. "
gameforge.subquest_42._130_say = "Karanlik Tapinak'taki Kibirli Karanlik Liderlerin[ENTER]Tapinak Atkisi ve Tapinak Ogretisi tasidiklarini[ENTER]duydum. Lutfen bana ve yoldaslarima, kralligi[ENTER]savunurken olen sehitlerin ruhlarini huzura[ENTER]kavusturmamizda yardim et. "
gameforge.subquest_42._140_sayTitle = "Ejderha Gucu Egitmenine Don "
gameforge.subquest_42._150_say = "Tapinak Atkisi ve Tapinak Ogretisini buldun.[ENTER]Samanlarin sehitleri huzura kavusturmayi amaclayan[ENTER]rituele baslayabilmeleri icin onlari Ejderha Gucu[ENTER]Egitmenine gotur. "
gameforge.subquest_42._160_sayTitle = "Tapinak Atkisi ve Tapinak Ogretisi Bul. "
gameforge.subquest_42._170_say = "Samanlar, savasta sehit dusen savascilarin ruhlarini[ENTER]huzura kavusturmayi amaclayan toreni gerceklestirmek[ENTER]icin Tapinak Atkisi ve Tapinak Ogretisine ihtiyac[ENTER]duyuyorlar. Gerekli esyalari elde etmek icin Hwang[ENTER]Tapinagi'nda bulunan Kibirli Karanlik Lider'i oldur. "
gameforge.subquest_42._180_npcChat = "Atki ve Ogreti bende. "
gameforge.subquest_42._190_say = "Bu inanilmaz bir seydi. Artik sehit askerlerin[ENTER]ruhlarini huzura kavusturabiliriz. Harika bir is[ENTER]cikardilar. Artik huzur icinde yatabilirler.[ENTER]Bu asil davranisin icin sana bir odul vermeme izin[ENTER]ver. "
gameforge.subquest_42._200_sayReward = "1.700.000 Deneyim Puani kazandin. "
gameforge.subquest_42._20_sayTitle = "Ejderha Gucu Egitmeni: "
gameforge.subquest_42._210_sayReward = "30.000 Yang kazandin. "
gameforge.subquest_42._220_sayReward = "3 adet Elmas kazandin. "
gameforge.subquest_42._230_say = "Bu inanilmaz bir seydi. Artik sehit askerlerin[ENTER]ruhlarini huzura kavusturabiliriz. Harika bir is[ENTER]cikardilar. Artik huzur icinde yatabilirler.[ENTER]Bu asil davranisin icin sana bir odul vermeme izin[ENTER]ver. "
gameforge.subquest_42._30_say = "Korkunc savaslar olen insanlarin sayisini[ENTER]artiriyor. Savascilar cephe hattinda kendileri,[ENTER]aileleri ve Kralliklari icin savasiyorlar.[ENTER]Ancak oldukten sonra bir kismi cennete gidemiyor,[ENTER]bu dunyada kaliyor. "
gameforge.subquest_42._40_say = "Savas sirasinda olume karsi direncli olduklari[ENTER]soyleniyor. Kralliklarini savunmak zorunda[ENTER]olduklarina h�l� inaniyorlar. Samanlarimiz onlarin[ENTER]ruhlarini huzura kavusturacak bir ayin yapmak[ENTER]istiyor. Bunu gerceklestirmek icin ozel bir Tapinak[ENTER]Atkisi ve Tapinak Ogretisi gerekecek. Gunumuzde[ENTER]bunlari bulmak zordur. Bu esyalari bulabilir misin? "
gameforge.subquest_42._50_say = "Karanlik Tapinak'taki Kibirli Karanlik Liderlerin[ENTER]Tapinak Atkisi ve Tapinak Ogretisi tasidiklarini[ENTER]duydum. Lutfen bana ve yoldaslarima, kralligi[ENTER]savunurken olen sehitlerin ruhlarini huzura[ENTER]kavusturmamizda yardim et. "
gameforge.subquest_42._60_select = "Sana yardim edecegim. "
gameforge.subquest_42._70_select = "Üzgunum, bu cok korkunc... "
gameforge.subquest_42._80_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_42._90_say = "Huzur icinde yatabilmeleri icin ruhlarini[ENTER]yatistirmamiza yardim et. Seni burada bekliyor[ENTER]olacagim. "
gameforge.subquest_44 = {}
gameforge.subquest_44._100_sendLetter = "Cingirakli orumcek "
gameforge.subquest_44._10_targetVid = "Orumcek "
gameforge.subquest_44._110_say = "Taurean bir Orumcege cingirak taktigini soyledi.[ENTER]Ve simdi Yu-Rang arkadasinin gercekten o kadar cesur[ENTER]olup olmadigini gormek istiyor. Colde o Orumcegi bul. "
gameforge.subquest_44._120_say = "Cingirakli Orumcegi buldun mu? Hayir mi?[ENTER]Muhtemelen onu asla bulamayacaksin. Taurean bir[ENTER]korkaktir ve sadece oyle boburleniyordu! "
gameforge.subquest_44._130_sendLetter = "Cingiragi bulamadin "
gameforge.subquest_44._140_sayTitle = "Cok orumcek var, hic cingirak yok "
gameforge.subquest_44._150_say = "Zaten bircok Orumcek oldurdun ama henuz uzerinde[ENTER]Cingirak olan bir tanesini bile bulamadin. Sonsuza[ENTER]dek onu arayamazsin ya. Taurean'i bulup ona gercegi[ENTER]sormak cok daha kolay degil mi? "
gameforge.subquest_44._160_sendLetter = "Taurean'a Git "
gameforge.subquest_44._170_targetVid = "Taurean'a cingiragi sor "
gameforge.subquest_44._180_say = "Taurean'in bu kadar cesur olduguna inanmak zor.[ENTER]Bir Orumcege Cingirak asmak oyle kolay is degildir.[ENTER]Sadece yanina git ve bunun dogru olup olmadigini sor. "
gameforge.subquest_44._190_npcChat = "Yu-Rang ile girdigin iddiayi anlat... "
gameforge.subquest_44._200_say = "Evet! Yu-Rang ile olan iddiayi biliyor musun?[ENTER]Bana aslinda hic inanmiyor ve bunu yapmadigimi[ENTER]dusunuyor. Bir Orumcek gordugum an korkudan dusup[ENTER]olecegimi saniyor. "
gameforge.subquest_44._20_npcChat = "Cingirakli orumcek mi...? "
gameforge.subquest_44._210_say = "Dogruyu soylemek gerekirse... Sey evet, aslinda[ENTER]hakli. Gercegi soylemeye cesaret edemedim cunku[ENTER]fazla gururluyum. "
gameforge.subquest_44._220_say = "Cok guclu gorunuyorsun! Yavru bir Orumcege[ENTER]Cingirak takip bunu benim yaptigimi soyleyemez[ENTER]misin? Sana yalvariyorum! Yoksa hayatim boyunca[ENTER]benimle dalga gececek. "
gameforge.subquest_44._230_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_44._240_say = "Bunu yapmak istemiyor musun? Ama her seyi Yu-Rang'a[ENTER]anlatmayacaksin degil mi?! Lutfen bana yardim et.[ENTER]Biraz vaktin oldugunda tekrar yanima ugra! "
gameforge.subquest_44._250_say = "Artik Yu-Rang benimle asla konusmayacak ya da[ENTER]benimle dalga gececek... "
gameforge.subquest_44._260_say = "Gercekten cok naziksin. Yardimin icin tesekkurler.[ENTER]Iyi sanslar! "
gameforge.subquest_44._270_sendLetter = "Yu-Rang'a Don "
gameforge.subquest_44._280_say = "Yu-Rang'a don ve Taurean'in yalan soyledigini[ENTER]ona bildir. "
gameforge.subquest_44._290_npcChat = "Yu-Rang sana guvenini kaybetti. "
gameforge.subquest_44._300_say = "Ona soyledin mi?![ENTER]Artik neden arkadasim olmak istemedigini anlayabiliyorum.[ENTER]Bu beni cok uzdu ama yine de bir gun fikrini[ENTER]degistirecegini umuyorum. Belki aklima onu[ENTER]sasirtabilecegim harika bir fikir gelir... "
gameforge.subquest_44._30_say = "Hey, benim icin bir sey yapabilir misin? Arkadasim[ENTER]Taurean ona korkak dedigim icin bana sik sik kizar.[ENTER]Tam tersi oldugunu ve cok cesur oldugunu soyler.[ENTER]Yavru bir Orumcege Cingirak takip takamayacagi[ENTER]konusunda iddiaya girdik. Yaptigini soyledi ama buna[ENTER]pek inanasim gelmiyor. "
gameforge.subquest_44._310_npcChat = "Taurean yalan soyledi. "
gameforge.subquest_44._320_say = "Demek bana yalan soyledi ha?[ENTER]Hmm, mesele artik yalan degil, kimsenin beceriksiz[ENTER]gorunmek istemeyecegini anliyorum elbette. Ama en[ENTER]azindan bu hikayenin gercek gibi gorunmesi icin[ENTER]caba gostermeliydi. Boyle bir korkakla arkadas olmak[ENTER]istemiyorum. "
gameforge.subquest_44._330_sayReward = "Yu-Rang durustlugun icin sana bir odul verecek. "
gameforge.subquest_44._340_sayReward = "30.000 Yang kazandin. "
gameforge.subquest_44._350_sayReward = "350.000 Deneyim Puani kazandin. "
gameforge.subquest_44._360_sendLetter = "Orumcek icin cingirak "
gameforge.subquest_44._370_say = "Cole, Yavru Orumceklerin yanina git ve Taurean'dan[ENTER]aldigin Cingiragi onlardan birine takmaya calis. "
gameforge.subquest_44._380_npcChat = "Cingirak hakkinda... "
gameforge.subquest_44._390_say = "Cingiragi taktin mi? Henuz degil mi? Lutfen acele[ENTER]et o zaman. Ve Yu-Rang'in seni bunu yaparken[ENTER]yakalamamasina dikkat et. "
gameforge.subquest_44._400_sendLetter = "Yapildi! "
gameforge.subquest_44._40_say = "Arkadasima guvenmem gerektigini biliyorum ama bunu[ENTER]gercekten yapip yapmadigini bilmek istiyorum. Oraya[ENTER]gidip kontrol etmek benim icin cok tehlikeli.[ENTER]Sen cok guclu gorunuyorsun, kesinlikle ustesinden[ENTER]gelirsin. Oraya gidip bunu benim icin kontrol[ENTER]edebilir misin? "
gameforge.subquest_44._410_say = "Cok zordu ama sonunda Yavru bir Orumcege Cingirak[ENTER]takmayi basardin. Simdi Yu-Rang'a don ve Orumcege[ENTER]Cingiragi Taurean'in taktigini soyle. "
gameforge.subquest_44._420_npcChat = "Cingirak orumcege takildi. "
gameforge.subquest_44._430_say = "Bunu basardin mi? Harika![ENTER]Lutfen simdi bunu Yu-Rang'a anlat ki nihayet bana[ENTER]inansin. "
gameforge.subquest_44._440_npcChat = "Taurean yalan soylemedi. "
gameforge.subquest_44._450_say = "Ne? Gercekten Cingirakli Orumcek buldun mu? Bu,[ENTER]Taurean'in bunu gercekten yaptigi anlamina gelir.[ENTER]Bunun mumkun olmadigini saniyordum. Belki bir gun[ENTER]gercek bir erkek olur. Bunu benim icin kontrol[ENTER]ettigin icin tesekkurler. Iste odulun. "
gameforge.subquest_44._460_sendLetter = "Taurean'a Don "
gameforge.subquest_44._470_targetVid = "Taurean'a Don "
gameforge.subquest_44._480_say = "Yu-Rang'a arkadasinin gercekten de Yavru bir[ENTER]Orumcege cingirak taktigini soyledin.[ENTER]Simdi Taurean'a don ve her seyi ona anlat. "
gameforge.subquest_44._490_npcChat = "Yu-Rang sana inaniyor. "
gameforge.subquest_44._500_say = "Cok tesekkur ederim. Artik Yu-Rang beni kucuk[ENTER]gormeyecek. Bu sonsuza kadar bizim sirrimiz olsun,[ENTER]olur mu? Soz veriyor musun? Yakinda gorusmek uzere! "
gameforge.subquest_44._50_select = "Kabul et "
gameforge.subquest_44._510_sayReward = "Taurean yalanina yardim ettigin icin sana bir odul[ENTER]veriyor: "
gameforge.subquest_44._520_sayReward = "700.000 Deneyim Puani kazandin. "
gameforge.subquest_44._60_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_44._70_say = "Neden olmasin? Korkuyor musun?[ENTER]Fikrini degistirdiginde yanima don. "
gameforge.subquest_44._80_say = "Aaah, korkuyor musun? Oysa benden cok daha uzun[ENTER]ve guclusun! Hahaha, ne korkak ama! O halde baskasindan[ENTER]rica ederim. "
gameforge.subquest_44._90_say = "Orumcekler colde yasarlar. Gercekten cok guclusun.[ENTER]Basaracagindan hic suphem yok. Iyi sanslar! "
