gameforge.subquest_45._100_sayTitle = "Gizli bilgileri ele gecir "
gameforge.subquest_45._10_npcChat = "Karanlik Tapinak ile Ilgili Sorun "
gameforge.subquest_45._110_say = "Tapinak Ogretisi, Tapinak Atkisi ve Lanet Kitabi[ENTER]Cevirisi sende. Bu esyalari Soon'a gotur. "
gameforge.subquest_45._120_say = "Kitap Kurdu Soon'a yardim edersen Karanlik[ENTER]Tapinak ile ilgili arastirmalarina devam edebilecektir.[ENTER]Daha fazla arastirma ancak su esyalarin elde[ENTER]edilmesinden sonra mumkun olacaktir: Tapinak[ENTER]Ogretisi, Tapinak Atkisi ve Lanet Kitabi Cevirisi.[ENTER]Bu esyalari temin et ve Soon'a gotur. Onlari[ENTER]Seungryong Vadisi'ndeki Hwang Tapinagi'nda[ENTER]bulabilirsin. "
gameforge.subquest_45._130_npcChat = "Karanlik Tapinak esyalari "
gameforge.subquest_45._140_say = "Ah, istedigim seyleri buldun! Tesekkur ederim.[ENTER]Tapinaktaki yaratiklara gelince, bu basit bir mesele.[ENTER]Kendi teninde hissettigin gibi onlar tehlikelidirler.[ENTER]Ayrica kotu tanrilara hizmet ediyorlar. Ayrintilari[ENTER]bilmiyorum ama sinsi planlari oldugundan supheleniyorum. "
gameforge.subquest_45._150_say = "Artik kutsal emanetlerinden bazilarina sahip olduguma[ENTER]gore daha fazlasini ogrenmeliyim. Sanirim Tapinak[ENTER]Ogretisi ile baslayacagim.[ENTER]Bir dakika.... hmmm... aha...[ENTER]Neden h�l� burada duruyorsun? Yapacak daha iyi bir[ENTER]isin yok mu senin? "
gameforge.subquest_45._160_sayReward = "7.000.000 Deneyim Puani kazandin. "
gameforge.subquest_45._170_sayReward = "70.000 Yang kazandin. "
gameforge.subquest_45._180_sayReward = "Liderin Kitabi kazandin. "
gameforge.subquest_45._190_say = "Ne? Yaninda yoklar mi? Acele et, yapacak bir isin[ENTER]var senin![ENTER]Hadi ama, cabuk! "
gameforge.subquest_45._200_select = "Tekrar dene "
gameforge.subquest_45._20_say = "Karanlik Tapinak'ta bir seyler donuyor.[ENTER]Tehlikeli varliklar orada kadim buyu uzerinde[ENTER]calisiyor olmali.[ENTER]Karanlik Tapinak'in bu sirlarini cozmek benim icin[ENTER]bile cok zor. Ama bu varliklarin niyetlerinin asil[ENTER]olmadigindan eminim. Daha fazlasini ogrenmeliyim! "
gameforge.subquest_45._210_say = "Bu durumda daha cesur bir kahramana sormak[ENTER]zorunda kalacagim. Hosca kal. "
gameforge.subquest_45._220_say = "Tesekkur ederim![ENTER]Umarim bu sefer basarili olursun! "
gameforge.subquest_45._30_say = "Daha kapsamli bir analiz yapabilmek icin daha[ENTER]fazla bilgiye ihtiyacim var. Tapinak Ogretisi,[ENTER]Tapinak Atkisi ve Lanet Kitabi Cevirisi'nin bana[ENTER]yardimci olacagini dusunuyorum.[ENTER]Bu esyalari benim icin temin edebilir misin? Sana[ENTER]cok minnettar kalirdim. Ve fazla oyalanma,[ENTER]onlara bir an once ihtiyacim var! "
gameforge.subquest_45._40_select = "Gidiyorum. "
gameforge.subquest_45._50_say = "Bunu yapmak istiyor musun? "
gameforge.subquest_45._60_say = "Senden yardim istiyorum![ENTER]Su an mesgulsen daha fazla vaktin oldugunda gel.[ENTER]Seni bekliyor olacagim. "
gameforge.subquest_45._70_say = "Ben senden yardim istiyorum, sense oylece arkana[ENTER]bakmadan gidiyor musun?[ENTER]Aman, yardimina hic ihtiyacim yok zaten... Cekil git[ENTER]buradan! "
gameforge.subquest_45._80_say = "Sag ol! "
gameforge.subquest_45._90_makequestbutton = "Karanlik Tapinak "
