gameforge.subquest_46._10_targetVid = "Seladon porseleninin sirri "
gameforge.subquest_46._110_makequestbutton = "Seladon Porseleni "
gameforge.subquest_46._120_qSetTitle = "Seladon Porseleni "
gameforge.subquest_46._130_say = "Yonah'in Seladon Porseleni yapabilmesi icin gereken[ENTER]tum malzemeleri buldun. Onlari ona gotur. "
gameforge.subquest_46._140_say = "Yonah Seladon Porseleni uretebilir ancak su[ENTER]malzemelere ihtiyaci var: Yongbi Colu'ndeki Col[ENTER]Haydutlarindan Col Kumu, Kristal Damarindan 50x[ENTER]Kristal Cevheri ve Guclu Kaya Maymunlarindan veya[ENTER]Guclu Altin Maymunlardan Maymun Kani. Tum malzemeleri[ENTER]topla ve Yonah'a teslim et. "
gameforge.subquest_46._150_targetVid = "Seladon porseleninin sirri "
gameforge.subquest_46._160_npcChat = "Butun malzemeleri topladim "
gameforge.subquest_46._170_say = "Basardin! Sana cok tesekkur ederim![ENTER]Ozel bir teknik ve dogru malzemeler sayesinde goz[ENTER]alici bir Seladon Porseleni uretebilirim. Satisindan[ENTER]elde edilecek gelirler nihayet kesemi dolduracak.[ENTER]Al lutfen, iste odulun, bunu hak ettin. Ben de[ENTER]hemen ise koyuluyorum! "
gameforge.subquest_46._180_sayReward = "3.000.000 Deneyim Puani kazandin. "
gameforge.subquest_46._190_sayReward = "30.000 Yang kazandin. "
gameforge.subquest_46._20_say = "Selam maceraci! Gecenlerde Soon'un Seladon[ENTER]Porseleni yapma tarifini bana getiren sen degil[ENTER]miydin? Yine de bir sorunum daha var... Artik[ENTER]teknigi bilsem de gercek bir Seladon Porseleni[ENTER]uretmeyi basaramiyorum. Muhtemelen bunu tarifteki[ENTER]elde edilmesi zor malzemeler yerine standart[ENTER]malzemelerimle yapmaya calistigim icindir. "
gameforge.subquest_46._30_say = "Kil icin ozel Col Kumuna, 50 adet Kristal Cevherine[ENTER]ve Maymun Kanina ihtiyacim var. Bu malzemeler[ENTER]karistirilip Kile eklenirse pisirme sirasinda cok[ENTER]sertlesir. Sir tabakasi o zaman Yesim Tasini andiran[ENTER]tipik seladon tonunu alir. Bu renk musteriler[ENTER]arasinda cok populerdir ve bir an once daha fazla[ENTER]satmaliyim! "
gameforge.subquest_46._40_say = "Col Kumunu Col Haydutlarindan, Kristal Cevherini[ENTER]Kristal Damarindan, Maymun Kanini ise Sangsun[ENTER]Dong'daki Maymunlari oldurerek elde edersin. Bu[ENTER]malzemeleri benim icin bulabilir misin? Kolay[ENTER]olmayacagini biliyorum ama seni comertce[ENTER]odullendiririm. "
gameforge.subquest_46._50_select = "Kabul et "
gameforge.subquest_46._60_select = "Reddet "
gameforge.subquest_46._70_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_46._80_say = "Su anda cok mesgulsen daha sonra gel. "
gameforge.subquest_46._90_say = "Gercekten vazgecmek mi istiyorsun? O zaman bunu[ENTER]kendim yapmak zorundayim... Bu porselene gercekten[ENTER]ihtiyacim var. Gorusmek uzere ve iyi sanslar. "
