gameforge.subquest_47._330_say = "Er ya da gec kesinlikle basaracaksin. Kendini[ENTER]hazir hissettiginde tekrar gel! "
gameforge.subquest_47._40_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_47._50_say = "Ama... Gecen sefer basarmistin.[ENTER]Neden tereddut ediyorsun? Bunu iyi dusun lutfen. "
gameforge.subquest_47._60_say = "Anliyorum. Artik bizimle calismak istemiyorsun,[ENTER]oyle mi? Cok yazik. Cesur savascilara nadir[ENTER]rastlanir. "
