gameforge.subquest_48._10_npcChat = "Casusu bul "
gameforge.subquest_48._110_say = "Yuzbasi'nin casuslarindan biri Jinno Kralligi'ndaki[ENTER]Pyungmoo koyunde Balikci kiliginda yasiyor. Onunla[ENTER]fark edilmeden temas kurmaya calis. Gerekli[ENTER]bilgileri elde eder etmez Yuzbasi'ya ilet. "
gameforge.subquest_48._120_say = "Yuzbasi'nin casuslarindan biri Shinsoo Kralligi'ndaki[ENTER]Yongan koyunde Balikci kiliginda yasiyor. Onunla[ENTER]fark edilmeden temas kurmaya calis. Gerekli[ENTER]bilgileri elde eder etmez Yuzbasi'ya ilet. "
gameforge.subquest_48._130_say = "Yuzbasi'nin casuslarindan biri Chunjo Kralligi'ndaki[ENTER]Joan koyunde Balikci kiliginda yasiyor. Onunla[ENTER]fark edilmeden temas kurmaya calis. Gerekli[ENTER]bilgileri elde eder etmez Yuzbasi'ya ilet. "
gameforge.subquest_48._140_npcChat = "Ne yapiyorsun sen? "
gameforge.subquest_48._150_say = "Ssst, sessiz ol! Butun baliklari kaciracaksin.[ENTER]Burada ne isin var senin? Oyle gurultucu ve[ENTER]sakarsin ki buraya balik tutmaya gelmedigin kesin. "
gameforge.subquest_48._160_say = "Ah, simdi anladim. Bir sure once seni bekliyordum,[ENTER]gec kaldin. Bu bilgileri elde etmek ve yakalanmamak[ENTER]hic kolay olmadi. Bilmelisin ki dusman her yerde[ENTER]pusuda ve acik vermemizi bekliyor. "
gameforge.subquest_48._170_say = "O zaman bizi biri gormeden cabucak halledelim.[ENTER]Iste belgeler. Onlari derhal Yuzbasi'ya gotur ve[ENTER]yalnizca ona ver. "
gameforge.subquest_48._180_say = "Bir saniye! Senin icin bir seyim var. Kucuk bir[ENTER]hediye. Simdi yola koyul. Basarilar. "
gameforge.subquest_48._190_sayReward = "Merakla paketi acip casusun sana ne hediye ettigine[ENTER]bakiyorsun. "
gameforge.subquest_48._200_say = "Harika! Izgara Kizilkanat! Kuskusuz Casus baliktan[ENTER]mukemmel anliyor. "
gameforge.subquest_48._20_say = "Rahat asker! Komsu Kralliklar dusmanimiz oldugu[ENTER]icin bizim adimiza gizlice bilgi toplayacak dostlarimizin[ENTER]orada bulunmasi cok onemlidir. Bu sayede saldirilari[ENTER]puskurtmeye hazirlanabiliriz. Bu casuslarin aciga[ENTER]cikmamasi son derece onemlidir. "
gameforge.subquest_48._210_sayReward = "3 adet Izgara Kizilkanat kazandin. "
gameforge.subquest_48._220_sendLetter = "Yuzbasi'ya Don. "
gameforge.subquest_48._230_targetVid = "Yuzbasi "
gameforge.subquest_48._240_say = "Jinno Kralligi'ndaki Pyungmoo'ya yapilan yolculuk[ENTER]cok tehlikeliydi: Balikci kiligina girmis casusun[ENTER]raporunu aldin. Simdi cabucak kendi Kralligina don[ENTER]ve edindigin bilgileri Yuzbasi'ya ilet. "
gameforge.subquest_48._250_say = "Shinsoo Kralligi'ndaki Yongan'a yapilan yolculuk[ENTER]cok tehlikeliydi: Balikci kiligina girmis casusun[ENTER]raporunu aldin. Simdi cabucak kendi Kralligina don[ENTER]ve edindigin bilgileri Yuzbasi'ya ilet. "
gameforge.subquest_48._260_say = "Chunjo Kralligi'ndaki Joan'a yapilan yolculuk[ENTER]cok tehlikeliydi: Balikci kiligina girmis casusun[ENTER]raporunu aldin. Simdi cabucak kendi Kralligina don[ENTER]ve edindigin bilgileri Yuzbasi'ya ilet. "
gameforge.subquest_48._270_npcChat = "Gorev tamamlandi! "
gameforge.subquest_48._280_say = "O belgeler bunlar mi? Harika! Tesekkur ederim.[ENTER]Artik dusmanimizin planlarini biliyoruz ve gereken[ENTER]hazirliklari yapabiliriz.[ENTER]Artik korkmamiza gerek kalmadi.[ENTER]Kralliga muazzam bir iyilik yaptin. "
gameforge.subquest_48._290_sayReward = "5.500.000 Deneyim Puani kazandin. "
gameforge.subquest_48._300_sayReward = "50.000 Yang kazandin. "
gameforge.subquest_48._30_say = "Muzisyen Yu-Hwan'i kesinlikle taniyorsundur?[ENTER]Bizim casusumuzdur, muzisyen kiliginda calisir.[ENTER]Tek bir casus fazla bir sey yapamaz, bu yuzden tum[ENTER]dunyaya yayilmis birkac casusumuz var. Bazilari ilk[ENTER]koydeki balikcilardir. "
gameforge.subquest_48._40_say = "Onlari desifre etmeden temas kuramayacagim icin[ENTER]senin gibi cok cesur askerlerin yardimina ihtiyacim[ENTER]var. Balikciya gidip Kralligimizi korumak icin acilen[ENTER]ihtiyacim olan bilgileri alabilir misin? "
gameforge.subquest_48._50_say = "Gorevden vazgecmek istiyor musun? "
gameforge.subquest_48._60_say = "Once hazirlanmak mi istiyorsun? O zaman daha sonra[ENTER]ugra. Seni bekliyorum. Ama lutfen acele et, bu cok[ENTER]onemli! Bu rapora ihtiyacim var! "
gameforge.subquest_48._70_say = "Nen var senin? Gecen sefer bizim icin harika bir[ENTER]is cikarmistin! Kralligi zor durumunda oylece terk[ENTER]ettigine inanamiyorum. Ama senin tercihin, yapacak[ENTER]bir sey yok... Gorusmek uzere. "
gameforge.subquest_48._80_say = "Harika! Sana guvenilebilecegini biliyordum.[ENTER]Basarilar ve kendine dikkat et. "
gameforge.subquest_48._90_makequestbutton = "Casusla Bulus "
gameforge.subquest_49 = {}
gameforge.subquest_49._100_sayTitle = "Bingsu nedir? "
gameforge.subquest_49._10_targetVid = "Bingsu? "
gameforge.subquest_49._110_say = "Taurean yazin dondurma yapilabilecegine inanmadigi[ENTER]icin Harang ile tartisti. Harang'a git ve Bingsu[ENTER]hakkinda ne bildigini sor. "
gameforge.subquest_49._120_qSetTitle = "Harang'a Sor "
gameforge.subquest_49._130_targetVid = "Harang'a Sor "
gameforge.subquest_49._140_npcChat = "Bingsu nedir? "
gameforge.subquest_49._150_say = "Ah su Taurean! Bingsu'nun ne oldugunu bilmiyor[ENTER]ama her seyi bildigini iddia ediyor. Insan boyle[ENTER]bir yemegi nasil bilmez? Ne aptal cocuk. Senin de mi[ENTER]Bingsu'nun ne oldugu hakkinda fikrin yok? En iyisi[ENTER]bir sonraki koyde yasayan Octavio'ya gitmen.[ENTER]Ünlu bir ascidir ve tum guzel tarifleri bilir.[ENTER]Bir keresinde benim icin Bingsu yapmisti, hmm...[ENTER]Hakli oldugumu sana o kanitlayacaktir! "
gameforge.subquest_49._160_makequestbutton = "Octavio'ya git "
gameforge.subquest_49._170_say = "Taurean Bingsu'nun ne oldugunu kesinlikle ogrenmek[ENTER]istiyor. Meyhane sahibi Octavio'ya git. Kesinlikle[ENTER]sana yardimci olabilecektir. "
gameforge.subquest_49._180_npcChat = "Bingsu'nun ne oldugunu biliyor musun? "
gameforge.subquest_49._190_say = "Bingsu mu? Elbette ne oldugunu biliyorum. Her iyi[ENTER]asci Bingsu'nun nasil hazirlanacagini bilir! Ilk[ENTER]olarak ince kirilmis buza ihtiyac vardir. Üzerine[ENTER]seker, ince dilimlenmis pirinc keki ve susleme icin[ENTER]taze meyveler eklenir. "
gameforge.subquest_49._200_say = "Neden soruyorsun? Taurean Harang ile tartisiyor[ENTER]diye mi? Bu yeni bir sey degil ki. Ama Harang hakli.[ENTER]Ozellikle sicak yaz gunlerinde Bingsu cok populer[ENTER]bir lezzettir.[ENTER]Taurean iyi bir cocuktur, bazen biraz kit kafali[ENTER]gorunse bile. Malzemeleri bulursan sana Bingsu[ENTER]yapabilirim. "
gameforge.subquest_49._20_npcChat = "Bingsu? "
gameforge.subquest_49._210_say = "Taurean'i mutlu edip ona Bingsu ikram etmek[ENTER]isterdim. Ne dersin? Sohan Dagi'ndan bana biraz Buz[ENTER]getirebilir misin? "
gameforge.subquest_49._220_say = "Bu gorevden temelli vazgecmek istiyor musun? "
gameforge.subquest_49._230_say = "Dondurma sevmez misin? Yoksa cok mu yedin? Bu[ENTER]Taurean icin bir iyilik, bu yuzden lutfen bir kez[ENTER]daha dusun. "
gameforge.subquest_49._240_say = "Yazik oldu. Taurean cok hayal kirikligina ugrayacak.[ENTER]Simdilik hosca kal. "
gameforge.subquest_49._250_say = "Harika. Sohan Dagi'ndaki Buyulu Buz'dan Buz Parcasi'na[ENTER]ihtiyacim var. Bana 50 adet getirirsen lezzetli bir[ENTER]Bingsu yaparim. "
gameforge.subquest_49._260_targetVid = "Octavio'ya git "
gameforge.subquest_49._270_say = "%s[ENTER]Taurean'in Bingsu'su icin Buz Parcasi bende.[ENTER]Onu Octavio'ya gotur. "
gameforge.subquest_49._275_say = "Buz Parcasi alindi "
gameforge.subquest_49._280_say = "Octavio Taurean icin Bingsu hazirlayacak ama bunun[ENTER]icin buza ihtiyaci var. Sohan Dagi'nda Buyulu Buz[ENTER]oldur ve 50 buz parcasi toplayip Octavio'ya gotur. "
gameforge.subquest_49._285_say = "Buz Arayisi "
gameforge.subquest_49._290_npcChat = "Al bakalim, Buz Parcalarini getirdim. "
gameforge.subquest_49._300_say = "Ah, harika! Bingsu hazirlamanin en zor asamasini[ENTER]geride biraktik o zaman. Simdi sadece biraz seker...[ENTER]ve meyve ekliyorum... ve iste buyrun! Taurean icin[ENTER]buz. Bunu ona hemen gotur, yakinda ofkesini[ENTER]unutacaktir. "
gameforge.subquest_49._30_sayTitle = "Taurean: "
gameforge.subquest_49._310_say = "Cok uzgunum ama bu cok az. Bana daha fazlasini[ENTER]getirmelisin, yoksa bundan ufacik bir porsiyon[ENTER]cikar! "
gameforge.subquest_49._320_select = "Tekrar dene... "
gameforge.subquest_49._330_say = "Yolun uzak ve canavarlarin tehlikeli oldugunu[ENTER]biliyorum. Kendini hazir hissetmiyorsan yapacak bir[ENTER]sey yok. Simdilik hosca kal. "
gameforge.subquest_49._340_say = "Elbette tekrar deneyebilirsin. Cesaretin ve[ENTER]dayanikliliginla sonunda kesinlikle basarili[ENTER]olacaksin! "
gameforge.subquest_49._350_targetVid = "Bingsu? "
gameforge.subquest_49._360_say = "Basardik! Octavio Sohan Dagi'nin Buzundan Bingsu[ENTER]hazirladi. Simdi Bingsu erimeden cabucak Taurean'a[ENTER]git. "
gameforge.subquest_49._370_npcChat = "Iste burada! Bingsu! "
gameforge.subquest_49._380_say = "Bingsu bu mu? Gercekten mukemmel bir tadi var.[ENTER]Tatli ve serinletici. Daha once hic boyle bir sey[ENTER]yememistim, tesekkur ederim! Harang hakliymis demek.[ENTER]Ondan ozur dilemem gerekecek... "
gameforge.subquest_49._40_say = "Bugun Harang ile kavga ettim. Normalde onu bir[ENTER]kasik suda bogardim...[ENTER]Incecik kirilmis Buzdan yapilan cok lezzetli bir[ENTER]tatli oldugunu iddia ediyor. Adi Bingsu'ymus. "
gameforge.subquest_49._410_sayReward = "Savas Parsomeni kazandin. "
gameforge.subquest_49._420_say = "Benim icin Bingsu meselesi, hatirliyor musun? "
gameforge.subquest_49._430_say = "Aman Tanrim, bunu tamamen unutmustum! Hmm, denemeye[ENTER]devam mi edeyim yoksa bos mu vereyim? "
gameforge.subquest_49._440_select = "Devam etmek istiyorum. "
gameforge.subquest_49._450_select = "Pes ediyorum. "
gameforge.subquest_49._460_say = "Bunu yapamam, uzgunum. "
gameforge.subquest_49._50_say = "Boyle bir sey genellikle sadece kisin, hava cok[ENTER]sogukken mumkundur. Oysa o bunun yazin da mumkun[ENTER]oldugunu iddia edip duruyor. Yazin da Bingsu yapilip[ENTER]yapilamayacagini ogrenebilir misin? Eger boyle bir[ENTER]sey gercekten varsa tabii... "
gameforge.subquest_49._60_say = "Bu Bingsu kesinlikle cok lezzetlidir! Onu hazirlamama[ENTER]asla yardim etmek istemediginden emin misin? "
gameforge.subquest_49._70_say = "Bunu daha sonra yapmak istersen bana haber ver. "
gameforge.subquest_49._80_say = "Bu Bingsu'yu tatmayi o kadar cok isterdim ki...[ENTER]Ama haklisin. Harang muhtemelen sadece hava atmak[ENTER]istemistir, aslinda ortada Bingsu falan yoktur![ENTER]Gorusmek uzere. "
gameforge.subquest_49._90_say = "Bana yardim ettigin icin tesekkurler. Bir sey[ENTER]ogrendiginde bana haber ver. O zaman Harang'a tum[ENTER]bunlar hakkinda ne dusundugumu soyleyebilirim! "
